    array->data = NULL;
    array->capacity = 0;
    array->size = 0;
    array->elementSize = sizeof(NFAPI_RX_FRAME_T);
    customMalloc(&array->memoryPool, sizeof(NFAPI_RX_FRAME_T*) * INITIAL_CAPACITY);
    array->data = (NFAPI_RX_FRAME_T**) array->memoryPool;
    return array;
}

void resizeDynamicArray(DYNAMIC_ARRAY* array) {
    size_t newCapacity = array->capacity * 2;
    void* newMemoryPool;
    customMalloc(&newMemoryPool, sizeof(NFAPI_RX_FRAME_T*) * newCapacity);

    for (size_t i = 0; i < array->size; ++i) {
        NFAPI_RX_FRAME_T** element = &array->data[i];
        *element = (NFAPI_RX_FRAME_T*) ((char*) newMemoryPool + sizeof(NFAPI_RX_FRAME_T*) * i);
    }

    free(array->memoryPool);
    array->memoryPool = newMemoryPool;
    array->capacity = newCapacity;
}

NFAPI_RX_FRAME_T* pushBackDynamicArray(DYNAMIC_ARRAY* array) {
    if (array->size == array->capacity) {
        resizeDynamicArray(array);
    }

    NFAPI_RX_FRAME_T* newElement = &array->data[array->size];
    pthread_mutex_init(&newElement->lock, NULL);

    ++array->size;
    return newElement;
}

NFAPI_RX_FRAME_T* getAtDynamicArray(DYNAMIC_ARRAY* array, size_t index) {
    if (index >= array->size) {
        return NULL;
    }

    return &array->data[index];
}

void destroyDynamicArray(DYNAMIC_ARRAY* array) {
    for (size_t i = 0; i < array->size; ++i) {
        customFree(&array->data[i]);
    }

    free(array->memoryPool);
    free(array);
