#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct Record {
    int value;
    int key;
    long offset;
    struct Record *next;
} Record;

Record* create_record(int key, long offset, int value) {
    Record *new_record = (Record *) malloc(sizeof(Record));
    new_record->key = key;
    new_record->offset = offset;
    new_record->value = value;
    new_record->next = NULL;
    return new_record;
}

void initialize_arrays(int *keys, long *offsets, int records_count, int record_size) {
    keys = calloc(records_count, sizeof(int));
    offsets = calloc(record_size, sizeof(long));
}

Record** create_record_list(int record_count, int record_size) {
    Record **records = (Record **) malloc(record_count * sizeof(Record*));
    for (int i = 0; i < record_count; ++i) {
        records[i] = NULL;
    }
    return records;
}

void insert_record(Record **records, int key, long offset, int value) {
    Record *new_record = create_record(key, offset, value);
    if (!records[key]) {
        records[key] = new_record;
    } else {
        Record *current = records[key];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }
}

void randomize_records(Record **records, int record_count, int min_value, int max_value) {
    srand(time(NULL));
    for (int i = 0; i < record_count; ++i) {
        if (records[i]) {
            records[i]->value = rand() % (max_value - min_value + 1) + min_value;
        }
    }
}

void resize_record_array(Record **records, int record_count, int *record_size, int threshold) {
    if (record_count >= *record_size * threshold) {
        *record_size *= 2;
        Record **new_records = realloc(records, (*record_size) * sizeof(Record*));
        if (!new_records) {
            printf("Memory allocation error!\n");
            exit(EXIT_FAILURE);
        }
        records = new_records;
    }
}

void initialize_and_randomize_records(int record_count, int record_size, int min_value, int max_value) {
    Record **records = create_record_list(record_count, record_size);
    int *keys = NULL;
    long *offsets = NULL;
    initialize_arrays(keys, offsets, record_count, record_size);

    int *keys_ptr = keys;
    long *offsets_ptr = offsets;

    for (int i = 0; i < record_count; ++i) {
        resize_record_array(records, i + 1, &record_size, 0.5);
        insert_record(records, keys_ptr[i], offsets_ptr[i], rand() % (max_value - min_value + 1) + min_value);
    }
    randomize_records(records, record_count, min_value, max_value);
}
