#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#include <pthread.h>
#include <getopt.h>

typedef struct {
    size_t buf_size;
    char *buf;
} LineBuffer;

void destroy_linebuffer(LineBuffer *lb) {
    if (lb->buf != NULL) {
        munmap(lb->buf, lb->buf_size);
        free(lb);
    }
}

LineBuffer* create_linebuffer(size_t size) {
    LineBuffer *lb = malloc(sizeof(LineBuffer));
    lb->buf = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    lb->buf_size = size;
    return lb;
}

int main(int argc, char **argv) {
    const char *log_file = "output.log";
    int opt;
    char *input_file = NULL;
    char *output_file = log_file;
    int manpage = 0;

    static struct option long_options[] = {
        {"manpage", no_argument, 0, 'h'},
        {"cs", no_argument, 0, 'c'},
        {"output-file", required_argument, 0, 'o'},
        {0, 0, 0, 0}
    };

    while ((opt = getopt_long(argc, argv, "h:c:o:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                manpage = 1;
                break;
            case 'c':
                // No action required for this option.
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Invalid option: %c\n", optopt);
                return 1;
        }
    }

    if (!input_file) {
        fprintf(stderr, "Usage: %s [options] input_file\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(input_file, "r");
    if (!fp) {
        perror("Failed to open the file.");
        return 1;
    }

    pthread_t threads[argc - optind];
    size_t lines_count = 0;

    LineBuffer *lb = create_linebuffer(4096); // Buffer size can be tuned for optimal performance.

    for (int i = optind; i < argc; ++i) {
        FILE *thread_input = fopen(argv[i], "r");
        if (!thread_input) {
            perror("Failed to open the thread input file.");
            continue;
        }

        pthread_create(&threads[lines_count], NULL, read_file_and_count_lines, (void *) {.fp = thread_input, .output_file = output_file, .line_count = &lines_count});
        lines_count++;
    }

    // Wait for all threads to finish processing their input files.
    for (int i = 0; i < lines_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    fprintf(output_file, "Total lines: %lu\n", lines_count);
    destroy_linebuffer(lb);
    fcloseAllFiles(); // Function to close all opened file descriptors.

    return 0;
}

void *read_file_and_count_lines(void *args) {
    void *data = args;
    FILE *fp = ((struct read_args*) data)->fp;
    char *output_file = ((struct read_args*) data)->output_file;
    size_t *line_count = ((struct read_args*) data)->line_count;

    LineBuffer *lb = create_linebuffer(4096); // Buffer size can be tuned for optimal performance.
    char line[1024];
    size_t lines_count = 0;

    while (fgets(line, sizeof(line), fp)) {
        if (lines_count == 1 && manpage) { // Print usage information when the first line is read.
            fprintf(output_file, "Usage: %s [options] input_file\n", ((struct read_args*) data)->argv[0]);
            return NULL;
        }

        if (lines_count >= lb->buf_size) { // Flush buffer when it reaches the maximum capacity.
            fprintf(output_file, "%lu: %s", lines_count + 1, line);
            lines_count++;
            lb->buf[lines_count * lb->buf_size] = '\0';
        } else {
            strncpy(lb->buf + lines_count * lb->buf_size, line, sizeof(line) - 1);
        }

        lines_count++;
    }

    // Flush any remaining buffer content.
    if (lines_count > 0 && lines_count % lb->buf_size != 0) {
        fprintf(output_file, "%lu: %s", lines_count + 1, lb->buf);
        lines_count++;
    }

    pthread_mutex_lock(&global_mutex); // Lock global mutex to update shared data.
    (*line_count) += lines_count;
    pthread_mutex_unlock(&global_mutex);

    destroy_linebuffer(lb);
    fclose(fp);
    return NULL;
}
```

