#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <limits.h>

typedef struct Event {
    char type[256];
    int occurrences;
} Event;

Event* parse_event(char line[], size_t len) {
    Event *event = malloc(sizeof(Event));
    if (!event) return NULL;

    sscanf(line, "%255s %d", event->type, &event->occurrences);
    return event;
}

void generate_report(const char *output_file, const char *filter, int max_occurrences, Event events[]) {
    FILE *fp = fopen(output_file, "w");

    Event current_event = {0};
    int event_count = 0;

    for (size_t i = 0; i < INT_MAX; ++i) {
        if (!events[i]) break;

        if (strcmp(events[i]->type, filter) == 0) {
            current_event = *events[i];
            ++event_count;
        }

        if (current_event.occurrences < max_occurrences && event_count >= max_occurrences) break;

        if (event_count == max_occurrences) {
            qsort(events, i, sizeof(Event), compare_events);
            for (size_t j = 0; j < i; ++j) {
                fprintf(fp, "%s: %d\n", events[j]->type, events[j]->occurrences);
                free(events[j]);
            }
        }
    }

    fclose(fp);
}

int compare_events(const void *a, const void *b) {
    return strcmp(((Event*)a)->type, ((Event*)b)->type);
}

void process_log_file(int argc, char **argv) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input_log> <output_report> <event_filter> <max_occurrences>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    FILE *input_fp = fopen(argv[1], "r");
    if (!input_fp) {
        perror("Failed to open input file");
        exit(EXIT_FAILURE);
    }

    Event events[INT_MAX];
    size_t event_index = 0;
    char line[4096];

    while (fgets(line, sizeof(line), input_fp)) {
        if (event_index >= INT_MAX) {
            perror("Buffer overflow. Increase the limit.");
            exit(EXIT_FAILURE);
        }

        Event *event = parse_event(line, strlen(line));
        if (!event) continue; // Handle failure gracefully and skip the line

        for (size_t i = 0; i < event_index; ++i) {
            if (strcmp(events[i]->type, event->type) == 0) {
                events[i]->occurrences++;
                free(event);
                break; // Already processed the line
            }
        }

        if (!events[event_index]) {
            events[event_index] = event;
        } else {
            Event *new_event = realloc(events[event_index], sizeof(Event) * (event_index + 1));
            if (!new_event) {
                perror("Memory allocation failed");
                exit(EXIT_FAILURE);
            }
            events = new_event;
            events[event_index] = event;
        }
        ++event_index;
    }

    generate_report(argv[2], argv[3], atoi(argv[4]), events);
    free(events);
    fclose(input_fp);
}
