typedef struct Connection {
    int sockfd;
    struct sockaddr_in addr;
    time_t last_used;
} Connection;

pthread_mutex_t connection_pool_lock = PTHREAD_MUTEX_INITIALIZER;
static Connection *connection_pool = NULL;
static size_t connection_pool_size = 0;

int get_free_connection() {
    pthread_mutex_lock(&connection_pool_lock);
    if (connection_pool_size > 0) {
        Connection *conn = &connection_pool[--connection_pool_size];
        conn->last_used = time(NULL);
        pthread_mutex_unlock(&connection_pool_lock);
        return conn->sockfd;
    }
    pthread_mutex_unlock(&connection_pool_lock);
    return socket(AF_INET, SOCK_STREAM, 0);
}

void release_connection(int sockfd) {
    Connection *conn;
    pthread_mutex_lock(&connection_pool_lock);
    if (connection_pool_size >= connection_pool_size) {
        if (connection_pool) {
            conn = &connection_pool[connection_pool_size];
            conn->sockfd = sockfd;
            conn->last_used = time(NULL);
        } else {
            connection_pool = malloc(sizeof(Connection));
            conn = connection_pool;
            connection_pool_size++;
            conn->sockfd = sockfd;
            conn->last_used = time(NULL);
        }
    }
    pthread_mutex_unlock(&connection_pool_lock);
}

int dns_resolve(const char *hostname, u_char *ip_addr, size_t ip_addr_len) {
    struct hostent *host;
    int sockfd;
    struct timeval tv = {1, 0}; // 1 second timeout
    fd_set readfds;
    struct sockaddr_in server_addr;
    ssize_t n;
    socklen_t addr_len = sizeof(server_addr);

    host = gethostbyname(hostname);
    if (!host) {
        log(1, "Failed to resolve host %s", hostname);
        return 1;
    }

    // Use a connection from the pool if available, otherwise create a new one.
    sockfd = get_free_connection();

    memset((char *)&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(host->h_addrtype == AF_INET ? host->h_addr->sa_family == AF_INET ? htons(DNS_UDP_PORT) : htons(DNS_TCP_PORT) : 0);
    memcpy(&server_addr.sin_addr, host->h_addr, host->h_length);

    // Send DNS request.
    if (connect(sockfd, (struct sockaddr *)&server_addr, addr_len) < 0) {
        log(1, "Failed to connect to %s", inet_ntoa(server_addr.sin_addr));
        close(sockfd);
        return 1;
    }

    // Send the query and handle response.
    n = send(sockfd, host->h_name, strlen(host->h_name), 0);
    if (n < 0) {
        log(1, "Failed to send DNS request");
        close(sockfd);
        return 1;
    }

    FD_ZERO(&readfds);
    FD_SET(sockfd, &readfds);
    select(FD_SETSIZE, &readfds, NULL, NULL, &tv);
    if (!FD_ISSET(sockfd, &readfds)) {
        log(1, "DNS request timed out");
        close(sockfd);
        return 1;
    }

    memset(ip_addr, 0, ip_addr_len);
    n = recvfrom(sockfd, ip_addr, ip_addr_len, 0, NULL, NULL);
    if (n < 0) {
        log(1, "Failed to receive DNS response");
        close(sockfd);
        return 1;
    }

    release_connection(sockfd);

    // Handle multiple responses and retry up to three times if necessary.
    for (int i = 2; i < 4; ++i) {
        sockfd = get_free_connection();
        memset((char *)&server_addr, 0, sizeof(server_addr));
        // ... (send the same query and handle response as before)
    }

    if (*ip_addr == 0) {
        log(1, "Failed to get IP address for %s", hostname);
        return 1;
    }

    log(0, "Successfully resolved %s to %s", hostname, inet_ntoa(*((struct in_addr *)ip_addr)));
    return 0;
}
