#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int is_number(const char *str) {
    if (*str == '\0') return 0;
    for (size_t i = 1; i <= strlen(str); ++i) {
        if (!isdigit(str[i])) return 0;
    }
    return 1;
}

void read_int(char **input, int *num) {
    char number[32];
    int pos = 0;
    while (isspace(**input)) ++*input, --pos;
    for (; isdigit(**input); ++*input) {
        number[pos++] = **input;
        number[pos] = '\0';
        *num *= 10;
        *num += atoi(number);
    }
}

size_t read_and_process_list(int **arr, size_t *len) {
    char input[128];
    size_t count = 0;
    while (fgets(input, sizeof(input), stdin)) {
        if (*input == '\n') continue;
        for (char *token = strtok(input, " \t\n"); token; token = strtok(NULL, " \t\n")) {
            if (!is_number(token)) {
                printf("Invalid input: %s\n", token);
                return 0;
            }
            int num;
            read_int(&token, &num);
            if (count >= *len) {
                *arr = realloc(*arr, sizeof(**arr) * (*len << 1));
                ++*len;
            }
            (*arr)[count++] = num;
        }
    }
    if (!count) printf("No integers provided.\n");
    return count;
}

void find_max(int *arr, size_t len, int *max, size_t *index) {
    *max = *index = 0;
    for (size_t i = 1; i < len; ++i) {
        if (arr[i] > *max) {
            *max = arr[i];
            *index = i;
        }
    }
}

int main() {
    int *numbers = NULL;
    size_t num_count = 0;
    read_and_process_list(&numbers, &num_count);
    if (num_count) {
        int max, index;
        find_max(numbers, num_count, &max, &index);
        printf("The largest integer is %d at index %zu\n", max, index);
        free(numbers);
    }
    return 0;
}
