static time_t last_log_time = 0;
static const int LOG_RATE_SECS = 5; // Adjust this value to control log rate

void log_error_condition(const char *format, ...) {
    time_t now = time(NULL);
    if (difftime(now, last_log_time) >= LOG_RATE_SECS) {
        last_log_time = now;

        FILE *file = fopen("error.log", "a");
        if (file != NULL) {
            va_list args;
            char buffer[4096]; // Adjust this value to control the maximum length of a log message
            va_start(args, format);
            snprintf(buffer, sizeof(buffer), "%s %d: ", ctime(&now), getpid());
            vsnprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), format, args);
            fprintf(file, "%s\n", buffer);
            fclose(file);
            va_end(args);
        }
    }

    pthread_mutex_lock(&log_mutex);
    // Implement thread-safe logging using a queue and producer-consumer pattern if needed.
    // For simplicity, this example does not include multithreading.
    pthread_mutex_unlock(&log_mutex);
}
