#include <jansson/jansson.h>
#include <openssl/des.h>
#include <openssl/evp.h>

typedef struct {
    const char* access_token;
    int expires_in;
    const char* token_type;
    const char* refresh_token;
    char cipher_mode[10]; // 'ECB', 'EDE', 'EDE3', 'CFB' or 'NULL'
} oauth2_response;

oauth2_response parse_json(const char* json) {
    json_t *root, *access_token, *expires_in, *token_type, *refresh_token, *cipher_mode;
    root = json_loads(json, 0, NULL);
    access_token = json_object_get(root, "access_token");
    expires_in = json_object_get(root, "expires_in");
    token_type = json_object_get(root, "token_type");
    refresh_token = json_object_get(root, "refresh_token");
    cipher_mode = json_object_get(root, "cipher_mode");
    oauth2_response result = {
        .access_token = json_string_value(access_token),
        .expires_in = json_integer_value(expires_in) > 0 ? json_integer_value(expires_in) : 0,
        .token_type = json_string_value(token_type) && !strcmp(json_string_value(token_type), "Bearer") ? json_string_value(token_type) : NULL,
        .refresh_token = json_is_null(refresh_token) ? NULL : json_string_value(refresh_token),
        .cipher_mode = json_is_null(cipher_mode) ? "NULL" : json_string_value(cipher_mode)
    };
    json_decref(root);
    return result;
}

EVP_CIPHER* init_des_cipher(const oauth2_response* response) {
    EVP_CIPHER_TYPE type = EVP_cipherbyname(response->cipher_mode);
    if (type == EVP_aes_128_cbc() || // ECB, EDE, EDE3 not supported in OpenSSL directly
        strcmp(response->cipher_mode, "NULL") == 0) {
        EVP_CIPHER* cipher = EVP_des_ecb(); // or EVP_aes_128_cbc() for non-NULL modes
        return cipher;
    }
    return NULL;
}
