typedef struct {
    const char *access_token;
    int expires_in;
    const char *token_type;
    const char *refresh_token;
} oauth2_response;

typedef enum { ECB, EDE, EDE3, CFB, NULL_ENCRYPTION } cipher_mode;

struct des_cipher {
    EVP_CIPHER_CTX *ctx;
    const char *json_settings;
    cipher_mode mode;
};

bool parse_and_validate(const char *str) {
    json_t *root = json_loads(str, 0, NULL);
    if (!root || !json_is_object(root)) return false;

    oauth2_response token;
    token.access_token = json_string_value(json_object_get(root, "access_token"));
    token.expires_in = json_integer_value(json_object_get(root, "expires_in"));
    token.token_type = json_string_value(json_object_get(root, "token_type"));
    if (json_object_has_member(root, "refresh_token")) {
        token.refresh_token = json_string_value(json_object_get(root, "refresh_token"));
    }

    if (strcmp(token.token_type, "Bearer") != 0 || token.expires_in <= 0) return false;

    json_t *cipher = json_object_get(root, "cipher");
    if (!json_is_string(cipher)) return false;

    const char *cipher_str = json_string_value(cipher);
    struct des_cipher *cipher_ctx = malloc(sizeof(struct des_cipher));
    cipher_ctx->json_settings = cipher_str;
    cipher_ctx->mode = CFB; // Default mode

    if (strcmp(cipher_str, "ECB") == 0) cipher_ctx->mode = ECB;
    else if (strcmp(cipher_str, "EDE") == 0) cipher_ctx->mode = EDE;
    else if (strcmp(cipher_str, "EDE3") == 0) cipher_ctx->mode = EDE3;
    else if (strcmp(cipher_str, "CFB") == 0) cipher_ctx->mode = CFB;
    else if (strcmp(cipher_str, "NULL_ENCRYPTION") == 0) cipher_ctx->mode = NULL_ENCRYPTION;

    return true;
}

struct des_cipher *setup_des_cipher(const char *access_token, const char *cipher) {
    if (!parse_and_validate(access_token)) return NULL;

    struct des_cipher *cipher_ctx = malloc(sizeof(struct des_cipher));
    cipher_ctx->json_settings = access_token;

    const char *cipher_str = cipher;
    if (strcmp(cipher, "ECB") == 0) cipher_ctx->mode = ECB;
    else if (strcmp(cipher, "EDE") == 0) cipher_ctx->mode = EDE;
    else if (strcmp(cipher, "EDE3") == 0) cipher_ctx->mode = EDE3;
    else if (strcmp(cipher, "CFB") == 0) cipher_ctx->mode = CFB;
    else if (strcmp(cipher, "NULL_ENCRYPTION") == 0) cipher_ctx->mode = NULL_ENCRYPTION;

    return cipher_ctx;
}

void des_cipher_init(struct des_cipher *cipher_ctx) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_des_ecb(), NULL);

    if (cipher_ctx->mode == EDE || cipher_ctx->mode == EDE3 || cipher_ctx->mode == CFB) {
        // Load initialization vectors and keys from the JSON configuration
        // ...
    }

    cipher_ctx->ctx = ctx;
}

void des_cipher_free(struct des_cipher *cipher_ctx) {
    EVP_CIPHER_CTX_free(cipher_ctx->ctx);
    free(cipher_ctx);
}
