#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>

typedef void (*TaskFunc)(void*);

struct Task {
    TaskFunc func;
    void *arg;
};

struct ThreadPool {
    pthread_mutex_t queue_lock;
    pthread_cond_t notempty;
    pthread_cond_t notfull;
    size_t max_threads;
    size_t num_threads;
    bool shutdown;
    struct Task queue[16]; // Adjust the number as per your requirement
};

void thread_pool_init(struct ThreadPool *pool, size_t max_threads) {
    pthread_mutex_init(&pool->queue_lock, NULL);
    pthread_cond_init(&pool->notempty, NULL);
    pthread_cond_init(&pool->notfull, NULL);
    pool->max_threads = max_threads;
    pool->num_threads = 0;
    pool->shutdown = false;
}

void enqueue(struct ThreadPool *pool, TaskFunc func, void *arg) {
    struct Task task = {func, arg};
    pthread_mutex_lock(&pool->queue_lock);
    while (pool->num_threads == pool->max_threads && !pool->shutdown) {
        pthread_cond_wait(&pool->notfull, &pool->queue_lock);
    }
    if (!pool->shutdown) {
        pool->queue[pool->num_threads++] = task;
        pthread_cond_signal(&pool->notempty);
    }
    pthread_mutex_unlock(&pool->queue_lock);
}

void *worker(void* arg) {
    struct ThreadPool *pool = (struct ThreadPool *)arg;
    while (!pool->shutdown) {
        Task task;
        pthread_mutex_lock(&pool->queue_lock);
        while (pool->num_threads == 0 && !pool->shutdown) {
            pthread_cond_wait(&pool->notempty, &pool->queue_lock);
        }
        if (!pool->shutdown) {
            task = pool->queue[--pool->num_threads];
            pthread_mutex_unlock(&pool->queue_lock);
            task.func(task.arg);
        }
    }
    return NULL;
}

void thread_pool_start(struct ThreadPool *pool) {
    for (size_t i = 0; i < pool->max_threads; ++i) {
        pthread_create(&pool->worker_threads[i], NULL, worker, pool);
    }
}

void thread_pool_wait(struct ThreadPool *pool) {
    for (size_t i = 0; i < pool->max_threads; ++i) {
        pthread_join(pool->worker_threads[i], NULL);
    }
}

void thread_pool_shutdown(struct ThreadPool *pool) {
    pool->shutdown = true;
    enqueue(pool, NULL, NULL); // Wake up all worker threads
    thread_pool_wait(pool);
    pthread_mutex_destroy(&pool->queue_lock);
    pthread_cond_destroy(&pool->notempty);
    pthread_cond_destroy(&pool->notfull);
}
```']

