#include <iostream>
#include <list>

void insertAfter(std::list<int>& myList, int key, int newVal) {
    auto it = myList.begin();
    while (it != myList.end() && *(it++) != key); // find the first occurrence of key

    if (it == myList.end()) {
        myList.push_back(newVal);
    } else {
        auto next = it;
        ++next;
        myList.insert(next, newVal);
    }
}
