public List<XmlElement> GetElementsByNameWithAttribute(XmlDocument document, string name, string attributeName, string attributeValue)
{
    var nodes = document.SelectNodes($"/{name}[@{attributeName}='{attributeValue}']");

    if (nodes == null || nodes.Count == 0)
    {
        throw new Exception($"No elements with name '{name}' and attribute '{attributeName}' value '{attributeValue}' were found.");
    }

    var result = nodes.Cast<XmlElement>().ToList();

    if (result.Count > 1)
    {
        // Sort the list based on a specified sorting attribute, if present.
        var sortingAttribute = document.SelectSingleNode($"/{name}[1]/@{SortingAttributeName}");
        string sortingAttributeValue;

        if (sortingAttribute != null)
        {
            sortingAttributeValue = sortingAttribute.Value;
        }
        else
        {
            return result; // Return an empty list when no sorting attribute is present.
        }

        var sortedElements = result.OrderByDescending(e => e.SelectSingleNode($"@{sortingAttributeValue}")).ToList();
        return sortedElements;
    }

    return new List<XmlElement> { nodes[0] };
}
