        $this->requestsPerMinute = $requestsPerMinute;
        $this->timeWindowLength = $timeWindowLength;
    }

    public function check() {
        $currentTime = time();
        $ipAddress = $_SERVER['REMOTE_ADDR'];

        if (!isset($this->requestCounts[$ipAddress])) {
            $this->requestCounts[$ipAddress] = 0;
        }

        $this->requestCounts[$ipAddress]++;

        if (($currentTime - $this->requestCounts[$ipAddress]['timestamp']) >= $this->timeWindowLength) {
            $this->requestCounts[$ipAddress] = [
                'requests' => 1,
                'timestamp' => $currentTime
            ];
        } else {
            $this->requestCounts[$ipAddress]['requests']++;
        }

        if ($this->requestCounts[$ipAddress]['requests'] > $this->requestsPerMinute) {
            sleep(60 - (time() % 60)); // Wait the remaining seconds of the minute to respect the rate limit
        }
    }
