public class StateLoader {
    private static final Logger LOGGER = Logger.getLogger(StateLoader.class.getName());
    private static final ConcurrentHashMap<Path, MoSTState> LOADED_STATES = new ConcurrentHashMap<>();

    public synchronized MoSTState loadStateFromFile(Path filePath) {
        if (LOADED_STATES.containsKey(filePath)) {
            return LOADED_states.get(filePath);
        }

        MoSTState loadedState = null;
        ObjectInputStream objectInput = null;

        try {
            objectInput = new ObjectInputStream(Files.newInputStream(filePath));
            Object object = objectInput.readObject();

            if (object instanceof MoSTState) {
                loadedState = (MoSTState) object;
                LOADED_STATES.put(filePath, loadedState);
                LOGGER.info("Successfully loaded state from file: " + filePath);

                // Add your verification code here to check the integrity of the loaded object before returning it.
            } else {
                LOGGER.severe("Failed to load state from file: " + filePath + ". Incorrect object type.");
            }
        } catch (IOException | ClassNotFoundException e) {
            LOGGER.severe("Failed to load state from file: " + filePath, e);
        } finally {
            if (objectInput != null) {
                try {
                    objectInput.close();
                } catch (IOException e) {
                    LOGGER.warning("Error while closing ObjectInputStream.");
                }
            }
        }

        return loadedState;
    }
}
