const { default: Blueslip } = require('blueslip');
const chalk = require('chalk');
const { promises: fs } = require('fs');
const { timeout } = require('stream');

class TestRunner {
  constructor() {
    this.mock = new Blueslip();
  }

  async runModuleTests(moduleName, testFunction) {
    try {
      const module = await fs.promises.require(moduleName);

      if (!testFunction || !testFunction.length || !(typeof testFunction === 'function' && typeof testFunction().then === 'function')) {
        console.warn(`Invalid or missing test function for ${chalk.bold(moduleName)}`);
        return { success: false, failedTests: [], timeouts: [] };
      }

      const tests = Object.keys(module).filter(key => key.startsWith('test'));

      let results = { success: true, failedTests: [], timeouts: [] };

      for (const testName of tests) {
        console.log(`Testing ${chalk.bold(moduleName)} > ${chalk.underline(testName)}`);
        const startTime = Date.now();
        this.mock.reset();

        try {
          await testFunction().catch((error) => {
            results.failedTests.push({ name: testName, error });
            console.log(`${chalk.red(`Test ${testName} failed:`)}`);
            console.error(error);
          });
        } catch (error) {
          console.warn(`Unexpected error while running test ${testName}`);
          console.error(error);
        } finally {
          const executionTime = Date.now() - startTime;
          if (executionTime > 5000) {
            results.timeouts.push({ name: testName, timeout: true });
            console.warn(`${chalk.yellow(`Test ${testName} timed out`)}`);
          }
        }
      }

      return results;
    } catch (error) {
      console.error(`Error while loading module ${chalk.bold(moduleName)}:`);
      console.error(error);
      return { success: false, failedTests: [], timeouts: [] };
    }
  }
}

module.exports = TestRunner;
