const axios = require('axios');
const _ = require('lodash');
const requestCache = new Map(); // Cache for text content
const stopWords = ['a', 'an', 'the', 'and', 'of'];
const oldTestamentBooks = [
  "Genesis",
  "Exodus",
  "Leviticus",
  "Numbers",
  "Deuteronomy",
  "Joshua",
  "Judges",
  "Ruth",
  "1 Samuel",
