function insertCodeSnippets(codeSnippets, containerId) {
    const container = document.getElementById(containerId);
    const errors = [];

    for (const snippet of codeSnippets) {
        try {
            const parser = new DOMParser();
            const html = parser.parseFromString(snippet, 'text/html');

            if (!html.body.innerHTML.match(/<!--.*-->/g)) {
                container.appendChild(html);
                continue;
            }
        } catch (e) {
            errors.push(`Error in snippet: ${snippet}\n${e}`);
            continue;
        }

        try {
            const valid = Ace.edit("code-container").getSession().checkMode(html.body.innerHTML, 'javascript');
            if (valid) {
                container.appendChild(html.body);
            } else {
                errors.push(`Syntax error in snippet: ${snippet}`);
            }
        } catch (e) {
            errors.push(`Error in snippet: ${snippet}\n${e}`);
        }
    }

    return !errors.length;
}
