async function invalidFormFieldsReport() {
  const formFields = Array.from(document.forms).reduce((acc, form) => [...acc, ...Array.from(form.elements)], []);
  const validationRulesCache = new Map();

  async function validateField(field) {
    if (!validationRulesCache.has(field.name)) {
      const response = await fetch(`/api/forms/${field.form.name}/fields/${field.name}/rules`);
      validationRulesCache.set(field.name, await response.json());
    }

    let isValid = true;
    for (const rule of validationRulesCache.get(field.name)) {
      switch (rule.type) {
        case 'required':
          isValid = field.value.length > 0;
          break;
        // Add other types as needed (e.g., pattern, minLength, maxLength, etc.)
        default:
          throw new Error(`Unsupported validation rule type: ${rule.type}`);
      }
    }

    field.isValid = isValid;
    if (!field.isValid && !field.errorMessage) {
      field.errorMessage = 'This field is required'; // Default error message for required fields
    }
  }

  async function constructReport() {
    await Promise.all(formFields.map(validateField));
    return formFields.filter(field => !field.isValid).map(field => ({ label: field.label, name: field.name, errorMessage: field.errorMessage }));
  }

  const report = constructReport();

  // Update the report container whenever a field's state changes (value or isValid)
  formFields.forEach((field) => {
    field.addEventListener('input', async () => {
      await validateField(field);
      requestUpdate(reportContainer, constructReport());
    });

    field.addEventListener('change', async () => {
      await validateField(field);
      requestUpdate(reportContainer, constructReport());
    });
  });
}
```

