import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class NIOConnectionHandler {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final Selector selector;
    private final AtomicInteger connectionCount = new AtomicInteger(0);
    private static final int BUFFER_SIZE = 1024;

    public NIOConnectionHandler(int port) throws IOException {
       Selector selector = Selector.open();
        ServerSocketChannel server = ServerSocketChannel.open();
        server.socket().bind(new InetSocketAddress(port));
        server.configureBlocking(false);
        server.register(selector, SelectionKey.OP_ACCEPT);
    }

    public void handleConnectionRequests() throws IOException {
        while (!Thread.currentThread().isInterrupted()) {
            selector.select();
            iterator().forEachRemaining(key -> handleKey(key));
        }
    }

    private Iterator<SelectionKey> iterator() {
        return selector.selectedKeys().iterator();
    }

    private void handleKey(SelectionKey key) throws IOException {
        if (key.isAcceptable()) {
            acceptConnection(key);
        } else if (key.isReadable()) {
            readDataFromClient(key);
        }
    }

    private void acceptConnection(SelectionKey key) throws IOException {
        ServerSocketChannel server = (ServerSocketChannel) key.channel();
        SocketChannel socketChannel = server.accept();
        connectionCount.incrementAndGet();
        socketChannel.configureBlocking(false);
        socketChannel.register(selector, SelectionKey.OP_READ);
    }

    private void readDataFromClient(SelectionKey key) throws IOException {
        SocketChannel client = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(BUFFER_SIZE);
        int bytesRead = client.read(buffer);
        if (bytesRead > 0) {
            buffer.flip();
            while (buffer.hasRemaining()) {
                client.write(buffer);
            }
            buffer.clear();
        } else {
            key.cancel();
            connectionCount.decrementAndGet();
            client.close();
        }
    }
}
