Then, create the custom configuration struct and HTTP client function:

```rust
use reqwest::Client;
use reqwest::header::{HeaderMap, HeaderValue};
use std::collections::HashMap;
use std::sync::Arc;
use std::sync::Mutex;
use tokio::task::JoinHandle;
use tokio::runtime::Runtime;

type RequestBuilder = reqwest::blocking::RequestBuilder;

struct Config {
    user_agent: HeaderValue,
    max_redirects: u16,
    timeout: reqwest::Duration,
    enable_cert_validation: bool,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            user_agent: HeaderValue::from_str("MyUserAgent/1.0"),
            max_redirects: 5,
            timeout: reqwest::Duration::new(30, 0),
            enable_cert_validation: true,
        }
    }
}

struct HttpClient {
    client: Arc<Mutex<Client>>,
    runtime: Runtime,
}

impl HttpClient {
    async fn new(config: Config) -> Self {
        let client = Arc::new(Mutex::new(Client::builder()
            .user_agent(config.user_agent)
            .max_redirects(config.max_redirects)
            .timeout(config.timeout)
            .dangerously_disable_http2_if_possible()
            .build()));
        let runtime = Runtime::new().expect("Failed to create Tokio runtime");
        Self { client, runtime }
    }

    async fn request(&self, url: &str, method: reqwest::Method, headers: HashMap<&'static str, String>) -> Result<RequestBuilder, Box<dyn std::error::Error>> {
        let mut client = self.client.lock().await;
        if !self.config.enable_cert_validation {
            client.set_ssl(reqwest::Client::get_native_tls_config().unwrap().into_builder().build()?);
        }
        let builder = (client.request(method, url)
                      .headers(HeaderMap::from_iter(headers)))
            .timeout(self.config.timeout);
        Ok(builder)
    }
}
```

You can now use the `HttpClient` struct to make requests and utilize its functionality as needed. The code provided above does not include retry logic or error handling, but you could easily expand it according to your requirements.']

