```rust
use std::process::{Command, Stdio};
use std::time::{Duration, SystemTime};
use std::os::unix::prelude::ResourceId;
use syscall::{getrlimit64, rlimit};

fn get_resident_set_size() -> ResourceId {
    let mut rlim: rlimit = unsafe { std::mem::zeroed() };
    unsafe {
        if getrlimit64(-1, &mut rlim) == 0 {
            rlim.rlim_cur
        } else {
            0
        }
    }
}

fn compile_and_measure(log: &Log) -> Result<(), CompileError> {
    let start_time = SystemTime::now();
    let start_rss = get_resident_set_size();
    Command::new("rustc")
        .stdio(Stdio::inherit())
        .spawn()?
        .wait()?;
    let end_time = SystemTime::now();
    let end_rss = get_resident_set_size();

    log.info(&format!("Compilation time: {:?}", end_time - start_time));
    log.info(&format!("Resident Set Size (before): {}", start_rss));
    log.info(&format!("Resident Set Size (after): {}", end_rss));

    Ok(())
}
```

2. Ice Hook with panic handling (`ice_hook.rs`)

```rust
use std::sync::{Arc, Mutex};
use std::sync::mpsc::{channel, Sender};
use std::thread;
use std::panicking::panic_anyhow;

struct IceHook {
    sender: Arc<Mutex<Sender<Box<dyn std::error::Error + Send>>>>,
}

impl IceHook {
    fn new(sender: Sender<Box<dyn std::error::Error + Send>>) -> Self {
        IceHook {
            sender: Arc::new(Mutex::new(sender)),
        }
    }

    fn catch_panic(&self, pt: &mut std::panicking::PanicInfo<'_>) {
        let mut sender = self.sender.lock().unwrap();
        *sender.send(Box::new(pt)).ok();
    }
}
```

