['```java
import java.io.*;
import java.security.*;
import java.nio.file.*;
import org.apache.tinkerpop.gremlin.process.graphtraversal.*;
import org.apache.tinkerpop.gremlin.structure.Vertex;
import org.apache.tinkerpop.gremlin.process.traverser.dsl.graph.__;
import org.json.*;

public static void processOAuthRequest(Traversal traversal, String requestBody) {
    JSONObject json = new JSONObject(requestBody);
    Path directoryPath = Paths.get(json.getString("directory_path"));
    try {
        PKCS12KeyStore keyStore = PKCS12KeyStore.getInstance(new File(directoryPath.resolve("keystore.p12").toFile()));
        keyStore.load(new FileInputStream(directoryPath.resolve("keystore.p12").toFile()), "password".toCharArray());
        PrivateKey privateKey = keyStore.getKey("alias", "password".toCharArray());
        Certificate certificate = privateKey.getCertificates()[0];

        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        CertificateFactory cf = CertificateFactory.getInstance("X.509");
        OutputStream os = outputStream;
        cf.generateCertificate(certificate, os);
        byte[] pemCertificate = Base64.getEncoder().encode(outputStream.toByteArray());

        Vertex vertex = traversal.addV("Certificate")
                .property("private_key", privateKey.getEncoded())
                .property("certificate", Base64.getEncoder().encodeToString(pemCertificate))
                .next();

        traversal.V().limit(10)
                .union(__.outE(), __.inE())
                .where(has("type", eq("existingVertexType")))
                .forEach(__.addE("trust").property("strength", random()));
    } catch (Exception e) {
        // Handle exceptions
    }
}
```
This code assumes the use of Apache TinkerPop graph traversal library for managing the graph database and Java's built-in libraries for handling OAuth request, file operations, and working with certificates. The code extracts the directory path from an incoming OAuth request, reads the private key and certificate files from the provided directory, combines them into a single PEM file, adds the certificate as a vertex to the graph database, and creates edges between the newly created vertex and existing vertices in the graph.']

