#include <functional>

const int max_transactions = 10000; //max concurrent transactions
const int window_size = 5; //time window for transaction filtering
const double weight_penalty = 0.8; //weight penalty multiplier
const unsigned long long upper_limit = 1000000000; //upper limit for weights

std::vector<std::thread> threads;
std::queue<Transaction> transactions;
std::priority_queue<Transaction, std::vector<Transaction>, std::greater<Transaction>> priority_queue;
std::deque<TimeLogEntry> log(window_size); //log buffer with FIFO order
boost::circular_buffer<TimeLogEntry> circular_log(50000); //circular buffer for long-term storage
std::atomic<int> valid_transactions{ 0 }, total_weight{ 0 }, max_weight{ std::numeric_limits<decltype(max_weight)>::min() };

struct Transaction {
    int id;
    double weight;
    std::chrono::steady_clock::time_point timestamp;
};

struct TimeLogEntry {
    std::chrono::steady_clock::time_point time;
    bool accepted; //accepted or rejected
};

void log_transaction(const Transaction& transaction, const bool accepted) {
    TimeLogEntry entry{ transaction.timestamp, accepted };
    log.push_back(entry);
    if (log.size() > window_size)
        log.pop_front();
}

bool is_valid(const Transaction& transaction) {
    auto now = std::chrono::steady_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(now - transaction.timestamp).count();
    return elapsed <= 10 && transactions.size() < max_transactions;
}

void process_transaction(Transaction transaction) {
    if (transaction.weight > upper_limit || transaction.id < 0) {
        std::cerr << "Error: invalid input (ID or weight)" << std::endl;
        return;
    }

    if (!is_valid(transaction))
        return;

    if (transactions.size() >= max_transactions) {
        circular_log.push_back(TimeLogEntry{ transaction.timestamp, false }); //log dropped transaction
        return;
    }

    transactions.push(transaction);

    auto total_in_window = transactions.size();
    if (total_in_window > window_size)
        total_in_window -= window_size;

    if (total_in_window >= max_transactions / 5) { //penalize frequent transactions
        transaction.weight *= weight_penalty;
    }

    std::lock_guard<std::mutex> lock(priority_queue_mutex); //critical section for priority queue manipulation
    priority_queue.push(transaction);

    valid_transactions++;
    total_weight += transaction.weight;
    if (total_weight > max_weight)
        max_weight = total_weight;

    log_transaction(transaction, true); //log accepted transaction
}

double highest_weighted_sum() { return max_weight; }
int highest_weighted_id() { //TODO: Implement finding the corresponding ID
    return -1;
}
bool transaction_status() { //TODO: Implement checking if the most recent transaction was accepted or rejected
    return false;
}

void run() {
    while (true) {
        Transaction transaction;
        std::cin >> transaction.id >> transaction.weight;
        process_transaction(transaction);
    }
}

int main() {
    for (int i = 0; i < max_transactions; ++i)
        threads.push_back(std::thread(run));

    for (auto& thread : threads)
        thread.join();

    std::cout << "Highest weighted sum: " << highest_weighted_sum() << std::endl;
    std::cout << "Highest weighted ID: " << highest_weighted_id() << std::endl;
    std::cout << "Transaction status: " << transaction_status() << std::endl;

    return 0;
}
