["```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>

struct Attack {
    int id;
    std::chrono::steady_clock::duration cooldown;
};

class Character {
public:
    Character(const std::vector<Attack>& availableAttacks) {
        for (const auto& attack : availableAttacks) {
            _attacks.insert({attack.id, attack});
        }
        _nextAttack = _availableAttacks.begin();
        _cooldown = std::chrono::steady_clock::now() + _nextAttack->second;
    }

    void performAttack() {
        std::unique_lock<std::mutex> lock(_mutex);
        _condition.wait_until(lock, _cooldown, std::chrono::steady_clock::now());
        auto it = _nextAttack;
        if (it != _availableAttacks.end()) {
            _nextAttack++;
            if (_nextAttack == _availableAttacks.end()) {
                _nextAttack = _availableAttacks.begin();
            }
            _cooldown = std::chrono::steady_clock::now() + it->second;
        }
        std::cout << it->id << '\n';
    }

    void updateAvailableAttacks(const std::vector<Attack>& newAttacks) {
        std::unique_lock<std::mutex> lock(_mutex);
        _availableAttacks.clear();
        for (const auto& attack : newAttacks) {
            _availableAttacks.insert({attack.id, attack});
        }
        if (_nextAttack != _availableAttacks.end()) {
            if (_nextAttack->second > _cooldown) {
                _nextAttack = std::prev(_availableAttacks.end());
            }
            _cooldown = std::chrono::steady_clock::now() + _nextAttack->second;
        }
    }

private:
    std::vector<Attack> _availableAttacks;
    std::vector<Attack>::iterator _nextAttack;
    std::chrono::steady_clock::time_point _cooldown;
    std::mutex _mutex;
    std::condition_variable _condition;
};
```

In this example, the `Character` class handles the given requirements:
- The constructor initializes with a list of available attacks and sets the initial cooldown timer.
- When the `performAttack()` function is called, it checks if the cooldown timer has elapsed, selects the next attack, and updates the cooldown timer. If there are no more attacks available, it will cycle back to the beginning of the list.
- The `updateAvailableAttacks()` function allows for runtime changes to the list of available attacks, gracefully handling these updates without losing state or causing unintended behavior.
- In a multi-threaded environment, the use of a mutex and condition variable helps handle potential race conditions when multiple characters are attacking simultaneously.
- The implementation supports efficient performance even under high-load scenarios as it dynamically selects attacks based on available options.
- Error handling for unexpected states is not explicitly included in this example but can be added depending on the specific requirements of the game system.
- Resource management to prevent memory leaks or excessive garbage collection is also not explicitly included but good coding practices should be followed, such as deleting unnecessary objects and using smart pointers when appropriate."]

['```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public class CustomRandom
{
    private readonly Random _random;
    private double _min, _max;

    public CustomRandom(double min, double max)
    {
        if (min > max)
            throw new ArgumentException("Minimum value should be less than or equal to maximum value.");

        _min = min;
        _max = max;
        _random = new Random(ThreadId);
    }

    public int NextInt(bool inclusiveMin = true, bool inclusiveMax = true)
    {
        var range = (inclusiveMax ? _max + 1 : _max) - (inclusiveMin ? _min : _min + 1);
        return (int)_random.NextDouble() * range + (inclusiveMin ? _min : _min + 1);
    }

    public float NextFloat(bool inclusiveMin = true, bool inclusiveMax = true)
    {
        var range = (inclusiveMax ? _max + 1f : _max) - (inclusiveMin ? _min : _min + 1f);
        return (float)_random.NextDouble() * range + (inclusiveMin ? _min : _min + 1f);
    }

    public T Next<T>(Func<T> generator, int count = 1) where T : new()
    {
        var result = new List<T>();

        for (var i = 0; i < count; i++)
        {
            T value = generator();
            if (!result.Contains(value))
                result.Add(value);
            else
                i--;
        }

        return new T[] { result[RandomNext(_random)].ToArray() };
    }

    public override string ToString() => $"CustomRandom({_min}, {_max})";

    public bool NextBool(double percentage)
    {
        if (percentage < 0 || percentage > 100)
            throw new ArgumentOutOfRangeException(nameof(percentage), "Percentage should be between 0 and 100.");

        return _random.NextDouble() * 100 <= percentage;
    }
}
