int loadResourceBundle(const char *filename, ResourceItem **bundle, int *errorCode) {
    FILE *file = fopen(filename, "r");
    if (!file) return 1; // File not found or I/O error

    struct stat fileStat;
    if (stat(filename, &fileStat) == -1) {
        fclose(file);
        return 1; // Stat error
    }

    size_t bufferSize = fileStat.st_size + 1; // Adding one for null terminator
    char *buffer = malloc(bufferSize);
    if (!buffer) {
        fclose(file);
        return 1; // Memory allocation error
    }

    size_t bytesRead = fread(buffer, sizeof(char), bufferSize - 1, file);
    if (bytesRead < bufferSize - 1) {
        free(buffer);
        fclose(file);
        return 1; // Truncated read
    }
    buffer[bytesRead] = '\0';
    fclose(file);

    ResourceItem *item = NULL;
    ResourceItem **current = bundle;
    char *token = strtok(buffer, "\n");
    while (token) {
        item = malloc(sizeof(ResourceItem));
        if (!item) {
            free(buffer);
            while (*current) free(*current++);
            return 1; // Memory allocation error
        }
        size_t keyLen = strlen(token);
        item->key = malloc(keyLen + 2); // Adding one for colon and null terminator
        if (!item->key) {
            free(item);
            free(buffer);
            while (*current) free(*current++);
            return 1; // Memory allocation error
        }
        strncpy(item->key, token, keyLen + 1);
        item->key[keyLen++] = ':';
        item->key[keyLen] = '\0';
        token = strtok(NULL, "\n");
        if (!token) {
            free(item->key);
            free(item);
            while (*current) free(*current++);
            free(buffer);
            return 2; // Invalid format error
        }
        size_t valueLen = strlen(token);
        item->value = malloc(valueLen + 1);
        if (!item->value) {
            free(item->key);
            free(item);
            while (*current) free(*current++);
            free(buffer);
            return 1; // Memory allocation error
        }
        strncpy(item->value, token, valueLen + 1);
        *current = item;
        current++;
        token = strtok(NULL, "\n");
    }

    *errorCode = 0;
    return 0; // Success
}

// Implement cache here...

