char* safe_append_slash(const char *str, size_t limit, char *buf) {
    if (!str || !buf)
        return NULL;

    size_t str_len = strlen(str);

    // Check if the string length exceeds the specified limit or buffer is not large enough.
    if (str_len > limit || (str_len + 2 > bufsize_t(buf + strlen(buf))))
        return NULL;

    // Use memcpy instead of strcpy to avoid unnecessary memory allocation and copying.
    memcpy(buf, str, str_len);
    buf[str_len] = '/';
    buf[str_len + 1] = '\0';

    return buf;
}

