['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Line {
    size_t num_fields;
    size_t capacity;
    double *fields;
} Line;

Line* create_line() {
    Line *new_line = malloc(sizeof(Line));
    new_line->num_fields = 0;
    new_line->capacity = 3;
    new_line->fields = calloc(new_line->capacity, sizeof(double));
    return new_line;
}

void add_field(Line *line, double value) {
    if (line->num_fields >= line->capacity) {
        line->capacity *= 2;
        line->fields = realloc(line->fields, line->capacity * sizeof(double));
    }

    line->fields[line->num_fields] = value;
    line->num_fields++;
}

void compute_average(Line *line, size_t start, double *avg) {
    size_t sum = 0;
    for (size_t i = start; i < line->num_fields; ++i) {
        sum += line->fields[i];
    }

    *avg = (double)(sum) / (line->num_fields - start);
}

int process_file(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    Line *current_line = create_line();
    size_t line_count = 0;

    char buffer[4096];
    while (fgets(buffer, sizeof(buffer), fp)) {
        Line *new_line = create_line();
        size_t field_count = 0;

        char *token = strtok(buffer, " ");
        while (token) {
            if (field_count >= 3) break;
            add_field(new_line, atof(token));
            field_count++;
            token = strtok(NULL, " ");
        }

        // Check if the line has at least three numbers
        if (field_count < 3) {
            fprintf(stderr, "Error: Invalid number of fields in line %zu\n", line_count);
            free(new_line->fields);
            free(new_line);
            continue;
        }

        double avg;
        compute_average(current_line, 3, &avg);
        add_field(new_line, avg);
        line_count++;

        Line *temp = current_line;
        current_line = new_line;
        free(temp->fields);
        free(temp);
    }

    fclose(fp);

    // Process the final line
    double avg;
    compute_average(current_line, 3, &avg);
    printf("Average of last three fields in line %zu: %.6f\n", line_count, avg);

    free(current_line->fields);
    free(current_line);
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [input file]\n", argv[0]);
        return 1;
    }

    return process_file(argv[1]);
}
