typedef struct {
    unsigned short bits_per_sample;
    unsigned int sample_per_pixel;
    unsigned char* extra_samples;
    unsigned int num_extra_samples;
    EVP_CIPHER_CTX *cipher_ctx;
} TiffInfo;

TiffInfo parse_tiff(char *filename, EVP_CIPHER_KEY *key) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error: Could not open file %s\n", filename);
        exit(1);
    }

    TiffInfo info;
    int bits_per_sample = 0;
    unsigned int sample_per_pixel = 0;
    unsigned char photometric = 0;
    unsigned short samples_per_line = 0;
    unsigned int extra_samples_count = 0;
    unsigned char **extra_samples_buf;

    // Parse TIFF information
    while (TIFFReadDirectory(tif) == 1) {
        if (TIFFGetField(tif, TIFFTagSAMPLESPERPIXEL, &sample_per_pixel) == 1 &&
            sample_per_pixel > 0) break;
    }

    while (TIFFReadDirectory(tif)) {
        switch (TIFFGetField(tif, TIFFTagBITSPERSAMPLE, &bits_per_sample)) {
            case 1:
                if (!extra_samples_buf) {
                    extra_samples_count = samples_per_line - sample_per_pixel;
                    extra_samples_buf = malloc(sizeof(unsigned char*) * extra_samples_count);
                }
                TIFFReadSample(tif, 0, extra_samples_count + sample_per_pixel, &extra_samples_buf[extra_samples_count]);
                ++extra_samples_count;
                break;
            case -1:
                fprintf(stderr, "Error: Missing tag %d\n", TIFFTagBITSPERSAMPLE);
                exit(1);
        }
    }

    info.bits_per_sample = bits_per_sample;
    info.sample_per_pixel = sample_per_pixel;
    info.extra_samples = extra_samples_buf;
    info.num_extra_samples = extra_samples_count;

    // OpenSSL operations (if key is provided)
    if (key) {
        EVP_CIPHER_CTX *cipher_ctx = EVP_EncryptInit(EVP_aes_256_gcm(), key, NULL);
        info.cipher_ctx = cipher_ctx;
    }

    TIFFClose(tif);
    return info;
}
