#include <stdio.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <regex.h>
#include <stdlib.h>
#include <unistd.h>

// Maximum filename length
#define MAX_FILENAME_LENGTH 255

// Function to generate a random number using arc4random
void rand_number(char* buffer, size_t len) {
    arc4random_buf(buffer, len);
}

// Function to validate the filename according to the operating system's requirements
int is_valid_filename(const char* filename) {
    // Regex pattern for validating filenames on Unix-like systems
    const char* pattern = "^[a-zA-Z0-9._-]{1," MAX_FILENAME_LENGTH "}$";
    regmatch_t match;
    regex_t re;

    // Compile the regex pattern
    regcomp(&re, pattern, REG_EXTENDED | REG_NEWLINE);

    // Check if the filename matches the pattern and return 1 on success or 0 on failure
    if (regexec(&re, filename, 1, &match, 0) == 0) {
        return 1;
    } else {
        return 0;
    }

    // Cleanup after using regex functions
    regfree(&re);
}

// Function to modify the file extension and add a timestamp and random number
void rename_extension(const char* filename, char* new_filename) {
    size_t len = strlen(filename);

    // Find the last dot (.) to get the current file extension
    for (size_t i = len; i > 0; --i) {
        if (filename[i] == '.') {
            len -= i;
            break;
        }
    }

    // Allocate memory for the new filename and copy the filename without the extension
    size_t required_size = MAX_FILENAME_LENGTH - len - 9; // 9 is the length of the timestamp, random number, and file type
    if (required_size > MAX_FILENAME_LENGTH) {
        fprintf(stderr, "Error: New filename exceeds maximum length.\n");
        exit(EXIT_FAILURE);
    }
    char* new_filename_without_ext = malloc(required_size + 1);
    memcpy(new_filename_without_ext, filename, len);
    new_filename_without_ext[len] = '\0';

    // Combine the timestamp, random number, and file type to form the new extension
    char timestamp[24];
    char rand_number[8];
    char file_type[] = ".txt";
    time_t rawtime;
    struct tm* timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y%m%dT%H%M%S", timeinfo);
    rand_number(rand_number, 8);

    // Combine the timestamp, random number, and file type to form the new extension
    size_t new_extension_length = strlen(timestamp) + strlen(rand_number) + strlen(file_type);
    char* new_extension = malloc(new_extension_length + 1);
    snprintf(new_extension, sizeof(new_extension), "%s%s%s", timestamp, rand_number, file_type);

    // Concatenate the new filename without the extension and the new extension to form the new filename
    strcpy(new_filename, new_filename_without_ext);
    strcat(new_filename, new_extension);

    // Free the allocated memory
    free(new_filename_without_ext);
    free(new_extension);
}

// Main function to rename files based on the given task
int main(int argc, char** argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Validate and rename the file extension
    char new_filename[MAX_FILENAME_LENGTH];
    if (is_valid_filename(argv[1]) == 0) {
        fprintf(stderr, "Error: Invalid filename.\n");
        return EXIT_FAILURE;
    }
    rename_extension(argv[1], new_filename);

    // Rename the file using the new filename
    if (rename(argv[1], new_filename) != 0) {
        perror("Error: Failed to rename the file.");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```']

