using namespace std;
using namespace rapidjson;
using namespace tinyxml2;

const char *template_file = "template.html";
const char *output_file = "report.html";
const char *xsd_file = "schema.xsd";

int generate_report(Document &doc, const char *user_input, const char *output_file) {
    stringstream ss;
    Writer<StringBuffer> writer(ss);
    doc.Accept(writer);

    ofstream outfile(output_file);
    if (!outfile) {
        cerr << "Error: Could not open output file" << endl;
        return 1;
    }

    outfile << ss.str();
    outfile.close();

    XMLSchema schema;
    schema.LoadFile(xsd_file);
    XMLDocument doc2;
    stringstream ss2;
    MemoryBuffer buffer(ss2);

    if (!XMLReaderSettings::UpgradeDefaults()) {
        XMLReaderSettings::SetSchemas(schema);
    }

    XMLReader reader;
    reader.Reset();
    reader.Load(doc.GetString());

    while (reader.ReadNextElement()) {
        if (reader.Failed()) {
            cerr << "Error: Validation failed" << endl;
            continue;
        }

        if (!schema.Validate(reader)) {
            cerr << "Validation error: " << reader.GetError() << endl;
            continue;
        }
    }

    return 0;
}

int main(int argc, char **argv) {
    const char *user_input = nullptr;
    const char *output_file = output_file;
    const char *xsd_file = xsd_file;

    static struct option long_options[] = {
        {"template", required_argument, nullptr, 't'},
        {"output", required_argument, nullptr, 'o'},
        {"xsd", required_argument, nullptr, 'x'},
        {nullptr}
    };

    int option_index;
    while (true) {
        int c = getopt_long(argc, argv, "t:o:x:", long_options, &option_index);

        if (c == -1) break;

        switch (c) {
            case 't':
                template_file = optarg;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'x':
                xsd_file = optarg;
                break;
        }
    }

    if (optind >= argc) {
        cerr << "Error: Missing user input string" << endl;
        return 1;
    }

    user_input = argv[optind++];

    Document doc;
    FileReadStream fs(template_file, IOMode::Read);
    if (!fs.IsOpen()) {
        cerr << "Error: Could not open template file" << endl;
        return 1;
    }

    I streaming_input = &fs;
    doc.ParseStream(streaming_input);

    return generate_report(doc, user_input, output_file);
}
```
