    private readonly ILogger<WebAppCreator> _logger;

    public WebAppCreator(IWebHostBuilder hostBuilder, ILogger<WebAppCreator> logger)
    {
        _hostBuilder = hostBuilder;
        _logger = logger;
    }

    public async Task<IWebHost>? AddWebApplicationAsync(string directoryPath, string siteName, bool isPublicAccess)
    {
        if (!Directory.Exists(directoryPath))
            return null;

        var webConfigFile = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigFile))
            return null;

        var mutex = new Mutex();
        if (!mutex.WaitOne(0, false)) // If the mutex is owned by another instance, it will return false and do nothing.
            return null;

        try
        {
            var host = _hostBuilder
                .UseContentRoot(directoryPath)
                .UseStartup<Startup>()
                .UseUrls($"http://localhost:5000/{siteName}")
                .ConfigureLogging((hostingContext, loggingBuilder) =>
                {
                    loggingBuilder.AddConsole();
                    loggingBuilder.SetMinimumLevel(LogLevel.Debug);
                })
                .Build();

            if (isPublicAccess)
                host.Run(); // For publicly accessible apps, start the web server and return immediately.
            else
                await host.StartAsync(); // For non-publicly accessible apps, start the web server asynchronously.

            _logger.LogInformation($"Added web application '{siteName}' in directory '{directoryPath}'.");

            // Handle network connectivity issues here by using try-catch blocks for external dependencies and logging any errors.

            return host;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to add web application '{siteName}' in directory '{directoryPath}'.");
        }
        finally
        {
            mutex.ReleaseMutex(); // Always release the mutex to avoid deadlocks.
        }

        return null;
    }
}
