import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import java.text.*;
import java.util.*;
import javax.xml.bind.DatatypeConverter;

public class CommandExecutor {
    private static final String LOG_DIR = "logs";
    private static final int TIMEOUT_MS = 10000;
    private static ExecutorService executor = Executors.newCachedThreadPool();

    public void executeCommand(String command, File tempFile) throws IOException, InterruptedException {
        Path logPath = Paths.get(LOG_DIR, "execution.log");
        if (!Files.exists(logPath)) {
            Files.createDirectory(Paths.get(LOG_DIR));
        }
        PrintWriter logWriter = new PrintWriter(new FileWriter(logPath.toFile(), true));

        // Check if temporary directory exists, delete the file only if it does
        Path tempDirPath = Paths.get(System.getProperty("user.dir"), "temp");
        if (Files.exists(tempDirPath)) {
            Files.deleteIfExists(tempFile.toPath());
        } else {
            logWriter.println("Error: Temporary directory does not exist.");
            throw new IOException("Temporary directory does not exist.");
        }

        // Execute command in a separate thread and process I/O using another thread
        final ProcessBuilder pb = new ProcessBuilder(command.split(" "));
        Future<Integer> execFuture = executor.submit(() -> {
            try (Process p = pb.start(); InputStream err = p.getErrorStream(), out = p.getInputStream()) {
                Thread ioThread = new Thread(() -> {
                    try (BufferedReader reader = new BufferedReader(new InputStreamReader(out))) {
                        String line;
                        while ((line = reader.readLine()) != null) {
                            logWriter.println(line);
                        }
                    } catch (IOException e) {
                        logWriter.println("Error reading output stream: " + e.getMessage());
                    }
                });
                ioThread.start();

                // Timeout for command execution and I/O processing
                long start = System.currentTimeMillis();
                while (!p.exitValue() != 0 && (System.currentTimeMillis() - start) < TIMEOUT_MS) {
                    Thread.sleep(100);
                }

                if (p.exitValue() == 0) {
                    logWriter.println("Command executed successfully.");
                } else {
                    logWriter.println("Command execution failed with exit code: " + p.exitValue());
                }
            } catch (IOException | InterruptedException e) {
                logWriter.println("Error executing command: " + e.getMessage());
            } finally {
                // Cleanup resources and log any errors during cleanup
                try {
                    pb.destroy();
                } catch (IOException e) {
                    logWriter.println("Error destroying process builder: " + e.getMessage());
                }
                executor.shutdownNow();
            }
        });

        execFuture.get();
        logWriter.close();
    }
}
```

This program creates a `CommandExecutor` class that handles command execution using the specified requirements. The main logic is in the `executeCommand` method, which takes a command string and a file as arguments. It checks if the temporary directory exists, deletes the specified file if it does, executes the command using separate threads for command execution and I/O processing, handles timeouts, logs all operations and errors to a file named `execution.log`, ensures proper resource cleanup after each execution, validates command arguments, and gracefully handles failures.']

