typedef struct Session {
    const char* config;
    void* network_connection;
    void (*auth_callback)(char*, char*, char*);
    pthread_mutex_t mutex;
} Session;

const int SESSION_INVALID = -1;
const int SESSION_OK = 0;

int is_session_valid(Session* session) {
    if (!session || !session->config || strlen(session->config) == 0 || strchr(session->config, '\0') != session->config) {
        return SESSION_INVALID_CONFIG;
    }

    if (session->network_connection == NULL) {
        return SESSION_NULL_NETWORK_CONNECTION;
    }

    if (!strcmp(((NetworkConnection*)session->network_connection)->title, "")) {
        return SESSION_INVALID_NETWORK_TITLE;
    }

    if (session->auth_callback == NULL) {
        return SESSION_NULL_AUTHENTICATION_CALLBACK;
    }

    pthread_mutex_lock(&session->mutex);
    if (!strcmp(((NetworkConnection*)session->network_connection)->title, "") || session->auth_callback == NULL) {
        pthread_mutex_unlock(&session->mutex);
        return SESSION_RACE_CONDITION;
    }
    pthread_mutex_unlock(&session->mutex);

    return SESSION_OK;
}
