    if (!obj) return false;

    OAuth2TokenResponse token_response;
    token_response.access_token = json_object_get_string(obj, "access_token");
    token_response.expires_in = json_object_get_int(obj, "expires_in");
    token_response.token_type = json_object_get_string(obj, "token_type");
    token_response.refresh_token = json_object_get_string_ex(obj, "refresh_token", NULL);

    if (!token_response.access_token || !token_response.token_type) {
        json_object_put(obj);
        return false;
    }

    if (strcmp(token_response.token_type, "Bearer") != 0) {
        json_object_put(obj);
        return false;
    }

    if (token_response.expires_in <= 0 || token_response.refresh_token && strcmp(token_response.refresh_token, config_hash) != 0) {
        if (token_response.refresh_token) {
            printf("Warning: Refresh token does not match the expected hash.\n");
        }
        json_object_put(obj);
        return true; // The primary access token is valid, but the refresh token is problematic
    }

