using System;
using System.Data;
using System.IO.Compression;
using System.Linq;

public class DataProcessor
{
    public IDataReader ProcessByteArray(byte[] inputData, byte[] filterSequence1, byte[] filterSequence2)
    {
        if (inputData == null) return null;

        var filteredData = new List<Tuple<int, byte[]>>();
        var tempBytes = new List<byte>();
        int index = 0;

        while (index < inputData.Length)
        {
            var currentSequence = new byte[Math.Min(filterSequence1.Length, filterSequence2.Length)];
            Array.Copy(inputData, index, currentSequence, 0, Math.Min(filterSequence1.Length, filterSequence2.Length));

            if (currentSequence.SequenceEqual(filterSequence1) && currentSequence.SequenceEqual(filterSequence2))
            {
                index += filterSequence1.Length;
                continue;
            }

            tempBytes.AddRange(inputData.Skip(index).Take(Math.Min(filterSequence1.Length, inputData.Length - index)));
            index += tempBytes.Count;
            tempBytes.ToArray().CopyTo(currentSequence, filterSequence1.Length);

            filteredData.Add(new Tuple<int, byte[]>(index, currentSequence));
        }

        var compressedData = CompressBytes(tempBytes.ToArray());
        filteredData.Add(new Tuple<int, byte[]>(inputData.Length, compressedData));

        var dt = new DataTable();
        dt.Columns.Add("StartIndex", typeof(int));
        dt.Columns.Add("Data", typeof(byte[]));
        dt.Rows.AddRange(filteredData.Select((t, i) => new object[] { t.Item1, t.Item2 }).ToArray());

        var dataReader = dt.CreateDataReader();
        return dataReader;
    }

    private byte[] CompressBytes(byte[] input)
    {
        if (input == null || input.Length <= 100) return input;

        using (var ms = new MemoryStream())
        {
            using (var gs = new GZipStream(ms, CompressionMode.Compress))
                gs.Write(input, 0, input.Length);

            return ms.ToArray();
        }
    }
}
