using System;
using System.Text;
using System.Security.Cryptography;
using System.IdentityModel.Tokens.Jwt;
using System.Linq;
using Org.BouncyCastle.Crypto;
using Org.BouncyCastle.Crypto.Parameters;
using Org.BouncyCastle.OpenSsl;

namespace MyNameSpace {
    public class ProcessInput {
        private TripleDESCryptoServiceProvider CreateTripleDES(byte[] key, byte[] iv) {
            var tripleDes = new TripleDESCryptoServiceProvider();
            tripleDes.Key = key;
            tripleDes.IV = iv;
            return tripleDes;
        }

        public T DesDecrypt<T>(string input, out EVP_CIPHER cipher) {
            try {
                var jwtHandler = new JwtSecurityTokenHandler();
                var token = jwtHandler.ReadToken(input);
                if (token is not JwtSecurityToken jwt || !jwt.Header.Alg.Equals("HS256", StringComparison.OrdinalIgnoreCase))
                    throw new ArgumentException("Invalid OAuth2 access token response.");

                var encryptedMessage = Encoding.UTF8.GetString(Convert.FromBase64String(jwt.Claims.First(c => c.Type == "encrypted_message").Value));
                var keyBytes = jwt.Claims.First(c => c.Type == "key").Value.Split('.').Select(b => Convert.FromBase64String(b)).ToArray();
                var ivBytes = jwt.Claims.First(c => c.Type == "iv").Value.Split('.').Select(b => Convert.FromBase64String(b)).ToArray();
                using (var tripleDes = CreateTripleDES(keyBytes, ivBytes)) {
                    var desCryptoServiceProvider = new DESCryptoServiceProvider();
                    switch (jwt.Claims.First(c => c.Type == "mode").Value.ToLowerInvariant()) {
                        case "ecb": desCryptoServiceProvider = desCryptoServiceProvider.CreateDecryptor(tripleDes.Key, tripleDes.IV); break;
                        case "ede": desCryptoServiceProvider = new TripleDESCryptoServiceProvider().CreateDecryptor(tripleDes.Key, tripleDes.IV); break;
                        case "ede3": desCryptoServiceProvider = new TripleTripleDES().CreateDecryptor(tripleDes, tripleDes); break;
                        case "cfb": desCryptoServiceProvider = desCryptoServiceProvider.CreateDecryptor(tripleDes.Key, tripleDes.IV); break;
                    }

                    var decryptedMessage = new StringBuilder();
                    foreach (var block in encryptedMessage.GroupBy(c => c == '\0')) {
                        if (block.SkipLast(1).All(c => c != '\0')) continue;
                        decryptedMessage.Append(desCryptoServiceProvider.Decrypt(Convert.FromBase64String(block.First()), true));
                    }
                    return (T)Convert.ChangeType(decryptedMessage.ToString(), typeof(T));
                }
            } catch {
                cipher = new EVP_CIPHER(); // Placeholder for command line option processing
                return default;
            }
        }
    }
}
