using System;
using System.Security.Cryptography;
using System.Text;

public class StringHasher
{
    private const string AlgorithmName = "MD5";

    public byte[] GetHash(string input)
    {
        using (var md5 = MD5.Create())
        {
            var inputBytes = Encoding.UTF8.GetBytes(input);
            return md5.ComputeHash(inputBytes);
        }
    }

    public bool ValidateHash(string input, string hash)
    {
        byte[] computedHash = GetHash(input);
        StringBuilder sb = new StringBuilder();
        foreach (byte t in computedHash)
            sb.AppendFormat("{0:x2}", t);
        return string.Equals(sb.ToString(), hash, StringComparison.OrdinalIgnoreCase);
    }
}
```

