using System.Text;

public byte[] DecryptAES_CBC(byte[] ciphertext, byte[] key, byte[] iv, PaddingMode padding)
{
    try
    {
        var aes = Aes.Create();
        using (var msKey = new MemoryStream(key))
        {
            using (var msIV = new MemoryStream(iv))
            {
                aes.Key = msKey.ToArray();
                aes.IV = msIV.ToArray();
            }
        }
        aes.Padding = padding;
        using (var decryptor = aes.CreateDecryptor())
        {
            using (var msCipherText = new MemoryStream(ciphertext))
            {
                using (var cs = new CryptoStream(msCipherText, decryptor, CryptoStreamMode.Read))
                using (var msPlainText = new MemoryStream())
                {
                    cs.CopyTo(msPlainText);
                    return msPlainText.ToArray();
                }
            }
        }
    }
    catch (CryptographicException ex)
    {
        Console.WriteLine($"Error: {ex.Message}");
        return null;
    }
}
```
