public class MyCustomData
{
    public int Id { get; set; }
    public string Name { get; set; }
    // Add other properties as needed
}

public async Task<MyCustomData[]> DeserializeFromCompressedFileAsync(string filePath)
{
    var data = new List<MyCustomData>();
    using (var fileStream = File.OpenRead(filePath))
    {
        using (var archive = ArchiveFactory.Open(fileStream, true))
        {
            foreach (var entry in archive.Entries)
            {
                if (!entry.IsDirectory)
                {
                    await ProcessEntryAsync(entry, data);
                }
            }
        }
    }
    return data.ToArray();
}

private async Task ProcessEntryAsync(IInArchiveEntry entry, List<MyCustomData> data)
{
    using (var decompressionStream = entry.Open())
    {
        if (decompressionStream.Length > 0)
        {
            var jsonText = await new StreamReader(decompressionStream).ReadToEndAsync();
            data.AddJsonDeserialize<MyCustomData>(jsonText);
        }
    }
}
```

