class CustomUploader {
  constructor(baseUrl, libraryName) {
    this._baseUrl = baseUrl;
    this._libraryName = libraryName;

    if (!/^https?:\/\//.test(baseUrl)) {
      throw new Error('Invalid URL format.');
    }
  }

  async upload(url, fileType, customHeaders) {
    // Initialize and configure the chosen upload library with 'url', 'fileType', and 'customHeaders'
    const UploadLibrary = require(`${this._libraryName}`);
    const uploader = new UploadLibrary();
    await uploader.configure({ url, fileType, customHeaders });

    return uploader.start().then(response => {
      this._processUploadResponse(response);
      return response;
    }).catch(error => {
      console.error(`Error during upload: ${error}`);
      throw error;
    });
  }

  _processUploadResponse(response) {
    const uniqueId = `${Date.now()}-${response.metadata.filename}`;
    response.uniqueIdentifier = uniqueId;
    this._uploads[uniqueId] = response;
  }

  getUploadStatus(uniqueIdentifier) {
    return this._uploads[uniqueIdentifier];
  }

  getFinalUrl(uniqueIdentifier) {
    return this._uploads[uniqueIdentifier].finalUrl;
  }

  uploadFiles(urls, fileTypes = [], customHeaders = {}) {
    return Promise.all(urls.map((url, index) => {
      const uniqueId = `${index}-${Date.now()}`; // Generates a temporary unique identifier for sorting purposes
      this._uploads[uniqueId] = { uniqueIdentifier: uniqueId, status: 'pending' };

      return this.upload(url, fileTypes[index], customHeaders).then(() => {
        delete this._uploads[uniqueId].status; // Resets the temporary unique identifier as it's no longer needed after upload completion
        return uniqueId;
      });
    })).then(sortedUrls => sortedUrls.sort((a, b) => new Date(b) - new Date(a)));
  }

  static compareAndSortUrls(a, b) {
    const aDate = new Date(a.timestamp);
    const bDate = new Date(b.timestamp);

    return bDate - aDate;
  }

  toString() {
    let summary = 'CustomUploader:\n';
    summary += `  Successful uploads: ${Object.keys(this._uploads).filter(key => this._uploads[key].status === 'completed').length}\n`;
    summary += `  Pending requests: ${Object.keys(this._uploads).filter(key => this._uploads[key].status === 'pending').length}\n`;

    return summary;
  }

  _uploads = {}; // Private field to store upload information
}
