import com.tinkerpop.gremlin.driver.Client;
import com.opencsv.CSVReader;
import java.io.FileReader;
import java.util.Arrays;
import java.util.concurrent.Future;
import java.util.stream.Collectors;

public void loadData(String csvFilePath, Client gremlinClient, String vertexLabel, String[] properties, String edgeLabel, String adjacencyProperty) {
    long totalRows = 0;
    int processedRows = 0;
    try (CSVReader reader = new CSVReader(new FileReader(csvFilePath))) {
        String[] nextLine;
        while ((nextLine = reader.readNext()) != null) {
            totalRows++;
            Vertex vtx = gremlinClient.submit("g.addVertex(label, '" + vertexLabel + "')", nextLine).toList().get(0);
            Map<String, Object> props = Arrays.stream(nextLine).collect(Collectors.toMap(i -> i, i -> nextLine[Integer.parseInt(i) + 1]));
            vtx.property(properties).putAll(props);

            Future<?> edgeFutures[] = new Future<?>[nextLine.length - 1]; // -1 for vertex itself
            int idx = 0;
            for (String id : Arrays.asList(nextLine)) {
                if (!id.equals(idx + "")) {
                    int adjId = Integer.parseInt(id);
                    edgeFutures[idx] = gremlinClient.submit("g.V(" + vtx.getId() + ").outE(" + edgeLabel + ").where(__.inV().hasId(" + adjId + ")).ifAbsent{it.addV(" + vertexLabel + ").property(properties, __)" +
                            ".outV().addEdge(" + edgeLabel + ", v)", nextLine[Integer.parseInt(id) + 1]).toList().get(0);
                }
                idx++;
            }
            gremlinClient.traversal().Futures.all(edgeFutures).get();

            System.out.println("Processed " + processedRows + "/" + totalRows + " rows.");
            processedRows++;
        }
    } catch (Exception e) {
        System.err.println("Error loading data: " + e.getMessage());
    }
}
