#include <json-c/json.h>
#include <openssl/aes.h>
#include <openssl/hmac.h>
#include <time.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    EVP_CIPHER_CTX *cipher;
    HMAC_CTX *hmac;
    int status;
} JwtContext;

JwtContext* jwt_process(const char *json) {
    JsonObject *obj = json_object_from_string(json);
    const char *iss, *sub, *aud, *alg;
    long exp, nbf;
    if (!obj || !json_object_object_get(obj, "iss") ||
        !json_object_object_get(obj, "sub") || !json_object_object_get(obj, "aud") ||
        !json_object_object_get(obj, "exp") || !json_object_object_get(obj, "nbf")) {
        return calloc(1, sizeof(JwtContext)); // Return an empty context indicating failure
    }

    iss = json_object_object_get_const(obj, "iss");
    sub = json_object_object_get_const(obj, "sub");
    aud = json_object_object_get_const(obj, "aud");
    exp = json_object_object_get_int(obj, "exp");
    nbf = json_object_object_get_int(obj, "nbf");

    if (strlen(iss) == 0 || strlen(sub) == 0 || strlen(aud) == 0 || exp <= 0 || nbf <= 0) {
        return calloc(1, sizeof(JwtContext)); // Return an empty context indicating failure
    }

    alg = json_object_object_get_const(obj, "alg");
    if (!alg || (strcmp(alg, "A256GCM") != 0 && strcmp(alg, "A128CBC-HS256") != 0)) {
        return calloc(1, sizeof(JwtContext)); // Return an empty context indicating failure
    }

    JwtContext *ctx = malloc(sizeof(JwtContext));
    ctx->cipher = AES_GCM_CTX_new();
    ctx->hmac = HMAC_CTX_new();
    ctx->status = 1; // Successful initialization

    return ctx;
}
