<?php
namespace App\Utilities;

class AdvancedUtils {
    private $characterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    private $hashAlgorithms = ['sha256', 'blowfish'];
    private static $randomStringsCache = [];
    private static $sessionCache = [];

    public function setCharacterSet(string $charset): void {
        $this->characterSet = $charset;
    }

    public function generateRandomString($length = 32): string {
        $key = md5(__FUNCTION__ . $length);
        if (isset(self::$randomStringsCache[$key])) {
            return self::$randomStringsCache[$key];
        }
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->characterSet[mt_rand(0, strlen($this->characterSet) - 1)];
        }
        self::$randomStringsCache[$key] = $randomString;
        return $randomString;
    }

    public function hashPassword(string $password, string $algorithm = 'sha256'): string {
        if (!in_array($algorithm, $this->hashAlgorithms)) {
            throw new \InvalidArgumentException('Invalid hashing algorithm.');
        }
        return password_hash($password, PASSWORD_DEFAULT . strtoupper($algorithm));
    }

    public function hashCompare(string $hashedPassword, string $plainPassword): bool {
        return password_verify($plainPassword, $hashedPassword);
    }

    /**
     * Session management functions
     */
    public function startSession() {
        if (!session_id()) {
            session_start();
        }
    }

    public function createSessionId(): string {
        return bin2hex(random_bytes(32));
    }

    public function setSessionExpirationTime($seconds) {
        ini_set('session.gc_maxlifetime', $seconds);
    }

    public function getSession($id) {
        if (!isset(self::$sessionCache[$id])) {
            self::$sessionCache[$id] = @serialize($_SESSION[$id]);
        }
        return unserialize(self::$sessionCache[$id]);
    }

    public function setSession($id, $data) {
        $_SESSION[$id] = $data;
        self::$sessionCache[$id] = @serialize($_SESSION[$id]);
    }

    public function destroySession($id) {
        unset($_SESSION[$id]);
        unset(self::$sessionCache[$id]);
    }

    /**
     * Security measures for session management
     */
    public function requiresSecureCookie(): bool {
        return (bool)(filter_input(INPUT_SERVER, 'HTTPS') === 'on' || filter_input(INPUT_SERVER, 'HTTP_X_FORWARDED_PROTO') === 'https');
    }

    public function generateSessionIdWithUnpredictableToken(): string {
        $token = hash('sha256', microtime(true) . uniqid());
        return substr($this->createSessionId(), 0, 16) . '-' . substr($token, 0, 16);
    }
}
