        if (!head) {
            head = new_record;
            current = head;
        } else {
            current->next = new_record;
            current = new_record;
        }

        ++(*num_records);
        if ((i + 1) % batch_size == 0 || i + 1 >= length) {
            // Resize record array if necessary and traverse the linked list for efficiency
            if (*num_records > record_threshold) {
                Record** records = realloc(head, sizeof(Record) * *num_records);
                if (!records) {
                    // Handle memory allocation failure
