typedef enum { ALERT_TYPE_1, ALERT_TYPE_2, ALERT_TYPE_3 } alert_type;

struct alert {
    alert_type type;
    int64_t value;
    bool log_detailed;
};

void parse_config_line(char* line, struct alert** alerts, size_t* count) {
    char* token = strtok(line, ":");
    if (!token) return;

    int type = atoi(token);
    token = strtok(NULL, ":");
    if (!token) return;

    int64_t value = strtoll(token, NULL, 10);
    token = strtok(NULL, ":");
    bool log_detailed = !strcmp(token, "true");

    struct alert* alert = malloc(sizeof(struct alert));
    *alert = (struct alert){ .type = type, .value = value, .log_detailed = log_detailed };
    (*alerts)[(*count)++] = alert;
}

void write_alert(FILE* file, const struct alert* alert) {
    fprintf(file, "%s: %" PRId64 "\n", (alert->type == ALERT_TYPE_1 ? "Alert Type 1" :
                                        (alert->type == ALERT_TYPE_2 ? "Alert Type 2" : "Alert Type 3")), alert->value);
    if (alert->log_detailed) {
        fprintf(file, "Detailed Log:\n");
        // Add detailed log here
    }
}

void generate_alerts(const char* config_filename, const char* output_filename, const char* alert_types, int64_t* thresholds, size_t num_thresholds, bool enable_logging) {
    FILE* config = fopen(config_filename, "r");
    if (!config) {
        fprintf(stderr, "Failed to open configuration file\n");
        exit(1);
    }

    size_t count = 0;
    struct alert* alerts = NULL;

    char line[4096];
    while (fgets(line, sizeof(line), config)) {
        parse_config_line(line, &alerts, &count);
    }

    fclose(config);

    FILE* output = fopen(output_filename, "w");
    if (!output) {
        fprintf(stderr, "Failed to open output file\n");
        exit(1);
    }

    for (size_t i = 0; i < count; ++i) {
        const struct alert* alert = &alerts[i];
        if (alert->value > thresholds[alert->type]) {
            write_alert(output, alert);
        }
    }

    fclose(output);
}

int main(int argc, char** argv) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <config_file> <output_file> <alert_types> <thresholds> <log_level>\n", argv[0]);
        exit(1);
    }

    const char* config_filename = argv[1];
    const char* output_filename = argv[2];
    const char* alert_types = argv[3];
    int64_t thresholds[3] = { atoll(strtok(alert_types, ",")), atoll(strtok(NULL, ",")), atoll(strtok(NULL, "")) };
    bool log_detailed = !strcmp(argv[5], "true");

    mkdir("logs", S_IRWXU | S_IRGRP | S_IXGRP | S_IROTH | S_IXOTH); // Create logs directory for detailed logging

    generate_alerts(config_filename, output_filename, alert_types, thresholds, 3, log_detailed);
}
