class MD5Hasher implements Runnable {
    Queue<String> queue;
    Map<String, BigInteger> results;
    Future<?> future;
    boolean cancelRequested = false;

    MD5Hasher(Queue<String> queue, Map<String, BigInteger> results) {
        this.queue = queue;
        this.results = results;
    }

    @Override
    public void run() {
        MessageDigest md;
        while (!cancelRequested && !queue.isEmpty()) {
            String str = queue.poll();
            if (str == null || str.isEmpty()) continue; // Handle null and empty strings appropriately

            md = MessageDigest.getInstance("MD5");
            md.update(str.getBytes());
            results.put(str, new BigInteger(1, md.digest()));
        }
    }

    void cancel() {
        cancelRequested = true;
        if (future != null) try {
            future.cancel(true);
        } catch (Exception e) {}
    }
}

public Map<String, BigInteger> computeMD5Hashes(List<String> list, Octree octree) throws InterruptedException, ExecutionException {
    // Split the input list into batches to optimize memory usage
    int batchSize = 1024;
    List<List<String>> batches = Lists.partition(list, batchSize);

    // Create a thread pool and initialize MD5Hasher tasks for each batch
    ExecutorService executor = Executors.newCachedThreadPool();
    Map<String, BigInteger> results = new HashMap<>();
    Queue<String> currentBatchQueue = new ConcurrentLinkedQueue<>();
    Queue<MD5Hasher> currentBatchTasks = new ConcurrentLinkedQueue<>();

    for (List<String> batch : batches) {
        for (int i = 0; i < batch.size(); ++i) {
            String str = batch.get(i);
            if (str == null || str.isEmpty()) continue; // Handle null and empty strings appropriately
            currentBatchQueue.add(str);
        }

        if (!currentBatchQueue.isEmpty()) {
            MD5Hasher hasherTask = new MD5Hasher(currentBatchQueue, results);
            currentBatchTasks.add(hasherTask);
            Future<?> future = executor.submit(hasherTask);
            hasherTask.future = future;
        }
    }

    // Wait for all tasks to finish or cancel operation mid-execution
    while (!currentBatchTasks.isEmpty() || !results.isEmpty()) {
        if (cancelRequested) {
            for (MD5Hasher hasherTask : currentBatchTasks) hasherTask.cancel();
            executor.shutdownNow();
            break;
        }

        MD5Hasher task = null;
        Future<Void> future = null;
        for (Iterator<MD5Hasher> iterator = currentBatchTasks.iterator(); iterator.hasNext(); ) {
            MD5Hasher hasherTask = iterator.next();
            if (!hasherTask.cancelRequested) {
                task = hasherTask;
                future = hasherTask.future;
                break;
            } else iterator.remove();
        }

        if (task != null && !future.isDone()) continue; // Wait for the task to finish processing its batch

        if (!results.isEmpty()) {
            String key = currentBatchQueue.poll();
            if (key != null) results.remove(key);
        }
    }

    executor.shutdown();
    executor.awaitTermination(1, TimeUnit.HOURS); // Wait for the executor to terminate gracefully

    return results;
}
