using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;

public class CustomRandom
{
    private readonly int _min;
    private readonly int _max;
    private Random _random;
    private HashSet<int> _cachedIntValues;
    private HashSet<float> _cachedFloatValues;

    public CustomRandom(int min, int max)
    {
        if (min > max)
            throw new ArgumentOutOfRangeException(nameof(min), "Min value should be less than or equal to Max value.");

        _min = min;
        _max = max;
        _random = new Random();
        _cachedIntValues = Enumerable.Range(_min, _max - _min + 1).ToHashSet();
        _cachedFloatValues = new HashSet<float>();
    }

    public int NextInt(bool inclusiveMin = true, bool inclusiveMax = true)
    {
        var rangeSize = _max - (_inclusiveMin ? _min : _min + 1);
        return inclusiveMin && inclusiveMax ? _random.Next(_min, _max + 1) : _random.Next(0, rangeSize);
    }

    public float NextFloat(bool inclusiveMin = true, bool inclusiveMax = true, int precision = 2)
    {
        var fltRange = (float)(_max - (_inclusiveMin ? _min : _min + 1));
        var rndVal = _random.NextDouble() * fltRange;
        return MathF.Round(rndVal, precision);
    }

    public bool NextBoolean(int probabilityPercentage)
    {
        if (probabilityPercentage < 0 || probabilityPercentage > 100)
            throw new ArgumentOutOfRangeException(nameof(probabilityPercentage), "Probability percentage should be between 0 and 100.");

        return _random.Next(0, 100) < probabilityPercentage;
    }

    public IEnumerable<int> NextIntSequence(int count, bool exclusiveEnd = false)
    {
        if (count > _max - (_exclusiveEnd ? _min : _min + 1))
            throw new ArgumentOutOfRangeException(nameof(count), "Count should be less than or equal to the range size.");

        var list = new List<int>();
        for (var i = 0; i < count; ++i)
        {
            int val;
            if (_cachedIntValues.Any())
            {
                val = _cachedIntValues.First();
                _cachedIntValues.Remove(val);
            }
            else
                val = NextInt(false, exclusiveEnd);

            list.Add(val);
        }

        return list;
    }

    public IEnumerable<float> NextFloatSequence(int count, bool inclusiveMin = true, bool inclusiveMax = true, int precision = 2)
    {
        if (count > _max - (_inclusiveMin ? _min : _min + 1))
            throw new ArgumentOutOfRangeException(nameof(count), "Count should be less than or equal to the range size.");

        var list = new List<float>();
        for (var i = 0; i < count; ++i)
            list.Add(NextFloat(inclusiveMin, inclusiveMax, precision));

        return list;
    }

    private void CacheValues()
    {
        _cachedIntValues = Enumerable.Range(_min, _max - _min + 1).ToHashSet();
        _cachedFloatValues.Clear();
    }

    protected override string ToString()
    {
        return $"CustomRandom({_min}, {_max}) [{_cachedIntValues.Count} int values cached, {_cachedFloatValues.Count} float values cached]";
    }
}
```
