// Define the maximum size of the TIFF file to prevent excessive memory usage
#define MAX_TIFF_SIZE 10 * 1024 * 1024 // 10 MB

// Function to parse a TIFF image file and perform cryptographic operations based on command line options
TIFF* parse_tiff_and_encrypt(const char* filename, const char* option) {
    TIFF* tif = NULL;
    EVP_CIPHER_CTX* ctx = NULL;
    unsigned long tiff_size = 0;

    // Open the TIFF file
    tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error opening TIFF file: %s\n", filename);
        return NULL;
    }

    // Retrieve the file size to ensure it does not exceed the defined limit
    tiff_size = TIFFCheckFileDirectory(tif);
    if (tiff_size > MAX_TIFF_SIZE) {
