#include <sys/socket.h>
#include <netdb.h>
#include <openssl/sha.h>

#define BUFFER_SIZE 8192
#define PROGRESS_STEP 1024

typedef struct {
    SHA256_CTX ctx;
    u_char hash[SHA256_DIGEST_LENGTH];
    size_t total, processed;
} HashContext;

int get_ip(const char* hostname, u_char* ip) {
    struct addrinfo hints, *res;
    int status = 0;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) return -1;

    int sockfd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (sockfd < 0) goto cleanup;

    if (connect(sockfd, res->ai_addr, res->ai_addrlen) < 0) {
        close(sockfd);
        goto cleanup;
    }

    memset(ip, 0, sizeof(u_char)*4);
    socklen_t addr_len = sizeof(struct sockaddr_in);
    getsockname(sockfd, (struct sockaddr*)&res->ai_addr, &addr_len);
    memcpy(ip, &(reinterpret_cast<struct sockaddr_in*>(res->ai_addr)->sin_addr), 4);

cleanup:
    freeaddrinfo(res);
    return status;
}

HashContext hash_init() {
    HashContext ctx = {};
    SHA256_Init(&ctx.ctx);
    return ctx;
}

void hash_update(HashContext* ctx, const u_char* data, size_t len) {
    SHA256_Update(&ctx->ctx, data, len);
    ctx->processed += len;
}

u_char* hash_final(HashContext* ctx) {
    SHA256_Final(ctx->hash, &ctx->ctx);
    return ctx->hash;
}

int main() {
    const char* hostname = "example.com";
    u_char ip[4];
    int status = get_ip(hostname, ip);
    if (status < 0) return status;

    FILE* fp = fopen("large_file", "rb");
    if (!fp) return -1;

    HashContext ctx = hash_init();
    char buffer[BUFFER_SIZE];
    size_t read_len, total_read = 0;

    while ((read_len = fread(buffer, 1, BUFFER_SIZE, fp)) > 0) {
        hash_update(&ctx, buffer, read_len);
        total_read += read_len;
        if (total_read >= PROGRESS_STEP) {
            printf("%.2f%% hashed\n", ((double)ctx.processed / ctx.total) * 100);
            total_read -= PROGRESS_STEP;
        }
    }

    fclose(fp);
    u_char* hash = hash_final(&ctx);

    // Return the hexdigest and total bytes processed here, e.g., printf("%s %zu\n", bin2hex(hash), ctx.total);

    return 0;
}
