        executor = Executors.newFixedThreadPool(maxThreadCount);
        eventBus = new EventBus();
        ringBuffer = LMAXDisruptorUtils.createRingBuffer(HashEvent.class, bufferSize, ProducerType.MULTI);
        cache = cachingEnabled ? CacheBuilder.newBuilder().maximumWeight(cacheCapacity).buildOnlyIfAbsent() : null;
    }

    public Map<String, BigInteger> processHashes(List<String> filePaths) {
        final AtomicLong processed = new AtomicLong(0);
        final AtomicLong cancelled = new AtomicLong(0);
        final AtomicReference<Throwable> exception = new AtomicReference<>();

        HashProgressListener progressListener = new HashProgressListener(processed, cancelled, eventBus);
        eventBus.register(progressListener);

        try {
            for (String filePath : filePaths) {
                readFileChunks(filePath, chunkSize, executor, ringBuffer, cache, progressListener, processed);
            }
        } catch (Throwable t) {
            exception.set(t);
            cancelled.incrementAndGet();
        } finally {
            if (!executor.isShutdown()) {
                executor.shutdownNow();
            }
        }

        eventBus.unregister(progressListener);

        Map<String, BigInteger> result = new HashMap<>();
        if (exception.get() == null) {
            while (!processed.get().equals(cachedProcessed.get())) {
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    LOGGER.log(Level.WARNING, "Sleep interrupted", e);
                }
            }

            for (Map.Entry<String, String> entry : processedStrings.entrySet()) {
                result.put(entry.getKey(), stringToHash.getOrDefault(entry.getKey(), null));
            }
        } else {
            result = null;
        }

        return result;
    }

