size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t remaing = ((size_t*)userp)[0];
    size_t total_size = remaing + size * nmemb;
    ((char*)userp)[remaing] = '\0';

    if(total_size > remaing) {
        printf("Error: Out of memory!\n");
        return 0;
    }

    memcpy(((char*)userp) + remaing, contents, size * nmemb);
    ((size_t*)userp)[0] = total_size;
    remaing -= total_size;

    return size * nmemb;
}

void processConfigFile(const char* file, const char* logFlag, const char* endpoint) {
    // JSON parsing and configuration loading...
    jsmn_parser parser;
    jsmntok_t tokens[1024];
    int count = 0;

    jsmn_init(&parser);
    jsmn_parse(file, sizeof(tokens), tokens, &count);

    Alert* alerts = malloc(count * sizeof(Alert));

    for (int i = 1; i < count; ++i) {
        if (strcmp(tokens[i].name, "type") == 0 && strcmp(tokens[i+1].name, "threshold") == 0) {
            strncpy(alerts[i - 1].type, tokens[i].start, tokens[i].end - tokens[i].start);
            alerts[i - 1].threshold = atof(tokens[i+1].start);
        }
    }

    // Periodic data fetching and alert generation...
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    curl_easy_setopt(curl, CURLOPT_URL, endpoint);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, malloc(1024));
    curl_easy_perform(curl);

    // Update alerts with the fetched threshold values...
    // Generate output alert file in a readable format...

    // Don't forget to cleanup:
    free(alerts);
    free(curl_easy_get_writefunction(curl));
    curl_easy_cleanup(curl);
    curl_global_cleanup();
}
