class TaskQueue {
private:
    std::priority_queue<Task, std::vector<Task>, std::greater<Task>> heap;
    std::map<unsigned long, Task> tasks;
    std::mutex mtx;
    unsigned int maxTasks = 10000; // Predefined threshold for dynamic resizing

public:
    void init(const std::vector<unsigned long>& ids, const std::vector<int>& priorities, const std::vector<time_t>& deadlines) {
        std::deque<Task> batch;

        for (size_t i = 0; i < ids.size(); ++i) {
            if (ids[i] && priorities[i] && deadlines[i]) {
                Task task{ ids[i], priorities[i], deadlines[i] };
                tasks[task.id] = task;
                batch.push_back(task);
            }
        }

        processBatch(batch);
    }

    void processBatch(std::deque<Task>& batch) {
        if (batch.empty()) return;

        std::vector<Task> tempTasks;
        size_t count = 0;

        { // Lock for parallel processing safety
            std::lock_guard<std::mutex> lock(mtx);

            while (!batch.empty() && count < maxTasks) {
                heap.push(batch.back());
                batch.pop_back();
                ++count;
            }
        }

        processHeap();
    }

    void processHeap() {
