public class RandomValueGenerator
{
    private ConcurrentQueue<float> _floats;
    private ConcurrentQueue<int> _ints;
    private Vector3 _vector3Min;
    private Vector3 _vector3Max;

    public RandomValueGenerator(Vector3 min, Vector3 max)
    {
        _floats = new ConcurrentQueue<float>();
        _ints = new ConcurrentQueue<int>();
        _vector3Min = min;
        _vector3Max = max;
    }

    public float NextFloat(bool inclusive)
    {
        if (_floats.TryDequeue(out var result)) return result;
        float resultValue;
        if (inclusive)
            resultValue = UnityEngine.Random.Range(_vector3Min.x, _vector3Max.x);
        else
            resultValue = UnityEngine.Random.Range(_vector3Min.x + 0.001f, _vector3Max.x - 0.001f);
        _floats.Enqueue(resultValue);
        return resultValue;
    }

    public int NextInt(bool inclusive)
    {
        if (_ints.TryDequeue(out var result)) return result;
        int resultValue;
        if (inclusive)
            resultValue = Mathf.RoundToInt(UnityEngine.Random.Range(_vector3Min.x, _vector3Max.x));
        else
            resultValue = Mathf.RoundToInt(UnityEngine.Random.Range(_vector3Min.x + 1, _vector3Max.x));
        _ints.Enqueue(resultValue);
        return resultValue;
    }

    public Vector3 NextVector3()
    {
        return new Vector3(NextFloat(true), NextFloat(true), NextFloat(true));
    }

    public float Average(int iterations)
    {
        for (int i = 0; i < iterations; ++i)
        {
            switch (UnityEngine.Random.value)
            {
                case 0: _floats.Enqueue(NextFloat(true)); break;
                case 1: _ints.Enqueue(NextInt(true)); break;
            }
        }
        return _floats.Sum() / iterations + _ints.Sum() / (2 * iterations);
    }

    public override string ToString() => $"Min: {_vector3Min}, Max: {_vector3Max}, Floats: Count={_floats.Count}, Ints: Count={_ints.Count}";
}
