    public float GenerateRandomValue(float min, float max, bool inclusive = true)
    {
        if (min > max) throw new ArgumentOutOfRangeException(nameof(min), "Minimum value should not be greater than maximum value.");

        var rangeSize = max - min;
        float randomValue;

        if (inclusive)
        {
            randomValue = UnityEngine.Random.Range(0, rangeSize);
        }
        else
        {
            randomValue = UnityEngine.Random.Range(0, rangeSize + 1) - rangeSize;
