public class RandomValueGenerator
{
    private readonly ConcurrentDictionary<string, (float min, float max)> _generators;

    public RandomValueGenerator() : this(0f, float.MaxValue) { }

    public RandomValueGenerator(float min, float max)
    {
        _generators = new ConcurrentDictionary<string, (float min, float max)>();
        SetRange(min, max);
    }

    public void SetRange(float min, float max, bool inclusive = true)
    {
        if (_generators.ContainsKey(GetGeneratorId())) return;
        _generators[GetGeneratorId()] = (min, max);
    }

    private string GetGeneratorId()
    {
        return $"{nameof(RandomValueGenerator)}{System.Reflection.MethodBase.GetCurrentMethod().Name}";
    }

    public float GenerateFloat(int iterations = 10)
    {
        var average = 0f;
        for (var i = 0; i < iterations; i++)
            average += GenerateRandomValue(this);

        return average / iterations;
    }

    public int GenerateInteger(int iterations = 10)
    {
        var average = 0;
        for (var i = 0; i < iterations; i++)
            average += GenerateRandomValue(this);

        return average / iterations;
    }

    public float Min { get => _generators.Values.Select(v => v.min).First(); }
    public float Max { get => _generators.Values.Select(v => v.max).First(); }
}

