```csharp
public sealed class RandomValueGenerator
{
    private int _min;
    private int _max;
    private double _epsilon = 0.0001;
    private bool _inclusiveMin = true;
    private bool _inclusiveMax = true;
    private object _syncLock = new object();
    private long _currentState;

    public RandomValueGenerator(int min, int max) : this(min, max, false, false) { }

    public RandomValueGenerator(int min, int max, bool inclusiveMin, bool inclusiveMax)
    {
        _min = min;
        _max = max;
        _inclusiveMin = inclusiveMin;
        _inclusiveMax = inclusiveMax;
    }

    public double GenerateFloat()
    {
        lock (_syncLock)
        {
            var currentState = Interlocked.Read(_currentState);
            while (true)
            {
                var rnd = new Random((int)(currentState * 123456));
                var val = rnd.NextDouble();
                if (_inclusiveMin && _inclusiveMax)
                {
                    if (val >= _min && val <= _max) return val;
                }
                else if (_inclusiveMin)
                {
                    if (val > _min && val <= _max) return val;
                }
                else if (_inclusiveMax)
                {
                    if (val >= _min && val < _max) return val;
                }
                else
                {
                    if (val > _min && val < _max - _epsilon) return val;
                }
                Interlocked.Increment(ref currentState);
            }
        }
    }

    public int GenerateInt() => (int)Math.Floor(GenerateFloat() + 0.5);

    public override string ToString() => $"[{_min}:{(_inclusiveMin ? "[" : "[>")} {_max}:{( _inclusiveMax ? "]" : "<")}]";
}
