function findElementsBySelector(rootElement, selector, testFunction) {
  if (rootElement.matches && rootElement.matches(selector)) {
    const results = [];
    if (testFunction(rootElement)) results.push(rootElement);

    for (const child of rootElement.children) {
      results.push(...findElementsBySelector(child, selector, testFunction));
    }

    return results;
  }

