#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

typedef struct net_interface {
    char iface[IF_NAMESIZE];
    char ip_addr[INET_ADDRSTRLEN];
    char subnet_mask[INET_ADDRSTRLEN];
    char gateway[INET_ADDRSTRLEN];
    char mac_addr[MAC_ADDRSTRLEN];
} NetInterface;

typedef struct node {
    NetInterface data;
    struct node *next;
} Node;

Node* create_node(NetInterface data) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_node(Node** head, NetInterface data) {
    Node* new_node = create_node(data);
    if (!new_node) return;

    if (*head == NULL) {
        *head = new_node;
        return;
    }

    Node* current = *head;
    while (current->next != NULL) current = current->next;
    current->next = new_node;
}

NetInterface get_interface(Node* node, const char* iface) {
    if (!node || strcmp(node->data.iface, iface)) return (NetInterface){0};
    return node->data;
}

void update_interface(Node** head, const char* iface, NetInterface new_data) {
    Node* current = *head;
    while (current != NULL && strcmp(current->data.iface, iface)) current = current->next;

    if (!current) return;
    current->data = new_data;
}

void list_interfaces(const Node* node) {
    const Node* current = node;
    while (current != NULL) {
        printf("\nInterface: %s\n", current->data.iface);
        printf("IP Address:  %s\n", current->data.ip_addr);
        printf("Subnet Mask: %s\n", current->data.subnet_mask);
        printf("Gateway:    %s\n", current->data.gateway);
        printf("MAC Address: %s\n", current->data.mac_addr);
        current = current->next;
    }
}
