typedef struct {
    long offset;
    int key;
} record;

void read_keys(const char *filename, record **records, int *randoms, size_t *num_records) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        *num_records = 0;
        *randoms = malloc(*num_records * sizeof(int));
        for (size_t i = 0; i < *num_records; ++i)
            (*randoms)[i] = 0;
        return;
    }

    struct stat file_stat;
    if (fstat(fileno(file), &file_stat) == -1) {
        fclose(file);
        *num_records = 0;
        *randoms = malloc(*num_records * sizeof(int));
        for (size_t i = 0; i < *num_records; ++i)
            (*randoms)[i] = 0;
        return;
    }

    size_t num_lines = file_stat.st_size / sizeof(long); // Assuming each line is a long and newline character.
    if (num_lines == 0) {
        fclose(file);
        *num_records = 0;
        *randoms = malloc(*num_records * sizeof(int));
        for (size_t i = 0; i < *num_records; ++i)
            (*randoms)[i] = 0;
        return;
    }

    *records = malloc(num_lines * sizeof(record));
    if (!*records) {
        fclose(file);
        *num_records = 0;
        *randoms = malloc(*num_records * sizeof(int));
        for (size_t i = 0; i < *num_records; ++i)
            (*randoms)[i] = 0;
        return;
    }

    if (fseek(file, 0, SEEK_SET) != 0) {
        free(*records);
        fclose(file);
        *num_records = 0;
        *randoms = malloc(*num_records * sizeof(int));
        for (size_t i = 0; i < *num_records; ++i)
            (*randoms)[i] = 0;
        return;
    }

    size_t num_read = 0;
    while (!feof(file)) {
        record *curr = &(*records)[num_read];
        curr->offset = ftell(file) / sizeof(long);
        curr->key = fgetl(file);
        if (ferror(file)) break;
        ++num_read;
    }

    *num_records = num_read;
    *randoms = malloc(*num_records * sizeof(int));
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < *num_records; ++i) {
        (*randoms)[i] = rand() % 1000 + 1;
    }

    fclose(file);
}

void free_memory(record *records, int *randoms, size_t num_records) {
    if (records) free(records);
    if (randoms) free(randoms);
}
