#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <limits.h>

typedef struct record {
    long offset;
    int key;
} Record;

struct node {
    Record data;
    struct node *next;
};

void log(const char* message) {
    printf("[Log] %s\n", message);
}

int random_in_range(int min, int max) {
    return (rand() % ((max - min) + 1)) + min;
}

void read_keys(struct node** head, FILE* file) {
    Record record;
    bool success = true;
    while (success) {
        success = fscanf(file, "%ld%*c%d\n", &record.offset, &record.key);
        if (success) {
            *head = realloc(*head, sizeof(struct node) + 1);
            (*head)->data = record;
            (*head)->next = NULL;
            head = &((*head)->next);
        }
    }
}

void init_keys(struct node** head, int count, int min, int max) {
    *head = malloc(count * sizeof(struct node));
    for (int i = 0; i < count; ++i) {
        (*head)->data.offset = i;
        (*head)->data.key = random_in_range(min, max);
        (*head)->next = NULL;
        head = &((*head)->next);
    }
}

void free_linked_list(struct node** head) {
    struct node *current = *head, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}

int main() {
    const int MAX_RECORDS = 1000;
    FILE* file = fopen("keys.txt", "r");
    struct node* head = NULL, *current = NULL;

    if (file == NULL) {
        log("Error: Unable to open 'keys.txt'.");
        init_keys(&head, MAX_RECORDS, 1, 1000);
    } else {
        int records_read = 0;
        while ((feof(file) == 0) && (records_read < MAX_RECORDS)) {
            read_keys(&current, file);
            if (current != NULL) {
                current->data.key = random_in_range(1, 1000);
                records_read++;
            }
        }

        fclose(file);
    }

    // Perform operations on the data structures here...

    free_linked_list(&head);

    return 0;
}
