struct random_generator {
    int seed;
};

void srand_init(struct random_generator *rng, time_t t) {
    rng->seed = (int)(t % INT32_MAX);
}

int rand_int(struct random_generator *rng, int limit) {
    return (rng->seed = (rng->seed * 16807) % INT32_MAX) / limit;
}

struct record {
    long offset;
    int key;
    struct record* prev;
    struct record* next;
};

struct list {
    size_t capacity;
    size_t size;
    struct record** storage;
};

void resize_list(struct list *list, size_t new_capacity) {
    if (new_capacity <= list->size) return;

    struct record** new_storage = realloc(list->storage, new_capacity * sizeof(struct record*));
    if (!new_storage) {
        fprintf(stderr, "Failed to resize list\n");
        exit(EXIT_FAILURE);
    }

    list->capacity = new_capacity;
    list->storage = new_storage;
}

void append_record(struct list *list, struct record* record) {
    if (list->size == list->capacity) resize_list(list, list->capacity * 2);

    list->storage[list->size] = record;
    record->prev = list->storage[(list->size > 0 ? list->size - 1 : 0)];
    record->next = NULL;

    if (record->prev) record->prev->next = record;
    else list->head = record;

    ++list->size;
}

struct record* find_record(struct list *list, long offset) {
    struct record* current = list->head;
    while (current != NULL) {
        if (current->offset == offset) return current;
        current = current->next;
    }
    return NULL;
}

void log_event(const char *message, const char *file, int line) {
    FILE *log_file = fopen("program.log", "a");
    if (log_file) {
        fprintf(log_file, "%s [%s:%d]\n", message, file, line);
        fclose(log_file);
    } else {
        fprintf(stderr, "Failed to open log file\n");
    }

    printf("%s\n", message);
}

struct record* create_record() {
    struct record* record = malloc(sizeof(struct record));
    if (!record) {
        log_event("Out of memory error", __FILE__, __LINE__);
        exit(EXIT_FAILURE);
    }

    record->offset = 0;
    record->key = -1;
    record->prev = NULL;
    record->next = NULL;

    return record;
}

int main() {
    struct random_generator rng;
    srand_init(&rng, time(NULL));

    struct list records;
    struct list keys;

    resize_list(&records, 1);
    resize_list(&keys, 10);
    records.storage[0] = create_record();
    keys.storage[0] = create_record();

    FILE *file = fopen("keys.txt", "r");
    if (!file) {
        log_event("Failed to open 'keys.txt'", __FILE__, __LINE__);
        for (int i = 1; i <= 10; ++i) {
            keys.storage[i]->key = rand_int(&rng, 1000);
        }
    } else {
        char line[256];
        size_t lines = 0;
        while (fgets(line, sizeof(line), file)) {
            if (lines >= keys.capacity) resize_list(&keys, keys.capacity * 2);
            keys.storage[lines] = create_record();
            keys.storage[lines]->key = atoi(line);
            ++lines;
        }
        fclose(file);
    }

    struct record* current_record = records.storage[0];
    for (int i = 1; i <= lines; ++i) {
        int key_index = (current_record->offset + i) % keys.size;
        if (keys.storage[key_index]->key != -1) {
            current_record->key = rand_int(&rng, 1000);
            struct record* next_record = find_record(&records, current_record->offset + i + 1);
            if (next_record && next_record->key != -1) {
                log_event("Cyclic reference detected", __FILE__, __LINE__);
            } else {
                struct record* new_record = create_record();
                new_record->offset = current_record->offset + i + 1;
                new_record->key = keys.storage[key_index]->key;
                append_record(&records, new_record);
            }
        } else {
            current_record->key = (lines > 0 ? 0 : rand_int(&rng, 1000));
        }
    }

    log_event(("Processed %ld records with %d keys").format(records.size, lines), __FILE__, __LINE__);

    free(keys.storage);
    free(records.storage);

    return 0;
}
```

This code snippet accomplishes the given task of managing memory for a doubly linked list of `struct record` and performing operations on it as specified in your requirements. The code includes functions to handle dynamic resizing, error checking, custom random number generation, file handling with logging, and cyclic reference detection.']

