['```c
#include <pthread.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/time.h>
#include <time.h>

typedef struct CacheEntry {
    uint64_t timestamp;
    void *value;
} CacheEntry;

typedef struct Node {
    CacheEntry entry;
    struct Node *next;
} Node;

typedef struct HashTable {
    size_t capacity;
    size_t size;
    Node **table;
    pthread_mutex_t mutex;
} HashTable;

static uint64_t custom_hash(const char *key, const size_t key_len) {
    uint64_t hash = 0;
    for (size_t i = 0; i < key_len; ++i) {
        hash = (hash << 5) + hash + key[i];
        hash &= ~((uint64_t)1 << 63); // Ensure 64-bit unsigned integer
    }
    return hash % CACHE_CAPACITY;
}

static CacheEntry *get_entry(HashTable *ht, const char *key, const size_t key_len) {
    pthread_mutex_lock(&ht->mutex);
    size_t index = custom_hash(key, key_len) % ht->capacity;
    Node *node = ht->table[index];
    while (node != NULL) {
        if (strcmp(node->entry.key, key) == 0) {
            CacheEntry *entry = &node->entry;
            pthread_mutex_unlock(&ht->mutex);
            return entry;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&ht->mutex);
    return NULL;
}

static void add_entry(HashTable *ht, const char *key, const size_t key_len, CacheEntry *entry) {
    pthread_mutex_lock(&ht->mutex);
    size_t index = custom_hash(key, key_len) % ht->capacity;
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&ht->mutex);
        return;
    }
    new_node->entry = *entry;
    new_node->next = ht->table[index];
    ht->table[index] = new_node;
    if (++ht->size > ht->capacity) {
        evict_least_recently_used(ht);
    }
    pthread_mutex_unlock(&ht->mutex);
}

static void remove_expired_entries(HashTable *ht) {
    time_t now = time(NULL);
    pthread_mutex_lock(&ht->mutex);
    for (size_t i = 0; i < ht->capacity; ++i) {
        Node *node = ht->table[i];
        while (node != NULL) {
            if (now - node->entry.timestamp > CACHE_EXPIRATION) {
                Node *next = node->next;
                free(node);
                node = next;
            } else {
                node = node->next;
            }
        }
    }
    pthread_mutex_unlock(&ht->mutex);
}

static void evict_least_recently_used(HashTable *ht) {
    remove_expired_entries(ht);
    if (ht->size > ht->capacity / 2) {
        resize_hash_table(ht, ht->capacity * 2);
    }
}

static void resize_hash_table(HashTable *ht, size_t new_capacity) {
    pthread_mutex_lock(&ht->mutex);
    Node **old_table = ht->table;
    ht->capacity = new_capacity;
    ht->table = malloc(sizeof(Node *) * new_capacity);
    if (ht->table == NULL) {
        pthread_mutex_unlock(&ht->mutex);
        return;
    }
    for (size_t i = 0; i < old_capacity; ++i) {
        Node *node = old_table[i];
        while (node != NULL) {
            CacheEntry *entry = &node->entry;
            size_t index = custom_hash(entry->key, strlen(entry->key)) % ht->capacity;
            node->next = ht->table[index];
            ht->table[index] = node;
            node = node->next;
        }
    }
    free(old_table);
    pthread_mutex_unlock(&ht->mutex);
}

void caching_system_init(HashTable *ht, size_t capacity) {
    ht->capacity = capacity;
    ht->size = 0;
    ht->table = malloc(sizeof(Node *) * capacity);
    if (ht->table == NULL) {
        fprintf(stderr, "Failed to allocate memory for hash table.\n");
        exit(EXIT_FAILURE);
    }
    memset(ht->table, 0, sizeof(Node *) * capacity);
    pthread_mutex_init(&ht->mutex, NULL);
}

CacheEntry *caching_system_get(HashTable *ht, const char *key, const size_t key_len) {
    CacheEntry *entry = get_entry(ht, key, key_len);
    if (entry == NULL) return NULL;
    entry->timestamp = time(NULL);
    return entry;
}

void caching_system_set(HashTable *ht, const char *key, const size_t key_len, CacheEntry *entry) {
    add_entry(ht, key, key_len, entry);
}
```

This code assumes you have defined a `CACHE_CAPACITY`, `CACHE_EXPIRATION`, and other necessary constants. It also assumes that the keys are null-terminated strings and that CacheEntry is a user-defined struct containing a timestamp and a value. The function does not include the timeout and logging mechanisms, as they would require additional parameters and details specific to your application's requirements.

You can improve this code by implementing more sophisticated hash functions, eviction policies, and adding support for concurrent access using other synchronization primitives or data structures. Also, consider incorporating the timeout and logging mechanisms to meet your desired performance and reliability goals.']

