typedef struct {
    uint32_t rxi;
    uint16_t rnti;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_list(int N) {
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; ++i) {
        list[i].rxi = i + 1;
        list[i].rnti = i + 2000;
        list[i].crcflag = rand() % 2;
    }
    return list;
}

xmlDocPtr parse_xml(const char *xml_data, const char *xpath_query) {
    xmlDocPtr doc = xmlReadMemory(xml_data, XML_ENC_UTF8, NULL);
    if (doc == NULL) {
        fprintf(stderr, "Failed to parse XML data\n");
        return NULL;
    }
    xmlNodeSetPtr nodeset = xmlXPathEvalExpression(xpath_query, doc, NULL, 0);
    if (nodeset == NULL) {
        fprintf(stderr, "No matching nodes found\n");
        xmlFreeDoc(doc);
        return NULL;
    }
    return doc;
}

xmlNodeSetPtr filter_and_sort(xmlDocPtr doc, const char *xpath_filter, const char *xpath_sort) {
    if (doc == NULL || xpath_filter == NULL || xpath_sort == NULL)
        return NULL;

    xmlNodeSetPtr nodeset = xmlXPathEvalExpression(xpath_filter, doc, NULL, 0);
    if (nodeset == NULL) {
        fprintf(stderr, "No matching nodes found\n");
        xmlFreeDoc(doc);
        return NULL;
    }

    int node_count = nodeset->nodeNr;
    if (node_count <= 0) {
        xmlFreeNodeSet(nodeset);
        xmlFreeDoc(doc);
        return NULL;
    }

    xmlNodeSetPtr sorted_nodeset = xmlXPathNodeSetCreate(xpath_sort, doc, XML_XPATH_USE_OPERAND|XML_XPATH_NODESET_PEER);
    if (sorted_nodeset == NULL) {
        fprintf(stderr, "Failed to create sorted nodeset\n");
        xmlFreeNodeSet(nodeset);
        xmlFreeDoc(doc);
        return NULL;
    }

    for (int i = 0; i < node_count - 1; ++i) {
        for (int j = i + 1; j < node_count; ++j) {
            if (xmlCompareNode((xmlNode *)sorted_nodeset->nodeTab[i], (xmlNode *)sorted_nodeset->nodeTab[j]) > 0) {
                xmlNode *temp = sorted_nodeset->nodeTab[i];
                sorted_nodeset->nodeTab[i] = sorted_nodeset->nodeTab[j];
                sorted_nodeset->nodeTab[j] = temp;
            }
        }
    }
    return sorted_nodeset;
}
