}

NFAPI_RX_FRAME_T *allocate() {
    pthread_mutex_lock(&allocator.mutex);
    while (allocator.used_count == SLAB_COUNT) {
        pthread_cond_wait(&allocator.not_empty, &allocator.mutex);
    }

    NFAPI_RX_FRAME_T *frame = allocator.slabs[--allocator.used_count];
    memset(frame, 0, allocator.slab_size);

    pthread_mutex_unlock(&allocator.mutex);
    return frame;
}

void deallocate(NFAPI_RX_FRAME_T *frame) {
    pthread_mutex_lock(&allocator.mutex);
    allocator.slabs[allocator.used_count++] = frame;
    pthread_cond_signal(&allocator.not_empty);
    pthread_mutex_unlock(&allocator.mutex);
}

