void push_frame(NFAPI_RX_FRAME_T *frame) {
    pthread_mutex_lock(&allocator.mutex);
    if (frame_index < MAX_FRAMES) {
        frames[frame_index++] = *frame;
    } else {
        deallocate(frames[0]);
        memcpy(frames + 1, frames, sizeof(NFAPI_RX_FRAME_T) * (frame_index - 1));
        frames[frame_index - 1] = *frame;
    }
    pthread_mutex_unlock(&allocator.mutex);
}

NFAPI_RX_FRAME_T* get_frame(size_t index) {
    pthread_mutex_lock(&allocator.mutex);
    if (index < frame_index) {
        NFAPI_RX_FRAME_T *frame = frames + index;
        pthread_mutex_unlock(&allocator.mutex);
        return frame;
    } else {
        pthread_mutex_unlock(&allocator.mutex);
        return NULL;
    }
}
