#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void read_and_process_integers(int **arr, size_t *size) {
    char line[100];
    size_t capacity = 10000;
    size_t current_capacity = 0;
    size_t i = 0;

    *arr = malloc(capacity * sizeof(int));

    while (fgets(line, sizeof(line), stdin) && strlen(line) > 0) {
        char *token = strtok(line, " \n");
        long long value;

        if (sscanf(token, "%lld", &value) != 1) {
            printf("Invalid input. Expected an integer.\n");
            continue;
        }

        if (current_capacity == capacity) {
            capacity *= 2;
            *arr = realloc(*arr, capacity * sizeof(int));
        }

        (*arr)[i] = (int)value;
        i++;
    }

    if (i == 0) {
        printf("No integers provided.\n");
        free(*arr);
        *arr = NULL;
        *size = 0;
        return;
    }

    qsort((*arr), i, sizeof(int), (int(*)(const void*, const void*))comparator);
    size_t largest_index = find_largest(*arr, i);
    printf("Largest integer: %d at index: %ld\n", (*arr)[largest_index], largest_index);
    *size = i;
}

int comparator(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

size_t find_largest(int *arr, size_t size) {
    size_t largest_index = 0;
    for (size_t i = 1; i < size; ++i) {
        if (*(arr + i) > *(arr + largest_index))
            largest_index = i;
    }
    return largest_index;
}
```

