#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>

enum AppState { INIT, RUNNING, TERMINATING };

static enum AppState current_state = INIT;
static sem_t state_mutex;
static bool log_rate_limited = false;
static time_t last_log_time = 0;
static size_t max_logs = 1000;

void track_application_state(const char *format, ...) {
    if (current_state == TERMINATING || log_rate_limited)
        return;

    sem_wait(&state_mutex);
    current_state++;
    if (current_state > TERMINATING)
        current_state = INIT;
    sem_post(&state_mutex);

    time_t now = time(NULL);
    if (difftime(now, last_log_time) >= 60) {
        log_rate_limited = false;
        last_log_time = now;
    }

    va_list args;
    va_start(args, format);
    char state_message[256];
    snprintf(state_message, sizeof(state_message), format, args...);
    va_end(args);

    printf("%s\n", state_message);
}
```
