import okhttp3.RequestBody;

public class ComprehensivePokemonReport {
 private static final Map<String, Pokemon> cache = new HashMap<>();
 private static final OkHttpClient client = new OkHttpClient();
 private static final boolean VERBOSE_LOGGING = false;

 public static String getReport(Pokemon pokemon) throws IOException {
 if (cache.containsKey(pokemon.getName())) {
 return cache.get(pokemon.getName()).getReport();
 }

 String apiUrl = "https://pokeapi.co/api/v2/pokemon/{name}";
 RequestBody body = RequestBody.create(null, new JSONObject().toString());

 Try {
 Response response = client.newCall(new Request.Builder()
 .url(String.format(apiUrl, pokemon.getName()))
 .post(body)
 .build())
 .execute();

 if (!response.isSuccessful()) {
 throw new IOException("Error fetching Pokemon data");
 }

 JSONObject json = new JSONObject(response.body().string());
 String speciesUrl = json.getString("species");
 String abilitiesUrl = json.getJSONArray("abilities").getJSONObject(0).getString("url");
 String evolutionsUrl = json.has("evolves_from_species") ? json.getJSONObject("evolves_from_species").getString("url") : "";
 String movesUrl = json.getJSONArray("moves").getJSONObject(0).getString("url");

 Response speciesResponse = client.newCall(new Request.Builder()
 .url(speciesUrl)
 .build())
 .execute();

 JSONObject speciesJson = new JSONObject(speciesResponse.body().string());
 String habitat = speciesJson.getJSONObject("version_groups").getJSONObject("generation-v").getJSONArray("versions").getJSONObject(0).getString("location_area_url");

 Response abilitiesResponse = client.newCall(new Request.Builder()
 .url(abilitiesUrl)
 .build())
 .execute();
 JSONArray abilitiesArray = new JSONArray(abilitiesResponse.body().string());
 String ability1 = abilitiesArray.getJSONObject(0).getString("name");

 Response evolutionsResponse = client.newCall(new Request.Builder()
 .url(evolutionsUrl)
 .build())
 .execute();
 JSONObject evolutionsJson = new JSONObject(evolutionsResponse.body().string());
 List<String> evolutionChain = getEvolutionChain(evolutionsJson);

 Response movesResponse = client.newCall(new Request.Builder()
 .url(movesUrl)
 .build())
 .execute();
 JSONArray movesArray = new JSONArray(movesResponse.body().string());
 List<String> notableMoves = getNotableMoves(movesArray);

 String report = "Name: " + pokemon.getName() + "\n";
 report += "Species: " + speciesJson.getString("name") + "\n";
 report += "Habitat: " + getHabitatInfo(habitat) + "\n\n";
 report += "Type: " + pokemon.getType().getName() + "\n";
 report += "Weaknesses:\n";
 switch (pokemon.getType()) {
 case FIRE:
 case FIGHTING:
 case FLYING:
 case PSYCHIC:
 case DARK:
 report += "- Water\n- Ground\n- Rock\n";
 break;
 // Add more cases for other Pokemon types
 }
 report += "Resistances:\n";
 switch (pokemon.getType()) {
 case FIRE:
 report += "- Water\n- Ground\n- Rock\n";
 break;
 // Add more cases for other Pokemon types
 }
 report += "Immunities:\n";
 switch (pokemon.getType()) {
 case FIRE:
 report += "- Ice\n";
 break;
 // Add more cases for other Pokemon types
 }
 report += "\nAbilities:\n- " + ability1 + "\n";
 if (abilitiesArray.length() > 1) {
 report += "- " + abilitiesArray.getJSONObject(1).getString("name") + "\n";
 }
 report += "\nEvolution Chain:\n" + String.join("\n", evolutionChain) + "\n\n";
 report += "Notable Moves:\n" + String.join("\n", notableMoves);

 cache.put(pokemon.getName(), new Pokemon(pokemon.getName(), report));
 return report;
 } catch (IOException e) {
 if (VERBOSE_LOGGING) {
 System.err.println("Error: " + e.getMessage());
 }
 return "Error fetching data from API.";
 }
 }

 private static List<String> getEvolutionChain(JSONObject evolutionsJson) throws IOException {
 List<String> chain = new ArrayList<>();
 JSONObject currentEvolution = evolutionsJson;
 while (currentEvolution != null) {
 String url = currentEvolution.getString("url");
 Response evolutionResponse = client.newCall(new Request.Builder()
 .url(url)
 .build())
 .execute();
 JSONObject evolutionJson = new JSONObject(evolutionResponse.body().string());
 chain.add(0, evolutionJson.getString("name"));
 currentEvolution = evolutionJson.getJSONObject("evolves_from_species");
 }
 return chain;
 }

 private static List<String> getNotableMoves(JSONArray movesArray) {
 List<String> notableMoves = new ArrayList<>();
 for (int i = 0; i < movesArray.length() && notableMoves.size() < 3; i++) {
 JSONObject moveJson = movesArray.getJSONObject(i);
 if (moveJson.getString("machine").equalsIgnoreCase("TM")) {
 notableMoves.add(moveJson.getString("name"));
 }
 }
 return notableMoves;
 }

 private static String getHabitatInfo(String habitatUrl) throws IOException {
 Response habitatResponse = client.newCall(new Request.Builder()
 .url(habitatUrl)
 .build())
 .execute();
 JSONObject habitatJson = new JSONObject(habitatResponse.body().string());
 return habitatJson.getString("name");
 }
}
```

