#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <dlfcn.h>

typedef struct AlgoNode {
    const char *name;
    int id;
    void* (*init)(void);
    void (*encrypt)(void*, const void*, void*);
    void (*decrypt)(void*, const void*, void*);
    void* (*hash)(const void*, const void*, unsigned int*);
    int ref_count;
    struct AlgoNode *prev, *next;
    pthread_mutex_t mutex;
    double cpu_usage;
    unsigned long latency;
    int priority;
} AlgoNode;

typedef struct List {
    AlgoNode* head;
    AlgoNode* tail;
} List;

List list = {NULL, NULL};
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_algo(AlgoNode *node) {
    if (node->init == NULL) return;

    void* handle = dlopen("crypto.so", RTLD_NOW);
    if (!handle) {
        perror("dlopen");
        return;
    }

    node->init = dlsym(handle, node->name);
    node->cpu_usage = 0.0;
    node->latency = 0;
    node->priority = 100;

    dlclose(handle);
}

AlgoNode* find_algo(const char *name) {
    pthread_mutex_lock(&list_mutex);

    AlgoNode *node = list.head;
    while (node != NULL) {
        if (strcmp(node->name, name) == 0) break;
        node = node->next;
    }

    pthread_mutex_unlock(&list_mutex);

    return node;
}

AlgoNode* create_algo(const char *name, int id, void* (*init)(void), void (*encrypt)(void*, const void*, void*), void (*decrypt)(void*, const void*, void*), void* (*hash)(const void*, const void*, unsigned int*), double cpu_usage, unsigned long latency, int priority) {
    AlgoNode *node = (AlgoNode*)malloc(sizeof(AlgoNode));
    if (!node) return NULL;

    node->name = name;
    node->id = id;
    node->init = init;
    node->encrypt = encrypt;
    node->decrypt = decrypt;
    node->hash = hash;
    node->ref_count = 0;
    node->cpu_usage = cpu_usage;
    node->latency = latency;
    node->priority = priority;
    init_algo(node);

    pthread_mutex_init(&node->mutex, NULL);

    return node;
}

void add_to_list(AlgoNode *node) {
    if (!list.head) {
        list.head = node;
        list.tail = node;
    } else {
        list.tail->next = node;
        node->prev = list.tail;
        list.tail = node;
    }
}

void remove_from_list(AlgoNode *node) {
    if (node == list.head) {
        list.head = node->next;
        if (list.head) list.head->prev = NULL;
        else list.tail = NULL;
    } else if (node == list.tail) {
        list.tail = node->prev;
        list.tail->next = NULL;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }
}

void ref_count_inc(AlgoNode *node) {
    pthread_mutex_lock(&node->mutex);
    node->ref_count++;
    pthread_mutex_unlock(&node->mutex);
}

void ref_count_dec(AlgoNode *node) {
    if (--node->ref_count > 0) return;

    pthread_mutex_lock(&node->mutex);

    if (node->ref_count == 0) {
        remove_from_list(node);
        free(node);
    }

    pthread_mutex_unlock(&node->mutex);
}

AlgoNode* get_algo(const char *name) {
    AlgoNode *node = find_algo(name);
    if (!node || !node->init) return NULL;

    ref_count_inc(node);
    return node;
}

void set_algo_cpu_usage(const char *name, double usage) {
    AlgoNode *node = find_algo(name);
    if (!node || !node->init) return;

    pthread_mutex_lock(&node->mutex);
    node->cpu_usage = usage;
    pthread_mutex_unlock(&node->mutex);
}

unsigned long get_algo_latency(const char *name) {
    AlgoNode *node = find_algo(name);
    if (!node || !node->init) return 0;

    return node->latency;
}

int get_algo_priority(const char *name) {
    AlgoNode *node = find_algo(name);
    if (!node || !node->init) return 0;

    return node->priority;
}

void set_algo_priority(const char *name, int priority) {
    AlgoNode *node = find_algo(name);
    if (!node || !node->init) return;

    pthread_mutex_lock(&node->mutex);
    node->priority = priority;
    pthread_mutex_unlock(&node->mutex);
}
```

This code defines a doubly linked list of cryptographic algorithms with the given properties. It uses a system configuration manager to dynamically load and unload algorithms based on runtime environment constraints and user preferences. The initialization is done lazily, and the results are cached for better performance. Memory allocation failures are handled gracefully, ensuring that the linked list remains consistent even if some operations fail. Thread safety is ensured with pthread mutexes.

The function `get_algo` allows users to query the available algorithms, while functions like `set_algo_cpu_usage`, `get_algo_latency`, `get_algo_priority`, and `set_algo_priority` enable users to adjust algorithm performance metrics and priorities dynamically. This code is optimized for memory usage by reusing existing algorithm instances whenever possible.']

