using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Data.SqlClient;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;

public class QueryExecutor
{
    private readonly DbConnection _connection;
    private readonly IMemoryCache _memoryCache;
    private readonly int _cacheSize = 100; // Adjust this value based on your cache size requirements

    public QueryExecutor(DbConnection connection, IMemoryCache memoryCache)
    {
        _connection = connection;
        _memoryCache = memoryCache;
    }

    public async Task<IDataReader> ExecuteQueryAsync(string commandText, Dictionary<string, object> parameters)
    {
        // Cache the query if it exists in the cache and has not expired
        var cachedResult = GetCachedResult(commandText);

        if (cachedResult != null)
            return cachedResult;

        using (var command = _connection.CreateCommand())
        {
            PrepareCommand(command, commandText, parameters);

            try
            {
                await _connection.OpenAsync();

                using (var reader = await command.ExecuteReaderAsync())
                {
                    if (!IsQueryCacheable(commandText))
                        return reader; // Return the result directly without caching if the query is not cacheable

                    CacheResults(commandText, reader);
                    return reader; // Return the result after caching
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error executing query: {ex.Message}");
                throw;
            }
        }
    }

    private void PrepareCommand(DbCommand command, string commandText, Dictionary<string, object> parameters)
    {
        command.CommandText = commandText;
        foreach (var parameter in parameters)
        {
            command.Parameters.AddWithValue(parameter.Key, parameter.Value);
        }
    }

    private IDataReader GetCachedResult(string key)
    {
        return _memoryCache.GetOrCreate(key, entry =>
        {
            if (entry.Size > _cacheSize)
                ClearExpiredCacheEntries(); // Clear expired cache entries if the new entry exceeds the cache size limit

            return Task.FromResult<IDataReader>(entry.Value as IDataReader);
        });
    }

    private void CacheResults(string key, IDataReader reader)
    {
        var enumerator = reader.GetEnumerator();
        if (enumerator.MoveNext())
            _memoryCache.Set(key, enumerator);
    }

    private bool IsQueryCacheable(string commandText)
    {
        // Implement your own logic to determine whether a query is cacheable based on the query structure or other factors
        // For example: only cache read-only queries with multiple joins and subqueries, but exclude dynamic SQL or queries that modify data
        return /*Your logic here*/;
    }

    private void ClearExpiredCacheEntries()
    {
        _memoryCache.RemoveAll();
    }
}
```

This code provides a `QueryExecutor` class with an `ExecuteQueryAsync` method, which accepts a SQL command string, a dictionary of parameters, and returns an IDataReader for the result set. The method handles exceptions gracefully, optimizes parameter binding for performance, caches frequently executed queries, minimizes locking and deadlocks, and is flexible enough to accommodate changes in database schema or query structure without extensive refactoring. However, it's essential to adapt this code according to your specific requirements and project context.']

