["1. PUT endpoint for updating a resource:

```python
from datetime import datetime, timedelta
from flask import Flask, request, jsonify, make_response
from uuid import uuid4
import re

app = Flask(__name__)

RESOURCE_ID_PATTERN = re.compile(r'[a-zA-Z0-9_-]{1,32}')

# Sample data structure for a resource
resources = {}

def generate_id():
    return str(uuid4())

@app.route('/api/v1/resources/<resource_id>', methods=['PUT'])
def update_resource(resource_id):
    if not RESOURCE_ID_PATTERN.match(resource_id):
        return make_response(jsonify({'error': 'Invalid resource ID.'}), 400)

    if resource_id not in resources:
        return make_response(jsonify({'error': 'Resource not found.'}), 404)

    version = request.args.get('version')

    if not version or int(version) < resources[resource_id]['version']:
        return make_response(jsonify({'error': 'Optimistic concurrency control failed.'}), 409)

    data = request.get_json()

    if not data:
        return make_response(jsonify({'error': 'Request body cannot be empty.'}), 400)

    updated_at = datetime.now()
    resources[resource_id]['data'] = data
    resources[resource_id]['version'] += 1
    resources[resource_id]['updated_at'] = updated_at
    resources[resource_id]['deleted_at'] = None
    log_entry(resource_id, 'update', updated_at)

    return make_response(jsonify({'success': True}), 200)

# DELETE endpoint for soft deletion
@app.route('/api/v1/resources/<resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    if not RESOURCE_ID_PATTERN.match(resource_id):
        return make_response(jsonify({'error': 'Invalid resource ID.'}), 400)

    if resource_id not in resources:
        return make_response(jsonify({'error': 'Resource not found.'}), 404)

    resources[resource_id]['deleted_at'] = datetime.now()
    log_entry(resource_id, 'delete')

    return make_response(jsonify({'success': True}), 200)

# DELETE endpoint for permanent deletion after soft delete period
@app.route('/api/v1/resources/<resource_id>/permanent_delete', methods=['DELETE'])
def permanent_delete_resource(resource_id):
    if not RESOURCE_ID_PATTERN.match(resource_id):
        return make_response(jsonify({'error': 'Invalid resource ID.'}), 400)

    if resource_id not in resources or resources[resource_id]['deleted_at'] is None:
        return make_response(jsonify({'error': 'Resource not found or not soft-deleted.'}), 404)

    del resources[resource_id]
    log_entry(resource_id, 'permanent_delete')

    return make_response(jsonify({'success': True}), 200)

# Helper function to log update and delete operations
def log_entry(resource_id, action, timestamp=None):
    user_id = str(uuid4())
    if timestamp is None:
        timestamp = datetime.now()
    log = {
        'user_id': user_id,
        'resource_id': resource_id,
        'action': action,
        'timestamp': timestamp
    }
    # Save the log entry here, for example in a database or a file
```

