import java.io.FileInputStream;
import java.io.IOException;
import java.io.PropertyPermission;
import java.lang.reflect.Constructor;
import java.util.Properties;
import java.util.logging.Level;
import java.util.logging.Logger;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Enumeration;

public class ConfigServiceLoader {
    private static final Logger LOGGER = Logger.getLogger(ConfigServiceLoader.class.getName());
    private static final ConcurrentHashMap<String, ConfigService> CONFIG_SERVICES = new ConcurrentHashMap<>();
    private static final Object LOCK = new Object();

    public synchronized static ConfigService loadConfigService(String configFile) {
        Properties props = new Properties();
        try (FileInputStream fis = new FileInputStream(configFile)) {
            props.load(fis);
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "Failed to load configuration file: {0}", configFile);
            return null;
        }

        if (!validateConfiguration(props)) {
            LOGGER.log(Level.WARNING, "Invalid or incomplete configuration detected: {0}", configFile);
            return null;
        }

        try {
            Class<?> serviceClass = Class.forName(props.getProperty("service.class"));
            Constructor<?> constructor = serviceClass.getDeclaredConstructor();
            constructor.setAccessible(true);
            Object serviceInstance = constructor.newInstance();

            for (Map.Entry<Object, Object> entry : props.entrySet()) {
                if (entry.getKey().startsWith("service.")) {
                    String propertyName = (String) entry.getKey();
                    String propertyValue = (String) entry.getValue();
                    PropertyPermission permission = new PropertyPermission(propertyName, "read");
                    AccessController.doPrivileged((PrivilegedAction<Void>) () -> {
                        System.setProperty(propertyName, propertyValue);
                        return null;
                    });
                }
            }

            ConfigService configService = (ConfigService) serviceInstance;
            CONFIG_SERVICES.putIfAbsent(configFile, configService);
            return configService;
        } catch (ClassNotFoundException | InstantiationException | IllegalAccessException | NoSuchMethodException e) {
            LOGGER.log(Level.SEVERE, "Failed to initialize configuration service: {0}", configFile);
            return null;
        }
    }

    private static boolean validateConfiguration(Properties props) {
        // Implement your validation logic here
        Enumeration<?> keys = props.propertyNames();
        while (keys.hasMoreElements()) {
            String key = (String) keys.nextElement();
            if (!key.startsWith("service.") || props.getProperty(key) == null) {
                return false;
            }
        }
        return true;
    }
}
```

