function dialogAction( $_REQUEST ) {
  const url = 'your_api_url';
  const http = new XMLHttpRequest();
  let data, message;

  // Validate input
  if ( !$_REQUEST.hasOwnProperty('name') || !$_REQUEST.hasOwnProperty('email') || !$_REQUEST.hasOwnProperty('password')) {
    return JSON.stringify({message: 'error'});
  }

  if ($_REQUEST.fields && $_REQUEST.fields.length > 10) {
    return JSON.stringify({message: 'error'});
  }

  // Prepare data based on id presence and sub_action
  let preparedData = {name: $_REQUEST.name, email: $_REQUEST.email, password: $_REQUEST.password};
  if ( $_REQUEST.hasOwnProperty('id') ) {
    const subAction = $_REQUEST.sub_action;
    switch (subAction) {
      case 'update':
        preparedData.id = $_REQUEST.id;
        // Validate updated data and save to db
        break;
      case 'delete':
        preparedData.id = $_REQUEST.id;
        // Prepare delete request
        break;
    }
  } else {
    preparedData.sub_action = 'create';
  }

  http.open('POST', url);
  http.setRequestHeader('Content-Type', 'application/json');
  http.onload = () => {
    data = JSON.parse(http.responseText);
    message = data.message;

    if (message === 'success') {
      // Update dialog fields and send messages for each field in fields array
      const promises = $_REQUEST.fields.map(fieldName => {
        return new Promise((resolve) => {
          http.open('GET', `${url}/${fieldName}`);
          http.onload = () => {
            if (http.responseText !== 'not found') {
              // Update dialog field with the result and send message to parent window
              resolve(true);
            } else {
              resolve(false);
            }
          };
          http.send();
        });
      });

      Promise.all(promises).then((results) => {
        const updatedFields = results.filter(result => result === true).map(result => result.fieldName || ''); // Set field name if available, otherwise set empty string
        message = JSON.stringify({message: 'success', updatedFields});
      });
    }
  };

  http.send(JSON.stringify(preparedData));
  return message;
}
