class DataAggregator extends Transform {
  constructor(options) {
    super(options);
    this._packets = [];
    this._processing = false;
  }

  _transform(chunk, encoding, callback) {
    try {
      const packet = JSON.parse(chunk.toString());
      // Validate the packet here (e.g., using a custom function or library)
      this._packets.push(packet);
    } catch (error) {
      console.error(`Error processing packet: ${error}`);
    } finally {
      callback();
      this._maybeProcessPackets();
    }
  }

  _flush(callback) {
    // Handle any remaining packets and call the callback
    this._maybeProcessPackets(true);
    callback();
  }

  async process() {
    if (this._processing) return;
    this._processing = true;

    let result = [];
    try {
      result = await this._aggregatePackets();
    } catch (error) {
      console.error(`Error aggregating packets: ${error}`);
    } finally {
      this._packets = [];
      this._processing = false;
    }

    return result;
  }

  pause() {
    this.pause();
  }

  resume() {
    this.resume();
  }

  _maybeProcessPackets(force = false) {
    if (!this._processing && (this._packets.length > 10 || force)) { // Adjust the threshold according to your needs
      this.process().catch(error => console.error(`Error during packet processing: ${error}`));
    }
