```javascript
class DataChunk {
  constructor(data) {
    this.buffer = Buffer.from(data);
    this.offset = 0;
    this.length = this.buffer.length;
  }
}

function copyDataChunks(src, dest, count) {
  const srcChunk = new DataChunk(src);
  let destChunk = new Buffer(count);
  let copiedBytes = 0;

  function copyLoop() {
    const remainingSrc = Math.min(count - copiedBytes, srcChunk.length - srcChunk.offset);
    const remainingDest = Math.min(remainingSrc, destChunk.length - copiedBytes);

    if (remainingSrc > 0 && remainingDest > 0) {
      srcChunk.buffer.copy(destChunk, copiedBytes, srcChunk.offset, srcChunk.offset + remainingSrc, remainingDest);
      copiedBytes += remainingDest;
      srcChunk.offset += remainingSrc;
    }

    if (srcChunk.length === srcChunk.offset) {
      srcChunk = null;
    }

    if (copiedBytes < count) {
      setTimeout(() => copyLoop(), 0);
    } else {
      console.log(`${new Date().toISOString()} - Copied ${copiedBytes} bytes from ${srcChunk ? srcChunk.buffer.length : 0} bytes available in source.`);
    }
  }

  if (!srcChunk) {
    throw new Error('Source data chunk is not initialized');
  }

  if (destChunk.byteLength < count) {
    destChunk = Buffer.allocUnsafe(Math.min(count, 1048576)); // Buffer allocation optimized for 1 MB at a time
  }

  copyLoop();
}
```

Java implementation:

```java
import java.io.*;

class DataChunk implements Serializable {
    private static final long serialVersionUID = 1L;
    private byte[] data;
    private int offset;
    private int length;

    public DataChunk(byte[] data) {
        this.data = data;
        this.offset = 0;
        this.length = data.length;
    }

    // Getters and setters for data, offset, and length
}

class Copier {
    public static DataChunk copyDataChunks(DataChunk src, DataChunk dest, int count) throws IOException, ClassNotFoundException {
        byte[] destBytes = new byte[count];
        int copiedBytes = 0;

        ByteArrayInputStream inputStream = null;
        ByteArrayOutputStream outputStream = null;

        try {
            inputStream = new ByteArrayInputStream(src.data);
            outputStream = new ByteArrayOutputStream();

            byte[] buffer = new byte[1024]; // Buffer size optimized for 1 KB at a time
            int bytesRead;

            while ((bytesRead = inputStream.read(buffer)) != -1) {
                int remainingData = Math.min(bytesRead, src.length - src.offset);
                int remainingBuffer = Math.min(remainingData, buffer.length - copiedBytes);
                System.arraycopy(src.data, src.offset, buffer, copiedBytes, remainingData);

                outputStream.write(buffer, 0, remainingBuffer);

                copiedBytes += remainingBuffer;
                src.offset += remainingData;

                if (copiedBytes >= count) {
                    break;
                }
            }

            dest.data = outputStream.toByteArray();
            dest.offset = 0;
            dest.length = copiedBytes;
        } catch (IOException e) {
            throw new RuntimeException("I/O Error occurred while copying data", e);
        } finally {
            if (inputStream != null) inputStream.close();
            if (outputStream != null) outputStream.close();
        }

        if (copiedBytes < count) {
            throw new RuntimeException("Requested byte count exceeds available data");
        }

        System.out.printf("%tc - Copied %d bytes from %d bytes available in source.%n", new Date(), copiedBytes, src.length);

        return dest;
