const formFieldsReport = {};
let validationRulesCache = new Map();
let uiUpdaterInterval;

function fetchValidationRules(field) {
  const url = field.dataset.validationUrl;

  return new Promise((resolve, reject) => {
    if (validationRulesCache.has(url)) {
      resolve(validationRulesCache.get(url));
    } else {
      const xhr = new XMLHttpRequest();
      xhr.open('GET', url);
      xhr.onload = () => {
        if (xhr.status === 200) {
          validationRulesCache.set(url, JSON.parse(xhr.responseText));
          resolve(validationRulesCache.get(url));
        } else {
          // Fallback logic: use rules from a default source or client-side validation if the server is unavailable
          resolve([...fallbackValidationRules][field.name]);
        }
      };
      xhr.onerror = () => reject(new Error('Network error'));
      xhr.send();
    }
  });
}

function validateField(field) {
  return fetchValidationRules(field).then((rules) => {
    const valid = rules.every((rule) => field.value === rule.test || new RegExp(rule.test).test(field.value));
    if (!valid) {
      formFieldsReport[field.name] = { label: field.label, errorMessage: rules[0].message };
    }
  });
}

function collectFormFieldsReports() {
  const forms = document.querySelectorAll('form');
  let reportPromises = [];

  forms.forEach((form) => {
    Array.from(form.elements).forEach((field) => {
      if (field.type !== 'submit') {
        reportPromises.push(validateField(field));
      }
    });
  });

  return Promise.all(reportPromises);
}

function renderReport() {
  const reportContainer = document.getElementById('form-fields-report');
  reportContainer.innerHTML = '';

  for (const [name, data] of Object.entries(formFieldsReport)) {
    const labelElement = document.createElement('label');
    labelElement.textContent = data.label;
    const errorMessageElement = document.createElement('small');
    errorMessageElement.textContent = data.errorMessage;
    errorMessageElement.style.color = 'red';

    const wrapper = document.createElement('div');
    wrapper.appendChild(labelElement);
    wrapper.appendChild(errorMessageElement);

    reportContainer.appendChild(wrapper);
  }
}

async function updateFormFieldsReport() {
  clearInterval(uiUpdaterInterval);

  uiUpdaterInterval = setInterval(async () => {
    try {
      await collectFormFieldsReports();
      renderReport();
    } catch (error) {
      console.error('Error updating form fields report:', error);
    }
  }, 1000);
}

document.addEventListener('DOMContentLoaded', updateFormFieldsReport);
```
