public class AsyncNIOServer {
    private Selector selector;
    private ExecutorService executor;
    private ConcurrentSkipListSet<SocketChannel> connections = new ConcurrentSkipListSet<>();
    private final MessageBroker messageBroker;

    public AsyncNIOServer(int port, MessageBroker messageBroker) throws IOException {
        selector = Selector.open();
        ServerSocketChannel serverSocket = ServerSocketChannel.open();
        serverSocket.socket().bind(new InetSocketAddress(port));
        serverSocket.configureBlocking(false);
        register(serverSocket);
        this.messageBroker = messageBroker;
        executor = Executors.newCachedThreadPool();
    }

    private void register(SelectionKey key) {
        if (key.channel() instanceof ServerSocketChannel) {
            key.interestOps(SelectionKey.OP_ACCEPT);
        } else {
            key.interestOps(SelectionKey.OP_READ | SelectionKey.OP_WRITE);
        }
        selector.register(key);
    }

    private void handleConnections() throws IOException {
        while (true) {
            if (selector.select(100) < 0) break; // Break on interruption, e.g. shutdown signal

            Iterator<SelectionKey> it = selector.selectedKeys().iterator();
            while (it.hasNext()) {
                SelectionKey key = it.next();
                it.remove();

                if (key.isAcceptable()) handleAccept(key);
                else if (key.isReadable()) handleRead(key);
                else if (key.isWritable()) handleWrite(key);
            }
        }
    }

    private void handleAccept(SelectionKey key) throws IOException {
        ServerSocketChannel server = (ServerSocketChannel) key.channel();
        SocketChannel client = server.accept();
        if (client != null) {
            client.configureBlocking(false);
            register(client.register(selector, SelectionKey.OP_READ));
        }
    }

    private void handleRead(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocateDirect(1024);
        int read = channel.read(buffer);
        if (read > 0) {
            buffer.flip();
            handleMessage(channel, buffer);
        } else if (read == -1) {
            connections.remove(channel);
            closeConnection(channel);
        }
    }

    private void handleWrite(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        ByteBuffer buffer = bufferPool.get();
        if (buffer != null) {
            int written = channel.write(buffer);
            if (written > 0) buffer.clear();
            else closeConnection(channel);
        }
    }

    private void handleMessage(SocketChannel channel, ByteBuffer message) throws IOException {
        // Process the message and send a response, ensuring reliable communication with the external messaging system
        // ...

        // Update backpressure mechanism to prevent system overload based on current load conditions
        // ...

        // Set up asynchronous I/O operations for reading and writing, ensuring thread safety and optimal performance
        channel.register(selector, SelectionKey.OP_READ);
    }

    private void closeConnection(SocketChannel channel) throws IOException {
        if (channel != null && channel.isOpen()) channel.close();
    }

    public void start() throws IOException {
        executor.execute(this::handleConnections);
    }

    public void shutdown() {
        selector.wakeup();
        executor.shutdownNow();
        try {
            if (selector != null) selector.close();
        } catch (IOException e) {}
    }
}
