        $this->key = $key;
        $this->initCipher($mode);
    }

    private function initCipher($mode) {
        switch (strtolower($mode)) {
            case 'ecb':
                $this->cipher = openssl_cipher_iv('');
                break;
            case 'ede':
                $this->cipher = openssl_cipher_iv(openssl_random_pseudo_bytes(8));
                break;
            case 'ede3':
                $this->cipher = openssl_cipher_iv(openssl_random_pseudo_bytes(16));
