fn compile(log_sender: TokioSender<CompileReport>) -> Result<(), CompileReport> {
    let icp = ICEHook::new();
    let rss_before = unsafe { libc::getrlimit(libc::RLIMIT_DATA) }.max;

    let mut config = Config::new();
    // Configure logging hook here based on command-line options or environment variables.

    let log_file = OpenOptions::new()
        .write(true)
        .create(true)
        .open("rustc_log.txt")?;
    let stderr = BufWriter::new(log_file);
    config.set_error_handler(|e| {
        let error = CompileError {
            file: e.span().source_info().file().to_string_lossy(),
            line: e.span().source_info().line() as u32,
            message: e.to_string(),
        };
        log_sender.send(CompileReport {
            duration: 0.,
            resident_set_size_before: rss_before,
            resident_set_size_after: unsafe { libc::getrlimit(libc::RLIMIT_DATA) }.max as usize,
            peak_memory_usage: 0,
            errors: vec![error],
        })
        .unwrap();
        e.abort()
    });

    let mut child = run(&config)?;

    tokio::spawn(async move {
        let duration = std::time::Instant::now();
        child.wait().await?;
        let elapsed = duration.elapsed().as_secs_f64();

        let rss_after = unsafe { libc::getrlimit(libc::RLIMIT_DATA) }.max as usize;
        let peak_memory_usage = child.peak_rss() as usize;

        log_sender.send(CompileReport {
            duration: elapsed,
            resident_set_size_before,
            resident_set_size_after,
            peak_memory_usage,
            errors: vec![],
        })
        .unwrap();
    });

    catch_with_exit_code(child, stderr)?;
    Ok(())
}

fn main() {
    let (log_sender, log_receiver) = channel(10);
    tokio::runtime::Builder::new_multi_thread()
        .build_async()
        .expect("Failed to create a Tokio runtime.")
        .block_on(async move {
            match compile(log_sender).await {
                Ok(_) => {
                    // Compilation successful, now we can process the report received on log_receiver.
                    let report = log_receiver.recv().await;
                    if !report.errors.is_empty() {
                        println!("{}", format_error_report(&report));
                    } else {
                        println!("Compilation successful!");
                    }
                }
                Err(report) => {
                    // Compilation failed, now we can process the error report received on log_receiver.
                    let report = log_receiver.recv().await;
                    if !report.errors.is_empty() {
                        println!("{}", format_error_report(&report));
                    } else {
                        println!("Compilation failed with error: {}", report);
                    }
                }
            }
        });
}

fn format_error_report(report: &CompileReport) -> String {
    let errors = report.errors.iter().map(|e| {
        format!(
            "{}:{}\n  error: {}",
            e.file, e.line, e.message
        )
    });
    let mut sb = String::new();
    for (i, e) in errors.enumerate() {
        if i != 0 {
            sb.push_str("\n---\n");
        }
        sb.push_str(e);
    }
    sb
}
