        public DataTable GetEmployeesBySupervisorId(int supervisorId, int offset, int limit)
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                connection.Open();

                var command = new SqlCommand("GetEmployeesBySupervisorId", connection);
                command.CommandType = CommandType.StoredProcedure;

                var parameterSupervisorId = new SqlParameter("@supervisorId", supervisorId);
                parameterSupervisorId.SqlDbType = SqlDbType.Int;
                command.Parameters.Add(parameterSupervisorId);

                var parameterOffset = new SqlParameter("@offset", offset);
                parameterOffset.SqlDbType = SqlDbType.Int;
                command.Parameters.Add(parameterOffset);

                var parameterLimit = new SqlParameter("@limit", limit);
                parameterLimit.SqlDbType = SqlDbType.Int;
                command.Parameters.Add(parameterLimit);

                using (var dataAdapter = new SqlDataAdapter(command))
                {
                    var returnParam = new SqlParameter("@results", SqlDbType.Structured);
                    returnParam.Direction = ParameterDirection.ReturnValue;
                    command.Parameters.Add(returnParam);

                    dataAdapter.Fill(new DataTable(), "employeeResults");

                    var employeeTable = new DataTable();
                    employeeTable.Columns.CopyFrom(dataAdapter.SelectCommand.Connection.GetSchemaTable("columns", null).Rows.Find("name", "employeeResults"));
                    employeeTable.Merge(dataAdapter.SelectCommand.Connection.GetSchemaTable("columns", null).Rows.Find("name", "@results"));
                    employeeTable.Merge(dataAdapter.SelectCommand.Connection.CreateCommand().ExecuteReader(CommandBehavior.SchemaOnly));

                    using (var reader = dataAdapter.SelectCommand.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            var employeeRow = employeeTable.NewRow();
                            employeeRow["Name"] = Decrypt(reader["Name"] as byte[]);
                            employeeRow["City"] = reader["City"];
                            employeeRow["Address"] = reader["Address"];
                            employeeTable.Rows.Add(employeeRow);
                        }
                    }

                    return employeeTable;
                }
            }
        }

        private byte[] Decrypt(byte[] cipherText)
        {
            using (var aes = Aes.Create())
            {
                using (var msEncrypt = new MemoryStream())
                {
                    using (var cryptographStreamEncrypt = aes.CreateEncryptor(_key, _IV).CreateCryptoStream(msEncrypt, CryptoStreamMode.Write))
                        cryptographStreamEncrypt.Write(cipherText, 0, cipherText.Length);
                    cryptographStreamEncrypt.FlushFinalBlock();
                    return msEncrypt.ToArray();
                }
            }
        }
    }
}
