        // Validate password complexity and check for active sessions using DAO
        $validationResult = $this->validatePasswordComplexityAndCheckActiveSessions($userId, $newPassword);

        if (!$validationResult['success']) {
            return new Response($validationResult['message'], $validationResult['status_code']);
