        // Compute MD5 hash for the new password in batches to optimize memory usage
        $md5Hasher = new Md5Hasher();
        $batchSize = 100;
        $hashedPasswords = [];
        foreach (new ArrayIterator(str_split($newPassword)) as $chunk) {
            if (!empty($chunk)) {
                $hashedPasswords[] = $md5Hasher->hash($chunk);

                if (count($hashedPasswords) === $batchSize) {
                    list($updated, $errors) = $this->dao->updateUserPasswordInBatch($userId, $hashedPasswords);
                    $hashedPasswords = []; // Reset the batch for the next iteration

                    if (empty($updated)) {
                        return new Response('Failed to update user password.', 500);
