bool filter_transaction(const Transaction& transaction) {
    auto now = chrono::high_resolution_clock::now().time_since_epoch().count();
    int64_t age = now - transaction.timestamp;
    if (age > 15000000000) return false; // Ignore transactions older than 15 seconds
    auto& recentTransactions = TransactionManager::getRecentTransactions();
