#include <fstream>
#include <sstream>
#include <string>
#include <unordered_map>
#include <boost/filesystem.hpp>
#include <nlohmann/json.hpp>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>

using json = nlohmann::json;
using namespace std;
using boost::filesystem::path;

class ResourceBundleCache {
public:
    ResourceBundleCache() : m_mutex(), m_cache{}, m_lastModified{} {}

    unordered_map<string, json> load(const string& filePath) {
        lock_guard<mutex> lock(m_mutex);
        if (auto it = m_cache.find(filePath); it != m_cache.end() && !it->second.empty()) {
            return it->second;
        }

        path p(filePath);
        if (!exists(p) || !is_regular_file(p)) {
            cerr << "Invalid or missing file: " << filePath << endl;
            return {};
        }

        stringstream ss;
        if (p.extension() == ".txt") {
            ifstream ifs(filePath);
            if (!ifs) {
                cerr << "Could not open file: " << filePath << endl;
                return {};
            }
            string line;
            while (getline(ifs, line)) {
                size_t pos = line.find(':');
                if (pos == string::npos) continue;
                ss << line.substr(0, pos) << ',' << line.substr(pos + 1) << endl;
            }
        } else if (p.extension() == ".json") {
            ifstream ifs(filePath);
            if (!ifs) {
                cerr << "Could not open file: " << filePath << endl;
                return {};
            }
            ss << ifs.rdbuf();
        }

        json j;
        try {
            j = json::parse(ss.str());
        } catch (const exception& e) {
            cerr << "Invalid JSON in file: " << filePath << endl;
            return {};
        }

        if (!j.is_array()) {
            cerr << "File is not a valid array: " << filePath << endl;
            return {};
        }

        m_cache[filePath] = j;
        m_lastModified = modified_time(p);

        return j;
    }

    time_t getLastModified() const {
        lock_guard<mutex> lock(m_mutex);
        return m_lastModified;
    }

private:
    mutex m_mutex;
    unordered_map<string, json> m_cache;
    time_t m_lastModified;
};
```

This class provides a simple cache for resource bundles. The `load()` method takes a file path and attempts to load its content from either a .txt or .json file. In case of errors, it returns an empty json object. The `getLastModified()` method retrieves the last modified time of the most recently loaded resource bundle.

To make this implementation thread-safe, use multiple instances of `ResourceBundleCache` for different scopes or utilize a more advanced synchronization mechanism such as `std::shared_mutex`. Additionally, consider using a cache invalidation strategy based on file modification timestamps and/or periodic revalidation to balance between memory usage, performance, and data consistency.

This implementation does not cover stress tests, edge cases, or network failures. You may want to use Google Test (gtest) or other unit testing frameworks for writing the tests.']

