char *safe_append_slash(const char *input, size_t limit, char *buffer) {
    if (input == NULL || buffer == NULL) {
        return NULL;
    }

    size_t input_len = strlen(input);
    if (input_len > limit) {
        size_t truncated_len = (limit > 0 ? limit : 1);
        char *truncated_input = malloc(truncated_len + 1);
        if (!truncated_input) {
            return NULL;
        }
        memcpy(truncated_input, input, truncated_len < input_len ? truncated_len : input_len);
        truncated_input[truncated_len] = '\0';
        snprintf(buffer, limit + 1, "%s/%s", (truncated_len == input_len) ? input : truncated_input, (truncated_len == input_len) ? "" : "TRUNCATED");
        free(truncated_input);
    } else {
        snprintf(buffer, limit + 1, "%s/", input);
    }

    if (strlen(buffer) >= limit) {
        printf("Buffer overflow warning: The string exceeded the specified buffer size.\n");
        return NULL;
    }

    return buffer;
}
