int aes_init(unsigned char *key, unsigned char *iv, const char *password, int max_attempts) {
    unsigned char key_buf[AES_KEYSIZE_256 / 8], iv_buf[AES_BLOCK_SIZE];
    int attempts = 0;
    EVP_CIPHER_CTX* ctx = NULL;
    RAND_bytes(salt, sizeof(salt));

    for (attempts = 0; attempts < max_attempts; ++attempts) {
        EVP_MD_CTX *md_ctx = EVP_MD_CTX_new();
        if (!md_ctx) return 1; // Handle memory allocation errors

        HMAC(EVP_sha256(), salt, sizeof(salt), (unsigned char*)password, strlen((char*)password), key_buf, NULL);

        ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            EVP_MD_CTX_free(md_ctx); // Clean up resources on failure
            return 1;
        }

        if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key_buf, iv_buf)) {
            EVP_CIPHER_CTX_free(ctx);
            EVP_MD_CTX_free(md_ctx);
            continue; // Increment attempts and retry if the key derivation fails
        }

        unsigned char test_iv[AES_BLOCK_SIZE];
        size_t test_iv_len = AES_BLOCK_SIZE;

        if (1 != EVP_CIPHER_CTX_ctrl(ctx, SSL_CTRL_SET_IV, test_iv, &test_iv_len)) {
            continue; // Increment attempts and retry if the IV derivation fails
        }

        if (memcmp(test_iv, iv_buf, AES_BLOCK_SIZE) == 0) {
            EVP_CIPHER_CTX_free(ctx);
            EVP_MD_CTX_free(md_ctx);
            memcpy(key, key_buf, sizeof(key_buf));
            memcpy(iv, iv_buf, sizeof(iv_buf));
            return 0; // Derivation succeeded, exit the loop
        }
    }

    EVP_MD_CTX_free(md_ctx);
    EVP_CIPHER_CTX_free(ctx);

    fprintf(stderr, "AES-256-CBC key derivation failed. Exiting.\n");
    return 1;
}
```

