typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void *aes_init(const char *password) {
    size_t password_len = strlen(password);
    if (password_len < AES_KEYSIZE_256) {
        char padding[AES_KEYSIZE_256];
        memset(padding, RAND_bytes(AES_KEYSIZE_256), AES_KEYSIZE_256);
        password = padding;
    }

    unsigned char key[AES_BLOCK_SIZE + AES_KEYSIZE_256];
    size_t prf_len = EVP_PKCS5_HMAC(EVP_sha256(), password, password_len, NULL, key, sizeof(key));
    key += prf_len;

    unsigned char iv[AES_BLOCK_SIZE];
    memset(iv, 0, AES_BLOCK_SIZE);

    AES_KEY aes;
    AES_set_encrypt_key((const unsigned char *)key, AES_KEYSIZE_256, &aes);

    void *ctx = AES_CTX_new();
    AES_ctx_init(&aes, iv, ctx);

    return ctx;
}

NFAPI_CRC_INDICATION_PDU_T **create_pdu_array(size_t N) {
    NFAPI_CRC_INDICATION_PDU_T **arr = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    for (size_t i = 0; i < N; ++i) {
        arr[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memset(arr[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    return arr;
}

void populate_pdus(NFAPI_CRC_INDICATION_PDU_T **arr, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        arr[i]->RX_UE_INFORMATION_TAG = rand() % 0xFFFFFFFF + 1;
        arr[i]->RNTI = rand() % 0xFFFF + 1;
        arr[i]->CRC_INDICATION_REL8_TAG = rand() % 0xFF;
        arr[i]->CRCFLAG = (rand() & 1) != 0;
    }
}

void xpath_filter(xmlDocPtr doc, const char *xpath, const char *attribute, const char *value, xmlNodeSetPtr nodeset) {
    xmlXPathObjectPtr res = xmlXPathEvalExpression((xmlChar *)xpath, doc);
    if (res && res->nodeSet.nodeNr > 0) {
        for (unsigned i = 0; i < res->nodeSet.nodeNr; ++i) {
            xmlNodePtr cur = res->nodeSet.tab[i];
            if (cur->properties == NULL || !(xmlHasProp(cur, (const xmlChar *)attribute)) || strcmp((char*)xmlGetProp((xmlNodePtr)cur, (const xmlChar *)attribute), (char *)value)) {
                continue;
            }
            xmlAddChild((xmlNodePtr)nodeset, cur->xmlChildrenNode);
        }
    }
    xmlXPathFreeObject(res);
}

void xpath_sort(xmlNodeSetPtr nodeset) {
    if (nodeset->nodeNr <= 1) return;

    qsort((void *)nodeset->tab, nodeset->nodeNr, sizeof(xmlNode), xmlNodeCompare);
}

xmlNodeSetPtr xpath_parse(xmlDocPtr doc, const char *xpath, const char *attribute1, const char *value1, const char *attribute2) {
    xmlNodeSetPtr nodeset = xmlNewNodeSet();
    if (nodeset == NULL) return NULL;

    xmlXPathObjectPtr res1 = xmlXPathEvalExpression((xmlChar *)xpath, doc);
    if (res1 == NULL || res1->nodeSet.nodeNr <= 0) goto end;

    xpath_filter(doc, xpath, attribute1, value1, nodeset);

    if (attribute2 != NULL && nodeset->nodeNr > 1) {
        xpath_sort(nodeset);
    }

end:
    xmlXPathFreeObject(res1);
    return nodeset;
}

void aes_free(void *ctx) {
    AES_CTX_free((AES_CTX *)ctx);
}
