// Custom salt for deriving the encryption key
unsigned char salt[] = {0x49, 0x76, 0x61, 0x6e, 0x20, 0x32, 0x56, 0x65, 0x72, 0x65, 0x6E, 0x69, 0x67, 0x68, 0x74, 0x50};

