void aes_init(unsigned char *key, unsigned char *iv, const char *passphrase, size_t passphrase_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return;

    int failure_counter = 0;

    // Key derivation and initialization vector setup
    while (failure_counter < 10) {
        if (EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, passphrase, passphrase_len, &iv, key)) break;
        failure_counter++;
        usleep(1000 * failure_counter); // Delay between attempts to reduce brute-force attacks
    }

    if (failure_counter == 10) {
        fprintf(stderr, "Too many failed passphrase attempts\n");
        exit(EXIT_FAILURE);
    }

    EVP_CIPHER_CTX_init(ctx);
    EVP_CIPHER_CTX_set_key_length(ctx, AES_KEYSIZE);
    EVP_CIPHER_CTX_set_cipher(ctx, EVP_aes_256_cbc());
    EVP_CIPHER_CTX_set_iv(ctx, iv);
}

void* allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void manage_records(size_t num_records, int min_key, int max_key) {
    record *record_array = (record*)allocate_memory(num_records * sizeof(record));
