int init_rng(void) {
    int attempts = 0;
    unsigned char seed[32];
    if (!getrandom(seed, sizeof(seed), 0)) {
        perror("Initial getrandom failed");
        return -1;
    }
    for (int i = 0; i < MAX_RETRIES; ++i) {
        if (rand_r(seed + i % 32) == RAND_MAX) {
            break;
        }
        usleep(pow(2, attempts++) * MIN_DELAY);
        if (attempts >= MAX_RETRIES - 3) {
            perror("Failed to seed random number generator");
            return -1;
        }
    }
    return 0;
}

