#include <openssl/rand.h>
#include <openssl/gcm.h>

typedef struct {
    AES_KEY aes;
    unsigned char iv[AES_BLOCK_SIZE + 128 / 8]; // IV and tag combined
} AES_GCM_ctx;

void AES_GCM_init(AES_GCM_ctx* ctx, const char* passphrase, size_t key_len, unsigned int iterations, unsigned char salt[]) {
    EVP_CIPHER_CTX* pkcs5 = EVP_PKCS5_CTX_new();
    unsigned char key[AES_BLOCK_SIZE];
    int key_len_out;

    PKCS5_deriveKey(pkcs5, PBKDF2, passphrase, strlen(passphrase), salt, iterations, EVP_aes_128_gcm(), key, sizeof(key), &key_len_out);

    AES_set_encrypt_key(key, key_len_out * 8, &ctx->aes);

    for (size_t i = 0; i < sizeof(ctx->iv); ++i) {
        ctx->iv[i] = Rand_bytes_exact(1)[0];
    }
}

void AES_GCM_encrypt(AES_GCM_ctx* ctx, const unsigned char* nonce, const unsigned char* input, unsigned char* output) {
    GCMP_KEY gcm_key = ctx->aes;
    unsigned int len = strlen((const char*)input);
    unsigned char tag[GCM_TAG_LENGTH];

    GCM(len + sizeof(tag), nonce, input, output, &gcm_key, ctx->iv, tag);
}

void AES_GCM_cleanup(AES_GCM_ctx* ctx) {
    EVP_CIPHER_CTX_free(ctx->aes.ctx);
}
