#include <fcntl.h>
#include <sys/mman.h>
#include <boost/log/trivial.hpp>
#include <zlib.h>

struct worker_args {
    char* input_file;
    char* output_format;
    size_t batch_size;
    sem_t* sem;
};

void* process_file(void* args) {
    struct worker_args* data = args;
    // read, parse, transform and write the file...
}

int main(int argc, char** argv) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s input_directory output_format num_workers batch_size\n", argv[0]);
        return -1;
    }

    const char* input_dir = argv[1];
    const char* out_fmt = argv[2];
    int num_workers = atoi(argv[3]);
    size_t batch_size = atoll(argv[4]);

    // Initialize logging, external services, etc.
    BOOST_LOG_TRIVIAL(info) << "Initializing...";

    // Prepare the input directory and create worker threads
    DIR* dir = opendir(input_dir);
    if (!dir) {
        perror("opendir");
        return -1;
    }

    struct dirent* entry;
    pthread_t workers[num_workers];
    sem_t* semaphore = sem_init(0, 0, num_workers);

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        struct stat st;
        lstat(entry->d_name, &st);
        if (!S_ISREG(st.st_mode))
            continue;

        char* input_path = malloc((strlen(input_dir) + strlen(entry->d_name) + 2) * sizeof(char));
        sprintf(input_path, "%s/%s", input_dir, entry->d_name);

        struct worker_args* args = malloc(sizeof(struct worker_args));
        args->input_file = input_path;
        args->output_format = out_fmt;
        args->batch_size = batch_size;
        args->sem = semaphore;

        pthread_create(&workers[pthread_self() % num_workers], NULL, process_file, args);
    }

    closedir(dir);

    // Wait for all threads to finish
    for (int i = 0; i < num_workers; ++i) {
        pthread_join(workers[i], NULL);
    }

    return 0;
}
```

This code reads a directory, creates worker threads to process its contents concurrently, and provides a simple mechanism for adjusting the batch size based on command-line arguments. The actual file processing is left as an exercise to the reader, as it depends on the specific requirements of your use case.']

