LTE_ENB_CONTEXT_MANAGER_T *lte_enb_context_manager_init(size_t initial_capacity) {
    LTE_ENB_CONTEXT_MANAGER_T *manager = malloc(sizeof(LTE_ENB_CONTEXT_MANAGER_T));
    manager->array = calloc(initial_capacity, sizeof(LTE_ENB_CONTEXT_T));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void lte_enb_context_manager_destroy(LTE_ENB_CONTEXT_MANAGER_T *manager) {
    free(manager->array);
    free(manager);
}

int lte_enb_context_add(LTE_ENB_CONTEXT_MANAGER_T *manager, PHY_VARS_eNB *phy, RRC_INST_eNB *rrc, int DL_BANDWIDTH, int UL_BANDWIDTH, int CELL_ID) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size == manager->capacity) {
        LTE_ENB_CONTEXT_T *tmp = realloc(manager->array, manager->capacity * 2 * sizeof(LTE_ENB_CONTEXT_T));
        if (!tmp) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Memory allocation failure
        }
        manager->array = tmp;
        manager->capacity *= 2;
    }

    LTE_ENB_CONTEXT_T *context = &manager->array[manager->size];
    context->phy = phy;
    context->rrc = rrc;
    context->DL_BANDWIDTH = DL_BANDWIDTH;
    context->UL_BANDWIDTH = UL_BANDWIDTH;
    context->CELL_ID = CELL_ID;

    // Initialize PHY_VARS_eNB pointers based on configuration parameters
    // ...

    manager->size++;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

LTE_ENB_CONTEXT_T *lte_enb_context_get(LTE_ENB_CONTEXT_MANAGER_T *manager, size_t index) {
    pthread_mutex_lock(&manager->mutex);

    if (index >= manager->size) {
        pthread_mutex_unlock(&manager->mutex);
        return NULL; // Index out of range
    }

    LTE_ENB_CONTEXT_T *context = &manager->array[index];
    pthread_mutex_unlock(&manager->mutex);
    return context;
}
