    list->lock = PTHREAD_MUTEX_INITIALIZER;
    list->max_connections = max_connections;
    list->memory_limit = memory_limit;
    list->log_level = log_level;
}

TCP_CONNECTION_T* create_connection(const struct sockaddr_in* remote_address) {
    TCP_CONNECTION_T* conn = malloc(sizeof(TCP_CONNECTION_T));
    if (!conn) return NULL;
    memset(conn, 0, sizeof(TCP_CONNECTION_T));
    conn->remote_address = *remote_address;
    return conn;
}

void free_connection(TCP_CONNECTION_T* conn) {
    free(conn);
}

struct memory_block* allocate_memory_block() {
    struct memory_block* block = malloc(sizeof(struct memory_block));
    if (!block) return NULL;
    block->used = 0;
    block->next = NULL;
    return block;
}

void deallocate_memory_block(struct memory_block** head) {
    struct memory_block* current = *head, *next;

    pthread_mutex_lock(&((*head)->next)->lock);
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = next;
    pthread_mutex_unlock(&((*head)->next)->lock);
}

int add_connection(struct connection_list* list, TCP_CONNECTION_T* conn) {
    struct memory_block* current = list->head;
    struct memory_block* new_block;

    if (current == NULL || current->used == list->max_connections) {
        // Allocate a new memory block if necessary
        new_block = allocate_memory_block();
        if (!new_block) return -1;

        pthread_mutex_lock(&list->lock);
        new_block->next = list->head;
        list->head = new_block;
        pthread_mutex_unlock(&list->lock);
    }

    if (current->used == list->max_connections) {
        // Evict connections from the current block if it's full
        for (int i = 0; i < list->max_connections; ++i) {
            if (!current->connections[i]) {
                current->connections[i] = conn;
                current->used++;
                return 0;
            }
        }
    } else {
        // Add the connection to the current block if there's room
        for (int i = 0; i < list->max_connections; ++i) {
            if (!current->connections[i]) {
                current->connections[i] = conn;
                current->used++;
                return 0;
            }
        }
    }

    // Move to the next memory block and repeat the process
    current = current->next;

    if (current != NULL) {
        pthread_mutex_lock(&current->lock);
        if (current->used < list->max_connections) {
            for (int i = 0; i < list->max_connections; ++i) {
                if (!current->connections[i]) {
                    current->connections[i] = conn;
                    current->used++;
                    return 0;
                }
            }
        }
        pthread_mutex_unlock(&current->lock);
    }

    // If no room is found, the connection cannot be added
    return -1;
}

TCP_CONNECTION_T* remove_connection(struct connection_list* list, TCP_CONNECTION_T* conn) {
    struct memory_block* current = list->head;

    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        for (int i = 0; i < list->max_connections; ++i) {
            if (current->connections[i] == conn) {
                current->connections[i] = NULL;
                current->used--;
                pthread_mutex_unlock(&list->lock);
                return conn;
            }
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    // Connection not found in the list
    return NULL;
}

void traverse_connections(struct connection_list* list, void (*fn)(TCP_CONNECTION_T*)) {
    struct memory_block* current = list->head;

    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        for (int i = 0; i < list->max_connections; ++i) {
            if (current->connections[i]) {
                (*fn)(current->connections[i]);
            }
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}
```

