const OldTestamentBooksRegex = {
  "Genesis": /\bGenesis\b/,
  "Exodus": /\bExodus\b/,
  "Leviticus": /\bLeviticus\b/,
  // Add more books here...
};

const maxAttempts = parseInt(process.env.MAX_ATTEMPTS || 3);
const logLevel = process.env.LOG_LEVEL || 'info';
const loggingFramework = require('./logging-framework');

let extractedBooks = {};
let concurrentInstances = 0;

function extractBookMentions(text) {
  concurrentInstances++;

  Object.entries(OldTestamentBooksRegex).forEach(([book, regex]) => {
    let match;
    for (let i = 1; i <= maxAttempts && !match; i++) {
      match = text.match(regex);
      if (!match) continue;

      const count = (extractedBooks[book] || 0) + 1;
      extractedBooks[book] = count;

      loggingFramework.log({
        level: logLevel,
        message: `Successfully extracted book "${book}" with frequency ${count} from the text`,
      });

      concurrentInstances--;
      if (concurrentInstances === 0) return;
    }

    if (!match) {
      loggingFramework.log({
        level: logLevel,
        message: `Failed to extract book "${book}" after ${maxAttempts} attempts`,
      });
    }
  });
}

module.exports = {
  extractBookMentions,
};
