[' ```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

typedef struct Record {
    long offset;
    int key;
    struct Record *prev, *next;
} Record;

Record* create_record() {
    Record *rec = malloc(sizeof(Record));
    rec->offset = 0;
    rec->key = -1; // Uninitialized
    rec->prev = rec->next = NULL;
    return rec;
}

void read_keys(FILE *file, Record **head) {
    char line[256];
    int i = 0;
    while (fgets(line, sizeof(line), file)) {
        if (!head || !*head) {
            *head = create_record();
            (*head)->key = atoi(line);
            continue;
        }
        Record *temp = create_record();
        temp->key = atoi(line);
        temp->prev = (*head);
        temp->next = (*head)->next;
        if (temp->next) {
            temp->next->prev = temp;
        }
        (*head)->next = temp;
        (*head) = temp;
    }
}

void randomize_keys(Record *head, int min, int max) {
    Record *current = head;
    for (; current != NULL; current = current->next) {
        if (current->key == -1) {
            current->key = rand() % (max - min + 1) + min;
        }
    }
}

Record* handle_file(const char *filename, int num_records, int *error) {
    Record *head = NULL;
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Could not open file %s\n", filename);
        *error = 1;
        return NULL;
    }

    int lines_read = 0;
    while (lines_read < num_records && fgets(line, sizeof(line), file)) {
        if (!head || !*head) {
            head = create_record();
            continue;
        }
        Record *temp = create_record();
        temp->key = -1; // Uninitialized
        if (fscanf(file, "%*[^\n]\n") != EOF) {
            lines_read++;
        } else {
            fprintf(stderr, "Warning: Malformed line in keys.txt\n");
            continue;
        }
        temp->key = atoi(line);
        if (temp->key <= 0 || temp->key > 1000) {
            fprintf(stderr, "Warning: Invalid key value %d in keys.txt\n", temp->key);
            temp->key = 0;
        }
        if (!head || !*head) {
            *head = temp;
        } else {
            Record *current = head;
            for (; current->next != NULL; current = current->next) {}
            current->next = temp;
            temp->prev = current;
        }
    }

    if (feof(file)) {
        fclose(file);
        if (lines_read < num_records) {
            fprintf(stderr, "Warning: Number of records read (%d) less than expected number (%d)\n", lines_read, num_records);
        }
    } else {
        fprintf(stderr, "Error: Unexpected end-of-file in keys.txt\n");
        *error = 1;
    }

    if (lines_read < num_records) {
        randomize_keys(head, min, max);
    } else if (num_records != lines_read + ferror(file)) {
        fprintf(stderr, "Error: Incomplete or corrupted file %s\n", filename);
        *error = 1;
    }

    fclose(file);
    return head;
}

void free_records(Record **head) {
    Record *current = *head;
    while (current != NULL) {
        Record *temp = current->next;
        free(current);
        current = temp;
    }
    *head = NULL;
}

void log_output(const char *message, ...) {
    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    va_list args;
    va_start(args, message);
    vfprintf(stderr, message, args);
    va_end(args);
}

int main() {
    const char *filename = "keys.txt";
    int num_records = 1000;
    int error = 0;

    Record *head = handle_file(filename, num_records, &error);

    if (!error) {
        log_output("Read %d records from file.\n", num_records);
        randomize_keys(head, 1, 1000);
    } else {
        log_output("Error while reading keys: Exiting...\n");
        return 1;
    }

    free_records(&head);
    return 0;
}
```

This C code handles the given programming task with a focus on memory management for multiple data structures and file operations. It uses a doubly linked list to store `struct record` objects containing an offset and key, reads keys from a file, or generates random keys if the file is not found or unreadable. The custom random number generator ensures better distribution and determinism using a fixed seed based on the current time.

The code also handles cyclic references within the linked list, dynamic resizing of the list, error handling for file operations, and logging to track processed records and any errors encountered during file operations.']

