        while (true) {
            std::pair<size_t, LTE_ENB_CONTEXT_T*> action;
            if (!actionQueue_.try_pop(action))
                break; // All actions have been processed

            auto& context = *action.second;
            // Perform the operation based on the action type here
        }
    }

private:
    void compressArray() {
