['```c
#include <openssl/aes.h>
#include <openssl/pbkdf2.h>
#include <openssl/err.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    AES_KEY aes;
    unsigned char iv[16];
} AESGCM_CONTEXT;

void AESGCM_init(AESGCM_CONTEXT* ctx, const char* passphrase, size_t keySize, const uint8_t* salt, unsigned int iterations) {
    EVP_CIPHER_CTX* keyGenCtx = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX* derivingCtx = EVP_CIPHER_CTX_new();
    size_t saltLen = sizeof(salt);
    unsigned char key[32];
    unsigned char tmp_iv[16];

    // Set key-deriving algorithm to PBKDF2 with HMAC-SHA256 and initialise the context
    EVP_PBKDF2_init(derivingCtx);
    EVP_CIPHER_CTX_set_key_length(derivingCtx, 32); // AES-128 key length is 32 bytes

    // Set salt and iteration count for the PBKDF2 key derivation function
    EVP_CIPHER_CTX_set_pbkdf2_param(derivingCtx, salt, saltLen, iterations);

    // Derive a key from the passphrase using PBKDF2
    EVP_PBKDF2(keyGenCtx, key, sizeof(key), passphrase, strlen(passphrase), derivingCtx);

    // Determine IV length based on key size (16 bytes for AES-128-GCM) or use the full 16 bytes if keySize is less than 16
    size_t ivLen = keySize < 16 ? keySize : 16;

    // Set up cipher context with derived key and IV
    AES_set_encrypt_key(key, keySize, &ctx->aes);
    memcpy(tmp_iv, ctx->iv, ivLen);

    // If the IV length is less than 16 bytes, append a pseudo-random value to complete it
    if (ivLen < 16) {
        AESGCM_derive_iv(ctx, derivingCtx, passphrase, salt, iterations, tmp_iv);
    }

    // Copy derived IV into the context structure
    memcpy(ctx->iv, tmp_iv, 16);

    // Clean up resources
    EVP_CIPHER_CTX_free(keyGenCtx);
    EVP_CIPHER_CTX_free(derivingCtx);
}

void AESGCM_derive_iv(AESGCM_CONTEXT* ctx, EVP_CIPHER_CTX* derivingCtx, const char* passphrase, const uint8_t* salt, unsigned int iterations, unsigned char* iv) {
    // Derive the IV using PBKDF2 as per RFC 5116 section 9.3.2
    EVP_PBKDF2(ctx->aes.ctx, iv + 16 - ctx->aes.key_len, ctx->aes.key_len, passphrase, strlen(passphrase), derivingCtx);
    EVP_CIPHER_CTX_free(derivingCtx);
}

void AESGCM_cleanup(AESGCM_CONTEXT* ctx) {
    memset(&ctx->aes, 0, sizeof(ctx->aes));
    memset(ctx->iv, 0, sizeof(ctx->iv));
}
```

This code defines a structure `AESGCM_CONTEXT` that holds an AES-128-GCM cipher context and its initialization vector (IV). The function `AESGCM_init()` initializes the cipher with a given passphrase, dynamically adjusts the IV length based on the specified key size, derives the encryption key using the PBKDF2 algorithm with a user-specified salt and iteration count.

The code optimizes memory usage by reusing cryptographic objects to minimize peak memory consumption during heavy loads. The function is designed for both low-latency and high-throughput environments, balancing the trade-off between key derivation speed and key strength by choosing an appropriate number of PBKDF2 iterations based on the expected load and available computational resources.

The `AESGCM_cleanup()` function securesly cleans up and disables the cipher when it is no longer needed, ensuring that all resources are properly released to prevent memory leaks.']

