[' Here is a C implementation based on your requirements. I've used pthread_mutex_t for concurrent access to log and a custom struct to manage key generation. I've also used pthreads for the delay mechanism, though it can be replaced with usleep().

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/random.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    void *key;
    size_t key_len;
    pthread_mutex_t log_mutex;
    int num_log_entries;
    FILE *log_file;
} key_generator;

void clean_up(key_generator *generator) {
    if (generator->key) free(generator->key);
    if (generator->log_file) fclose(generator->log_file);
    free(generator);
}

key_generator* init_generator() {
    key_generator *generator = malloc(sizeof(key_generator));
    generator->key = NULL;
    generator->key_len = 0;
    pthread_mutex_init(&generator->log_mutex, NULL);
    generator->num_log_entries = 0;
    generator->log_file = stdout;
    return generator;
}

int generate_key(key_generator *generator, size_t key_len) {
    int retries = 3;
    void *key_buf = mmap(NULL, key_len, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (key_buf == MAP_FAILED) {
        perror("mmap failed");
        return 0;
    }

    getrandom(key_buf, key_len, 0);

    while (retries-- > 0 && memcmp(key_buf, generator->key, key_len)) {
        if (key_len * retries >= 1024) sleep(1 + retries / 16);
        else usleep((retries + 1) * 100000); // adjust sleep time linearly
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to generate key after three attempts\n");
        return 0;
    }

    if (generator->key) clean_up(generator);
    generator->key = key_buf;
    generator->key_len = key_len;

    log_success(generator, key_len);
    return 1;
}

void log_success(key_generator *generator, size_t key_len) {
    if (++generator->num_log_entries >= 100) {
        rewind(generator->log_file);
        generator->num_log_entries = 0;
    }

    pthread_mutex_lock(&generator->log_mutex);
    fprintf(generator->log_file, "Generated key of length %zu\n", key_len);
    pthread_mutex_unlock(&generator->log_mutex);
}

void log_error(key_generator *generator, const char *message) {
    if (++generator->num_log_entries >= 100) {
        rewind(generator->log_file);
        generator->num_log_entries = 0;
    }

    pthread_mutex_lock(&generator->log_mutex);
    fprintf(generator->log_file, "%s\n", message);
    pthread_mutex_unlock(&generator->log_mutex);
}

int generate_keys(key_generator *generator, size_t num_keys, size_t key_len) {
    int success = 0;

    for (size_t i = 0; i < num_keys; ++i) {
        if (!generate_key(generator, key_len)) {
            log_error(generator, "Failed to generate key\n");
            return -1;
        }
        success++;
    }

    if (success == num_keys) return 1;

    clean_up(generator);
    log_error(generator, "Not all requested keys were generated successfully\n");
    return -1;
}
```

You can use the functions like this:

```c
int main() {
    key_generator *generator = init_generator();
    if (!generate_keys(generator, 3, 32)) return 1;
    clean_up(generator);
    return 0;
}
```']

