#!/usr/bin/php
<?php

$inputFile = $argv[1];
$outputFile = $argv[2];
$alertTypes = explode(',', $argv[3]);
$thresholds = array_map('floatval', array_slice($argv, 4));
$logEnabled = $thresholds[count($thresholds) - 1];
unset($thresholds[$thresholds]);

if (empty($inputFile) || empty($outputFile)) {
    die("Usage: php script.php [config_file] [output_alert_file] [types,types...] [threshold,threshold...] [log_enabled|false]\n");
}

$data = json_decode(file_get_contents($inputFile), true);
$alerts = [];

foreach ($data as $type => $config) {
    if (in_array($type, $alertTypes)) {
        $threshold = $thresholds[$type] ?? 0;
        $logFormat = '%s: %f - %s\n';
        $bufferSize = 1024;
        $buffer = [];

        foreach ($config as $line) {
            $lineLength = strlen($line);
            if ($lineLength + $bufferSize > $bufferSize * 2) {
                $alerts[] = array_map(function ($item) use ($logFormat, $type) {
                    return sprintf($logFormat, $type, $item['value'], implode(', ', $item['details']));
                }, $buffer);
                $buffer = [];
            }

            list($value, ...$details) = explode(':', trim($line), 2);
            $value = floatval($value);
            if ($value > $threshold) {
                $buffer[] = ['value' => $value, 'details' => $details];
            }
        }

        if (!empty($buffer)) {
            $alerts[] = array_map(function ($item) use ($logFormat, $type) {
                return sprintf($logFormat, $type, $item['value'], implode(', ', $item['details']));
            }, $buffer);
        }
    }
}

file_put_contents($outputFile, implode("\n\n", $alerts), LOCK_EX);

if ($logEnabled) {
    // Add your detailed logging implementation here
}
