['Here's a simplified example using C++17 (with Boost.ProgramOptions for command-line options and doctest for testing), a third-party library like RapidJSON (for parsing JSON configuration settings) and Handlebars.js (as the templating engine, with its Node.js API used here). The solution leverages multi-threading to improve performance and memory management.

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <boost/program_options.hpp>
#include "rapidjson/document.h"
#include "rapidjson/writer.h"
#include "handlebars.js-x86_64-unknown-linux-gnu.min.js"

using namespace std;
using namespace rapidjson;

// Define the maximum number of threads and worker pool
const int MAX_THREADS = 8;
vector<unique_ptr<JSContext>> contexts(MAX_THREADS);

void generateReport(const string& input, const string& templateName, const string& output) {
    // Load the JSON configuration file for the specified template
    ifstream configFile(templateName + ".json");
    Document config;
    config.ParseStream(configFile);

    // Render the template using Handlebars.js
    JSContext& ctx = *contexts[this_thread::get_id() % MAX_THREADS];
    string compiledTemplate = Handlebars.compile(config["template"].GetString());
    string html = compiledTemplate.render(config["data"]);

    // Write the HTML output to a file
    ofstream outFile(output);
    outFile << html;
}

void workerThread() {
    while (true) {
        string input, templateName, output;
        if (!getNextInputOutput(input, templateName, output)) break; // Break if no more inputs
        generateReport(input, templateName, output);
    }
}

int main(int argc, char* argv[]) {
    namespace po = boost::program_options;

    po::options_description desc("Allowed options");
    desc.add_options()
        ("templates,t", po::value<string>()->composing(), "Template files")
        ("outputs,o", po::value<string>()->composing(), "Output file names")
        ("help,h", "Print help message");

    po::variables_map vm;
    store(parse_command_line(argc, argv, desc), vm);
    notify(vm);

    if (vm.count("help")) {
        cout << desc;
        return 0;
    }

    // Initialize JSContexts and start worker threads
    for (auto& ctx : contexts) ctx.reset(JS_NewContext());
    for (int i = 0; i < MAX_THREADS; ++i) {
        thread workerThread(workerThread);
        workerThread.detach();
    }

    // Process user input and feed it to the worker threads
    string input, templateName, output;
    while (getNextInputOutput(input, templateName, output)) {
        generateReport(input, templateName, output);
    }

    return 0;
}
```

In this example, `generateReport()` is responsible for rendering a given template with the specified data and writing it to an output file. The worker threads process inputs in parallel using a thread pool.']

