// A custom lock for concurrent access
struct AppLock {
    inner: StdMutex<()>,
}

impl AppLock {
    fn new() -> Self {
        Self {
            inner: StdMutex::new(()),
        }
    }

    fn lock(&self) -> std::sync::mpsc::Sender<()> {
        let (tx, rx) = std::sync::mpsc::channel();
        let mut guard = self.inner.lock().unwrap();
        drop(guard); // Release the lock for a moment to allow another thread to acquire it
        tx
    }
}

// Directory initialization function
fn init_app_dir(version: &str, app_home_base: &Path) -> Result<(), Box<dyn std::error::Error> {
    let app_home = resolve_app_home(app_home_base)?;
    if !fs::metadata(app_home).is_ok() {
