    Ok(())
}

// Resolve the APP_HOME environment variable or fallback to the base path
fn resolve_app_home(base: &Path) -> Result<PathBuf, Box<dyn std::error::Error>> {
    if let Some(val) = env::var("APP_HOME")? {
        Path::new(&val).canonicalize()?;
    }

    base.join("app")
}

// Update the APP_HOME environment variable, handling concurrent access safely
fn update_env_var(key: &str, value: &str) -> Result<(), Box<dyn std::error::Error>> {
    let lock = AppLock::new();
    let sender = lock.lock();
    simple_logger::init_with_level(log::LevelFilter::Info).unwrap();
    let mut guard = lock.inner.lock().unwrap();
    drop(guard); // Release the lock for a moment to allow another thread to acquire it
    std::env::set_var(key, value);
    Ok(())
}

// Main function that sets up the application directory, logging any errors for debugging purposes
