#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
    struct Record *prev, *next;
} Record;

Record* create_node(long offset) {
    Record* node = (Record*)malloc(sizeof(Record));
    node->offset = offset;
    node->key = 0;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void insert_node(Record** head, Record* node) {
    if (*head == NULL) {
        *head = node;
    } else {
        Record* last = *head;
        while (last->next != NULL)
            last = last->next;
        last->next = node;
        node->prev = last;
    }
}

long read_key(FILE* file, size_t* line_len) {
    char c;
    long result = 0;
    size_t pos = 0;

    while ((c = fgetc(file)) != EOF && c != '\n') {
        if (pos >= *line_len) {
            *line_len *= 2;
            realloc((void*)&c, *line_len);
        }
        c[pos++] = (char)c;
        if ('0' <= c && c <= '9')
            result = result * 10 + (c - '0');
    }

    if (result == 0)
        result = -1;

    return result;
}

void handle_error(const char* message, FILE* file) {
    if (file != NULL)
        fclose(file);
    fprintf(stderr, "Error: %s\n", message);
}

int custom_rand(unsigned long seed) {
    static unsigned long x = 123456789, y = 362436069, z = 521288629;
    static const unsigned long a = 2636458, b = 1834913, c = 4069269;
    unsigned long temp;

    seed = (a * seed + b) % x + (c * (seed / x)) % y;
    temp = seed;
    seed = (temp * temp + 1) % 4294967290ULL;
    return (int)(seed / 4294967288LL);
}

Record* manage_memory(const char* filename, size_t num_records) {
    Record *head = NULL, *current, *new_node;
    FILE *file = fopen(filename, "r");
    if (file == NULL)
        return NULL;

    size_t line_len = 1024;
    char buffer[line_len];

    long offset = 0;
    int key;

    while (num_records > 0 && fgets(buffer, line_len, file) != NULL) {
        key = read_key(file, &line_len);
        if (key == -1) {
            handle_error("Malformed line.", file);
            break;
        }

        new_node = create_node(offset++);
        new_node->key = key > 0 ? key : custom_rand();

        insert_node(&head, new_node);
        num_records--;
    }

    fclose(file);

    // Detect and handle cyclic references here...

    int* random_values = (int*)calloc(offset, sizeof(int));
    if (random_values == NULL) {
        handle_error("Out of memory.", NULL);
        return NULL;
    }

    current = head;
    for (size_t i = 0; i < offset; ++i)
        random_values[current->offset] = custom_rand();

    free(head); // Free the original linked list
    head = NULL;

    // Error handling and logging here...

    return random_values;
}
