        this.props = props;
        this.logger = logger;
        this.messagingSystem = messagingSystem;
    }

    public void manageService() throws Exception {
        String serviceName = props.getProperty("service_name");
        while (true) {
            startService(serviceName);
            TimeUnit.SECONDS.sleep(new Random().nextInt(10));
            stopService(serviceName);
        }
    }

    private void startService(String serviceName) throws Exception {
        logger.log("Starting service: " + serviceName);
        // Implement the logic for starting a service here
    }

    private void stopService(String serviceName) throws Exception {
        logger.log("Stopping service: " + serviceName);
        messagingSystem.sendMessage(serviceName, "STOP");
        TimeUnit.SECONDS.sleep(10); // Wait for the service to stop
        logger.log("Service stopped: " + serviceName);
    }
}
