// Custom memory allocator with specified memory limit
template<typename T>
class Allocator {
    std::vector<T*> freeList;
    std::unordered_map<void*, T*> managed;
    size_t maxSize;

public:
    explicit Allocator(size_t maxSize) : maxSize(maxSize) {}

    T* allocate(std::size_t n) {
        if (n > maxSize || freeList.empty()) throw std::bad_alloc();
        auto mem = &freeList.back();
        freeList.pop_back();
        managed[mem] = new(mem) T;
        return managed[mem];
    }

    void deallocate(T* ptr, std::size_t n) {
        if (n != 1) throw std::runtime_error("Invalid number of objects");
        if (!managed.count(ptr)) throw std::bad_alloc();
        managed.erase(ptr);
        new(ptr) char[sizeof(T)]; // Construct a dummy object to zero-initialize the memory
        freeList.push_back(ptr);
    }
};
```

