    // Attribute-based naming
    if (attributes & HIDDEN) {
        strcat(new_name, "H_");
    } else if (attributes & READONLY) {
        strcat(new_name, "R_");
    }

    // File type determination
    int file_type = *(path + strlen(path) - 1);
    if (strlen(path) > 3) {
        size_t hidden_segment_length = strlen(path) % 10;
        file_type = *(path + strlen(path) - hidden_segment_length - 1);
    }

    // Replace illegal characters
    if (!is_valid_char(file_type)) {
        file_type = '_';
    }
    strcat(new_name, &file_type);

    // Ensure filename does not exceed the maximum length
    int new_len = strlen(new_name) + strlen(path + strlen(path) - 1);
    if (new_len > MAX_FILE) {
        new_len = MAX_FILE;
        new_name[MAX_FILE - 1] = '\0';
    }

    // Concatenate the base name with the new prefix and type
    strncat(new_name, path + strlen(path) - strlen(path + strlen(path) - 1), new_len - strlen(new_name));

    rename(path, new_name);
}

int process_directory(const char *dir_path, int depth, int attributes, pthread_mutex_t *mutex) {
    DIR *dir = opendir(dir_path);
    if (NULL == dir) {
        return -1; // Invalid directory path
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        pthread_mutex_lock(mutex);
        // Skip special entries (., ..) and hidden files
        if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) {
            pthread_mutex_unlock(mutex);
            continue;
        }
        char path[MAX_PATH];
        snprintf(path, sizeof(path), "%s/%s", dir_path, entry->d_name);
        if (lstat(path, NULL) == -1) { // Stat failed or it's not a directory
            pthread_mutex_unlock(mutex);
            continue;
        }

        struct stat st;
        lstat(path, &st);
        int is_dir = S_ISDIR(st.st_mode);
        pthread_mutex_unlock(mutex);

        if (is_dir) { // Recursively process subdirectories
            if (process_directory(path, depth + 1, attributes, mutex) < 0) {
                return -1; // Error in recursive call
            }
        } else {
            int is_hidden = st.st_mode & S_ISHIDDEN;
            if (!is_hidden && (S_IWUSR & st.st_mode) && (S_IXUSR & st.st_mode)) {
                rename_file(path, depth, attributes | (is_hidden ? HIDDEN : 0));
            }
        }
    }
    closedir(dir);
    return 0;
}

int process_files(const char *root_dir, int depth, int attributes, pthread_t *threads, pthread_mutex_t *mutex, unsigned int num_threads) {
    if (num_threads > MAX_DEPTH || num_threads == 0) {
        return -1; // Invalid number of threads
    }

    const int files_per_thread = strlen(root_dir) * 2 / num_threads + 1;
    pthread_t *thread_ids = malloc(num_threads * sizeof(pthread_t));
    DIR *root = opendir(root_dir);
    if (NULL == root) {
        free(thread_ids);
        return -1; // Error opening the root directory
    }

    struct dirent **namelist = NULL;
    int n = scandir(root_dir, &namelist, NULL, alphasort);
    if (n < 0) {
        free(thread_ids);
        closedir(root);
        return -1; // Error reading directory entries
    }

    unsigned int files_processed = 0;
    pthread_attr_t attr;
    pthread_mutex_init(&mutex, NULL);
    for (unsigned int i = 0; i < num_threads; ++i) {
        pthread_attr_init(&attr);
        pthread_create(&thread_ids[i], &attr, process_directory_wrapper, (void *)((char *)root + files_per_thread * i));
    }

    for (unsigned int i = 0; i < num_threads; ++i) {
        pthread_join(thread_ids[i], NULL);
    }

    free(thread_ids);
    free(namelist);
    closedir(root);

    return files_processed;
}

void *process_directory_wrapper(void *arg) {
    char *path = (char *)arg;
    process_directory(path, 1, HIDDEN | READONLY, &mutex);
    pthread_exit(0);
}
```

