#include <stdio.h>
#include <string.h>
#include <regex.h>
#include <pthread.h>
#include <semaphore.h>
#include <vector>

struct Command {
    char operation; // 'u' for uppercase, 'l' for lowercase, 'r' for replace, 'm' for match
    std::string pattern;
    std::string replacement;
};

class StringProcessor {
private:
    std::vector<Command> commands;
    char *buffer;
    size_t bufferSize;
    size_t bufferCapacity;
    sem_t mutex;

    void applyOperation(char operation, const std::string &pattern, const std::string &replacement, char *str) {
        if (operation == 'u') {
            for (size_t i = 0; i < strlen(str); ++i) str[i] = toupper((unsigned char)str[i]);
        } else if (operation == 'l') {
            for (size_t i = 0; i < strlen(str); ++i) str[i] = tolower((unsigned char)str[i]);
        } else if (operation == 'r') {
            size_t found = 0;
            while ((found = strchr(str, pattern.c_str()[found])) != nullptr) {
                memcpy(found + strlen(pattern.c_str()), replacement.c_str(), strlen(replacement.c_str()));
            }
        } else if (operation == 'm') {
            regex_t reg;
            int error = regcomp(&reg, pattern.c_str(), REG_EXTENDED | REG_ICASE | REG_NEWLINE);
            if (error) return;

            size_t lastMatchPos = 0;
            while ((error = regexec(&reg, str, 0, NULL, 0)) == 0) {
                size_t matchPos = regmatch(NULL, str + lastMatchPos);
                memcpy(str + matchPos, replacement.c_str(), strlen(replacement.c_str()));
                lastMatchPos += matchPos + strlen(replacement.c_str());
            }
            regfree(&reg);
        }
    }

    void resizeBuffer(size_t newCapacity) {
        if (newCapacity > bufferSize) {
            char *temp = static_cast<char*>(realloc(buffer, newCapacity));
            if (!temp) throw std::bad_alloc();
            buffer = temp;
            bufferSize = newCapacity;
        }
    }

public:
    StringProcessor(size_t initialCapacity) : buffer(new char[initialCapacity]), bufferSize(initialCapacity), bufferCapacity(initialCapacity), mutex(Semaphore()) {}

    ~StringProcessor() { delete[] buffer; }

    int processCommands(const std::vector<Command> &commands, const char *input, char *output) {
        resizeBuffer(strlen(input) + 1);
        strcpy(buffer, input);

        pthread_t threads[commands.size()];
        for (size_t i = 0; i < commands.size(); ++i) {
            sem_wait(&mutex);
            Command cmd = commands[i];
            sem_post(&mutex);

            pthread_create(&threads[i], NULL, [](void *arg)->void* {
                applyOperation(static_cast<Command*>(arg)->operation, static_cast<Command*>(arg)->pattern, static_cast<Command*>(arg)->replacement, buffer);
                return nullptr;
            }, &commands[i]);
        }

        for (size_t i = 0; i < commands.size(); ++i) {
            pthread_join(threads[i], NULL);
        }

        strcpy(output, buffer);
        return 0; // Success
    }
};
```

