        return NULL;
    }

    size_t username_len = strcspn(email, "@");
    size_t domain_len = strlen(email + username_len);
    if (domain_len > 64) {
        return NULL;
    }

    char *domain = malloc(domain_len + 2); // for the period and null terminator
    strncpy(domain, email + username_len, domain_len + 1);
    if (domain[domain_len] == '.') {
        domain[domain_len++] = '\0';
    } else if (domain[domain_len] != '\0') {
        return NULL;
    }

    size_t suffix_len = (sqrtl(domain_len) + 1 > domain_len ? sqrtl(domain_len) + 1 : (unsigned long)sqrtl(domain_len));
    char *suffix = malloc(suffix_len);
    sprintf(suffix, "#%.*s", suffix_len - 1, rand_alphanum(suffix_len - 1));

    size_t id_len = username_len + suffix_len;
    char *id = malloc(id_len + 1);
    strncpy(id, email before '@', username_len);
    strncpy(id + username_len, suffix, suffix_len);
    id[id_len] = '\0';

    // replace special characters with underscore (_)
    for (size_t i = 0; i < id_len; ++i) {
        if (!isalnum(id[i]) && id[i] != '_') {
            id[i] = '_';
        }
    }

    free(domain);
    free(suffix);
    return id;
}

char *rand_alphanum(size_t n) {
    char alphanum[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    char *str = malloc(n + 1);
    for (size_t i = 0; i < n; ++i) {
        str[i] = alphanum[rand() % (sizeof(alphanum) - 1)];
    }
    str[n] = '\0';
    return str;
}
