    // Validate email format and handle errors
    if (!email || strchr(email, '@') == NULL || strlen(email) <= 2 || strlen(email) > 256) {
        return (struct identifier){0, 0, {0}};
    }

    const char *username_start = email;
    const char *domain_start = strchr(email + 1, '@'); // Skip the '@' symbol
    const char *domain_end = strchr(domain_start + 1, '.');
    size_t domain_length = domain_end ? domain_end - domain_start : strlen(domain_start);

    if (strlen(username_start) > max_domain_length || domain_length > max_domain_length || (domain_end && domain_length + 1 >= max_domain_length)) {
        return (struct identifier){0, 0, {0}};
    }

    // Remove trailing period from the domain if present
    if (domain_end) {
        if (*(domain_end + 1) == '\0') {
            domain_length--;
