[" Here's the C code for initializing an AES-128-GCM cipher with a given password using OpenSSL library. The function uses PBKDF2 key derivation function with SHA-256, sets the IV length to 12 bytes, and supports key stretching by specifying a salt and iteration count.

```c
#include <openssl/pbkdf2.h>
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/gcm.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned char key[AES_BLOCK_SIZE];
    unsigned char iv[AES_GCM_128_TAG_LENGTH + AES_BLOCK_SIZE];
} aes_gcm_context;

int aes_gcm_init(aes_gcm_context* ctx, const char* password, size_t password_len, const char* salt, unsigned int iterations, unsigned int key_size) {
    if (password == NULL || password_len < 4 || password_len > AES_KEYSIZE_256/8) {
        return -1; // Invalid password length
    }
    if (salt == NULL || strlen(salt) != AES_KEYSIZE_256/8) {
        return -2; // Invalid salt length
    }
    if (iterations < 4096 || iterations > 1 << 30) {
        return -3; // Invalid iteration count
    }
    if (key_size != AES_KEYSIZE_128 && key_size != AES_KEYSIZE_192 && key_size != AES_KEYSIZE_256) {
        return -4; // Unsupported key size
    }

    uint8_t key[AES_BLOCK_SIZE], iv[AES_GCM_128_TAG_LENGTH + AES_BLOCK_SIZE];
    int ret = PBKDF2_HMAC((EVP_CIPHER_CTX*)NULL, key, sizeof(key), password, password_len, salt, strlen(salt), iterations, EVP_sha256(), NULL, 0);
    if (ret != 1) {
        return -5; // Failed to derive key or IV
    }

    memcpy(iv + AES_BLOCK_SIZE, key, sizeof(key));
    RAND_bytes(iv, AES_BLOCK_SIZE);

    ctx->key[0] = key[0];
    for (size_t i = 1; i < sizeof(ctx->key); ++i) {
        ctx->key[i] = EVP_CIPHER_ctf_encrypt(i, key + (i - 1), &iv, ctx->key + i, ctx->key, AES_ENCMODE_ECB, NULL)[0];
    }

    memcpy(ctx->iv, iv, sizeof(ctx->iv));

    return 0; // Success
}

void aes_gcm_cleanup(aes_gcm_context* ctx) {
    memset(ctx, 0, sizeof(*ctx));
}
```

