typedef struct IntNode {
    int value;
    size_t index;
    struct IntNode* next;
} IntNode;

struct MemoryPool {
    void *memory;
    size_t capacity;
    size_t allocated;
};

void* memory_pool_alloc(struct MemoryPool *pool, size_t size) {
    if (pool->allocated + size <= pool->capacity) {
        pool->allocated += size;
        return pool->memory + pool->allocated - size;
    }

    void* new_memory = realloc(pool->memory, pool->capacity * 2);
    if (!new_memory) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }

    pool->memory = new_memory;
    pool->capacity *= 2;
    return pool->memory + pool->allocated - size;
}

void* memory_pool_create(size_t initial_capacity) {
    void* memory = malloc(initial_capacity);
    if (!memory) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }

    struct MemoryPool *pool = malloc(sizeof(struct MemoryPool));
    pool->memory = memory;
    pool->capacity = initial_capacity;
    pool->allocated = 0;
    return pool;
}

void memory_pool_destroy(void* pool) {
    free((char*)pool - offsetof(struct MemoryPool, memory));
}

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
IntNode *head = NULL;
size_t count = 0;
struct MemoryPool *memory_pool = memory_pool_create(1024);

void add_integer(int value, size_t index) {
    IntNode* node = malloc(sizeof(IntNode));
    node->value = value;
    node->index = index;
    node->next = head;
    head = node;
    pthread_mutex_lock(&list_mutex);
    count++;
    pthread_mutex_unlock(&list_mutex);
}

int find_largest() {
    IntNode* current = head;
    int largest = INT32_MIN;
    size_t largest_index = 0;

    pthread_mutex_lock(&list_mutex);
    while (current != NULL) {
        if (current->value > largest) {
            largest = current->value;
            largest_index = current->index;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);

    return largest_index;
}

void process_input() {
    int value;
    size_t index = 0;

    while (scanf("%d", &value) == 1) {
        add_integer(value, index);
        index++;
    }

    if (count == 0) {
        printf("No integers provided.\n");
        return;
    }

    int largest_index = find_largest();
    printf("Largest integer: %d at index %zu\n", head[largest_index].value, largest_index);
}
