        ...

    def start_monitoring(self):
        if self.monitor_service_url:
            monitor_task = MonitorTask(self.monitor_service_url, self)
            threading.Thread(target=monitor_task.run).start()

    @staticmethod
    def serialize(obj: Any) -> str:
        ...

    @staticmethod
    def deserialize(data: str) -> Any:
        ...

class MonitorTask:
    def __init__(self, url: str, framework: DataProcessingFramework):
        self.url = url
        self.framework = framework

    def run(self):
        while True:
            timestamp = datetime.now().isoformat()
            data = {
                'timestamp': timestamp,
                'user_id': self.framework.get_current_user_id(),
                'operation': self.framework.get_current_operation()
            }
            if not self.framework.is_shutdown:
                requests.post(self.url, json=data)
            time.sleep(60)
