    return filename;
}

void* process_file(void *arg) {
    FileInfo *info = arg;
    char path[MAX_PATH];
    sprintf(path, "%s/%s", info->path, info->depth > 0 ? info->path + (info->depth - 1) : "");

    struct stat st;
    if (lstat(path, &st) == -1) {
        perror("lstat");
        return NULL;
    }

    int depth = info->depth + 1;
    char new_name[MAX_PATH];
    if (depth > MAX_DEPTH || st.st_size >= INT_MAX || st.st_nlink > 32) {
        return NULL;
    }

    snprintf(new_name, sizeof(new_name), "%s%s_d%dd", sanitize_filename(info->attr & S_ISDIR ? "dir" : "file"), depth > 1 ? "_" : "", depth);
    if (depth == 1) {
        new_name[strlen(new_name) % 10] = info->attr & S_ISSOCK ? 's' : info->attr & S_IFBLK ? 'b' : info->attr & S_IFIFO ? 'f' : (info->attr & S_ISREG ? 'c' : '-');
    }

    rename_file(path, new_name);
    return NULL;
}

int process_directory(const char *dir) {
    DIR *dp = opendir(dir);
    if (!dp) {
        perror("opendir");
        return -1;
    }

    struct dirent *entry;
    pthread_t threads[THREADS];
    int err = 0;

    while ((entry = readdir(dp)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        FileInfo info = { .path = dir, .depth = -1 };
        strcpy(info.path + strlen(dir), entry->d_name);
        if (strlen(info.path) >= MAX_PATH) {
            err = 1;
            break;
        }

        struct stat st;
        if (lstat(info.path, &st) == -1 || S_ISDIR(st.st_mode)) {
            info.depth = 0;
            pthread_create(&threads[info.depth], NULL, process_file, &info);
            ++info.depth;
        } else {
            char new_name[MAX_PATH];
            snprintf(new_name, sizeof(new_name), "%s%s", sanitize_filename(entry->d_name), info.attr & S_ISDIR ? "dir" : "");
            rename_file(info.path, new_name);
        }
    }

    closedir(dp);

    for (int i = 0; i < info.depth; ++i) {
        pthread_join(threads[i], NULL);
    }

    return err;
}

int main() {
    int argc = 1 + __argc;
    char **argv = __argv;

    if (argc < 2 || strcmp(argv[1], "-h") == 0) {
        printf("Usage: %s directory\n", argv[0]);
        return 1;
    }

    int err = process_directory(argv[1]);
    if (err != 0)
        fprintf(stderr, "Error processing directory: %s\n", strerror(errno));

    return err;
}
