#define NUM_SERVERS 4
struct server {
    struct hostent *he;
    int sockfd;
};

// Load balancer for DNS requests
void load_balance(struct server servers[], const char *hostname) {
    int index = hash(hostname) % NUM_SERVERS;
    while (servers[index].sockfd < 0 || !servers[index].he) {
        index = (index + 1) % NUM_SERVERS;
    }
    return;
}

// Hash function for load balancing
int hash(const char *str, int len) {
    uint32_t h = 5381;
    int c;
    for (int i = 0; i < len; ++i) {
        c = (unsigned char) str[i];
        h = ((h << 5) + h) + c; /* hash * 33 + c */
    }
    return h % NUM_SERVERS;
}

// Initialize and cleanup server array
void init_servers(struct server servers[], const char **server_list, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        struct hostent *he = gethostbyname(server_list[i]);
        if (!he) {
            fprintf(stderr, "Error: cannot resolve server %s\n", server_list[i]);
            exit(1);
        }
        servers[i].he = he;
    }
}

// Function to perform DNS resolution
