import hashlib
import os
import time
import socket
import threading
import queue
from urllib import resolver

MAX_QUERIES = 100
RATE_LIMIT_INTERVAL = 1.0

def gethostbyname(hostname):
    try:
        ip, _ = next(resolver.getaddrinfo(hostname, socket.AF_UNSPEC))
        return socket.inet_ntoa(ip[4])
    except (socket.gaierror, IndexError):
        return None

def rate_limited_function(func, limit, interval):
    last_call = 0.0

    def wrapper(*args, **kwargs):
        now = time.time()
        if now - last_call > interval:
            func(*args, **kwargs)
            last_call = now
        elif (now - last_call) / interval >= limit:
            raise Exception("Rate limit exceeded")

    return wrapper

def dns_resolver(hostname):
    ip = gethostbyname(hostname)
    if not ip:
        raise Exception("DNS resolution failed")
    return ip

def file_hasher(filepath, chunksize=65536):
    hash_obj = hashlib.sha256()
    total_bytes = os.path.getsize(filepath)
    processed_bytes = 0
    rate_limited_resolver = rate_limited_function(dns_resolver, MAX_QUERIES, RATE_LIMIT_INTERVAL)

    with open(filepath, "rb") as f:
        while True:
            chunk = f.read(chunksize)
            if not chunk:
                break

            hash_obj.update(chunk)
            processed_bytes += len(chunk)
            progress = int(processed_bytes * 100 / total_bytes)
            print(f"Progress: {progress}%", end="\r")

            if rate_limited_resolver.__func__.__name__ == "dns_resolver":
                dns_server = rate_limited_resolver("dns.google")
                f.seek(0)  # Reset file pointer to start

    print()
    return hash_obj.hexdigest(), processed_bytes
