    size_t size;
    struct mem_chunk *next;
} mem_chunk_t;

mem_chunk_t *head = NULL, *tail = NULL;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *custom_malloc(size_t size) {
    if (head == NULL) {
        head = malloc(sizeof(mem_chunk_t));
        head->ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        head->size = size;
        head->next = NULL;
        tail = head;
    } else {
        mem_chunk_t *iter = head;
        while (iter->next != NULL) iter = iter->next;
        if ((iter->size - (iter->ptr - ((char*)head)) + size) <= 0) {
            iter->next = malloc(sizeof(mem_chunk_t));
            iter->next->ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
            iter->next->size = size;
            iter->next->next = NULL;
            tail = iter->next;
        }
        tail->ptr += size;
    }
    return head->ptr;
}

void custom_free(void *ptr) {
    memmove((char*)head, (char*)ptr - ((char*)head), tail->ptr - (char*)head);
    free(tail);
    tail = head;
}

