    array_len = size;
    pthread_mutex_unlock(&mutex);
}

void push_to_array(NFAPI_RX_FRAME_T frame) {
    pthread_mutex_lock(&mutex);
    if (array_len >= array_len * 2) {
        size_t new_size = array_len * 2;
        NFAPI_RX_FRAME_T *new_array = realloc(array, sizeof(NFAPI_RX_FRAME_T) * new_size);
        if (new_array != NULL) {
            array = new_array;
            array_len = new_size;
        } else {
            printf("Memory allocation failure\n");
        }
    }
    array[array_len - 1] = frame;
    pthread_mutex_unlock(&mutex);
}

NFAPI_RX_FRAME_T* get_from_array(size_t index) {
    pthread_mutex_lock(&mutex);
    NFAPI_RX_FRAME_T *frame = &array[index];
    if (index >= array_len) {
        printf("Index out of bounds\n");
        frame = NULL;
    }
    pthread_mutex_unlock(&mutex);
