static struct memory_block* custom_allocator(size_t size) {
    void* memory = malloc(sizeof(NFAPI_RX_FRAME_T) * size);
    if (!memory) {
        perror("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    struct memory_block* block = (struct memory_block*) memory;
    block->capacity = size;
    block->count = 0;
    block->data = (NFAPI_RX_FRAME_T*)memory;
    return block;
}

static void custom_deallocator(struct memory_block* block) {
    free(block);
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_array(NFAPI_RX_FRAME_T** array, size_t capacity) {
    *array = custom_allocator(capacity);
}

size_t get_count(const NFAPI_RX_FRAME_T* array) {
    return (*array)->count;
}

void push(NFAPI_RX_FRAME_T** array, const NFAPI_RX_FRAME_T* frame) {
    pthread_mutex_lock(&mutex);
    struct memory_block* block = (struct memory_block*)(*array);

    if (block->count == block->capacity) {
        size_t new_capacity = block->capacity * 2;
        struct memory_block* new_block = custom_allocator(new_capacity);
        memcpy(new_block->data, block->data, sizeof(NFAPI_RX_FRAME_T) * block->count);
        custom_deallocator(block);
        block = new_block;
    }

    block->data[block->count] = *frame;
    block->count++;

    pthread_mutex_unlock(&mutex);
}

NFAPI_RX_FRAME_T* pop(NFAPI_RX_FRAME_T** array) {
    pthread_mutex_lock(&mutex);
    if (0 == (*array)->count) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    NFAPI_RX_FRAME_T* frame = &((*array)->data[0]);
    memmove(&(*array)->data[0], &((*array)->data[1]), sizeof(NFAPI_RX_FRAME_T) * (--(*array)->count));
    pthread_mutex_unlock(&mutex);
    return frame;
}

