  let failedExtracts = 0;

  asyncMap(config.eventPatterns, (pattern, callback) => {
    pattern.exec(text, (err, matches)) => {
      if (err) {
        failedExtracts++;
        logger.log({ level: config.logLevel, message: `Error extracting event: ${err}` });
        return;
      }

      if (matches && matches.length > 0) {
        successfulExtracts++;
        const eventName = matches[0][0];
        eventCounts[eventName] = (eventCounts[eventName] || 0) + 1;
        logger.log({ level: config.logLevel, message: `Successfully extracted event: ${eventName}` });
      }

      callback();
    };
  }, (err) => {
    if (err) {
      failedExtracts++;
      logger.log({ level: config.logLevel, message: `Error processing text: ${err}` });
      return;
    }

    if (successfulExtracts > 0) {
      logger.log({ level: config.logLevel, message: `Processed text successfully, total event extractions: ${successfulExtracts}, failed extractions: ${failedExtracts}` });
    } else {
      logger.log({ level: config.logLevel, message: 'No events found in the provided text' });
    }
  });

  return eventCounts;
}

