typedef struct mem_block {
    size_t capacity;
    size_t allocated;
    void* data;
    pthread_mutex_t lock;
    struct mem_block *next;
} MemBlock;

MemBlock* head = NULL;
size_t max_memory = 0;

void* custom_malloc(size_t size) {
    if (head == NULL || head->allocated + size > max_memory) {
        return NULL; // Handle error by returning NULL or throwing an exception
    }

    pthread_mutex_lock(&head->lock);
    MemBlock* current = head;
    while (current && current->allocated >= size) {
        size_t block_size = current->capacity - current->allocated;
        if (block_size >= size) {
            void* result = (char*)current->data + current->allocated;
            current->allocated += size;
            pthread_mutex_unlock(&head->lock);
            return result;
        }
        current = current->next;
    }
    if (current == NULL) {
        MemBlock* new_block = malloc(sizeof(MemBlock));
        if (new_block == NULL) {
            pthread_mutex_unlock(&head->lock);
            return NULL; // Handle error by returning NULL or throwing an exception
        }
        new_block->capacity = 1024; // Adjust capacity as needed
        new_block->allocated = 0;
        new_block->data = malloc(new_block->capacity);
        if (new_block->data == NULL) {
            free(new_block);
            pthread_mutex_unlock(&head->lock);
            return NULL; // Handle error by returning NULL or throwing an exception
        }
        pthread_mutex_init(&new_block->lock, NULL);
        new_block->next = head;
        head = new_block;
    }
    void* result = (char*)current->data + current->allocated;
    current->allocated += size;
    pthread_mutex_unlock(&head->lock);
    return result;
}

void custom_free(void* ptr) {
    if (!ptr) {
        return; // Handle error by doing nothing or logging an error
    }
    char* data = (char*)ptr - head->allocated;
    pthread_mutex_lock(&head->lock);
    MemBlock* current = head;
    while (current && data >= current->data && current->allocated > 0) {
        size_t block_size = current->capacity - current->allocated;
        if (data < current->data + block_size) {
            size_t remaining = current->allocated - (data - current->data);
            current->allocated -= remaining;
            if (current->allocated == 0 && current->next) {
                MemBlock* temp = current->next;
                free(current);
                current = temp;
            }
            pthread_mutex_unlock(&head->lock);
            free(data);
            return;
        }
        current = current->next;
    }
    if (current == NULL) {
        fprintf(stderr, "Error: Unable to find memory block for given pointer\n");
        pthread_mutex_unlock(&head->lock);
    }
}

void init_memory_pool(size_t max_mem) {
    max_memory = max_mem;
    head = malloc(sizeof(MemBlock));
    if (head == NULL) {
        fprintf(stderr, "Error: Unable to allocate memory for memory pool header\n");
        exit(1);
    }
    pthread_mutex_init(&head->lock, NULL);
    head->capacity = 1;
    head->allocated = 0;
    head->data = NULL;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdus(size_t N) {
