    queue->frames = mmap(NULL, initial_capacity * sizeof(NFAPI_RX_FRAME_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!queue->frames) {
