        exit(EXIT_FAILURE);
    }

    queue->capacity = initial_capacity;
    queue->size = 0;
    queue->log_handle = log_init(); // Integration with external logging framework

    return queue;
}

void destroy_queue(NFAPI_RX_QUEUE_T* queue) {
