    sem_wait(&queue->batch_full);
    if (sem_trywait(&queue->memory_manager) == 0 && queue->size > 0) {
        NFAPI_RX_FRAME_T* frame = &queue->frames[queue->size - 1];
        memcpy(frame, NULL, sizeof(NFAPI_RX_FRAME_T)); // Cache mechanism to temporarily store frequently accessed frames
