#include <log4cpp/Category.hh> // Logging library
#include <boost/filesystem.hpp> // File system operations

using namespace std;
using namespace boost::filesystem;
using namespace log4cpp;

class Worker {
public:
    explicit Worker(future<void(const path&)>* taskQueue, const int batchSize)
        : m_taskQueue(taskQueue), m_batchSize(batchSize), m_buffer(), m_mutex() {}

    void operator()() {
        for (auto fileIter = directoryIterator(path("input_directory")); fileIter != directoryIterator(); ++fileIter) {
            path filePath = fileIter->path();
            if (is_regular_file(filePath)) {
                m_buffer.push_back(move(filePath));
                if (m_buffer.size() >= m_batchSize) {
                    processBatch();
                }
            }
        }
        processRemainingBatch();
    }

private:
    void processBatch() {
        unique_lock<mutex> lock(m_mutex);
        condition_variable cv;
        cv.wait(lock, [this] { return m_buffer.size() >= m_batchSize; });

        auto batch = move(m_buffer);
        m_buffer.clear();

        lock.unlock();

        for (auto& filePath : batch) {
            (*m_taskQueue)->push_back([filePath]() mutable { processFile(filePath); });
        }
    }

    void processRemainingBatch() {
        unique_lock<mutex> lock(m_mutex);
        if (!m_buffer.empty()) {
            processBatch();
        }
    }

    void processFile(const path& filePath) {
        // Extract metadata using metadataExtractor library
        Metadata metadata = extractMetadata(filePath);

        // Validate the extracted metadata against predefined schemas
        if (!validateMetadata(metadata)) {
            log_error(Category::getInstance("Worker")) << "Invalid metadata for file: " << filePath;
            return;
        }

        // Generate summary report based on user-defined rules
        SummaryReport report = generateSummaryReport(metadata);

        // Write the summary report to an output file
        writeSummaryReportToFile(report, filePath);
    }

    mutable mutex m_mutex;
    std::vector<path> m_buffer;
    int m_batchSize;
    future<void(const path&)>* m_taskQueue;
};

int main(int argc, char* argv[]) {
    if (argc < 5) {
        cout << "Usage: ./program input_directory output_report_format num_threads batch_size" << endl;
        return -1;
    }

    path inputDirectory(argv[1]);
    string reportFormat(argv[2]);
    int numThreads = static_cast<int>(stoi(argv[3]));
    int batchSize = static_cast<int>(stoi(argv[4]));

    // Create a task queue to store the tasks for each worker thread
    future<void(const path&)>* taskQueue = new future<void(const path&)>[numThreads];

    // Create and launch worker threads
    vector<thread> workers;
    for (int i = 0; i < numThreads; ++i) {
        workers.emplace_back(Worker(taskQueue + i, batchSize));
    }

    // Wait for all worker threads to finish processing their tasks
    for (auto& worker : workers) {
        worker.join();
    }

    delete[] taskQueue;

    return 0;
}
```

