// Custom memory allocator with a hard limit on memory usage
typedef struct MemBlock {
    void* data;
    size_t size;
    struct MemBlock* next;
} MemBlock;

MemBlock* mem_head = NULL;
size_t max_mem_usage = 0; // Set a hard limit on memory usage (in bytes)

// Function to allocate memory with custom allocator
void* my_malloc(size_t size) {
    if (max_mem_usage + size > max_mem_usage) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    MemBlock* new_block = (MemBlock*) malloc(sizeof(MemBlock));
    if (!new_block) {
        fprintf(stderr, "Failed to allocate memory for block header\n");
        return NULL;
    }

    new_block->data = malloc(size);
    if (!new_block->data) {
        free(new_block);
        fprintf(stderr, "Failed to allocate memory for data block\n");
        return NULL;
    }

    new_block->size = size;
    new_block->next = mem_head;
    mem_head = new_block;

    max_mem_usage += size;
    return new_block->data;
}

// Function to free memory with custom allocator
void my_free(void* ptr) {
    if (!ptr || !mem_head) return;

    MemBlock* current = mem_head;
    MemBlock* next;

    while (current != NULL) {
        next = current->next;

        if (current->data == ptr) {
            free(current->data);
            free(current);

            max_mem_usage -= current->size;
            current = next;
        } else {
            current = next;
        }
    }
}

