    size_t allocated;
    size_t used;
    size_t limit;
};

void initMemoryManager(struct MemoryManager* manager, size_t limit) {
    manager->memory = mmap(NULL, limit, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    manager->allocated = limit;
    manager->used = 0;
    manager->limit = limit;
}

void* allocate(struct MemoryManager* manager, size_t size) {
    void* ptr = manager->memory + manager->used;
    manager->used += size;
    return ptr;
}

void free(struct MemoryManager* manager, void* ptr) {
    manager->used -= ((char*)ptr - (char*)manager->memory);
}

