    pthread_mutex_lock(&batch->lock);
    if (batch->size < batch->capacity) {
        memcpy(batch->frames + batch->size, &frame, sizeof(NFAPI_RX_FRAME_T));
        batch->size++;
    }
    pthread_mutex_unlock(&batch->lock);
}

NFAPI_RX_FRAME_T* retrieveFrame(Batch* batch) {
    NFAPI_RX_FRAME_T* frame;
    pthread_mutex_lock(&batch->lock);
    if (batch->size > 0) {
        frame = batch->frames;
        memcpy(batch->frames, batch->frames + 1, sizeof(NFAPI_RX_FRAME_T) * (batch->size - 1));
        batch->size--;
    } else {
        frame = NULL;
    }
