    mode_t attr;
} file_info;

static char *illegal_chars = "/\\:*\?" "<>|";

int depth(const char *path) {
    int depth = 0;
    while (*path != '\0') {
        if (*path++ == '/')
            ++depth;
    }
    return depth - 1;
}

char *sanitize_filename(char *name) {
    char *result = malloc((strlen(name) + sizeof(illegal_chars) - 1) * 2);
    strcpy(result, name);
    for (size_t i = 0; result[i] != '\0'; ++i) {
        if (strchr(illegal_chars, result[i]) != NULL)
            result[i] = '_';
    }
    return result;
}

int rename_file(const char *path) {
    struct stat st;
    char new_name[PATH_MAX];
    if (stat(path, &st) == -1 || S_ISDIR(st.st_mode))
        return -1;

    strcpy(new_name, path);
    int depth = depth(path);
    for (int i = 0; i < depth; ++i)
        new_name[0] = '_';

    if (S_ISREG(st.st_mode)) {
        // handle file attributes here
    } else if (S_ISLNK(st.st_mode)) {
        // handle symlinks here
    }

    char *ext = strrchr(new_name, '.');
    if (!ext)
        ext = new_name + strlen(new_name);

    // determine file type based on the extension or last visible segment of the path

    snprintf(new_name + (ext - new_name), sizeof(new_name) - (ext - new_name), "%s", sanitize_filename(ext));

    if (rename(path, new_name) == -1)
        return -1;
    return 0;
}

void *process_files(void *arg) {
    DIR *dir = arg;
    struct dirent *entry;
    file_info fi;

    while ((entry = readdir(dir)) != NULL) {
        strcpy(fi.path, dir->d_name);
        if (strlen(fi.path) >= PATH_MAX - sizeof(file_info) || rename_file(fi.path) == -1)
            continue;

        fi.attr = lstat(fi.path, &st);
        // handle file attributes here

        if (rename_file(&fi) == -1)
            continue;
    }

    closedir(dir);
    return NULL;
}

int process_directory(const char *dir_name) {
    DIR *dir = opendir(dir_name);
    if (!dir)
        return -1;

    pthread_t threads[10];
    struct dirent **namelist;
    int num_threads = 0, n = scandir(dir_name, &namelist, NULL, alphasort);

    if (n <= 0 || n > 50000) {
        closedir(dir);
        return -1;
    }

    for (int i = 0; i < n; ++i) {
        if (i % 50 == 0 && num_threads < 10) {
            pthread_create(&threads[num_threads++], NULL, process_files, namelist[i]);
        } else
            namelist[i]->d_off = 0; // reset offset for next thread iteration
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(namelist);
    closedir(dir);
    return 0;
}
