#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int value;
    char *next_string;
} node;

typedef struct {
    unsigned long capacity;
    unsigned long size;
    node **table;
} hash_table;

hash_table *create_hash_table(unsigned long capacity) {
    hash_table *ht = malloc(sizeof(hash_table));
    ht->capacity = capacity;
    ht->size = 0;
    ht->table = calloc(capacity, sizeof(node*));
    return ht;
}

unsigned long hash(char *str, unsigned long capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;
    return hash % capacity;
}

node *create_node(char *str) {
    node *n = malloc(sizeof(node));
    n->value = strlen(str);
    if (!strlen(str))
        n->value = 0;
    n->next_string = NULL;
    return n;
}

void insert(hash_table *ht, char *key) {
    node *n = create_node(key);
    unsigned long index = hash(key, ht->capacity);
    while (ht->table[index] != NULL && strcmp(ht->table[index]->next_string, key)) {
        index = (index + 1) % ht->capacity;
    }

    if (ht->table[index] == NULL) {
        ht->table[index] = n;
    } else {
        node *current = ht->table[index];
        while (current->next_string != NULL)
            current = current->next_string;
        current->next_string = n;
    }
}

void remove(hash_table *ht, char *key) {
    unsigned long index = hash(key, ht->capacity);
    node *current = ht->table[index];
    node **prev = NULL;

    while (current != NULL && strcmp(current->next_string, key)) {
        prev = &ht->table[index];
        current = current->next_string;
        index = (index + 1) % ht->capacity;
    }

    if (current == NULL)
        return;

    if (prev == NULL) {
        ht->table[index] = current->next_string;
    } else {
        *prev = current->next_string;
    }

    free(current);
}

void resize(hash_table *ht, unsigned long new_capacity) {
    // implementation for resizing hash table dynamically
}

int custom_random(unsigned int seed) {
