    for (unsigned int i = 0; i < len; ++i) {
        if (strlen(input[i]) == 0)
            continue;

        node *n = ht->table[hash(input[i], ht->capacity)];
        while (n != NULL && strcmp(n->next_string, input[i]))
            n = n->next_string;

        if (n == NULL) {
            insert(ht, input[i]);
            n = ht->table[hash(input[i], ht->capacity)];
        }

        if (!n || strlen(n->next_string) == 0)
            continue;

        int value = custom_random(i);
        n->value += value < 0 ? -value : value;
    }
}

void log_entries(hash_table *ht, FILE *logfile) {
