// Custom session token cache data structure
typedef struct {
    char key[32]; // Username
    uint8_t nonce[16];
    time_t timestamp;
    char token[129]; // Allocated 129 bytes to account for Base64 encoding overhead
} SessionTokenCache;

// Session token generation function
SessionTokenCache generate_session_token(const char* username, const char* nonce) {
    SessionTokenCache token;

    // Validate input
    if (!username || strlen(username) > 32 || !isalnum(static_cast<unsigned char>(*username))) {
        return token; // Return empty token on invalid input
    }

    // Generate random nonce if not provided
    if (!nonce) {
        RAND_bytes(token.nonce, sizeof(token.nonce));
    } else {
        memcpy(token.nonce, nonce, strlen(nonce));
    }

    // Set timestamp
    time(&token.timestamp);

    // Hash the nonce to differentiate between sessions
    uint8_t hashed[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)nonce, strlen(nonce), hashed);

    // Combine username, nonce, and timestamp, encode in Base64, and store in token
    char encoded[130]; // Allocate extra space for null terminator and Base64 encoding overhead
    snprintf(encoded, sizeof(encoded), "%s%s%lu", username, base64_encode((unsigned char*)hashed, SHA256_DIGEST_LENGTH), token.timestamp);
    base64_decode(&encoded[strlen(encoded) - 1], encoded + strlen(encoded), strlen(encoded) - 1); // Remove Base64 encoding overhead and null terminator
    strncpy(token.token, encoded, sizeof(token.token));

    return token;
}

// Custom data structure for caching session tokens (e.g., using a hash table or Redis)
// ...

// Main function to demonstrate usage of the generate_session_token() function
