    unsigned int size;
    NODE** buckets;
    pthread_mutex_t lock;
};

void init_hash_table(struct HASH_TABLE* table, unsigned int size) {
    table->size = size;
    table->buckets = calloc(size, sizeof(NODE*));
    table->lock = PTHREAD_MUTEX_INITIALIZER;
}

unsigned int hash(const uint32_t key) {
    return key % table->size;
}

void insert(struct HASH_TABLE* table, NFAPI_CRC_INDICATION_PDU data) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hash(data.RX_UE_INFORMATION_TAG);
    NODE *new_node = malloc(sizeof(NODE));
    new_node->data = data;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    pthread_mutex_unlock(&table->lock);
}

NFAPI_CRC_INDICATION_PDU* find(struct HASH_TABLE* table, uint32_t key) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hash(key);
    NODE* current = table->buckets[index];
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == key) {
            NFAPI_CRC_INDICATION_PDU* result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
            *result = current->data;
            pthread_mutex_unlock(&table->lock);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void cleanup(struct HASH_TABLE* table) {
    // Implement a garbage collection algorithm to clean up unused structures,
    // ensuring optimal performance over extended periods of operation.
}

void create_data(NFAPI_CRC_INDICATION_PDU* data, unsigned int count) {
    for (unsigned int i = 0; i < count; ++i) {
        data[i].RX_UE_INFORMATION_TAG = rand();
        data[i].RNTI = rand() % 65536;
        data[i].CRC_INDICATION_REL8_TAG = rand() % 65536;
        data[i].CRCFLAG = rand() % 2 == 0 ? true : false;
    }
}

void run(struct HASH_TABLE* table, unsigned int count) {
    NFAPI_CRC_INDICATION_PDU* data;
    create_data(data, count);
    for (unsigned int i = 0; i < count; ++i) {
        insert(table, data[i]);
    }
}
