using Newtonsoft.Json;
using Microsoft.Extensions.Logging;

namespace WebApp
{
    public class WebPageUpdater
    {
        private readonly HttpClient _httpClient;
        private readonly ILogger<WebPageUpdater> _logger;
        private readonly RandomValueGenerator _randomValueGenerator;

        public WebPageUpdater(HttpClient httpClient, ILogger<WebPageUpdater> logger, RandomValueGenerator randomValueGenerator)
        {
            _httpClient = httpClient;
            _logger = logger;
            _randomValueGenerator = randomValueGenerator;
        }

        public async Task UpdateElementAsync(string pageSectionId, string elementId, string htmlContent)
        {
            var updateData = new
            {
                PageSectionId = pageSectionId,
                ElementId = elementId,
                HtmlContent = htmlContent
            };

            var content = JsonConvert.SerializeObject(updateData);
            var response = await _httpClient.PostAsync($"/api/pages/{pageSectionId}/elements/{elementId}", new StringContent(content, Encoding.UTF8, "application/json"));

            if (!response.IsSuccessStatusCode)
                throw new InvalidOperationException("Failed to update element.");

            await RefreshPageAsync(pageSectionId);
        }

        private async Task RefreshPageAsync(string pageSectionId)
        {
            var response = await _httpClient.GetAsync($"/api/pages/{pageSectionId}");

            if (!response.IsSuccessStatusCode)
                throw new InvalidOperationException("Failed to refresh page.");
        }

        public float GenerateRandomValue(double min, double max, bool isFloat = true)
        {
            if (isFloat && max < min)
                throw new ArgumentOutOfRangeException(nameof(max), "Maximum value should be greater than minimum value.");

            var random = _randomValueGenerator;
            var delta = max - min;

            if (!isFloat)
                return (float)(random.NextDouble() * delta + min);

            var precision = Math.Pow(10, 6); // Precision for float calculations. Adjust as needed.
            var randomValue = (random.NextDouble() * delta + min) * precision;
            return (float)(randomValue / precision);
        }

        public double AverageOfRandomValues(int iterations, params Action<RandomValueGenerator>[] setupActions)
        {
            var sum = 0d;

            for (var i = 0; i < iterations; i++)
            {
                var generator = _randomValueGenerator;

                foreach (var setupAction in setupActions)
                    setupAction(generator);

                sum += GenerateRandomValue(1, 100); // Adjust range as needed.
            }

            return sum / iterations;
        }
    }

    public class RandomValueGenerator
    {
        private readonly object _syncLock = new object();
        private readonly Random _random;

        public RandomValueGenerator() : this(new Random()) { }

        public RandomValueGenerator(Random random) => _random = random;

        public double NextDouble()
        {
            lock (_syncLock)
                return _random.NextDouble();
        }
    }
}
