void json_log(LoggerConfig* config, const char* message, LogLevel level) {
    if (level >= config->level) {
        json_object_object_add(config->json_obj, "message", json_object_new_string(message));
        json_object_object_add(config->json_obj, "level", json_object_new_int((int)level));
        json_object_to_filestring(config->json_obj, 4, JSON_C_TO_STRING_PRETTY);
        fputs(config->json_obj->string, stdout);
