}

void syslog_log(LoggerConfig* config, const char* message, LogLevel level) {
    if (level >= config->level)
        openlog("MyApp", LOG_PID | LOG_CONS, LOG_DAEMON);
    syslog(LOG_LEVELS[level], "%s", message);
}

LoggerConfig* logger_config_init(const char* format_str, int level, void (*output)(LoggerConfig*, const char*, LogLevel)) {
    LoggerConfig* config = malloc(sizeof(LoggerConfig));
    config->format = format_str;
    config->level = level;
    config->output = output;

