#include <openssl/ssl.h>
#include <openssl/err.h>
#include <openssl/ec.h>

SSL_CTX *create_tls_context() {
    const SSL_METHOD *method;
    SSL_CTX *ctx;

    // Create TLS context with ECDH key exchange and ECDSA authentication method
    method = SSLv23_server_method();
    EC_KEY *ec_key = EC_KEY_new_by_ curve_name(NID_X9_62_prime256v1); // Use secp256r1 curve for ECDH and ECDSA
    if (!EC_KEY_generate_parameters(ec_key)) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    // Configure the context to use ephemeral ECDH parameters for each session and support PFS
    EC_KEY *tmp_ec_key = EC_KEY_dup(ec_key);
    SSL_CTX_set_ecdh_auto(ctx, 1);
    SSL_CTX_set_tmp_ecdh(ctx, tmp_ec_key);

    // Set the private key for ECDSA authentication
    SSL_CTX_use_certificate_chain_file("server.crt");
    SSL_CTX_set_ec_key(ctx, ec_key);

    // Configure context options
    SSL_CTX_set_options(ctx, SSL_OP_NO_COMPRESSION | SSL_OP_NO_SSLv2 | SSL_OP_NO_SSLv3 | SSL_OP_NO_TLSv1 | SSL_OP_NO_TLSv1_1);

    return ctx;
}

int tls_connect(SSL *ssl, const char *hostname) {
    // Connect to the server and initiate the TLS handshake using the provided context
    if (SSL_connect(ssl) <= 0) {
        ERR_print_errors_fp(stderr);
        return -1;
    }

    // Set hostname for SNI extension during the TLS handshake
    SSL_set_tlsext_host_name(ssl, hostname);

    return 0;
}

void tls_close(SSL *ssl) {
    // Clean up and close the SSL connection
    SSL_free(ssl);
    EVP_cleanup();
}
