typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_RX_FRAME_T;

struct memory_block {
    void *memory;
    size_t size;
    struct memory_block *next;
};

typedef struct {
    struct memory_block *head;
    pthread_mutex_t lock;
} CustomAllocator;

CustomAllocator ca;
AES_KEY aes_ctx;

void custom_allocator_init() {
    ca.head = NULL;
    pthread_mutex_init(&ca.lock, NULL);
}

void *custom_malloc(size_t size) {
    struct memory_block *new_block = (struct memory_block*) malloc(sizeof(struct memory_block));
    if (!new_block) return NULL;

    new_block->memory = malloc(size);
    if (!new_block->memory) {
        free(new_block);
        return NULL;
    }

    new_block->size = size;
    new_block->next = ca.head;
    ca.head = new_block;

    pthread_mutex_lock(&ca.lock);
    if (new_block->next)
        new_block->next->memory -= sizeof(struct memory_block);
    pthread_mutex_unlock(&ca.lock);

    return new_block->memory;
}

void custom_free(void *ptr) {
    struct memory_block *current = ca.head, *prev = NULL;
    void *block_ptr;

    pthread_mutex_lock(&ca.lock);
    while (current != NULL) {
        block_ptr = current->memory;
        if (ptr <= block_ptr && ptr + sizeof(NFAPI_RX_FRAME_T) >= block_ptr + current->size) {
            if (prev == NULL) {
                ca.head = current->next;
            } else {
                prev->next = current->next;
            }

            free(current);
            free(block_ptr - sizeof(struct memory_block));
            ptr += sizeof(NFAPI_RX_FRAME_T);
            break;
        }

        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&ca.lock);
}

void aes_init(const unsigned char *password, size_t password_len) {
    unsigned char digest[SHA_DIGEST_LENGTH];
    SHA1((unsigned char*)password, password_len, digest);

    AES_set_encrypt_key((const unsigned char*)digest, AES_KEY_SIZE, &aes_ctx);
    AES_ IV_length = AES_BLOCK_SIZE;
    unsigned char iv[AES_IV_LENGTH];
    memset(iv, 0, sizeof(iv)); // Set IV to zeros by default.
    aes_ctx.iv = iv;
}

void aes_cleanup() {
    AES_free_key(&aes_ctx);
}

NFAPI_RX_FRAME_T* nfapi_rx_frame_init() {
    NFAPI_RX_FRAME_T *frame = custom_malloc(sizeof(NFAPI_RX_FRAME_T));
    if (!frame) return NULL;

    return frame;
}
