NFAPI_RX_FRAME_T* dynamic_array_insert(struct cipher_manager* manager) {
    if (manager->size == manager->capacity) {
        manager->capacity *= 2;
        manager->contexts = realloc(manager->contexts, manager->capacity * sizeof(struct cipher_context));
    }

    pthread_mutex_lock(&manager->lock);
    NFAPI_RX_FRAME_T* frame = &manager->contexts[manager->size++];
    pthread_mutex_unlock(&manager->lock);

    return frame;
}

