int read_integers(int16_t **arr, size_t *len) {
    int c;
    size_t i = 0;
    while ((c = getchar()) != EOF && i < *len) {
        if (c < '0' || c > '9') {
            log_message("Invalid input detected.");
            return -1;
        }
        (*arr)[i] = c - '0';
        if ((*arr)[i] >= 10 * (*len)) {
            log_message("Input list size exceeded.");
            free(*arr);
            return -1;
        }
        i++;
    }

    if (c == EOF) {
        if (i > 0) {
            *len = i;
            return 0;
        } else {
            log_message("Empty input list.");
            free(*arr);
            return -1;
        }
    }

    // Reallocate memory and continue reading if more integers are detected
    int16_t *new_arr = realloc(*arr, sizeof(int16_t) * (i + 1));
    if (!new_arr) {
        log_message("Memory allocation error.");
        free(*arr);
        return -1;
    }
    *arr = new_arr;

    while ((c = getchar()) != EOF && i < *len) {
        if (c < '0' || c > '9') {
            log_message("Invalid input detected.");
            free(*arr);
            return -1;
        }
        (*arr)[i] = c - '0';
        if ((*arr)[i] >= 10 * (*len)) {
            log_message("Input list size exceeded.");
            free(*arr);
            return -1;
        }
        i++;
    }

    *len = i;
    return 0;
}

int find_max(const int16_t *arr, size_t len) {
    int max = arr[0];
    for (size_t i = 1; i < len; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

int main() {
    int16_t *arr = NULL;
    size_t len = 0;

    if (read_integers(&arr, &len) != 0) {
        log_message("Error occurred while reading input.");
        return -1;
    }

    int max = find_max(arr, len);
    printf("Largest integer: %" PRId16 "\n", max);

    free(arr);
    return 0;
}
