    pthread_mutex_lock(&mutex_frames);

    if (numFrames >= MAX_FRAMES) {
        fprintf(stderr, "Reached max frames limit\n");
        pthread_mutex_unlock(&mutex_frames);
        sem_post(&sem_frames);
        return;
    }

    frames[numFrames] = (*frame);
    numFrames++;
    pthread_mutex_unlock(&mutex_frames);
    sem_post(&sem_frames);
}

NFAPI_UL_TX_FRAME_T *frame_get(size_t index) {
    NFAPI_UL_TX_FRAME_T *frame;

    sem_wait(&sem_frames);
    pthread_mutex_lock(&mutex_frames);

    if (index >= numFrames || index >= MAX_FRAMES) {
        fprintf(stderr, "Invalid frame index\n");
        pthread_mutex_unlock(&mutex_frames);
        sem_post(&sem_frames);
        return NULL;
    }

    frame = &frames[index];
    pthread_mutex_unlock(&mutex_frames);
    sem_post(&sem_frames);
    return frame;
}

void crcIndication_add(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    sem_wait(&sem_crcs);
    pthread_mutex_lock(&mutex_crcs);

    if (numCrcIndications >= MAX_CRCS) {
        fprintf(stderr, "Reached max CRC indications limit\n");
        pthread_mutex_unlock(&mutex_crcs);
        sem_post(&sem_crcs);
        return;
    }

    crcIndications[numCrcIndications] = (*pdu);
    numCrcIndications++;
    pthread_mutex_unlock(&mutex_crcs);
    sem_post(&sem_crcs);
}

NFAPI_CRC_INDICATION_PDU_T *crcIndication_get(size_t index) {
    NFAPI_CRC_INDICATION_PDU_T *pdu;

    sem_wait(&sem_crcs);
    pthread_mutex_lock(&mutex_crcs);

    if (index >= numCrcIndications || index >= MAX_CRCS) {
        fprintf(stderr, "Invalid CRC indication index\n");
        pthread_mutex_unlock(&mutex_crcs);
        sem_post(&sem_crcs);
        return NULL;
    }

    pdu = &crcIndications[index];
    pthread_mutex_unlock(&mutex_crcs);
    sem_post(&sem_crcs);
    return pdu;
}
