#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    int len;
    int *data;
} IntArray;

typedef struct {
    int len;
    double *data;
} FloatArray;

void log_message(const char *message, const char *log_file) {
    if (log_file != NULL) {
        int fd = open(log_file, O_WRONLY | O_APPEND | O_CREAT | O_SYNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
        if (fd >= 0) {
            dprintf(fd, "%s\n", message);
            close(fd);
        }
    }
    printf("%s\n", message);
}

void free_int_array(IntArray *arr) {
    if (arr->data != NULL) {
        free(arr->data);
        arr->data = NULL;
        arr->len = 0;
    }
}

void free_float_array(FloatArray *arr) {
    if (arr->data != NULL) {
        free(arr->data);
        arr->data = NULL;
        arr->len = 0;
    }
}

IntArray *read_ints() {
    IntArray *arr = malloc(sizeof(IntArray));
    arr->data = NULL;
    arr->len = 0;

    int c, num = 0;
    while ((c = getchar()) != EOF) {
        if (isdigit(c)) {
            num *= 10;
            num += c - '0';
        } else if (num > 0) {
            arr->data = realloc(arr->data, sizeof(int) * (arr->len + 1));
            arr->data[arr->len] = num;
            arr->len++;
            num = 0;
        }
    }

    if (num > 0) {
        arr->data = realloc(arr->data, sizeof(int) * (arr->len + 1));
        arr->data[arr->len] = num;
        arr->len++;
    }

    return arr;
}

FloatArray *read_floats() {
    FloatArray *arr = malloc(sizeof(FloatArray));
    arr->data = NULL;
    arr->len = 0;

    int c, num_point = 0;
    double num = 0.0;
    while ((c = getchar()) != EOF) {
        if (isdigit(c)) {
            num *= 10;
            num += c - '0';
        } else if (c == '.') {
            if (num_point > 0) {
                fprintf(stderr, "Invalid floating-point number format\n");
                exit(EXIT_FAILURE);
            }
            num_point = 1;
        } else if (num > 0.0 || c == EOF) {
            if (num_point == 0 && num != 0.0) {
                arr->data = realloc(arr->data, sizeof(double) * (arr->len + 1));
                arr->data[arr->len] = num;
                arr->len++;
            }
            num = 0.0;
            num_point = 0;
        }
    }

    if (num_point == 1 && num != 0.0) {
        arr->data = realloc(arr->data, sizeof(double) * (arr->len + 1));
        arr->data[arr->len] = num;
        arr->len++;
    }

    return arr;
}

void find_maxes(IntArray *int_arr, FloatArray *float_arr, int *largest_int, double *largest_fp) {
    *largest_int = *largest_fp = -1.0;

    for (size_t i = 0; i < int_arr->len; ++i) {
        if (int_arr->data[i] > *largest_int) {
            *largest_int = int_arr->data[i];
        }
    }

    for (size_t i = 0; i < float_arr->len; ++i) {
        if (float_arr->data[i] > *largest_fp) {
            *largest_fp = float_arr->data[i];
        }
    }
}

double average(const FloatArray *arr) {
    double sum = 0.0;
    for (size_t i = 0; i < arr->len; ++i) {
        sum += arr->data[i];
    }
    return sum / arr->len;
}

int main() {
    char *log_file = "process.log";

    IntArray *ints = read_ints();
    FloatArray *floats = read_floats();

    double largest_int, largest_fp;
    find_maxes(ints, floats, &largest_int, &largest_fp);

    log_message("Largest Integer: ", log_file);
    log_message(format("%d", largest_int), log_file);
    printf("Largest Integer: %d\n", largest_int);

    log_message("Largest Floating-Point Number: ", log_file);
    log_message(format("%.6f", largest_fp), log_file);
    printf("Largest Floating-Point Number: %.6f\n", largest_fp);

    double avg_int = average(ints);
    double avg_fp = average(floats);

    log_message("Average of Integers: ", log_file);
    log_message(format("%.6f", avg_int), log_file);
    printf("Average of Integers: %.6f\n", avg_int);

    log_message("Average of Floating-Point Numbers: ", log_file);
    log_message(format("%.6f", avg_fp), log_file);
    printf("Average of Floating-Point Numbers: %.6f\n", avg_fp);

    free_int_array(ints);
    free_float_array(floats);

    return 0;
}
