#include <stdio.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/sha.h>
#include <uuid/uuid.h>
#include <pthread.h>
#include <sys/mman.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_RX_FRAME_T;

typedef struct {
    AES_KEY cipher;
    UUID uuid;
    pthread_mutex_t lock;
    size_t memory_allocated;
    size_t memory_used;
} CIPHER_CONTEXT_T;

static inline void* custom_malloc(size_t size) {
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

static inline void custom_free(void *ptr, size_t size) {
    if (munmap(ptr, size) == -1) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }
}

static CIPHER_CONTEXT_T* create_cipher_context() {
    CIPHER_CONTEXT_T *ctx = custom_malloc(sizeof(CIPHER_CONTEXT_T));
    ctx->lock = PTHREAD_MUTEX_INITIALIZER;
    ctx->memory_allocated = 0;
    ctx->memory_used = 0;
    return ctx;
}

static void destroy_cipher_context(CIPHER_CONTEXT_T *ctx) {
    custom_free(ctx, sizeof(CIPHER_CONTEXT_T));
}

static UUID create_uuid() {
    UUID uuid;
    uuid_gen_time(&uuid);
    uuid_genrand((uint8_t*)&uuid.time_low[0]);
    return uuid;
}

static int setup_aes(CIPHER_CONTEXT_T *ctx, const char *password) {
    SHA1_CTX ctx_sha1;
    unsigned char sha1_digest[SHA_DIGEST_LENGTH];

    SHA1_Init(&ctx_sha1);
    SHA1_Update(&ctx_sha1, (const unsigned char*)password, strlen(password));
    SHA1_Final(sha1_digest, &ctx_sha1);

    AES_set_encrypt_key((const unsigned char *)sha1_digest, 256, &ctx->cipher);
    ctx->cipher.iv = (unsigned char*)calloc(AES_BLOCK_SIZE, sizeof(uint8_t));

    return 0;
}

static void log_operation(CIPHER_CONTEXT_T *ctx, const char *message) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

    printf("[%s] [UUID: %s] [Operation: %s]\n", time_str, ctx->uuid.raw, message);
}

static CIPHER_CONTEXT_T* initialize_dynamic_array(size_t size) {
    CIPHER_CONTEXT_T *ctx = create_cipher_context();
    NFAPI_RX_FRAME_T **data = custom_malloc(sizeof(NFAPI_RX_FRAME_T*) * size);

    ctx->memory_allocated = (size_t)(sizeof(NFAPI_RX_FRAME_T*) * size + sizeof(NFAPI_RX_FRAME_T) * size);
    ctx->memory_used = 0;

    for (size_t i = 0; i < size; ++i) {
        data[i] = custom_malloc(sizeof(NFAPI_RX_FRAME_T));
        memset(data[i], 0, sizeof(NFAPI_RX_FRAME_T));
    }

    return ctx;
}

static void destroy_dynamic_array(CIPHER_CONTEXT_T *ctx) {
    for (size_t i = 0; i < ctx->memory_allocated / sizeof(NFAPI_RX_FRAME_T); ++i) {
        custom_free(ctx->data[i], sizeof(NFAPI_RX_FRAME_T));
    }
    custom_free(ctx->data, sizeof(NFAPI_RX_FRAME_T*) * ctx->memory_allocated / sizeof(NFAPI_RX_FRAME_T));
}
```

