#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

typedef struct {
    int *data;
    size_t capacity;
    size_t size;
} IntArray;

IntArray* create_int_array(size_t capacity) {
    IntArray *arr = malloc(sizeof(IntArray));
    if (!arr) return NULL;
    arr->capacity = capacity;
    arr->size = 0;
    arr->data = calloc(capacity, sizeof(int));
    if (!arr->data) {
        free(arr);
        return NULL;
    }
    return arr;
}

void resize_int_array(IntArray *arr, size_t new_capacity) {
    int *new_data = realloc(arr->data, new_capacity * sizeof(int));
    if (!new_data) return;
    arr->data = new_data;
    arr->capacity = new_capacity;
}

void push_int_array(IntArray *arr, int value) {
    if (arr->size == arr->capacity) resize_int_array(arr, arr->capacity ? arr->capacity * 2 : 4);
    arr->data[arr->size++] = value;
}

void destroy_int_array(IntArray *arr) {
    free(arr->data);
    free(arr);
}

void handle_error(const char *message, IntArray *arr) {
    fprintf(stderr, "%s\n", message);
    destroy_int_array(arr);
}

json_object* serialize_to_json(IntArray *arr) {
    json_object *json = json_object_new_array();
    for (size_t i = 0; i < arr->size; ++i) {
        json_object *obj = json_object_new_int(arr->data[i]);
        json_array_add(json, obj);
    }
    return json;
}

void process_batch(IntArray *arr, void (*callback)(const char*)) {
    if (arr->size == 0) return;

    json_object* json = serialize_to_json(arr);
    if (!json) handle_error("Failed to serialize data", arr);

    char *payload = json_object_to_json_string(json);
    if (!payload) handle_error("Failed to convert JSON object to string", arr);

    const int latency_limit = 100000; // 100 milliseconds in microseconds
    clock_t start = clock();

    callback(payload);

    free(payload);

    if (clock() - start > latency_limit) {
        fprintf(stderr, "Processing took too long: %lld microseconds\n", (clock() - start) * 1000);
    }
}

void read_and_process(size_t capacity, void (*callback)(const char*)) {
    IntArray *arr = create_int_array(capacity);
    if (!arr) handle_error("Failed to allocate memory for array", arr);

    int input;
    while (scanf("%d", &input) == 1 && input >= -100 && input <= 100 && arr->size < capacity) {
        push_int_array(arr, input);
    }
    if (ferror(stdin)) handle_error("Error reading from standard input", arr);

    process_batch(arr, callback);
}

void find_largest(const IntArray *arr) {
    int largest = INT_MIN;
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->data[i] > largest) largest = arr->data[i];
    }
    printf("Largest number: %d\n", largest);
}

int main() {
    read_and_process(10, find_largest);

    return 0;
}
```
