mem_pool_t *rx_frames_pool = NULL;
mem_pool_t *packets_pool = NULL;
int num_received_packets = 0;

// Function to manage dynamic collection of PHY_RX_FRAME_T structures and received packets
void process_queue(int M) {
    const int table_size = 1024;
    chm_node_t *table[table_size];
    for (int i = 0; i < table_size; ++i)
        table[i] = NULL;

    // Initialize memory pools with a specified capacity and size
    mem_pools_lock = PTHREAD_MUTEX_INITIALIZER;
    rx_frames_pool = mem_pool_create(sizeof(PHY_RX_FRAME_T), 10000);
    packets_pool = mem_pool_create(sizeof(PACKET_ID), M);

    // Process incoming packets asynchronously, handling delays in receiving frame configurations and packet data
    while (true) {
        // Allocate memory for a new packet ID if needed
        PACKET_ID *packet_id;
        if (num_received_packets >= M) break;
        pthread_mutex_lock(&mem_pools_lock);
        if (packets_pool->allocated == packets_pool->capacity) {
            pthread_mutex_unlock(&mem_pools_lock);
            continue; // Skip allocation if memory pool is full
        }
        packet_id = mem_pool_malloc(packets_pool);
        num_received_packets++;
        pthread_mutex_unlock(&mem_pools_lock);

        // Allocate memory for a new RX frame if needed
        PHY_RX_FRAME_T *rx_frame;
        pthread_mutex_lock(&mem_pools_lock);
        if (rx_frames_pool->allocated == rx_frames_pool->capacity) {
            pthread_mutex_unlock(&mem_pools_lock);
            continue; // Skip allocation if memory pool is full
        }
        rx_frame = mem_pool_malloc(rx_frames_pool);
        pthread_mutex_unlock(&mem_pools_lock);

        // Fill in the RX frame structure with received packet data and configure it according to external sources
        // ... (Implement this part based on the specific requirements of your system)

        // Hash the RX frame to find its position in the concurrent hash map
        uint64_t hash = hash_function(rx_frame);
        chm_node_t *chm_node = chm_lookup(table, hash);

        // Insert the RX frame into the CHM and chain it to the existing frames in the same bucket if any
        chm_insert(table, hash, *rx_frame);
    }
}
