#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>
#include <openssl/sha.h>

#define MAX_LOG_LEVEL 5
#define LOG(level, ...) if (log_level <= level) { printf(__VA_ARGS__); }

typedef struct {
    unsigned short bits_per_sample;
    unsigned short sample_per_pixel;
    int extra_samples;
    unsigned char* extra_data;
} image_info;

image_info parse_tiff(const char *filename, int log_level, const char *hash) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        LOG(1, "Error: Could not open file %s\n", filename);
        return (image_info){0};
    }

    image_info info = {0};
    unsigned short bitspersample, photometrics;
    unsigned char padding[TIFFScanlineSize(tif)];

    while (TIFFReadDirectory(tif) == 1) {
        if (TIFFGetField(tif, TIFFTagSAMPLESPERPIXEL, &info.sample_per_pixel) != 1) {
            info.sample_per_pixel = 3; // default to RGB
        }

        if (TIFFGetField(tif, TIFFTagBITSPERSAMPLE, &bitspersample) != 1) {
            LOG(1, "Error: Missing bits per sample field\n");
            TIFFCleanup(tif);
            return (image_info){0};
        }

        switch (bitspersample) {
            case 1:
            case 2:
            case 4:
            case 8:
            case 16:
                break;
            default:
                LOG(1, "Error: Unsupported bits per sample %d\n", bitspersample);
                TIFFCleanup(tif);
                return (image_info){0};
        }

        if (TIFFGetField(tif, TIFFTagEXTRASAMPLES, &info.extra_samples) != 1) {
            info.extra_samples = 0;
        } else {
            unsigned short num_extrasample;
            if (TIFFGetField(tif, TIFFTagEXTRASAMPLEDESCRIPTOR, info.extra_data) == -1) {
                LOG(1, "Error: Could not get extra sample descriptor\n");
                TIFFCleanup(tif);
                return (image_info){0};
            }

            memcpy(&num_extrasample, info.extra_data + 2, sizeof(unsigned short));
            info.extra_samples = num_extrasample;
        }
    }

    if (!TIFFGetField(tif, TIFFTagPHOTOMETRIC, &photometrics)) {
        photometrics = PHOTO_MINISBLACK; // default to minisblack
    }

    switch (info.sample_per_pixel) {
        case 1:
            if (photometrics == PHOTO_MINISWHITE || photometrics == PHOTO_RGB) {
                info.bits_per_sample = bitspersample;
            } else {
                LOG(1, "Error: Unsupported photometric value %d for single sample\n", photometrics);
                TIFFCleanup(tif);
                return (image_info){0};
            }
            break;
        case 2:
            if (photometrics == PHOTO_MINISWHITE || photometrics == PHOTO_RGB) {
                info.bits_per_sample = bitspersample / 2;
            } else if (photometrics == PHOTO_MINISBLACK || photometrics == PHOTO_PALETTE) {
                info.bits_per_sample = bitspersample;
            } else {
                LOG(1, "Error: Unsupported photometric value %d for dual sample\n", photometrics);
                TIFFCleanup(tif);
                return (image_info){0};
            }
            break;
        case 3:
            info.bits_per_sample = bitspersample / 3;
            if (photometrics != PHOTO_RGB) {
                LOG(1, "Error: Unsupported photometric value %d for RGB\n", photometrics);
                TIFFCleanup(tif);
                return (image_info){0};
            }
            break;
        case 4:
            if (photometrics != PHOTO_CMYK) {
                LOG(1, "Error: Unsupported photometric value %d for CMYK\n", photometrics);
                TIFFCleanup(tif);
                return (image_info){0};
            }
            info.bits_per_sample = bitspersample / 4;
            break;
        default:
            LOG(1, "Error: Unsupported sample per pixel value %d\n", info.sample_per_pixel);
            TIFFCleanup(tif);
            return (image_info){0};
    }

    unsigned char key[SHA256_DIGEST_LENGTH];
    if (log_level > 0 && strlen(hash) > 0) {
        EVP_MD_CTX *ctx = EVP_MD_CTX_new();
        EVP_DigestInit_ex(ctx, EVP_sha256(), NULL);
        EVP_DigestUpdate(ctx, key, SHA256_DIGEST_LENGTH);
        TIFFReadScanline(tif, padding, 0); // read a scanline to initialize the random number generator seed
        EVP_DigestFinal_ex(ctx, key, NULL);
        EVP_MD_CTX_free(ctx);

        unsigned char expected[SHA256_DIGEST_LENGTH];
        if (strncmp((const char*)key, hash, SHA256_DIGEST_LENGTH) != 0) {
            LOG(1, "Error: Generated key hash does not match the expected value\n");
            TIFFCleanup(tif);
            return (image_info){0};
        }
    }

    TIFFClose(tif);
    return info;
}
```']

