    public class RandomValueGenerator
    {
        private readonly Tuple<double, double> _range;
        private readonly bool _isExclusive;

        public RandomValueGenerator(Tuple<double, double> range, bool isExclusive = false)
        {
            _range = range;
            _isExclusive = isExclusive;
        }

        public float GetRandomFloat()
        {
            if (_range.Item1 > _range.Item2)
                throw new ArgumentOutOfRangeException(nameof(_range), "Lower bound must be smaller than the upper bound.");

            var random = new Random();
            var rangeSize = _range.Item1 - _range.Item2;
            if (rangeSize <= 0)
                return _range.Item2; // If the range size is zero or negative, return the lower bound.

            float value;
            lock (this)
            {
                value = _isExclusive ? (random.NextFloat() * rangeSize + _range.Item2) : (random.NextDouble() * rangeSize + _range.Item2);
            }
            return MathF.Round(value, 6); // Maintain floating-point precision by rounding the generated value to six decimal places.
        }

        public int GetRandomInt()
        {
            if (_range.Item1 > _range.Item2)
                throw new ArgumentOutOfRangeException(nameof(_range), "Lower bound must be smaller than the upper bound.");

            var random = new Random();
            return (int)_isExclusive ? random.Next((int)_range.Item2, (int)_range.Item1 + 1) : random.Next((int)_range.Item1, (int)_range.Item2 + 1);
        }

        public override string ToString()
        {
            return $"Range: ({_range.Item1}, {_range.Item2}), IsExclusive: {_isExclusive}";
        }

        public static IEnumerable<float> GetAverage(Func<RandomValueGenerator, float> generatorFunction, int iterations = 1000)
        {
            var randomGenerators = Enumerable.Range(0, iterations).Select(_ => new RandomValueGenerator((2.5, 7.3), true)).ToList();
            var sum = randomGenerators.Sum(generatorFunction);
            return Enumerable.Repeat(sum / iterations, 1);
        }
    }

    public static string DecryptBase64(string base64EncodedString, string key, string iv)
    {
        var encryptedData = Convert.FromBase64String(base64EncodedString);
        using (var tripleDES = TripleDESCryptoServiceProvider.Create())
        {
            tripleDES.Key = Encoding.UTF8.GetBytes(key);
            tripleDES.IV = Encoding.UTF8.GetBytes(iv);
            var transform = tripleDES.CreateDecryptor();
            return Encoding.UTF8.GetString(transform.TransformFinalBlock(encryptedData, 0, encryptedData.Length));
        }
    }
}
