    public void BatchUpdate(List<(int pageSectionId, int elementId, string content)> updates)
    {
        var priorityQueue = new PriorityQueue(updates.OrderByDescending(x => x.Item1.Priority));
        while (priorityQueue.Count > 0)
        {
            var update = priorityQueue.Dequeue();
            _service.UpdateElementContent(update.pageSectionId, update.elementId, update.content);
        }
        RefreshPage();
    }

    public string DecryptBase64(string base64EncodedData)
    {
        var encoder = new Base64Decoder();
        var decryptedBytes = encoder.DecodeBuffer(base64EncodedData);
        var decryptor = TripleDES.Create();
        using (var memoryStream = new MemoryStream(decryptedBytes))
        {
            memoryStream.Seek(0, SeekOrigin.Begin);
            using (var cryptoStream = new CryptoStream(memoryStream, decryptor.CreateDecryptor(Key.GetBytes(), IV), CryptoStreamMode.Read))
            {
                var result = new StringBuilder();
                int read;
                while ((read = cryptoStream.ReadByte()) != -1)
                    result.Append((char)read);
                return result.ToString();
            }
        }
    }

