    private float _fMax;
    private double _dSum;
    private long _count;

    public int Min { get => _min; set => _min = Math.Clamp(value, int.MinValue, int.MaxValue); }
    public int Max { get => _max; set => _max = Math.Clamp(value, int.MinValue, int.MaxValue); }
    public float FMin { get => _fMin; set => _fMin = Math.Clamp(value, float.MinValue, float.MaxValue); }
    public float FMax { get => _fMax; set => _fMax = Math.Clamp(value, float.MinValue, float.MaxValue); }

    public RandomValueGenerator(int min, int max)
    {
        _min = min;
        _max = max;
    }

    public double Generate()
    {
        if (_count == 0)
        {
            _dSum = 0;
            _count = 0;
        }

        var value = Random.Shared.Next(_min, _max + 1);
        _dSum += value;
        _count++;

        if (_count >= 1000) // Adjust the number as needed
        {
            double average = _dSum / _count;
            _dSum -= average * _count;
            _count -= 1000;
            return average;
        }

        return value;
    }
}
