struct MoSTState {};

class BatchFileProcessor {
public:
    void batchFileProcessing(const std::vector<std::string>& filenames, const std::string& fileType) {
        // Generate unique identifier based on filename's characters
        auto generateIdentifier = [](const std::string& str) {
            std::hash<std::string> hasher;
            return std::to_string(hasher(str));
        };

        boost::mt19937 rng(time(0));
        std::uniform_int_distribution<> distr(0, 9999);

        std::atomic<int> concurrentBatches{0};
        std::vector<std::future<void>> futures;
        for (size_t i = 0; i < filenames.size(); ++i) {
            if (concurrentBatches >= 10 || futures.size() >= 1000) {
                // Wait for completion of previous batches before starting a new one
                while (concurrentBatches > 0 && !futures.empty()) {
                    concurrentBatches--;
                    futures[futures.size() - 1].wait();
                    futures.pop_back();
                }
            }

            std::string id = generateIdentifier(filenames[i]);
            int suffix = 0;
            do {
                std::string timestamp = std::to_string(std::chrono::duration_cast<std::chrono::seconds>(
                        std::chrono::system_clock::now().time_since_epoch()).count()) + ".sss";
                std::string newFileName = id + "_" + timestamp + distr(rng) % 10000 + "." + fileType;

                // Check for valid filename and path
                if (boost::filesystem::is_regular_file(filenames[i]) && newFileName.length() <= 255 &&
                    boost::regex_match(newFileName, regex("^[a-zA-Z0-9\\._-]+$"))) {
                    // Replace original file with the processed one
                    rename(filenames[i].c_str(), (newFileName).c_str());
                    concurrentBatches++;
                } else {
                    std::cout << "Error: Invalid filename or path: " << filenames[i] << std::endl;
                }
            } while (!boost::filesystem::is_regular_file(newFileName) && ++suffix < 10);
        }

        // Load and process state object if required
        loadState();

        // Implement parallel processing for up to 10 concurrent batches
        futures.clear();
        for (size_t i = 0; i < std::min(filenames.size(), 10U); ++i) {
            if (concurrentBatches >= 10 || futures.size() >= 1000) {
                // Wait for completion of previous batches before starting a new one
                while (concurrentBatches > 0 && !futures.empty()) {
                    concurrentBatches--;
                    futures[futures.size() - 1].wait();
                    futures.pop_back();
                }
            }
            std::vector<std::string> batchFiles(filenames.begin() + i * 500, filenames.begin() + std::min((i+1)*500, filenames.size()));
            futures.push_back(std::async(std::launch::async, [&](const auto& files) {
                batchFileProcessing(files, fileType);
            }, batchFiles));
        }

        // Wait for all batches to complete
        for (auto& future : futures) future.wait();
    }

private:
    MoSTState* loadState() {
        std::ifstream inFile("state.txt", std::ios::binary);
        if (!inFile) return nullptr;

        MoSTState* state = nullptr;
        try {
            std::cout << "Loading state object..." << std::endl;
            state = new MoSTState();
            boost::serialization::ifstream is(inFile, boost::serialization::is_boost);
            boost::serialization::load_nvp(is, *state);
        } catch (const std::exception& e) {
            std::cerr << "Error while loading state object: " << e.what() << std::endl;
        }

        if (inFile.is_open()) inFile.close();
        return state;
    }
};
