```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Task {
    unsigned long id;
    int priority;
    time_t deadline;
} Task;

typedef struct PriorityQueue {
    Task* tasks;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} PriorityQueue;

void task_queue_init(PriorityQueue* queue) {
    queue->tasks = NULL;
    queue->capacity = 0;
    queue->count = 0;
    pthread_mutex_init(&queue->mutex, NULL);
}

void task_queue_destroy(PriorityQueue* queue) {
    free(queue->tasks);
    pthread_mutex_destroy(&queue->mutex);
}

static int compare_task(const void* a, const void* b) {
    const Task* ta = (const Task*)a;
    const Task* tb = (const Task*)b;
    if (ta->priority != tb->priority) return tb->priority - ta->priority;
    return ta->deadline > tb->deadline ? 1 : -1;
}

static void enqueue(PriorityQueue* queue, Task task) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count >= queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        Task* new_tasks = realloc(queue->tasks, sizeof(Task) * new_capacity);
        if (!new_tasks) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&queue->mutex);
            return;
        }
        queue->tasks = new_tasks;
        queue->capacity = new_capacity;
    }
    queue->tasks[queue->count++] = task;
    qsort(queue->tasks, queue->count, sizeof(Task), compare_task);
    pthread_mutex_unlock(&queue->mutex);
}

// ... (implement other required functions such as dequeue, cancel, log)
```

This code provides a basic priority queue data structure for managing tasks. You can use it as a foundation to build the rest of your application according to your specific needs and requirements.']

