#include <pthread.h>
#define MAX_ELEMENTS 1024

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG ctag;
    unsigned char crcflag;
    uint32_t reserved[2]; // For future expansion
} NFAPI_CRC_INDICATION_PDU_T;

struct dyn_array {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

void init_dyn_array(struct dyn_array *arr) {
    arr->elements = NULL;
    arr->capacity = 0;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
}

void destroy_dyn_array(struct dyn_array *arr) {
    if (arr->elements) {
        free(arr->elements);
    }
    pthread_mutex_destroy(&arr->mutex);
}

int add_element(struct dyn_array *arr, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!arr || !pdu) {
        return -1; // Invalid input
    }

    pthread_mutex_lock(&arr->mutex);

    if (arr->size == arr->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(arr->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (arr->capacity + MAX_ELEMENTS));
        if (!new_elements) { // Memory allocation failed
            pthread_mutex_unlock(&arr->mutex);
            return -1;
        }
        arr->capacity += MAX_ELEMENTS;
        arr->elements = new_elements;
    }

    memcpy(arr->elements + arr->size, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->size++;

    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

const NFAPI_CRC_INDICATION_PDU_T *get_element(const struct dyn_array *arr, size_t index) {
    if (!arr || index >= arr->size) {
        return NULL; // Invalid input or out of bounds
    }

    pthread_mutex_lock(&arr->mutex);
    const NFAPI_CRC_INDICATION_PDU_T *pdu = arr->elements + index;
    pthread_mutex_unlock(&arr->mutex);

    return pdu;
}

// Implement other functions for handling edge cases, error handling, and optimizations.
