using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class RandomValueGenerator
{
    private readonly object _syncLock;
    private float _min, _max;
    private Random _random;

    public RandomValueGenerator(float min, float max)
    {
        if (max <= min) throw new ArgumentException("Max value should be greater than or equal to Min value.");
        _syncLock = new object();
        _min = min;
        _max = max;
        _random = new Random((int)(DateTime.Now.Ticks * (ThreadStaticFieldLocation.Manual)) ^ Environment.ProcessorCount);
    }

    public float Min { get => _min; set => _min = value; }
    public float Max { get => _max; set => _max = value; }

    public override string ToString() => $"({_min}, {_max})";

    private float Clamp(float value)
    {
        if (value < _min) return _min;
        if (value > _max) return _max;
        return value;
    }

    public float GetRandomFloat(bool excludeMax = false)
    {
        lock (_syncLock)
        {
            float randomValue;
            do
            {
                randomValue = (float)_random.NextDouble() * (_max - _min) + _min;
            } while ((excludeMax && randomValue == _max) || (randomValue > _max));

            return Clamp(randomValue);
        }
    }

    public int GetRandomInt(bool excludeMax = false)
    {
        lock (_syncLock)
        {
            int randomValue;
            do
            {
                randomValue = (int)(_random.NextDouble() * (_max - _min + 1)) + _min;
            } while ((excludeMax && randomValue == _max) || (randomValue > _max));

            return Clamp(randomValue);
        }
    }

    public async Task GenerateSampleDataAsync(int size, float samplingFrequency, CancellationToken cancellationToken = default)
    {
        var data = new List<float>();
        int sampleCount = (int)(size * samplingFrequency);

        for (int i = 0; i < sampleCount && !cancellationToken.IsCancellationRequested; ++i)
        {
            data.Add(GetRandomFloat());
        }

        // Generate the remaining values if needed, ensuring no more than size items in the dataset
        int remaining = size - data.Count;
        if (remaining > 0 && !cancellationToken.IsCancellationRequested)
        {
            int sampleCountToGenerate = Math.Min(sampleCount, remaining);
            var tempData = data.ToArray();
            Array.Resize(ref tempData, size);
            for (int i = data.Count; i < size; ++i)
            {
                tempData[i] = GetRandomFloat();
            }
            data.Clear();
            data.AddRange(tempData);
        }
    }
}
