namespace WebApplication.Utilities
{
    public class EnhancedRandomValueGenerator
    {
        private readonly Random _random;
        private double _min;
        private double _max;
        private double _currentSampleRate = 1.0;
        private int _sampleSize = 10000;
        private readonly HashSet<double> _sequenceCache;
        private readonly List<(double value, DateTime timestamp)> _sampleBuffer;

        public EnhancedRandomValueGenerator(double min, double max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value should be less than or equal to maximum value.", nameof(min));

            _min = min;
            _max = max;
            _random = new Random((int)DateTime.Now.Ticks);
            _sequenceCache = new HashSet<double>();
            _sampleBuffer = new List<(double, DateTime)>(_sampleSize);
        }

        public int NextInt(bool isInclusiveMin, bool isInclusiveMax) => (int)((NextDouble(isInclusiveMin, isInclusiveMax) - _min) * ((double)(_max - _min + 1)) + _min);

        public float NextFloat(bool isInclusiveMin, bool isInclusiveMax) => (float)((NextDouble(isInclusiveMin, isInclusiveMax) - _min) * ((_max - _min) / (float)(_max - _min + 1)) + _min);

        public double NextDouble(bool isInclusiveMin, bool isInclusiveMax) => _random.NextDouble() * (_isInclusive(isInclusiveMax) ? (_max - _min) : _max - _min) + (_isInclusive(isInclusiveMin) ? _min : _min + ((_max - _min + 1) * 0.5));

        public bool NextBoolean(double probability) => _random.NextDouble() < probability;

        public IEnumerable<T> GenerateSequence<T>(int count, Func<T> valueGenerator) where T : struct
        {
            var sequence = new List<T>();
            for (var i = 0; i < count; ++i)
            {
                var currentValue = valueGenerator();
                if (!sequence.Contains(currentValue))
                    sequence.Add(currentValue);
                else
                    i--;
            }

            return sequence;
        }

        public IEnumerable<T> GenerateSampleData<T>(int size, Func<T> valueGenerator, double sampleRate = 1.0)
        {
            if (size <= 0) throw new ArgumentException("Size should be greater than zero.", nameof(size));
            _currentSampleRate = Math.Min(_currentSampleRate, sampleRate);

            var rng = new System.Collections.ThreadSafeRandom(new Random((int)DateTime.Now.Ticks));

            for (var i = 0; i < size; ++i)
            {
                if (rng.NextDouble() < _currentSampleRate / _sampleSize)
                {
                    _sampleBuffer.Add((valueGenerator(), DateTime.UtcNow));

                    if (_sampleBuffer.Count == _sampleSize)
                        SampleData();
                }

                valueGenerator();
            }

            return null;
        }

        private void SampleData()
        {
            var samples = from b in _sampleBuffer
                          group b by b.Item1 into g
                          let average = g.Average(x => x.Item2)
                          select new { Value = g.Key, Frequency = g.Count(), AverageTimestamp = average };

            Log.Information($"Sample data: [{JsonConvert.SerializeObject(samples)}]");
            _sampleBuffer.Clear();
        }

        public override string ToString() => $"Range: [{_min}, {_max}]; Current sample rate: {_currentSampleRate}; Sample size: {_sampleSize}; Sequence cache size: {_sequenceCache.Count}";

        private bool _isInclusive(bool value) => value;
    }
}
