3. Implement a wrapper for pthread_mutex_t to make it easier to use:

```c
#define LOCK(m) pthread_mutex_lock(&(m))
#define UNLOCK(m) pthread_mutex_unlock(&(m))
```

4. Implement the dynamic array function:

```c
typedef struct ARRAY {
    NFAPI_RX_FRAME_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ARRAY;

ARRAY* create_array() {
    ARRAY *array = (ARRAY *)custom_malloc(sizeof(ARRAY));
    array->capacity = 0;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_array(ARRAY *array) {
    pthread_mutex_destroy(&array->lock);
    custom_free(array);
}

bool insert(ARRAY* array, NFAPI_RX_FRAME_T frame) {
    LOCK(array->lock);

    // Handle the case when the array is full and needs to be resized
    if (array->capacity == array->count) {
        // Implement your resizing strategy here
    }

    NODE* node = custom_malloc(sizeof(NFAPI_RX_FRAME_T));
    node->data = frame;
    node->next = NULL;

    if (array->count == 0) {
        array->data = node;
    } else {
        NODE *last = array->data;
        while (last->next != NULL) last = last->next;
        last->next = node;
    }

    UNLOCK(array->lock);
    array->count++;

    return true;
}

NFAPI_RX_FRAME_T* find(ARRAY *array, uint32_t RX_UE_INFORMATION_TAG) {
    LOCK(array->lock);

    NODE *current = array->data;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            break;
        }
        current = current->next;
    }

    UNLOCK(array->lock);
    return current != NULL ? &current->data : NULL;
}
```

