    // Process incoming packets asynchronously
    void handlePacket(unsigned int packetId, const RX_FRAME_CONFIG& config, const RF_CHAIN& chain, ReceptionQuality quality) {
        PHY_RX_FRAME_T* frame = collection.addFrame(packetId, config, chain, quality);
        if (!frame) throw std::system_error(std::errc::resource_deadlock_would_occur, "Resource deadlock would occur");
    }
};
