        HashEntry *temp = *entry_ptr;
        *entry_ptr = malloc(sizeof(HashEntry));
        (*entry_ptr)->hash = customHash(key, ht->capacity);
        while (temp != NULL) {
            (*entry_ptr)->next = temp->next;
            temp->next = *entry_ptr;
            temp = temp->next;
        }
        (*entry_ptr)->node = createStringNode(key, NULL);
        ++ht->size;
    }
    pthread_mutex_unlock(&ht->mutex);
}

void removeEntry(const char *key, HashTable *ht) {
    pthread_mutex_lock(&ht->mutex);
    unsigned long hash = customHash(key, ht->capacity);
    for (; ht->table[hash] != NULL; ++hash %= ht->capacity) {
        if (strcmp(ht->table[hash]->node->data, key) == 0) {
            HashEntry *temp = ht->table[hash];
            ht->table[hash] = ht->table[hash]->next;
            freeStringNode(temp->node);
            free(temp);
            --ht->size;
            break;
        }
    }
