using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading;

public class DynamicValueGenerator
{
    private readonly Random _random;
    private readonly int _minValue;
    private readonly int _maxValue;
    private readonly string _configurationFilePath;
    private readonly Dictionary<string, (int min, int max)> _configuredRanges;

    public DynamicValueGenerator(int seed, int minValue, int maxValue, string configurationFilePath)
    {
        _random = new Random(seed);
        _minValue = minValue;
        _maxValue = maxValue;
        _configurationFilePath = configurationFilePath;
        _configuredRanges = ReadConfigurationFile();
    }

    private Dictionary<string, (int min, int max)> ReadConfigurationFile()
    {
        var ranges = new Dictionary<string, (int min, int max)>();
        try
        {
            if (!File.Exists(_configurationFilePath))
                throw new FileNotFoundException($"Configuration file not found: {_configurationFilePath}");

            using var reader = new StreamReader(_configurationFilePath);
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                if (string.IsNullOrWhiteSpace(line)) continue;

                var match = Regex.Match(line, @"^(\w+)\s+\[((\d+),(\d+))\]$");
                if (!match.Success) throw new FormatException($"Invalid configuration format: {line}");

                string sectionName = match.Groups[1].Value;
                int minValue = int.Parse(match.Groups[3].Value);
                int maxValue = int.Parse(match.Groups[4].Value);
                ranges[sectionName] = (minValue, maxValue);
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error reading configuration file: {ex}");
            throw; // re-throw the exception to be handled by calling code
        }

        return ranges;
    }

    public float GetRandomFloat(string sectionName = null) => (float)_random.NextDouble() * (_configuredRanges[sectionName].max - _configuredRanges[sectionName].min) + _configuredRanges[sectionName].min;

    public double GetRandomDouble(string sectionName = null) => _random.NextDouble() * (_configuredRanges[sectionName].max - _configuredRanges[sectionName].min) + _configuredRanges[sectionName].min;

    public int GetRandomInt(bool inclusive, string sectionName = null)
    {
        var range = _configuredRanges[sectionName];
        return inclusive ? _random.Next(range.min, range.max + 1) : _random.Next(range.min, range.max);
    }

    public override string ToString() => $"DynamicValueGenerator: ({_minValue}, {_maxValue}), ConfiguredRanges: {string.Join(", ", _configuredRanges.Select(kv => kv.Key + ": " + kv.Value))}";

    public int ExtractSequenceNumberFromDataFile(string filePath)
    {
        try
        {
            if (!File.Exists(filePath))
                throw new FileNotFoundException($"Data file not found: {filePath}");

            using var reader = new StreamReader(filePath);
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                if (Regex.IsMatch(line, @"\d+$"))
                    return int.Parse(line);
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error reading data file: {ex}");
            throw; // re-throw the exception to be handled by calling code
        }

        throw new FormatException("Data file does not contain a sequence number");
    }
}
