        block->data = malloc(BLOCK_SIZE);
        block->size = BLOCK_SIZE;
        manager->num_blocks++;
    }
    pthread_mutex_unlock(&manager->mutex);
    return manager->blocks + (manager->num_blocks - 1);
}

void free_block(ThreadData* manager, AllocatedBlock* block) {
    pthread_mutex_lock(&manager->mutex);
    if (block >= manager->blocks && block < &(manager->blocks[manager->capacity])) {
        free(block->data);
        block->data = NULL;
        block->size = 0;
        manager->num_blocks--;
    }
    pthread_mutex_unlock(&manager->mutex);
}

