#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    uint64_t SESSION_ID;
    char UE_IP_ADDRESS[32];
    uint64_t QUOTA_USAGE;
} USER_CONNECTION_INFO;

#define TABLE_SIZE 1024
#define LOAD_FACTOR 0.75
typedef struct NODE {
    USER_CONNECTION_INFO data;
    struct NODE *next;
    pthread_mutex_t lock;
} NODE;

struct HASH_TABLE {
    NODE **table;
    size_t count;
};

NODE* create_node(USER_CONNECTION_INFO data) {
    NODE *new_node = (NODE *)malloc(sizeof(NODE));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);
    return new_node;
}

uint64_t hash(uint64_t key) {
    uint64_t hash = 0;
    for (int i = 0; i < sizeof(key) * 8; ++i) {
        hash = (hash << 5) + hash + key >> (sizeof(key) * 8 - i);
    }
    return hash % TABLE_SIZE;
}

void resize_table(struct HASH_TABLE *ht) {
    NODE **new_table = (NODE **)realloc(ht->table, sizeof(NODE *) * (TABLE_SIZE * 2));
    if (!new_table) return;
    ht->table = new_table;
    for (size_t i = TABLE_SIZE; i < TABLE_SIZE * 2; ++i) {
        ht->table[i] = NULL;
    }
}

struct HASH_TABLE create_hash_table() {
    struct HASH_TABLE ht;
    ht.table = (NODE **)calloc(sizeof(NODE *) * TABLE_SIZE, 1);
    if (!ht.table) return ht;
    ht.count = 0;
    return ht;
}

bool insert(struct HASH_TABLE *ht, USER_CONNECTION_INFO data) {
    NODE* new_node = create_node(data);
    if (!new_node) return false;
    uint64_t index = hash(data.SESSION_ID);
    pthread_mutex_lock(&ht->table[index]->lock);
    NODE *current = ht->table[index];
    while (current != NULL) {
        if (current->data.SESSION_ID == data.SESSION_ID) {
            pthread_mutex_unlock(&ht->table[index]->lock);
            free(new_node);
            return false;
        }
        current = current->next;
    }
    new_node->next = ht->table[index];
    ht->table[index] = new_node;
    ++ht->count;
    if (static_cast<float>(ht->count) / TABLE_SIZE > LOAD_FACTOR) {
        resize_table(ht);
    }
    return true;
}

NODE* find(struct HASH_TABLE *ht, uint64_t key) {
    uint64_t index = hash(key);
    NODE* current = ht->table[index];
    while (current != NULL) {
        if (current->data.SESSION_ID == key) return current;
        current = current->next;
    }
    return NULL;
}

bool delete(struct HASH_TABLE *ht, uint64_t key) {
    NODE* node_to_delete = find(ht, key);
    if (!node_to_delete) return false;
    pthread_mutex_lock(&node_to_delete->lock);
    NODE* current = ht->table[hash(key)];
    if (current == node_to_delete) {
        ht->table[hash(key)] = node_to_delete->next;
    } else {
        NODE *prev = current;
        current = current->next;
        while (current != NULL && current != node_to_delete) {
            prev = current;
            current = current->next;
        }
        if (current == NULL) return false;
        prev->next = current->next;
    }
    --ht->count;
    pthread_mutex_unlock(&node_to_delete->lock);
    free(node_to_delete);
    return true;
}

