    public class DynamicFileProcessor
    {
        private readonly Dictionary<string, Action<Stream, Stream>> _transformations;
        private readonly string[] _supportedFormats;

        public DynamicFileProcessor(string transformConfig)
        {
            _transformations = JsonConvert.DeserializeObject<Dictionary<string, Action<Stream, Stream>>>(transformConfig);
            _supportedFormats = _transformations.Keys.ToArray();
        }

        private void ProcessFiles(string inputFilePath, string outputFilePath, params string[] formats)
        {
            using (FileStream inputFile = new FileStream(inputFilePath, FileMode.Open))
            using (FileStream outputFile = new FileStream(outputFilePath, FileMode.Create))
            {
                foreach (string format in formats)
                {
                    var reader = GetReaderForFormat(format, inputFile);
                    var writer = GetWriterForFormat(format, outputFile);

                    if (reader != null && writer != null)
                    {
                        _transformations[format](reader, writer);
                    }
                }
            }
        }

        private StreamReader GetReaderForFormat(string format, Stream stream)
        {
            var readerType = Type.GetType($"System.IO.{format}StreamReader");
            return readerType != null ? Activator.CreateInstance(readerType, stream) as StreamReader : null;
        }

        private StreamWriter GetWriterForFormat(string format, Stream stream)
        {
            var writerType = Type.GetType($"System.IO.{format}StreamWriter");
            return writerType != null ? Activator.CreateInstance(writerType, stream) as StreamWriter : null;
        }

        public override string ToString() => $"Supported Formats: [{string.Join(", ", _supportedFormats)}]";

        private Random _random = new Random();

        public int GenerateRandomNumber(int min, int max) => _random.Next(min, max);
    }
}
```

