public class ImageProcessingUtils {
    private ExecutorService executor = Executors.newCachedThreadPool();
    private ConcurrentLinkedQueue<ImageProcessingTask> taskQueue = new ConcurrentLinkedQueue<>();

    public void processImages(File[] images, int batchSize) {
        for (File image : images) {
            ImageProcessingTask task = new ImageProcessingTask(image);
            taskQueue.add(task);
        }
        processBatch(batchSize);
    }

    private void processBatch(int batchSize) {
        while (!taskQueue.isEmpty() && batchSize > 0) {
            ExecutorService subExecutor = Executors.newFixedThreadPool(Math.min(taskQueue.size(), batchSize));
            for (int i = 0; i < batchSize && !taskQueue.isEmpty(); i++) {
                ImageProcessingTask task = taskQueue.poll();
                subExecutor.submit(task);
            }
            subExecutor.shutdown();
            while (!subExecutor.isTerminated()) {} // Wait for completion
            processBatch(batchSize);
        }
    }

