```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libssh2.h>

static int ssh_init(const char *user, const char *host, const char *keyfile) {
    struct libssh2_session *session = NULL;
    LIBSSH2_KEY init_key = NULL;
    int ret = 0, i = 0;
    size_t key_len = 0;

    // Load private key from file
    if (!(init_key = libssh2_key_init_file(keyfile, LIBSSH2_KEY_RSA))) {
        fprintf(stderr, "Error loading key: %s\n", libssh2_strerror(libssh2_err));
        return -1;
    }

    // Initialize session
    session = libssh2_session_init();
    if (!session) {
        fprintf(stderr, "Error initializing session: %s\n", libssh2_strerror(libssh2_err));
        return -1;
    }

    // Set hostname and user for the connection
    if (libssh2_session_set_hostname(session, host) != 0 ||
        libssh2_session_set_user(session, user) != 0) {
        fprintf(stderr, "Error setting session properties: %s\n", libssh2_strerror(libssh2_err));
        goto cleanup;
    }

    // Try key pairs up to 5 times
    for (i = 0; i < 5 && ret == 0; ++i) {
        if (libssh2_key_from_buffer(session, &init_key, init_key->data, init_key->len, LIBSSH2_KEY_RSA)) {
            fprintf(stderr, "Error adding key to session: %s\n", libssh2_strerror(libssh2_err));
            continue;
        }

        if (libssh2_session_userauth_publickey(session, NULL, user) == 0 &&
            libssh2_session_connect(session) == 0) {
            ret = 1;
            break;
        } else if (i < 4) {
            fprintf(stderr, "Authentication failed. Trying next key...\n");
        }
    }

cleanup:
    if (init_key) libssh2_key_free(init_key);
    if (session) libssh2_session_dispose(session);

    return ret ? 0 : -1;
}

static void ssh_close(struct libssh2_session *session) {
    if (session) libssh2_session_disconnect(session);
    if (session) libssh2_session_free(session);
}
```

This code initializes a session using public key authentication and attempts up to 5 times. It also gracefully closes the SSH connection when it is no longer needed. Make sure to link your program with `-lssh2` flag, and install libssh2 library on your system if you haven't already.']

