typedef struct mem_block {
    void *data;
    size_t capacity;
    size_t used;
    struct mem_block *next;
} MemBlock;

static MemBlock *memory_pool = NULL;
static pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void *mem_alloc(size_t size) {
    pthread_mutex_lock(&memory_lock);

    if (!memory_pool) {
        memory_pool = malloc(sizeof(MemBlock));
        memory_pool->data = NULL;
        memory_pool->capacity = 0;
        memory_pool->used = 0;
        memory_pool->next = NULL;
    }

    MemBlock *current = memory_pool;
    while (current && current->capacity <= current->used) {
        current = current->next;
    }

    if (!current) {
        current = malloc(sizeof(MemBlock));
        current->data = NULL;
        current->capacity = 0;
        current->used = 0;
        current->next = memory_pool;
        memory_pool = current;
    }

    void *result = (current->data + current->used);
    if (size > current->capacity - current->used) {
        current->capacity += size - (current->capacity - current->used);
    }
    current->used += size;

    pthread_mutex_unlock(&memory_lock);
    return result;
}

void mem_free(void *ptr) {
    pthread_mutex_lock(&memory_lock);

    MemBlock *current = memory_pool;
    MemBlock *previous = NULL;
    while (current) {
        if (current->data == ptr) {
            if (previous) {
                previous->next = current->next;
                current->next = memory_pool;
                memory_pool = current;
            } else {
                memory_pool = current->next;
            }
            break;
        }
        previous = current;
        current = current->next;
    }

    if (current->used) {
        --current->used;
    }

    pthread_mutex_unlock(&memory_lock);
}

