        buf[sizeof(buf) - 1] = '\0';
        va_list args_copy;
        va_copy(args_copy, args);
        fputs(buf, stderr);
        len = snprintf(buf, sizeof(buf), va_arg(args_copy, const char *));
    }
    fputs(buf, stderr);
}

