void init_dynamic_array(size_t initial_capacity) {
    pthread_mutex_lock(&array_lock);
    if (!dynamic_array) {
        dynamic_array = malloc(initial_capacity * sizeof(NFAPI_RX_FRAME_T*));
        memset(dynamic_array, 0, initial_capacity * sizeof(NFAPI_RX_FRAME_T*));
        array_capacity = initial_capacity;
    }
    pthread_mutex_unlock(&array_lock);
}

void resize_dynamic_array() {
    pthread_mutex_lock(&array_lock);

    if (array_used >= array_capacity) {
        size_t new_capacity = array_capacity * 2;
        NFAPI_RX_FRAME_T** new_array = malloc(new_capacity * sizeof(NFAPI_RX_FRAME_T*));
        memset(new_array, 0, new_capacity * sizeof(NFAPI_RX_FRAME_T*));

        size_t i;
        for (i = 0; i < array_capacity && i < array_used; ++i) {
            new_array[i] = dynamic_array[i];
        }

        free(dynamic_array);
        dynamic_array = new_array;
        array_capacity *= 2;
    }

    pthread_mutex_unlock(&array_lock);
}

NFAPI_RX_FRAME_T* get_frame_by_index(size_t index) {
    pthread_mutex_lock(&array_lock);
    if (index >= array_used) {
        resize_dynamic_array();
    }
    NFAPI_RX_FRAME_T* frame = dynamic_array[index];
    if (!frame) {
        frame = mem_alloc(sizeof(NFAPI_RX_FRAME_T));
        dynamic_array[index] = frame;
    }
    pthread_mutex_unlock(&array_lock);
