```python
import os
import hashlib
import concurrent.futures
from time import time, sleep
import logging

logger = logging.getLogger(__name__)

def file_hash(filepath, chunk_size=65536):
    hasher = hashlib.sha256()
    with open(filepath, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def rate_limited_file_hash(filepath, limit=100):
    start_time = time()
    processed = 0
    while True:
        now = time()
        if (now - start_time) >= 1 / limit:
            start_time += 1 / limit
            processed += 1
            if processed < len(files):
                filepath = files[processed]
                result = file_hash(filepath)
                logger.info(f"Hashed {filepath}: {result}")
            else:
                break
        sleep(1 / limit - (now - start_time))

def main():
    files = ['largefile1.bin', 'largefile2.bin']
    with concurrent.futures.ThreadPoolExecutor() as executor:
        executor.map(rate_limited_file_hash, files)

if __name__ == "__main__":
    main()
