import os
import sys
import hashlib
import time
from tqdm import tqdm

def calculate_checksum(file_path, algorithm='sha256', incremental=True):
    checksums = {'sha256': None, 'crc32': None}
    total_size = os.path.getsize(file_path)

    with open(file_path, 'rb') as file:
        if algorithm == 'sha256':
            hasher = hashlib.sha256()
            buffer_size = 8 * (1024 ** 2)  # 8 MB chunk size

            progress_tracker = tqdm(total=total_size, unit='B', position=0, leave=True) if incremental else tqdm(total=total_size, unit='B', unit_scale=True, mininterval=1, desc=f"Calculating {algorithm.upper()} checksum")

            for chunk in iter(lambda: file.read(buffer_size), b''):
                hasher.update(chunk)
                progress_tracker.update(len(chunk))
                if incremental:
                    progress_tracker.set_postfix({algorithm.upper(): None})
                else:
                    progress_tracker.refresh()

            checksums[algorithm] = hasher.hexdigest()
            progress_tracker.close()

        elif algorithm == 'crc32':
            crc = CRC32()
            buffer_size = 16 * (1024 ** 2)  # 16 MB chunk size for CRC32

            progress_tracker = tqdm(total=total_size, unit='B', position=0, leave=True, mininterval=1, desc="Calculating CRC32 checksum")

            for chunk in iter(lambda: file.read(buffer_size), b''):
                crc.update(chunk)
                progress_tracker.update(len(chunk))
                progress_tracker.set_postfix({algorithm.upper(): None})

            checksums[algorithm] = hex(crc.getvalue())[2:].zfill(8).upper()
            progress_tracker.close()

        return (checksums[algorithm], f"{algorithm.upper()} checksum calculation completed {int((file_path == sys.argv[1]) and progress_tracker.n * 100 / total_size)}%")

class CRC32:
    def __init__(self):
        self.table = crc32_table
        self.crc = 0xFFFFFFFFL

    def update(self, data):
        for char in data:
            self.crc = self.table[(self.crc ^ ord(char)) & 0xFF] ^ (self.crc >> 8)

    def getvalue(self):
        return ~self.crc & 0xFFFFFFFFL
```']

