#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct MAC_MESSAGE_T {
    int sequence_number;
    int transmission_power_level;
    enum PHY_LAYER_STATUS { STATION_IDLE, STATION_BUSY } phy_layer_status;
} MAC_MESSAGE;

#define MAX_ELEMENTS 1024
typedef struct NODE {
    MAC_MESSAGE* data;
    struct NODE* next;
    pthread_mutex_t lock;
} NODE;

NODE* head = NULL;
pthread_mutex_t global_lock;

void *custom_malloc(size_t size) {
    void* result = malloc(size);
    if (!result) {
        fprintf(stderr, "Out of memory\n");
        pthread_exit(NULL);
    }
    return result;
}

MAC_MESSAGE* create_mac_message(int seq_num, int power, enum PHY_LAYER_STATUS status) {
    MAC_MESSAGE* message = (MAC_MESSAGE*)custom_malloc(sizeof(MAC_MESSAGE));
    message->sequence_number = seq_num;
    message->transmission_power_level = power;
    message->phy_layer_status = status;
    return message;
}

void insert_node(MAC_MESSAGE* message) {
    NODE* new_node = (NODE*)custom_malloc(sizeof(NODE));
    new_node->data = message;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    if (!head) {
        head = new_node;
        return;
    }

    NODE* current = head;
    while (current->next) {
        current = current->next;
    }
    current->next = new_node;
}

MAC_MESSAGE* retrieve_node(int index) {
    if (index < 0 || index >= MAX_ELEMENTS) {
        fprintf(stderr, "Invalid index\n");
        pthread_exit(NULL);
    }

    NODE* current = head;
    for (int i = 0; i < index; ++i) {
        if (!current) {
            fprintf(stderr, "Index out of range\n");
            pthread_exit(NULL);
        }
        current = current->next;
    }

    pthread_mutex_lock(&current->lock);
    MAC_MESSAGE* result = current->data;
    pthread_mutex_unlock(&current->lock);

    return result;
}

void init() {
    pthread_mutex_init(&global_lock, NULL);
}

void destroy() {
    NODE* current = head;
    while (head) {
        NODE* temp = head;
        head = head->next;
        free(temp);
    }
    pthread_mutex_destroy(&global_lock);
}
