#define LOG_BUFFER_MAX 1024
#define LOG_LEVELS_COUNT 5

typedef struct {
    time_t timestamp;
    int level;
    char payload[LOG_BUFFER_MAX];
} LOG_ENTRY_T;

typedef enum { DEBUG, INFO, WARN, ERROR, CRITICAL } LOG_LEVEL_T;

typedef struct log_queue_s {
    pthread_mutex_t mutex;
    pthread_cond_t cond_not_full;
    pthread_cond_t cond_not_empty;
    size_t head;
    size_t tail;
    size_t size;
    LOG_ENTRY_T *buffer;
} LOG_QUEUE_T;

LOG_QUEUE_T *log_queue_create(size_t buffer_size) {
    LOG_QUEUE_T *queue = mmap(NULL, sizeof(LOG_QUEUE_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (queue == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond_not_full, NULL);
    pthread_cond_init(&queue->cond_not_empty, NULL);
    queue->head = 0;
    queue->tail = 0;
    queue->size = buffer_size;
    queue->buffer = (LOG_ENTRY_T *)(queue + 1);
    return queue;
}

bool log_queue_push(LOG_QUEUE_T *queue, LOG_ENTRY_T entry) {
    pthread_mutex_lock(&queue->mutex);
    while ((queue->size - (queue->tail - queue->head)) == 0) {
        pthread_cond_wait(&queue->cond_not_full, &queue->mutex);
    }

    memcpy(queue->buffer + queue->tail, &entry, sizeof(LOG_ENTRY_T));
    queue->tail = (queue->tail + 1) % queue->size;
    pthread_cond_signal(&queue->cond_not_empty);
    pthread_mutex_unlock(&queue->mutex);
    return true;
}

LOG_ENTRY_T *log_queue_pop(LOG_QUEUE_T *queue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->head == queue->tail) {
        pthread_cond_wait(&queue->cond_not_empty, &queue->mutex);
    }

    LOG_ENTRY_T *entry = &queue->buffer[queue->head];
    queue->head = (queue->head + 1) % queue->size;
    pthread_cond_signal(&queue->cond_not_full);
    pthread_mutex_unlock(&queue->mutex);
    return entry;
}

// Implement filtering operations based on log level and timestamp here.

void log(LOG_LEVEL_T level, const char *fmt, ...) {
    static LOG_QUEUE_T *log_queue = NULL;
    static pthread_t log_writer_tid = 0;
    static bool log_writer_initialized = false;

    if (!log_writer_initialized) {
        log_queue = log_queue_create(LOG_BUFFER_MAX);
        pthread_create(&log_writer_tid, NULL, log_writer, log_queue);
        log_writer_initialized = true;
    }

    time_t now = time(NULL);
    LOG_ENTRY_T entry = {now, level, {0}};
    va_list args;
    va_start(args, fmt);
    vsprintf(entry.payload, fmt, args);
    log_queue_push(log_queue, entry);
}

void *log_writer(void *arg) {
    LOG_QUEUE_T *queue = arg;
    while (true) {
        LOG_ENTRY_T *entry = log_queue_pop(queue);
        // Write the logged data to a non-blocking I/O destination here.
    }
}
```

This code provides a basic structure for a logging system using pthreads, mmap and va_list for efficient logging operations. The log_queue_create function initializes a circular buffer that stores `LOG_ENTRY_T` structures. The log_queue_push function inserts new entries into the buffer, while log_queue_pop retrieves them. The filtering operation based on log level and timestamp needs to be implemented as well. A separate thread called `log_writer` is used to handle writing the logged data to a non-blocking I/O destination. Error handling for buffer overflow conditions and invalid input values is not provided, but you can implement it by returning appropriate error codes or calling pthread_exit in case of errors.']

