function traverseDOMTree(root, selector, visitElementCallback) {
    const queue = [root];
    const visitedElements = new Set();

    while (queue.length > 0) {
        const currentNode = queue.shift();

        if (!visitedElements.has(currentNode)) {
            visitedElements.add(currentNode);

            if (currentNode.matches && currentNode.matches(selector)) {
                visitElementCallback(currentNode);
            } else {
                Array.from(currentNode.childNodes).forEach((node) => queue.push(node));
                Array.from(currentNode.querySelectorAll('*')).forEach((node) => queue.push(node));
            }
        }
    }
}
```

