#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <semaphore.h>

typedef struct {
    RX_UE_INFORMATION_TAG rxi;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc;
} NFAPI_RX_FRAME_T;

typedef struct mem_block {
    size_t capacity;
    size_t used;
    NFAPI_RX_FRAME_T* frames;
    sem_t mutex;
    sem_t cleanup_sem;
} MemBlock;

MemBlock* create_mem_block(size_t initial_capacity, size_t max_capacity) {
    MemBlock* block = malloc(sizeof(MemBlock));
    if (!block) return NULL;

    pthread_mutexattr_t attr;
    if (pthread_mutexattr_init(&attr)) goto cleanup;
    if (pthread_mutexattr_destroy(&attr)) goto cleanup;

    if (pthread_mutex_init(&block->mutex, &attr)) goto cleanup;
    if (pthread_mutexattr_destroy(&attr)) goto cleanup;

    block->capacity = initial_capacity;
    block->used = 0;
    block->frames = calloc(initial_capacity, sizeof(NFAPI_RX_FRAME_T));
    if (!block->frames) goto cleanup;

    sem_init(&block->cleanup_sem, 0, 0);
    return block;

cleanup:
    free(block);
    return NULL;
}

bool insert(MemBlock* block, const NFAPI_RX_FRAME_T* frame) {
    if (!block || !frame) return false;

    sem_wait(&block->mutex);

    if (block->used == block->capacity) {
        block->frames = realloc(block->frames, block->capacity * 2 * sizeof(NFAPI_RX_FRAME_T));
        if (!block->frames) {
            sem_post(&block->mutex);
            return false;
        }
        block->capacity *= 2;
    }

    memcpy((void*)&block->frames[block->used], frame, sizeof(NFAPI_RX_FRAME_T));
    ++block->used;

    sem_post(&block->mutex);
    return true;
}

const NFAPI_RX_FRAME_T* get(MemBlock* block, size_t index) {
    if (!block || index >= block->used) return NULL;

    sem_wait(&block->mutex);
    const NFAPI_RX_FRAME_T* frame = &block->frames[index];
    sem_post(&block->mutex);

    return frame;
}

void cleanup(MemBlock* block, unsigned long time) {
    struct timespec timeout;
    timeout.tv_sec = time;
    timeout.tv_nsec = 0;

    sem_timedwait(&block->cleanup_sem, &timeout);

    if (block->used > 0) {
        block->frames = realloc(block->frames, block->capacity / 2 * sizeof(NFAPI_RX_FRAME_T));
        block->capacity /= 2;
        block->used = 0;
        memset((void*)block->frames, 0, block->capacity * sizeof(NFAPI_RX_FRAME_T));
    }

    sem_post(&block->cleanup_sem);
}

void reset(MemBlock* block) {
    if (!block) return;

    sem_wait(&block->mutex);

    memset((void*)block->frames, 0, block->capacity * sizeof(NFAPI_RX_FRAME_T));
    block->used = 0;

    sem_post(&block->mutex);
}
```

