#include <stdio.h>
#include <stdlib.h>
#include <resolv.h>
#include <netdb.h>
#include <openssl/sha.h>
#include <syslog.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/mman.h>
#include <semaphore.h>

struct config_entry {
    char host[256];
    char placeholder[32];
    char password[128];
};

struct config_data {
    struct config_entry* entries;
    size_t count;
    size_t capacity;
};

struct config_file {
    int fd;
    sem_t lock;
};

void init_config_data(struct config_data* data) {
    data->count = 0;
    data->capacity = 16;
    data->entries = mmap(NULL, data->capacity * sizeof(struct config_entry), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
}

void resize_config_data(struct config_data* data) {
    if (data->count == data->capacity) {
        data->capacity *= 2;
        void* new_entries = mremap(data->entries, data->capacity * sizeof(struct config_entry), data->capacity * 2 * sizeof(struct config_entry), MREMAP_FIXED | MREMAP_MAYMOVE);
        if (new_entries == MAP_FAILED) {
            syslog(LOG_ERR, "Failed to resize config_data");
            exit(EXIT_FAILURE);
        }
        data->entries = new_entries;
    }
}

void free_config_data(struct config_data* data) {
    munmap(data->entries, data->capacity * sizeof(struct config_entry));
}

int add_config_entry(struct config_data* data, const char* host, const char* placeholder, const char* password) {
    resize_config_data(data);
    memcpy(&data->entries[data->count], (void*){host, placeholder, password}, sizeof(struct config_entry));
    data->count++;
    return 0;
}

int read_config_file(const char* path, struct config_data* data) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        syslog(LOG_ERR, "Failed to open configuration file: %s", path);
        return EXIT_FAILURE;
    }

    struct config_entry entry;
    sem_t lock;
    sem_init(&lock, 0, 1);
    ssize_t nread;
    while ((nread = read(fd, &entry, sizeof(struct config_entry))) > 0) {
        pthread_mutex_lock(&lock);
        add_config_entry(data, entry.host, entry.placeholder, entry.password);
        pthread_mutex_unlock(&lock);
    }
    if (nread == -1 && errno != EWOULDBLOCK) {
        syslog(LOG_ERR, "Failed to read configuration file: %s", path);
        return EXIT_FAILURE;
    }

    close(fd);
    sem_destroy(&lock);
    return 0;
}

void write_config_file(const char* path, const struct config_data* data) {
    int fd = open(path, O_WRONLY | O_TRUNC | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd == -1) {
        syslog(LOG_ERR, "Failed to open configuration file for writing: %s", path);
        return;
    }

    sem_t lock;
    sem_init(&lock, 0, 1);

    ssize_t written;
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < data->count; ++i) {
        written = write(fd, &data->entries[i], sizeof(struct config_entry));
        if (written != sizeof(struct config_entry)) {
            syslog(LOG_ERR, "Failed to write configuration file: %s", path);
        }
    }
    pthread_mutex_unlock(&lock);
    sem_destroy(&lock);
}

int resolve_and_update_config(const char* hostname, const char* config_file_path, struct config_data* data) {
    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int status;
    struct addrinfo* res;
    getaddrinfo(hostname, NULL, &hints, &res);
    if (res == NULL) {
