#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <time.h>

typedef struct _NFAPI_RX_FRAME_T {
    // Frame data and other necessary fields...
} NFAPI_RX_FRAME_T;

typedef void (*frame_callback)(const NFAPI_RX_FRAME_T* frame);

struct dynamic_array {
    NFAPI_RX_FRAME_T** frames; // Dynamic array of pointers to frames
    size_t capacity;          // Current capacity of the array
    size_t size;              // Current number of elements in the array
    pthread_mutex_t mutex;    // Mutex for synchronizing access to the array
    pthread_cond_t not_full;  // Condition variable for notifying when there's space in the array
    pthread_cond_t not_empty; // Condition variable for notifying when there's a frame to process
    frame_callback validator; // External validation function
    time_t min_retention;     // Minimum retention period (in seconds)
};

void da_init(struct dynamic_array* array, size_t initial_capacity, frame_callback validator, time_t min_retention) {
    array->frames = calloc((size_t)initial_capacity, sizeof(NFAPI_RX_FRAME_T*));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    pthread_cond_init(&array->not_full, NULL);
    pthread_cond_init(&array->not_empty, NULL);
    array->validator = validator;
    array->min_retention = min_retention;
}

void da_push(struct dynamic_array* array, const NFAPI_RX_FRAME_T* frame) {
    pthread_mutex_lock(&array->mutex);
    // Validation logic...

    if (array->size == array->capacity) {
        pthread_cond_wait(&array->not_full, &array->mutex);
    }

    array->frames[array->size] = malloc(sizeof(NFAPI_RX_FRAME_T));
    memcpy(array->frames[array->size], frame, sizeof(NFAPI_RX_FRAME_T));
    ++array->size;

    if (array->size > 1 && time(NULL) - array->frames[0]->timestamp >= array->min_retention) {
        free(array->frames[0]);
        memmove(array->frames, array->frames + 1, --array->size * sizeof(NFAPI_RX_FRAME_T*));
    }

    pthread_cond_signal(&array->not_empty);
    pthread_mutex_unlock(&array->mutex);
}

void da_pop(struct dynamic_array* array, frame_callback callback) {
    pthread_mutex_lock(&array->mutex);
    while (array->size == 0) {
        pthread_cond_wait(&array->not_empty, &array->mutex);
    }

    frame_callback = array->validator;
    if (callback && !callback(array->frames[0])) {
        // Mark frame for retransmission...
    }

    free(array->frames[0]);
    memmove(array->frames, array->frames + 1, --array->size * sizeof(NFAPI_RX_FRAME_T*));
    pthread_cond_signal(&array->not_full);
    pthread_mutex_unlock(&array->mutex);
}

void da_cleanup(struct dynamic_array* array) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (time(NULL) - array->frames[i]->timestamp >= array->min_retention) {
            free(array->frames[i]);
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

void da_reset(struct dynamic_array* array) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->capacity; ++i) {
        if (array->frames[i]) {
            free(array->frames[i]);
        }
    }
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
}
```"]

