void processTasks() {
    // Dividing the task collection into smaller chunks for parallel processing
    std::vector<Task> chunk;
    {
        // Lock to ensure thread safety
        std::unique_lock<std::mutex> lock(mtx);

        // Filling the chunk with tasks
        auto it = tasks.begin();
        while (it != tasks.end() && chunk.size() < 1024) {
            if (it->second.deadline > std::time(nullptr)) {
                chunk.push_back(std::move(it->second));
            }
            it = tasks.erase(it);
        }
    }

    // Parallel processing
    std::for_each(std::execution::par, chunk.begin(), chunk.end(), [](Task& task) { processSingleTask(task); });
}
