#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>
#include <semaphore.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_RX_FRAME_T;

typedef struct Node {
    NFAPI_RX_FRAME_T data;
    struct Node *next;
} Node;

struct MemBlock {
    Node* nodes;
    size_t capacity;
    size_t used;
};

sem_t mem_mutex;

void mem_init() {
    sem_init(&mem_mutex, 0, 1);
}

void* custom_malloc(size_t size) {
    void *ptr;

    if ((ptr = malloc(size)) == NULL) {
        fprintf(stderr, "Error: Out of memory\n");
    }

    return ptr;
}

void custom_free(void* ptr) {
    free(ptr);
}

struct MemBlock* mem_create() {
    struct MemBlock *mb = (struct MemBlock*)custom_malloc(sizeof(struct MemBlock));
    mb->nodes = NULL;
    mb->capacity = 0;
    mb->used = 0;
    return mb;
}

void mem_destroy(struct MemBlock* mb) {
    while (mb->nodes != NULL) {
        struct Node *temp = mb->nodes;
        mb->nodes = mb->nodes->next;
        custom_free(temp);
    }
    custom_free(mb);
}

void mem_reserve(struct MemBlock* mb, size_t additional_capacity) {
    void *new_memory = custom_malloc((additional_capacity + 1) * sizeof(Node));
    if (new_memory == NULL) {
        fprintf(stderr, "Error: Out of memory\n");
    }

    Node* old_nodes = mb->nodes;
    mb->nodes = new_memory;
    memcpy(mb->nodes + mb->capacity, old_nodes, mb->used * sizeof(Node));
    mb->capacity += additional_capacity + 1;
}

struct MemBlock* mem_realloc(struct MemBlock* mb) {
    sem_wait(&mem_mutex);
    struct MemBlock *new_mb = mem_create();
    new_mb->nodes = mb->nodes;
    mb->used = 0;
    sem_post(&mem_mutex);

    return new_mb;
}

void log_error(const char* format, ...) {
    va_list args;
    time_t now;
