struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned char RX_UE_INFORMATION_TAG[4];
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[1];
};

AES_KEY *aes256cbc_init(const unsigned char *password, size_t password_len) {
    const ULONG key_len = AES_BLOCK_SIZE + ((password_len + AES_BLOCK_SIZE - 1) & ~(AES_BLOCK_SIZE - 1));
    unsigned char key[key_len];
    memset(key, 0, key_len);
    if (password_len < key_len) {
        size_t needed = key_len - password_len;
        getrandom(key + password_len, needed);
    }
    memcpy(key, password, password_len);
    PKCS5_PBKDF2(key, key_len, "AES-256-CBC", 10000, SHA256_DIGEST_LENGTH, key, &key_len);
    AES_KEY aes;
    AES_set_encrypt_key(key, AES_KEYSIZE_256, &aes);
    unsigned char iv[AES_BLOCK_SIZE] = {0};
    AES_cbc_encrypt((const unsigned char*)iv, iv, AES_BLOCK_SIZE, &aes, iv, AES_ENCRYPT);
    return &aes;
}

struct NFAPI_CRC_INDICATION_PDU_T** create_pdu_list(int N) {
    struct NFAPI_CRC_INDICATION_PDU_T **pdus = malloc(N * sizeof(struct NFAPI_CRX_UE_INFORMATION_TAG));
    for (int i = 0; i < N; ++i) {
        pdus[i] = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        memset(pdus[i], 0, sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        pdus[i]->RX_UE_INFORMATION_TAG[0] = i & 0xFF;
        pdus[i]->RX_UE_INFORMATION_TAG[1] = (i >> 8) & 0xFF;
        pdus[i]->RX_UE_INFORMATION_TAG[2] = (i >> 16) & 0xFF;
