int ssh_connect(const char *host, const char *user, struct ssh_key_pair *key, int *failure_counter) {
    int retries = 0;
    struct timeval start_time;
    gettimeofday(&start_time, NULL);

    while (retries < 5) {
        if (rate_limit(host)) return 1; // rate limit check fails, exit

        int status = ssh_open_connection(host, user);
        if (status == SSH_OK) {
            status = ssh_authenticate_with_publickey(user, key->public_key, key->private_key);
            if (status == SSH_OK) return 0; // connection succeeds, exit
        }

        if (status != SSH_EHOSTUNREACH && status != SSH_ENOTFOUND) {
            log_event("SSH connection attempt failed", "host": host, "user": user, "error": ssh_get_last_error(), "elapsed_time": time_since(&start_time));
        }

        if (failure_counter != NULL && retries >= 2) {
            *failure_counter += 1;
            if (*failure_counter > 2) {
                log_event("SSH connection attempts exceeded limit", "host": host, "user": user, "error": "exceeded limit", "elapsed_time": time_since(&start_time));
                return -1; // terminate the program if max failures reached
            }
        }

        retries++;
        network_monitor(host); // adjust retry strategy dynamically based on network stability
        sleep(1); // brief delay before next attempt
    }

    log_event("SSH connection attempts exceeded limit", "host": host, "user": user, "error": "exceeded limit", "elapsed_time": time_since(&start_time));
    return -1; // terminate the program if max retries reached
}
