#include <chrono>
#define MAX_FRAMES 10000
#define MAX_PACKETS variable_input_parameter

typedef struct PHY_RX_FRAME_T {
    RX_FRAME_CONFIG config;
    RF_CHAIN chain;
    RECEPTION_QUALITY quality;
    PACKET_ID packetId;
    time_t lastUpdate;
} PHY_RX_FRAME;

// Custom memory allocator with hard limit and error codes
struct mem_block {
    void* ptr;
    size_t size;
};

struct mem_allocator {
    struct mem_block blocks[MAX_BLOCKS];
    size_t numBlocks;
    size_t blockSize;
    size_t hardLimit;
};

void initMemAllocator(struct mem_allocator* alloc, size_t blockSize, size_t hardLimit) {
    alloc->blockSize = blockSize;
    alloc->hardLimit = hardLimit;
    alloc->numBlocks = 0;
}

void* allocFromMemAllocator(struct mem_allocator* alloc) {
    if (alloc->numBlocks >= alloc->hardLimit) return NULL; // Return null for failed allocation
    if (alloc->numBlocks < alloc->blockSize) {
        alloc->blocks[alloc->numBlocks].ptr = malloc(alloc->blockSize - alloc->numBlocks);
        alloc->blocks[alloc->numBlocks].size = alloc->blockSize - alloc->numBlocks;
        alloc->numBlocks += alloc->blockSize;
    }
    struct mem_block* block = &alloc->blocks[alloc->numBlocks - alloc->blockSize];
    block->ptr = (char*)block->ptr + block->size;
    block->size = alloc->blockSize;
    return block->ptr;
}

void freeFromMemAllocator(struct mem_allocator* alloc, void* ptr) {
    struct mem_block* block = (struct mem_block*)((char*)ptr - sizeof(struct mem_block));
    if (block >= &alloc->blocks[0] && block < &alloc->blocks[alloc->numBlocks]) {
        free(block->ptr);
        block->ptr = NULL;
        block->size = 0;
        alloc->numBlocks -= block->size;
    }
}

// Custom concurrent-safe linked list for efficient insertion and lookup
struct node {
    PHY_RX_FRAME frame;
    struct node* next;
};

struct list {
    struct node* head;
    struct node* tail;
    pthread_mutex_t lock;
    semaphore_t sem; // Semaphore for concurrent insertion without contention or deadlocks
};

void initList(struct list* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    sem_init(&list->sem, 0, MAX_FRAMES);
}

void addFrameToList(struct list* list, PHY_RX_FRAME frame) {
    struct node* node = (struct node*)allocFromMemAllocator(&gMemAllocator);
    if (!node) return; // Return for failed allocation
    memcpy(node, &frame, sizeof(PHY_RX_FRAME));
    sem_wait(&list->sem);
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->lock);
    sem_post(&list->sem);
}

PHY_RX_FRAME* getFrameFromList(struct list* list, PACKET_ID packetId) {
    PHY_RX_FRAME* result = NULL;
    pthread_mutex_lock(&list->lock);
    struct node* current = list->head;
    while (current != NULL) {
        if (current->frame.packetId == packetId) {
            result = &current->frame;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return result;
}

