from collections import deque

class MetricAggregator:
    def __init__(self, buffer_size=1000):
        self.buffer = deque(maxlen=buffer_size)
        self.aggregated_metrics = {
            'temperature': 0,
            'humidity': 0,
            // Add other sensor readings as necessary
        }
        self.alerts = []

    def add_data(self, data):
        try:
            self.buffer.extend(data)
            self.update_metrics()
            if len(self.alerts) > MAX_ALERTS:
                self.alerts = self.alerts[-MAX_ALERTS:]
        except Exception as e:
            print(f"Error processing data: {e}", file=sys.stderr)
            sys.exit(1)

    def update_metrics(self):
        for reading in self.buffer:
            self.aggregated_metrics['temperature'] += reading.temperature
            self.aggregated_metrics['humidity'] += reading.humidity
            // Update other metrics as necessary

    @property
    def completed_percentage(self):
        return len(self.buffer) / self.buffer.maxlen * 100

    @property
