typedef struct BookCount {
    char *name;
    size_t count;
} BookCount;

// Function to read a list of strings from standard input and store them in a dynamically allocated array
BookCount* readStrings() {
    size_t capacity = 10000, currentSize = 0;
    BookCount *strings = malloc(capacity * sizeof(BookCount));

    regex_t re;
    int err = regcomp(&re, "(\\w+)", REG_EXTENDED | REG_ICASE);
    if (err) {
        fprintf(stderr, "Regex compilation failed: %s\n", regerror(err, &re, NULL));
        exit(1);
    }

    char line[4096];
    while (fgets(line, sizeof(line), stdin)) {
        size_t len = strlen(trim(line));
        if (!len) continue; // Skip empty lines

        regexec(&re, line, 1, matches, 0);
        if (matches[0].rm_eo > 0 && matches[0].rm_so < len) {
            BookCount *temp = realloc(strings, (currentSize + 1) * sizeof(BookCount));
            if (!temp) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(1);
            }
            strings = temp;

            int bookIndex = -1;
            for (size_t i = 0; i < currentSize; ++i) {
                if (!strcmp(strings[i].name, line)) {
                    bookIndex = i;
                    break;
                }
            }

            if (bookIndex == -1) { // New unique string found
                strings[currentSize].name = strdup(line);
                strings[currentSize++].count = 1;
            } else { // Update count for existing string
                strings[bookIndex].count++;
            }
        }
    }

    regfree(&re); // Free the compiled regex to avoid memory leaks

    BookCount *result = malloc((currentSize) * sizeof(BookCount));
    memcpy(result, strings, currentSize * sizeof(BookCount));
    free(strings); // Deallocate dynamically allocated array
    return result;
}

