}

// Helper function to trim whitespace from a string
char* trim(char *str) {
    char *begin = str;
    for (; *begin && isspace(*begin); begin++) {}
    char *end = begin + strlen(begin);
    for (; end > begin && isspace(*(end - 1)); end--) {}
    if (end > begin) *((char*)memmove(begin, end, end - begin + 1)) = '\0';
    return begin;
}

int main() {
    BookCount* strings = readStrings();
    countAndPrintStrings(strings, sizeof(strings) / sizeof(BookCount));
    // Free the dynamically allocated array here if necessary for your application
    return 0;
}
