['1. Custom Memory Allocator (`nmalloc.h`, `nmalloc.c`)

```c
#ifndef NMALLOC_H
#define NMALLOC_H

typedef struct {
    void *ptr;
    size_t size;
} MemBlock;

void* nmalloc(size_t size);
void nfree(void *ptr);
MemBlock* ncalloc(size_t num, size_t size);
void nfree_block(MemBlock *blk);

#endif // NMALLOC_H
```

```c
#include "nmalloc.h"
#include <stdlib.h>
#include <pthread.h>

static pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t max_memory = 1048576; // 1MB by default

void* nmalloc(size_t size) {
    void *ptr;

    pthread_mutex_lock(&memory_mutex);
    if (max_memory - memory_used() < size) {
        pthread_mutex_unlock(&memory_mutex);
        return NULL;
    }

    ptr = malloc(size);
    if (!ptr) {
        pthread_mutex_unlock(&memory_mutex);
        return NULL;
    }

    memory_used(memory_used() + size);
    pthread_mutex_unlock(&memory_mutex);

    return ptr;
}

void nfree(void *ptr) {
    if (!ptr) {
        return;
    }

    pthread_mutex_lock(&memory_mutex);
    free(ptr);
    memory_used(memory_used() - sizeof(ptr));
    pthread_mutex_unlock(&memory_mutex);
}

MemBlock* ncalloc(size_t num, size_t size) {
    MemBlock *blk;

    blk = (MemBlock *)nmalloc(num * sizeof(MemBlock));
    if (!blk) {
        return NULL;
    }

    for (size_t i = 0; i < num; ++i) {
        blk[i].ptr = nmalloc(size);
        if (!blk[i].ptr) {
            nfree(blk);
            return NULL;
        }
        blk[i].size = size;
    }

    return blk;
}

void nfree_block(MemBlock *blk) {
    for (size_t i = 0; i < num; ++i) {
        nfree(blk[i].ptr);
    }
    free(blk);
}

// Implement memory_used() and other required functions here.
```

2. Dynamic Array Management (`dynarray.h`, `dynarray.c`)

```c
#ifndef DYNAARRAY_H
#define DYNAARRAY_H

typedef struct NFAPI_RX_FRAME_T RxFrame;

void initDynArray(DynArray *arr);
RxFrame* getFrameAt(DynArray *arr, size_t index);
void addFrameToDynArray(DynArray *arr, RxFrame frame);
size_t sizeOfDynArray(const DynArray *arr);

#endif // DYNAARRAY_H
```

```c
#include "dynarray.h"
#include <stdbool.h>
#include <pthread.h>

typedef struct DynArray {
    MemBlock *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynArray;

void initDynArray(DynArray *arr) {
    arr->capacity = 128;
    arr->size = 0;
    arr->data = ncalloc(arr->capacity, sizeof(RxFrame));
    if (!arr->data) {
        printf("Error: Failed to initialize dynarray.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&arr->mutex, NULL);
}

RxFrame* getFrameAt(DynArray *arr, size_t index) {
    RxFrame *frame;

    if (index >= arr->size || index < 0) {
        printf("Error: Index out of bounds.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&arr->mutex);
    frame = &arr->data[index];
    pthread_mutex_unlock(&arr->mutex);

    return frame;
}

void addFrameToDynArray(DynArray *arr, RxFrame frame) {
    if (arr->size >= arr->capacity) {
        growDynArray(arr);
    }

    pthread_mutex_lock(&arr->mutex);
    arr->data[arr->size] = frame;
    ++arr->size;
    pthread_mutex_unlock(&arr->mutex);
}

size_t sizeOfDynArray(const DynArray *arr) {
    return arr->size;
}

void growDynArray(DynArray *arr) {
    MemBlock *new_data = ncalloc(arr->capacity * 2, sizeof(RxFrame));

    if (!new_data) {
        printf("Error: Failed to grow dynarray.\n");
        exit(EXIT_FAILURE);
    }

    size_t i;
    for (i = 0; i < arr->size; ++i) {
        new_data[i] = arr->data[i];
    }

    nfree_block(arr->data);
    arr->capacity *= 2;
    arr->data = new_data;
}
```

