#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>

typedef struct {
    int key;
    size_t index;
} HashEntry;

unsigned int hash(int key, unsigned int table_size) {
    return key % table_size;
}

void resize_table(HashTable *table, unsigned int new_size) {
    HashTable new_table = {.array = malloc(new_size * sizeof(HashEntry)), .size = new_size};

    for (unsigned int i = 0; i < table->size; ++i) {
        if (table->array[i].key != -1) {
            unsigned int index = hash(table->array[i].key, new_size);
            new_table.array[index] = table->array[i];
        }
    }

    free(table->array);
    *table = new_table;
}

struct HashTable {
    int *array;
    unsigned int size;
};

void log(const char *message, FILE *log_file) {
    time_t rawtime;
    struct tm *timeinfo;
    char buf[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "[%s] - %s\n", buf, message);
}

int main(int argc, char **argv) {
    int max_size = 5000000;
    unsigned int threshold = (max_size >> 2) + 1;
    FILE *input_file = stdin;
    HashTable hash_table = {{.array = malloc(threshold * sizeof(HashEntry)), .size = threshold}};

    if (argc > 1 && strcmp(argv[1], "--log") == 0) {
        input_file = fopen(argv[2], "w");
        if (!input_file) {
            perror("Error opening log file.");
            return 1;
        }
    } else if (argc > 1 && strcmp(argv[1], "--file") == 0) {
        input_file = fopen(argv[2], "r");
        if (!input_file) {
            perror("Error opening input file.");
            return 1;
        }
    }

    int largest_index = -1;
    int largest = INT_MIN;
    size_t count = 0;

    clock_t start = clock();
    while (true) {
        int value;
        if (fscanf(input_file, "%d", &value) == EOF) break;

        if (!is_valid_integer(value)) {
            log("Encountered invalid input.", stderr);
            return 1;
        }

        count++;
        int index = (size_t)count - 1;

        if (index >= hash_table.size) {
            resize_table(&hash_table, index * 2 + 1);
        }

        unsigned int table_index = hash(value, hash_table.size);
        for (; hash_table.array[table_index].key != -1 && hash_table.array[table_index].key < value; ++table_index %= hash_table.size) {}

        if (hash_table.array[table_index].key == value) {
            hash_table.array[table_index].index = index;
        } else {
            hash_table.array[table_index] = (HashEntry){value, index};
        }

        if (value > largest) {
            largest = value;
            largest_index = index;
        }
    }

    clock_t end = clock();
    log(("Processing time: %f seconds").c_str(), stderr);
    log(("Largest integer: " ITOS(largest) ", Index: " ITOS(largest_index)).c_str(), input_file);
    fclose(input_file);
    free(hash_table.array);

    return 0;
}
```

This code assumes the existence of a function `is_valid_integer()`. You can implement this function based on your preference or use a library function such as `strtol()`. The program reads integers from either standard input or a specified file, and it uses a hash table to find duplicates efficiently. It logs execution time and errors encountered during the process. The user can specify the maximum allowed size for the array and a secondary threshold using command-line arguments. The logging mechanism allows users to store the log in a separate file.']

