#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    size_t success_count;
    size_t failure_count;
    double total_time;
    size_t current_size;
    NFAPI_CRC_INDICATION_PDU_T *array;
} DataManager;

DataManager *create_data_manager() {
    DataManager *dm = malloc(sizeof(DataManager));
    if (!dm) return NULL;
    pthread_mutex_init(&dm->mutex, NULL);
    dm->success_count = 0;
    dm->failure_count = 0;
    dm->total_time = 0.0;
    dm->current_size = 0;
    return dm;
}

void destroy_data_manager(DataManager *dm) {
    free(dm->array);
    pthread_mutex_destroy(&dm->mutex);
    free(dm);
}

NFAPI_CRC_INDICATION_PDU_T *get_next_free_element(DataManager *dm) {
    size_t i;
    for (i = dm->current_size; i < dm->current_size + 10000; ++i) {
        pthread_mutex_lock(&dm->mutex);
        if (i >= dm->current_size && dm->array[i].rx_ue_information_tag == 0) {
            pthread_mutex_unlock(&dm->mutex);
            return &dm->array[i];
        }
        pthread_mutex_unlock(&dm->mutex);
    }
    return NULL;
}

void process_batch(DataManager *dm, NFAPI_CRC_INDICATION_PDU_T batch[], size_t size) {
    clock_t start, end;
    double elapsed_time;
    for (size_t i = 0; i < size; ++i) {
        start = clock();
        NFAPI_CRC_INDICATION_PDU_T *element = get_next_free_element(dm);
        if (!element) continue; // No free element, skip this one.
        memcpy(element, &batch[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        end = clock();
        elapsed_time = (double)(end - start) / CLOCKS_PER_SEC;
        pthread_mutex_lock(&dm->mutex);
        dm->total_time += elapsed_time;
        ++dm->current_size;
        if (element->crc_indication_rel8_tag.crcflag == 0)
            ++dm->failure_count;
        else
            ++dm->success_count;
        pthread_mutex_unlock(&dm->mutex);
    }
}
```

