typedef struct {
    RX_FRAME_CONFIG config;
    RF_CHAIN chain;
    RECEPTION_QUALITY quality;
    unsigned int packet_id;
} PHY_RX_FRAME_T;

struct mem_block {
    void* start;
    size_t size;
};

static struct mem_block *mem_pool = NULL;
static size_t mem_used = 0;
static size_t mem_total = 0;
static sem_t mem_mutex;

static PHY_RX_FRAME_T* frames = NULL;
static int frame_count = 0;
static pthread_mutex_t frame_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t frame_cond = PTHREAD_COND_INITIALIZER;

void *custom_malloc(size_t size) {
    void* result;

    sem_wait(&mem_mutex);
    if (mem_used + size > mem_total) {
        fprintf(stderr, "Out of memory\n");
        result = NULL;
    } else {
        result = mmap((void*)(mem_used), size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (result == MAP_FAILED) {
            fprintf(stderr, "mmap failed\n");
            result = NULL;
        } else {
            mem_used += size;
        }
    }
    sem_post(&mem_mutex);

    return result;
}

void custom_free(void* ptr) {
    if (ptr != NULL) {
        munmap((void*)ptr, mem_used - (size_t)(ptr - mem_pool->start));
        mem_used -= (size_t)(ptr - mem_pool->start);
    }
}

PHY_RX_FRAME_T* frame_new(const RX_FRAME_CONFIG* config, const RF_CHAIN* chain, const RECEPTION_QUALITY* quality, unsigned int packet_id) {
    PHY_RX_FRAME_T* result;

    sem_wait(&mem_mutex);
    if (frame_count >= MAX_FRAMES) {
        fprintf(stderr, "Maximum number of frames reached\n");
        result = NULL;
    } else {
        result = &frames[frame_count++];
        memset(result, 0, sizeof(PHY_RX_FRAME_T));
        result->config = *config;
        result->chain = *chain;
        result->quality = *quality;
        result->packet_id = packet_id;
    }
    sem_post(&mem_mutex);

    return result;
}

PHY_RX_FRAME_T* frame_get(unsigned int index) {
    PHY_RX_FRAME_T* result;

    pthread_mutex_lock(&frame_lock);
    if (index >= frame_count || index < 0) {
        fprintf(stderr, "Index out of range\n");
        result = NULL;
    } else {
        result = &frames[index];
    }
    pthread_mutex_unlock(&frame_lock);

    return result;
}

void frame_export(FILE* file) {
    int i;

    pthread_mutex_lock(&frame_lock);
    fprintf(file, "PACKET_ID,RX_CONFIG,RF_CHAIN,RECEPTION_QUALITY\n");
    for (i = 0; i < frame_count; ++i) {
        PHY_RX_FRAME_T* frame = frames + i;
        fprintf(file, "%u,%d,%f,%f\n", frame->packet_id, frame->config.param1, frame->chain.param1, frame->quality.param1);
    }
    pthread_mutex_unlock(&frame_lock);
}

void process_queue(PHY_RX_FRAME_T* packet) {
