}

void init() {
    mem_total = 1024 * 1024; // 1MB memory pool
    mem_pool = mmap(NULL, mem_total, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem_pool == MAP_FAILED) {
        fprintf(stderr, "mmap failed\n");
        exit(EXIT_FAILURE);
    }

    sem_init(&mem_mutex, 1, 1);
}
