```javascript
function findElements(rootNode, selector, testElementFunction) {
    var result = [];

    if (rootNode && rootNode.matchesSelector) {
        if (rootNode.matchesSelector(selector)) {
            result.push(rootNode);
        }

        Array.from(rootNode.children).forEach((node) => result = result.concat(findElements(node, selector, testElementFunction)));
    }

    return result.filter((element) => testElementFunction(element));
}
```

