using System;
using System.Xml.Linq;

public static XElement GetFirstElementByName(XDocument xmlDoc, string elementName)
{
    var matchingElements = xmlDoc.Root.Elements().Where(e => e.Name.LocalName == elementName);

    if (matchingElements.Count() > 1)
        throw new Exception("More than one element with the given name found.");

    return matchingElements.FirstOrDefault();
}
