fn get_bits_per_sample(image: &TIFF) -> u16 {
    let ifd = image.get_primary().unwrap();
    match ifd.find_tag(Tag::BitsPerSample).ok() {
        Some(tag) => tag.values[0] as u16,
        None => 8, // Default to 8 bits per sample if not found
    }
}

fn get_samples_per_pixel(image: &TIFF) -> u32 {
    let ifd = image.get_primary().unwrap();
    match ifd.find_tag(Tag::SamplesPerPixel).ok() {
        Some(tag) => tag.values[0] as u32,
        None => 1, // Default to 1 sample per pixel if not found
    }
}
