#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <ctype.h>

// Function to check if a character is valid for the file name
int is_valid_char(char c) {
    return isalnum(c) || c == '_' || c == '-';
}

sem_t sem; // Semaphore for concurrent access

char* generate_filename(const char *input, const char *file_type) {
    size_t input_len = strlen(input);
    if (input_len > 255 - strlen(file_type)) {
        return NULL; // Return null if the new filename would exceed the maximum length
    }

    char *new_filename = malloc(256); // Allocate space for the new filename
    strncpy(new_filename, input, input_len); // Copy the input filename
    sem_wait(&sem); // Lock access to the directory to avoid race conditions

    int i;
    for (i = input_len; i < 255 - strlen(file_type); ++i) {
        new_filename[i] = toupper((rand() % 26) + 'A'); // Add a random character to the identifier
        if (!is_valid_char(new_filename[i])) {
            // Rollback changes if the added character is invalid
            i--;
            new_filename[i] = '\0';
            break;
        }
    }

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    strftime(new_filename + input_len, 256 - input_len, "%Y%m%d_%H%M%S", timeinfo); // Add timestamp to the filename

    char random[8]; // Random number
    snprintf(random, sizeof(random), "%07d", rand());
    strcat(new_filename + input_len + 15, random); // Add random number to the filename
    strcat(new_filename + input_len + 15 + strlen(random), file_type); // Append the specified file type

    sem_post(&sem); // Unlock access to the directory

    struct stat st;
    if (stat(new_filename, &st) == 0 && S_ISREG(st.st_mode)) {
        // Replace invalid characters and retry if the filename already exists
        int j;
        for (j = input_len + 15 + strlen(random); j < 255 - strlen(file_type) - 1; ++j) {
            new_filename[j] = toupper((rand() % 26) + 'A');
            if (is_valid_char(new_filename[j])) {
                break;
            }
        }
        if (j == 255 - strlen(file_type) - 1) {
            // Free memory and return NULL if no valid characters remain
            free(new_filename);
            return NULL;
        }
    }

    return new_filename;
}
```

This function creates a unique filename by appending a timestamp, random number, and a specified file type to the input filename. It uses a semaphore to avoid race conditions when accessing the directory and checking if the new filename already exists. Edge cases are handled by ensuring that the resulting filename does not exceed the maximum length and does not contain invalid characters. The function is designed to be easily maintainable and scalable, allowing for integration with additional features or systems.']

