// Function to modify filename extension based on composition
void modify_extension(char* filename, int digits) {
    char ext[5];

    if (digits == 0) strcpy(ext, ".txt");
    else if (digits == 1) strcpy(ext, ".dat");
    else if (digits >= 2 && digits <= 4) strcpy(ext, ".db");
    else strcpy(ext, ".bin");

    int len = strlen(filename);
    char* dot = strrchr(filename, '.');
    memmove(dot + 1, ext, strlen(ext) + 1);
}

// Function to read integers from stdin or file and find largest
int find_largest(char* filename, int max_size, int* arr) {
    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        for (int i = 0; i < max_size; ++i) {
            scanf("%d", &arr[i]);
            if (!feof(stdin)) arr[i] ?: -1; // If scanned value is not a number, replace it with an invalid marker (-1).
        }
    } else {
        for (int i = 0; i < max_size && fscanf(file, "%d", &arr[i]) != EOF; ++i) {
            if (!feof(file)) arr[i] ?: -1; // If scanned value is not a number, replace it with an invalid marker (-1).
        }
        fclose(file);
    }

    int n = 0;
    for (int i = 0; i < max_size; ++i) {
        if (arr[i] > -1) {
            n++;
            if (!n || arr[i] > *max_element) {
                max_index = i;
                *max_element = arr[i];
            }
        }
    }

    return n ? (*max_element, max_index) : ("No integers provided.", -1);
}

