// Maximum allowed size for the array, defaulting to one million elements
#define MAX_ARRAY_SIZE 1000000

typedef struct {
    int data;
    pid_t thread_id;
    size_t index;
} element;

element *array;
size_t array_len = 0;
sem_t sem;

// Function to modify the extension of a file based on its composition
void modify_extension(char *filename) {
    // Implementation omitted for brevity
}

// Comparison function for qsort
int compare(const void *a, const void *b) {
    return (*(element *)a).data - (*(element *)b).data;
}

// Function to read a potentially large list of integers from either standard input or a file
void read_integers() {
    FILE *file = stdin;
    char c;
    element temp;

    while (1) {
        scanf("%c", &c);
        if (!isdigit(c)) break;

        temp.data = atoi(&c);
        pthread_t thread_id;
        pthread_create(&thread_id, NULL, process_integer, (void *)&temp);
    }
}

// Thread function to process each integer and update the array
void *process_integer(void *arg) {
    element *data = arg;
    data->index = array_len++;

    sem_wait(&sem);
    array = realloc(array, sizeof(element) * array_len);
    if (!array) {
        perror("Realloc failed");
        exit(EXIT_FAILURE);
    }
    array[data->index] = *data;
    sem_post(&sem);

    pthread_exit(NULL);
}

// Function to find the largest integer and its index
void find_largest() {
    qsort(array, array_len, sizeof(element), compare);

