using System.Xml.Serialization;
using System.IO;
using System.Threading;
using System.Linq;
using System.Runtime.Serialization.Formatters.Binary;

[Serializable]
public class Record
{
    public int Value { get; set; }
    public int Key { get; set; }
    public long Offset { get; set; }
}

public class DynamicCollection : IEnumerable<Record>
{
    private List<Record> _records;
    private int _chunkSize = 1000;
    private int _currentChunkIndex = -1;
    private bool _isCancelRequested = false;
    private object _syncLock = new object();

    public event Action<int> ProgressUpdated;

    public void Initialize(int[] keys, long[] offsets)
    {
        if (keys == null || offsets == null) return;

        if (keys.Length != offsets.Length)
        {
            throw new ArgumentException("Both keys and offsets arrays must have the same length.");
        }

        _records = new List<Record>();

        var maxRecords = keys.Length;

        if (maxRecords > int.MaxValue / _chunkSize)
        {
            throw new ArgumentOutOfRangeException("The number of records exceeds the maximum possible capacity when chunking.");
        }

        ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
        Parallel.For(0, maxRecords, options, (index) =>
        {
            if (_isCancelRequested) return;

            _currentChunkIndex++;
            if (_currentChunkIndex >= _chunkSize)
            {
                lock (_syncLock)
                {
                    if (_isCancelRequested) return;
                }

                _currentChunkIndex = -1;
            }

            Record record = new Record { Value = keys[index], Key = index, Offset = offsets[index] };
            _records.Add(record);

            if (_currentChunkIndex >= _chunkSize - 1)
            {
                lock (_syncLock)
                {
                    int progress = ((float)_currentChunkIndex / _chunkSize) * 100;
                    ProgressUpdated?.Invoke(progress);
                }
            }
        });
    }

    public void Cancel()
    {
        _isCancelRequested = true;
    }

    public void Save()
    {
        using (FileStream stream = File.OpenWrite("data.dat"))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            formatter.Serialize(stream, _records);
        }
    }

    public static DynamicCollection Load()
    {
        if (!File.Exists("data.dat")) return new DynamicCollection();

        using (FileStream stream = File.OpenRead("data.dat"))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            return (DynamicCollection)formatter.Deserialize(stream);
        }
    }

    public IEnumerator<Record> GetEnumerator()
    {
        return _records.GetEnumerator();
    }

    IEnumerator IEnumerable.GetEnumerator()
    {
        return GetEnumerator();
    }
}

