    track_application_state("Initialization");

    // Main loop handling I/O and worker management...

    track_application_state("Termination");

    return 0;
}

void track_application_state(const char *state, ...) {
    time_t now = time(NULL);
    if (now - last_log >= 60) { // Rate-limiting: log once per minute
        sem_wait(&log_semaphore);
        last_log = now;
    } else {
        return;
    }

    va_list args;
    va_start(args, state);

    char message[4096];
    snprintf(message, sizeof(message), "[%s] %s", asctime(localtime(&now)), state);
    vsnprintf(message + strlen(message), sizeof(message) - strlen(message), args, va_arg_ptr(args));

    printf("%s\n", message);

    va_end(args);
}

void *process_file(void *arg) {
    file_data *fd = (file_data*) arg;

    // Process the file data in batches and write output to a stream...

    clean_up(fd);
    pthread_exit(0);
}

void clean_up(file_data *fd) {
    if (fd->fp != NULL) {
        fclose(fd->fp);
        fd->fp = NULL;
    }
    free(fd->filepath);
    fd->filepath = NULL;
    pthread_mutex_destroy(&fd->mutex);
    free(fd);
}
