['```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include "pokemon.h" // Assuming you have a header file 'pokemon.h' defining the Pokemon structure and functions to retrieve its type and name

typedef struct {
    pthread_t thread_id;
    void (*function)(void *);
    void *arg;
    sem_t *semaphore;
} worker_t;

struct thread_pool {
    int num_threads;
    worker_t **workers;
    sem_t queue_sem, free_sem;
};

void *worker(void *arg) {
    struct thread_pool *thread_pool = arg;
    while (1) {
        sem_wait(&thread_pool->free_sem);
        worker_t *worker = thread_pool->workers[*(int *)arg];
        *(int *)arg = -1; // Mark the index as 'idle'
        sem_post(&thread_pool->queue_sem);

        if (!worker) break; // Pool is shutting down

        worker->function(worker->arg);
        free(worker);
        sem_post(&thread_pool->free_sem);
    }
    return NULL;
}

struct thread_pool *create_thread_pool(int num_threads) {
    struct thread_pool *thread_pool = malloc(sizeof(*thread_pool));
    if (!thread_pool) return NULL;

    thread_pool->num_threads = num_threads;
    pthread_attr_t attr;
    int i, ret;
    sem_init(&thread_pool->queue_sem, 0, num_threads); // Initialize the queue semaphore
    sem_init(&thread_pool->free_sem, 0, num_threads); // Initialize the free semaphore
    thread_pool->workers = malloc(num_threads * sizeof(*thread_pool->workers));
    if (!thread_pool->workers) {
        free(thread_pool);
        return NULL;
    }

    pthread_attr_init(&attr);
    for (i = 0; i < num_threads; ++i) {
        worker_t *worker = thread_pool->workers + i;
        worker->function = worker;
        worker->arg = (void *)i;
        ret = pthread_create(&worker->thread_id, &attr, worker, worker);
        if (ret != 0) {
            perror("pthread_create");
            goto error;
        }
    }

    return thread_pool;

error:
    destroy_thread_pool(thread_pool);
    return NULL;
}

void enqueue(struct thread_pool *pool, void (*function)(void *), void *arg) {
    sem_wait(&pool->free_sem); // Wait for a worker to become idle
    worker_t *worker = malloc(sizeof(*worker));
    if (!worker) {
        perror("malloc");
        sem_post(&pool->free_sem);
        return;
    }

    worker->function = function;
    worker->arg = arg;
    pool->workers[*(int *)pthread_self()] = worker; // Assign the idle worker to the task
    *(int *)pthread_self() = -2; // Mark the current thread as 'busy'
    sem_post(&pool->queue_sem); // Notify a waiting worker of available work
}

void destroy_thread_pool(struct thread_pool *thread_pool) {
    int i;
    for (i = 0; i < thread_pool->num_threads; ++i) {
        enqueue(thread_pool, NULL, (void *)i); // Notify workers to shutdown
    }

    for (i = 0; i < thread_pool->num_threads; ++i) {
        pthread_join(thread_pool->workers[i]->thread_id, NULL); // Wait for all threads to finish
    }

    free(thread_pool->workers);
    sem_destroy(&thread_pool->queue_sem);
    sem_destroy(&thread_pool->free_sem);
    free(thread_pool);
}

