    struct task* next;
} Task;

struct thread_pool {
    pthread_t threads[MAX_THREADS];
    sem_t task_queue_sem;
    sem_t concurrency_sem;
    Task queue[TASK_QUEUE_SIZE];
    int head, tail;
};

void write_to_file(Task* tasks, size_t num_tasks) {
    // Implement serialization logic here
