struct thread_pool* create_thread_pool(int num_threads) {
    struct thread_pool* pool = malloc(sizeof(struct thread_pool));
    if (!pool) return NULL;

    for (int i = 0; i < num_threads; ++i)
        pthread_create(&pool->threads[i], NULL, worker, pool);

    sem_init(&pool->task_queue_sem, 0, 0);
    sem_init(&pool->concurrency_sem, 0, num_threads);

    pool->head = pool->tail = 0;

    return pool;
}

void destroy_thread_pool(struct thread_pool* pool) {
    sem_destroy(&pool->task_queue_sem);
    sem_destroy(&pool->concurrency_sem);
    free(pool);
}

Task* dequeue(struct thread_pool* pool) {
    Task* task = NULL;
    sem_wait(&pool->task_queue_sem);
    if (pool->head != pool->tail) {
        task = &pool->queue[pool->head];
        pool->head = (pool->head + 1) % TASK_QUEUE_SIZE;
    }
    sem_post(&pool->task_queue_sem);
    return task;
}

void enqueue(struct thread_pool* pool, Task* task) {
    sem_wait(&pool->concurrency_sem);
    if ((pool->tail + 1) % TASK_QUEUE_SIZE == pool->head) {
        // Task queue is full; handle overflow here
    } else {
        pool->queue[pool->tail] = *task;
        pool->tail = (pool->tail + 1) % TASK_QUEUE_SIZE;
    }
    sem_post(&pool->concurrency_sem);
}

// Implement worker function here, including task execution logic and backoff strategy

void* worker(void* arg) {
    // Cast arg to the thread pool struct pointer
    struct thread_pool* pool = (struct thread_pool*)arg;

    while (true) {
        Task* task = dequeue(pool);
        if (!task) break;
        // Execute task here, managing timeout and retries as needed
    }

    return NULL;
}
