[' Here is a simplified version of an AVL Tree implementation in C++ that satisfies your requirements. Note that this code is not optimized for large-scale applications and lacks some advanced features like customization options and caching mechanisms, but it serves as a good starting point.

```cpp
#include <iostream>
#include <map>
#include <utility>
#include <cassert>

template<typename KeyType> class AVLTreeNode {
public:
    KeyType key;
    int balanceFactor = 0;
    AVLTreeNode *leftChild, *rightChild, *parent;

    AVLTreeNode(KeyType k) : key(k), leftChild(nullptr), rightChild(nullptr), parent(nullptr) {}
};

template<typename KeyType> class AVLTree {
private:
    AVLTreeNode<KeyType>* root = nullptr;

public:
    void insert(const KeyType& key1, const KeyType& key2) {
        auto nodeToInsert = new AVLTreeNode<KeyType>(key2);
        insert(root, nodeToInsert, key1);
    }

private:
    void insert(AVLTreeNode<KeyType>* current, AVLTreeNode<KeyType>* nodeToInsert, const KeyType& key) {
        if (current == nullptr) {
            current = nodeToInsert;
            return;
        }

        int compareResult = key.compare(current->key);

        if (compareResult < 0) {
            if (!current->leftChild)
                current->leftChild = nodeToInsert;
            insert(current->leftChild, nodeToInsert, key);
        } else if (compareResult > 0) {
            if (!current->rightChild)
                current->rightChild = nodeToInsert;
            insert(current->rightChild, nodeToInsert, key);
        } else {
            // key already exists in the tree
            assert(false && "Key already exists in the tree");
        }

        updateBalanceFactor(nodeToInsert);
        rebalance(nodeToInsert);
    }

    void updateBalanceFactor(AVLTreeNode<KeyType>* node) {
        if (node) {
            node->balanceFactor = 1 + std::max(std::map<>{}.count(node->leftChild), std::map<>{}.count(node->rightChild)) -
                                   std::min(std::map<>{}.count(node->leftChild), std::map<>{}.count(node->rightChild));
        }
    }

    void rebalance(AVLTreeNode<KeyType>* node) {
        if (node->balanceFactor == 2) {
            if (node->rightChild->balanceFactor < 0) {
                rotateLeft(node);
                rotateRight(node->leftChild);
            } else {
                rotateRight(node);
            }
        } else if (node->balanceFactor == -2) {
            if (node->leftChild->balanceFactor > 0) {
                rotateLeft(node);
            } else {
                rotateLeft(node->leftChild);
                rotateRight(node->leftChild->rightChild);
            }
        }
    }

    void rotateLeft(AVLTreeNode<KeyType>* node) {
        AVLTreeNode<KeyType>* parent = node->parent;
        auto rightChild = node->rightChild;

        node->parent = rightChild;
        node->rightChild = rightChild->leftChild;

        if (rightChild->leftChild)
            rightChild->leftChild->parent = node;

        rightChild->leftChild = node;
        rightChild->parent = node->parent;

        if (node->rightChild == nullptr)
            parent->leftChild = rightChild;
        else
            parent->rightChild = rightChild;

        node->updateBalanceFactor();
        rightChild->updateBalanceFactor();
    }

    void rotateRight(AVLTreeNode<KeyType>* node) {
        AVLTreeNode<KeyType>* parent = node->parent;
        auto leftChild = node->leftChild;

        node->parent = leftChild;
        node->leftChild = leftChild->rightChild;

        if (leftChild->rightChild)
            leftChild->rightChild->parent = node;

        leftChild->rightChild = node;
        leftChild->parent = node->parent;

        if (node->leftChild == nullptr)
            parent->rightChild = leftChild;
        else
            parent->leftChild = leftChild;

        node->updateBalanceFactor();
        leftChild->updateBalanceFactor();
    }
};
```

