#include <vector>
#include <string>

void printInOrder(const AVLTreeNode<std::string>& node, std::vector<std::string> result) {
    if (node == nullptr) return;

    printInOrder(node->leftChild, result);
    result.push_back(node->key);
    printInOrder(node->rightChild, result);
}

int main() {
    AVLTree<std::string> tree;
    std::vector<std::string> keys = {"apple", "banana", "cherry", "date", "elderberry"};

    for (auto key : keys)
        tree.insert(keys[0], key);

