    {
        var queryBuilder = new QueryBuilder(_configuration);

        if (!queryBuilder.ValidateConfiguration(config))
            throw new InvalidOperationException("Invalid configuration provided.");

        var builder = new StringBuilder();
        using (var command = CreateCommand(builder, commandTimeout))
        {
