const yamlish = require('yamlish'); // for YAML support
const json5 = require('json5'); // for JSON5 support

const concurrencyLimit = process.env.CONCURRENCY_LIMIT || 4;
const cache = new Map();
const cacheTTL = 60 * 60 * 1000; // 1 hour cache duration
const distributedCache = require('./distributed-cache');

async function readFileAsync(filePath) {
    if (!fs.existsSync(filePath)) {
        console.warn(`[WARN] File not found: ${filePath}`);
        return '';
    }

    const ext = path.extname(filePath).toLowerCase();
    let contentType;

    switch (ext) {
        case '.csv':
            contentType = 'text/csv';
            break;
        case '.xml':
            contentType = 'application/xml';
            break;
        case '.json':
            contentType = 'application/json';
            break;
        case '.yaml':
        case '.yml':
            contentType = 'application/x-yaml';
            break;
        case '.json5':
            contentType = 'application/json5';
            break;
        default:
            contentType = 'text/plain';
    }

    // Ensure the file is not over 100 MB in size
    const stats = fs.statSync(filePath);
    if (stats.size > 100 * 1024 * 1024) {
        console.warn(`[WARN] File too large: ${filePath}`);
        return '';
    }

    let cacheKey = getCacheKey(filePath);
    let cachedContent;

    if (cache.has(cacheKey)) {
        // Check if the cached content is expired or not in distributed cache
        const now = Date.now();
        if ((now - cache[cacheKey][1]) > cacheTTL || !distributedCache.get(cacheKey)) {
            // Content is either expired or not in distributed cache, so re-read the file
            cachedContent = await readFileChunked(filePath);

            // Cache content locally and in distributed cache
            cache.set(cacheKey, [cachedContent, now]);
            distributedCache.set(cacheKey, cachedContent);
        } else {
            // Content is still valid, return it from the cache
            cachedContent = distributedCache.get(cacheKey);
        }
    } else {
        // Content is not in the local cache, so re-read the file
        cachedContent = await readFileChunked(filePath);

        // Cache content locally and in distributed cache
        cache.set(cacheKey, [cachedContent, Date.now()]);
        distributedCache.set(cacheKey, cachedContent);
    }

    return processedContent(ext, cachedContent);
}

function readFileChunked(filePath) {
    const chunkSize = 1048576; // 1 MB chunk size
    const stream = fs.createReadStream(filePath, { highWaterMark: chunkSize });
    return new Promise((resolve, reject) => {
        const chunks = [];

        let currentChunk = '';
        readline.createInterface({ input: stream }).on('line', (chunk) => {
            currentChunk += chunk;

            if (currentChunk.length > chunkSize) {
                chunks.push(currentChunk);
                currentChunk = '';
            }
        });

        stream.on('end', () => {
            // Handle the last chunk here, since it might not be exactly chunkSize long
            if (currentChunk) chunks.push(currentChunk);

            resolve(Buffer.concat(chunks).toString());
        });
    });
}

function processedContent(ext, content) {
    // Process the content according to its file type
    switch (ext) {
        case '.csv':
            return content.split('\n')[1] || ''; // Skip header row and return first line of data as a string
        case '.xml':
            const xml = xml2js.parseStringSync(content);
            // Process the XML data based on its structure and desired output format
            break;
        case '.json':
            try {
                return JSON.parse(content);
            } catch (err) {
                console.error(`[ERROR] Failed to parse JSON: ${filePath}`);
                throw err;
            }
        case '.yaml':
        case '.yml':
            try {
                return yamlish.parse(content);
            } catch (err) {
                console.error(`[ERROR] Failed to parse YAML: ${filePath}`);
                throw err;
            }
        case '.json5':
            try {
                return json5.parse(content);
            } catch (err) {
                console.error(`[ERROR] Failed to parse JSON5: ${filePath}`);
                throw err;
            }
        default:
            return content;
    }
}

function getCacheKey(filePath) {
