async function runModuleTests(testFunction, moduleName) {
  try {
    const module = await importDynamic(`./${moduleName}.mjs`);
    if (!testFunction || !testFunction.length === 1 || !(typeof testFunction[0] === 'function' && typeof testFunction[0].then === 'function')) {
      console.warn(`Invalid test function for ${moduleName}`);
