        console.error(error);
        tests.push({ name: `Test #${i + 1}`, error: error.stack });
      }));
    }

    await workerPool.drain(); // wait for all tests to complete

    const results = tests.reduce((acc, test) => {
      if (!test.result || !test.result.success) acc.failedTests.push(test);
      else if (test.result.duration > 10_000) acc.timeouts.push(test);
      return acc;
    }, { success: true, failedTests: [], timeouts: [] });

    results.resourceUsage = // add code to calculate resource usage during test runs

    return results;
  } catch (error) {
    console.log(`Error loading ${moduleName}:`);
    console.error(error);
    return { success: false, failedTests: [], timeouts: [] };
  }
}
