import redis
from datetime import timedelta, datetime
import requests
import os
from dotenv import load_dotenv
import smtplib
import logging
import functools
import time
from concurrent.futures import ThreadPoolExecutor

load_dotenv()
API_KEYS = {
    'API1': os.getenv('API1_KEY'),
    'API2': os.getenv('API2_KEY')
}
CACHE_TTL = 24 * 60 * 60  # Cache expiration in seconds (24 hours)
RATE_LIMIT_INTERVAL = 60  # Rate limit interval in seconds

def get_weather_api(api):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            rate_limited = kwargs.pop('rate_limited', True)
            last_request = redis.Redis().get(f'weather:{api}:last_request')
            if rate_limited and last_request and (datetime.now() - datetime.fromtimestamp(int(last_request))).seconds < RATE_LIMIT_INTERVAL:
                return 'Rate limited. Try again in {} seconds.'.format(RATE_LIMIT_INTERVAL - (datetime.now() - datetime.fromtimestamp(int(last_request))).seconds)
            resp = func(*args, **kwargs)
            redis.Redis().setex(f'weather:{api}:last_request', 5, int(time.time()))
            return resp
        return wrapper
    return decorator

@get_weather_api('API1')
def fetch_weather_data(city, unit='metric'):
    api_url = 'https://api.openweathermap.org/data/2.5/weather'
    params = {'q': city, 'appid': API_KEYS['API1'], 'units': unit}
    response = requests.get(api_url, params=params)
    if response.status_code == 200:
        return response.json()
    else:
        logging.error('Error fetching weather data for {}'.format(city))
        raise Exception('API error')

def cache_weather_data(key, value):
    redis_cache = redis.Redis()
    redis_cache.setex(key, CACHE_TTL, value)

@get_weather_api('API2', rate_limited=False)
def fetch_alternative_weather_data(city, unit='metric'):
    api_url = 'https://api.openweathermap.org/data/2.5/weather'
    params = {'q': city, 'appid': API_KEYS['API2'], 'units': unit}
    response = requests.get(api_url, params=params)
    if response.status_code == 200:
        return response.json()
    else:
        logging.error('Error fetching alternative weather data for {}'.format(city))
        raise Exception('API error')

def get_weather_details(city, unit='metric'):
    cache_key = 'weather:{unit}:{city}'.format(unit=unit, city=city)
    cached_data = cache_weather_data.get(cache_key)
    if cached_data:
        return cached_data

    try:
        data = fetch_weather_data(city, unit)
    except Exception as e:
        logging.error(e)
        data = fetch_alternative_weather_data(city, unit)

    cache_weather_data(cache_key, data)
    return data

def send_email_notification(prev_day_data, current_data):
    subject = 'Weather Condition Change Notification'
    body = 'Previous day: {}\nCurrent day: {}'.format(prev_day_data, current_data)

    server = smtplib.SMTP('smtp.example.com', 587)
    server.starttls()
    server.login("youremail@example.com", "yourpassword")
    msg = 'Subject: {}\n\n{}'.format(subject, body)
    server.sendmail("youremail@example.com", "recipient@example.com", msg)
    server.quit()

def main():
    city = 'New York'
    unit = 'metric'

    current_weather = get_weather_details(city, unit)
    previous_weather = cache_weather_data.get('weather:{unit}:{city}_prev'.format(unit=unit, city=city))

    if previous_weather:
        send_email_notification(previous_weather, current_weather)

    print("Current weather details for {}:\n{}".format(city, current_weather))

if __name__ == "__main__":
    main()
