    protected $sessionCheckUrl;

    public function __construct(HttpClient $httpClient, $complexityCheckUrl, $sessionCheckUrl)
    {
        $this->httpClient = $httpClient;
        $this->complexityCheckUrl = $complexityCheckUrl;
        $this->sessionCheckUrl = $sessionCheckUrl;
