    public function updatePassword(User $user, string $newPassword): void
    {
        if (!$this->validateComplexity($newPassword)) {
            throw new \Exception("The provided password does not meet complexity requirements.");
        }

        try {
            $sessionValid = $this->checkSession($user);
            if (!$sessionValid) {
                throw new \Exception("The session is invalid or has expired.");
            }
        } catch (Exception $e) {
            throw new \Exception("Error checking session: " . $e->getMessage());
        }

        try {
            $cachedValidationResult = Cache::get("password_validation_{$user->id}");
            if ($cachedValidationResult) {
                $validationResult = unserialize($cachedValidationResult);
                if (!$validationResult['success']) {
                    throw new \Exception("Password validation failed.");
                }
            } else {
                $response = $this->validateComplexityCheck($newPassword);
                $validationResult = json_decode((string)$response->getBody(), true);
                Cache::put("password_validation_{$user->id}", serialize([
                    'success' => $validationResult['success'],
                    'message' => $validationResult['message'] ?? '',
                ]), config('cache.options.ttl'));
            }
        } catch (GuzzleException $e) {
            throw new \Exception("Error validating password complexity: " . $e->getMessage());
        }

