#include <cstdio>
#include <cstring>
#include <vector>
#include <memory>
#include <mutex>
#include <sstream>
#include <openssl/md5.h>
#include <atomic>
#include <thread>
#include <queue>

class Octree {
public:
    struct Node {
        bool isLeaf = false;
        std::vector<std::unique_ptr<Node>> children;
        std::vector<float> data;

        std::mutex mtx;
    };

    Octree(size_t featureSize, size_t numLeafNodes, size_t dataCapacity) {
        _featureSize = featureSize;
        _numLeafNodes = numLeafNodes;
        _dataCapacity = dataCapacity;
        _cache.reserve(_numLeafNodes * 4);
        _queue.reserve(_numLeafNodes * 4);

        root = std::make_unique<Node>();
        initialize(root.get(), 0, 0, 1 << static_cast<unsigned int>(std::log2(_numLeafNodes)));
    }

    std::string computeMD5Hash(const char* input) {
        std::unique_ptr<uint8_t[]> md5_hash(new uint8_t[MD5_DIGEST_LENGTH]);
        MD5_CTX ctx;
        MD5_Init(&ctx);
        MD5_Update(&ctx, input, strlen(input));
        MD5_Final(md5_hash.get(), &ctx);

        std::stringstream ss;
        for (size_t i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(md5_hash[i]);
        }

        return ss.str();
    }

private:
    void initialize(Node* node, size_t index, size_t depth, unsigned int length) {
        if (depth > 0 && length <= 1) return;

        for (size_t i = index; i < index + length; ++i) {
            node->children.emplace_back(new Node());
            initialize(node->children[i], static_cast<size_t>((i * _featureSize)[0]), depth - 1, length >> 1);
            if (depth <= 1) {
                node->data.resize(_dataCapacity, 0.0f);
            }
        }
    }

    size_t _featureSize;
    size_t _numLeafNodes;
    size_t _dataCapacity;
    unsigned char* _cache[8];
    std::queue<Node*> _queue;
    std::unique_ptr<Node> root;

    // Mutex for thread safety
    std::mutex _mtx;

    // Atomic counter to handle concurrent updates
    std::atomic<size_t> _concurrentUpdates{0};
};
```

