import asyncio
import aiohttp
from typing import List, Callable, Any

class Aggregator:
    def __init__(self, user_ids: List[int], initial_state: Any, aggregator: Callable[[Any, dict], Any], api_fetcher: Callable[[int], aiohttp.ClientSession]):
        self.user_ids = user_ids
        self.initial_state = initial_state
        self.aggregator = aggregator
        self.api_fetcher = api_fetcher

    async def _fetch_profile(self, session: aiohttp.ClientSession, user_id: int) -> dict:
        try:
            async with session.get(f'/api/user/{user_id}') as response:
                if response.status == 200:
                    return await response.json()
        except Exception as e:
            print(f"Error fetching user {user_id}: {e}")
            return None
        finally:
            session.close()

    async def _fetch_metadata(self, session: aiohttp.ClientSession, user_id: int) -> dict:
        try:
            async with session.get(f'/api/metadata/{user_id}') as response:
                if response.status == 200:
                    return await response.json()
        except Exception as e:
            print(f"Error fetching metadata for user {user_id}: {e}")
            return None
        finally:
            session.close()

    async def _process_profile(self, current_state: Any, profile_data: dict) -> Any:
        additional_metadata = await self._fetch_metadata(self.api_fetcher(user_id), user_id)
        return self.aggregator(current_state, {**profile_data, **additional_metadata})

    async def _aggregate_profiles(self):
        tasks = []
        profiles_data = [None] * len(self.user_ids)
        sessions = set()

        for user_id in self.user_ids:
            session = self.api_fetcher(user_id)
            tasks.append(asyncio.create_task(self._process_profile(self.initial_state, profiles_data[user_id]) if profiles_data[user_id] is not None else self._fetch_profile(session, user_id)))
            sessions.add(session)

        results = await asyncio.gather(*tasks)
        for i, result in enumerate(results):
            if result is not None:
                profiles_data[self.user_ids[i]] = result

        return self.initial_state if len(profiles_data) == 0 else await self._process_profile(profiles_data[-1], profiles_data[0])

    async def aggregate(self):
        while True:
            try:
                final_state = await self._aggregate_profiles()
                print(f"Aggregated state: {final_state}")
                await asyncio.sleep(5) # Adjust this sleep time based on the API response times
            except Exception as e:
                print(f"Error aggregating profiles: {e}")
                await asyncio.sleep(10) # Retry after a short delay in case of an error

```

