    if (!input || !output) {
        fprintf(stderr, "Input or output string is null.\n");
        return NULL;
    }

    if (strlen(input) > size_limit)
        return NULL;

    size_t required = strlen(input) + 2; // Including / and null terminator

    if (required <= buffer_size) {
        strcat(output, "/");
        *required_size = required;
        return SUFFICIENT;
    }

    char *temp = malloc(required);
    if (!temp) {
        fprintf(stderr, "Out of memory while allocating temporary buffer.\n");
        return NULL;
    }

    strcpy(temp, input);
    strcat(temp, "/");

    size_t copy_size = (buffer_size < required) ? BUFFER_GROWTH : required;
    char *dest = realloc(output, copy_size);
    if (!dest) {
        fprintf(stderr, "Out of memory while allocating destination buffer.\n");
        free(temp);
        return NULL;
    }

    strcpy(dest, temp);
    free(temp);
    *required_size = required;
    return NEEDS_TEMPORARY;
}
