Node* create_record(int min, int max) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->record.value = rand() % (max - min + 1) + min;
    node->next = NULL;
    return node;
}

char* string_trim(const char* input, size_t limit, char* buffer, size_t buffer_size) {
    size_t len = strlen(input);

    if (len > limit) return NULL;

    if (len < limit - 1) {
        memcpy(buffer, input, len + 1);
        buffer[len] = '/';
    } else {
        if (buffer_size <= len + 1) return NULL;
        memcpy(buffer, input, len + 1);
    }

    return buffer;
}

Node** create_linked_list(size_t limit, size_t batch_size, size_t* records_count) {
    Node **records = (Node**)malloc(batch_size * sizeof(Node*));

    if (!records) return NULL;

    for (size_t i = 0; i < batch_size; ++i)
        records[i] = create_record(0, RAND_MAX);

    size_t processed_count = 0;
    *records_count = 0;

    Node** temp_array = records;
    for (size_t i = 0; i < batch_size; ++i) {
        if (!temp_array[i]) break;

        ++(*records_count);

        if ((processed_count + 1) % limit == 0 || !temp_array[i+1]) {
            size_t new_batch_size = processed_count >= batch_size ? processed_count * 2 : batch_size;
            Node** new_records = (Node**)realloc(records, new_batch_size * sizeof(Node*));
            if (!new_records) {
                for (size_t j = 0; j <= i; ++j) free(temp_array[j]);
                free(records);
                return NULL;
            }

            records = new_records;
            temp_array += batch_size;
        }

        processed_count++;
        temp_array[i] = temp_array[i]->next;
    }

    if (processed_count > 0) {
        size_t new_batch_size = processed_count >= batch_size ? processed_count * 2 : batch_size;
        Node** new_records = (Node**)realloc(records, new_batch_size * sizeof(Node*));
        if (!new_records) {
            for (size_t j = 0; j <= i; ++j) free(temp_array[j]);
            free(records);
            return NULL;
        }

        records = new_records;
        temp_array += batch_size;
    }

    return records;
}
