        *output_size = 0;
        return;
    }

    // Calculate required output buffer size
    size_t required_length = strlen(input) + 2;
    if (required_length > buffer_size) {
        // If the provided buffer is insufficient, allocate a temporary one and copy the result into it if possible
        SafeString temp_buffer;
        while (required_length > buffer_size) {
            buffer_size *= BUFFER_GROWTH_FACTOR;
        }

        temp_buffer.data = malloc(buffer_size);
        if (!temp_buffer.data) {
            printf("Error: Failed to allocate temporary buffer\n");
            *output_size = 0;
            return;
        }
        temp_buffer.capacity = buffer_size;
        temp_buffer.length = 0;

        pthread_mutex_lock(&mutex);
        if (strlen(input) + 2 <= buffer_size - temp_buffer.length) {
            // Copy data to the temporary buffer and append the '/' character
            memcpy(temp_buffer.data + temp_buffer.length, input, strlen(input));
            temp_buffer.length += strlen(input);
            temp_buffer.data[temp_buffer.length++] = '/';
        }
        pthread_mutex_unlock(&mutex);

        // Move the result to the output buffer and free the temporary one if needed
        if (buffer_size >= required_length) {
            memcpy(buffer, temp_buffer.data, required_length);
            *output_size = required_length;
