// Function to escape a single character by replacing backslashes with doubles and null characters with escape sequences
char *escape_char(const char c) {
    static const char *const escapes[] = {'\\', '\0'};
    static char escaped[3];

    if (c == '\\')
        strcpy(escaped, "\\\\");
    else if (c == '\0')
        sprintf(escaped, "\\0%o", c); // Octal representation of null character
    else {
        escaped[0] = c;
        escaped[1] = '\0';
    }

    return escaped;
}

