            for (i = copy_len; i < required_size; ++i) {
                temp_str->data[i] = (i == required_size - 1) ? '\0' : '/';
            }

            // Replace backslashes and null characters in the temporary buffer
            for (i = 0; i < temp_str->len; ++i) {
                if (temp_str->data[i] == '\\')
                    temp_str->data[i] = escape_char('\\')->[0];
                else if (temp_str->data[i] == '\0')
