char *truncate_string(const char *input, size_t limit, int truncate) {
    if (limit <= 0)
        return NULL;

    size_t input_len = strlen(input);

    if (input_len > limit && truncate) {
        if (input_len - limit >= 2)
            input += (input_len - limit - 1); // Truncate and move the pointer to the beginning of the truncated string
        else {
            // If the truncation leaves a single character, just return that character without the null terminator
            char *truncated = malloc(sizeof(char));
            if (truncated) {
                truncated[0] = *(input + (limit - 1));
                truncated[1] = '\0';
                return truncated;
            }
            // Return null in case of memory allocation failure
            return NULL;
        }
    }

    char *result = malloc(sizeof(char) * (limit + (input_len > limit ? 1 : 0)));
    if (!result) {
        // Return null in case of memory allocation failure
        return NULL;
    }

    memcpy(result, input, input_len <= limit ? input_len : limit);
    if (truncate && input_len > limit)
        result[limit] = '/';

    return result;
}
