// Custom synchronization mechanism using a per-buffer spinlock
typedef struct BufferLock {
    pthread_spinlock_t lock;
} BufferLock;

void buffer_lock_init(BufferLock* lock) {
    pthread_spin_init(&lock->lock, PTHREAD_PROCESS_PRIVATE);
}

void buffer_lock(BufferLock* lock) {
    pthread_spin_lock(&lock->lock);
}

void buffer_unlock(BufferLock* lock) {
    pthread_spin_unlock(&lock->lock);
}

// Custom memory pool for temporary buffers
typedef struct TempBuffer Pool;
struct TempBuffer {
    char* data;
    size_t capacity;
    size_t length;
};

Pool* temp_buffer_pool_create(size_t initial_size) {
    Pool* pool = malloc(sizeof(Pool));
    if (!pool) return NULL;

    pool->data = malloc(initial_size);
    if (!pool->data) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_size;
    pool->length = 0;
    return pool;
}

char* temp_buffer_get(Pool* pool) {
    if (pool->length >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        char* new_data = realloc(pool->data, new_capacity);
        if (!new_data) return NULL;
        pool->data = new_data;
        pool->capacity = new_capacity;
    }

    char* result = &pool->data[pool->length];
    pool->length += sizeof(char);
    return result;
}

void temp_buffer_put(Pool* pool, const char* buffer, size_t length) {
    memcpy(&pool->data[pool->length], buffer, length);
    pool->length += length;
}

void temp_buffer_destroy(Pool* pool) {
    free(pool->data);
    free(pool);
}

// Safe string append slash function
int safe_str_append_slash(char* input, size_t limit, char* output, size_t buffer_size, BufferLock* lock, Pool* temp_buffer_pool) {
    if (!input || !output) {
        fprintf(stderr, "Invalid input or output string\n");
        return -1;
    }

    if (strlen(input) > limit) return -2; // String exceeded size limit

    size_t required_size = strlen(input) + 1 + 1; // Include '/', null terminator

    if (required_size <= buffer_size) {
        strcat(output, "/");
    } else {
        char* temp_buffer = temp_buffer_get(temp_buffer_pool);
        if (!temp_buffer) return -3; // Insufficient memory for temporary buffer

        strcpy(temp_buffer, input);
        strcat(temp_buffer, "/");

        buffer_lock(lock);
        memcpy(output, temp_buffer, required_size);
        buffer_unlock(lock);
    }

    return 0; // Operation successful
}
