void dynamic_str_append_slash(char **buffer, size_t size, const char *input, const char *encoding, enum status_code *status) {
    struct buffer local_buf;
    iconv_t cd; // Character set conversion descriptor

    // Validate inputs and allocate resources if necessary
    if (!buffer || !input || !size || !encoding) {
        fprintf(stderr, "Error: Invalid input or size provided\n");
        *status = INVALID_INPUT;
        return;
    }

    pthread_mutex_lock(&g_lock);

    if (strlen(input) > size - 1) { // Check size limit
        *status = SIZE_LIMIT_EXCEEDED;
        pthread_mutex_unlock(&g_lock);
        return;
    }

    local_buf.length = strlen(input);
    if (!*buffer || local_buf.length + 2 > (*buffer)[0].capacity) { // Lazy evaluation for size determination
        local_buf.data = malloc((local_buf.length + 2) * sizeof(char));
        if (!local_buf.data) {
            *status = MEMORY_ALLOCATION_FAILURE;
            pthread_mutex_unlock(&g_lock);
            return;
        }
        local_buf.capacity = (local_buf.length + 2);
    } else {
        local_buf.data = (*buffer)[0].data;
        local_buf.capacity = (*buffer)[0].capacity;
    }

    // Copy input string, append slash and store result in output buffer or temporary one if required
    memcpy(local_buf.data, input, local_buf.length);
    local_buf.data[local_buf.length] = '/';
    local_buf.data[local_buf.length + 1] = '\0';

    // Character set conversion (if necessary) and update output buffer
    cd = iconv_open(encoding, "UTF-8");
    char *result = malloc((local_buf.length + 3) * sizeof(char));
    if (cd != (iconv_t)-1 && iconv(cd, &const char*[{local_buf.data}], &sizeof(char)*{(int)(local_buf.length)}, &result, &sizeof(char)*{(size_t*)&(*status)}) == (size_t) (local_buf.length + 3)) {
        free(local_buf.data);
        *buffer = realloc(*buffer, sizeof(struct buffer));
        (*buffer)[0].data = result;
        (*buffer)[0].length = local_buf.length + 2;
        (*buffer)[0].capacity = (local_buf.length + 2);
    } else {
        free(result);
        *status = ENCODING_FAILURE;
        pthread_mutex_unlock(&g_lock);
        return;
    }

    // Clean up and release resources
    iconv_close(cd);
    pthread_mutex_unlock(&g_lock);
}
