            // Copy the input string into the temporary buffer and append the '/' character
            strcpy(temp_buf, input);
            temp_buf[input_len] = '/';
            temp_buf[input_len + 1] = '\0';

            // Check if there is enough space left in the original buffer for the final copy
            if (buffer_size - needed_size <= 0) {
                safe_log("Error: Buffer too small to handle output with custom placeholder.");
                free(temp_buf);
                return NULL;
            }

            // Copy the result from the temporary buffer into the original buffer
            strcpy(output_buf, temp_buf);

            // Free the temporary buffer and return the modified output buffer
            free(temp_buf);
            return output_buf;
        } else {
            safe_log("Error: Buffer too small to handle output with custom placeholder. Using a custom placeholder for unavailable data.");
            snprintf(output_buf, buffer_size, "%.*s%s", input_len, input, custom_placeholder);
            return output_buf;
        }
    }

    // Append the '/' character and null terminator to the provided buffer
    strcpy(output_buf + input_len, "/");
    output_buf[input_len + 1] = '\0';

    return output_buf;
}
