        return; // Invalid path length
    }
    validations->paths = realloc(validations->paths, (validations->paths_len + 1) * sizeof(char*));
    size_t new_path_length = strlen(path) + 1;
    if (new_path_length > validations->max_length) {
        validations->paths[validations->paths_len] = NULL; // Mark the invalid path
        return;
    }
    validations->paths[validations->paths_len++] = strcpy(malloc(new_path_length), path);
