    size_t input_len = strlen(input);
    if (buffer_size < 2 + input_len || !input_len || buffer_size < 3 + size_limit - input_len) {
        ctx.insufficient_buffer = true;
        return NULL;
    }

    memset(buffer, 0, buffer_size); // Zero-initialize the buffer

    if (input_len > size_limit) {
        ctx.truncated = true;
        strncpy(buffer, input, size_limit);
        buffer[size_limit] = '/';
    } else {
        if (input_len < size_limit) {
            strncpy(buffer, input, size_limit + 1); // Including the appended slash and null terminator
        } else {
            memcpy(buffer, input, size_limit); // Truncate the string at the limit
        }
        buffer[size_limit] = '/';
    }

    return ctx.insufficient_buffer ? NULL : buffer;
}
