queue_t create_queue(size_t initial_capacity) {
    queue_t q = mmap(NULL, sizeof(queue_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (q == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    queue_init(q, initial_capacity);
    return q;
}

void queue_init(queue_t q, size_t initial_capacity) {
    q->batches = custom_allocator_calloc(initial_capacity, sizeof(struct batch));
    if (!q->batches) {
        perror("custom allocator calloc failed");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&q->lock, NULL);
    q->batch_count = 0;
    q->capacity = initial_capacity;
    q->allocator = custom_allocator_init();
    q->monitor = monitoring_init(q->allocator);
}

void enqueue(queue_t q, NFAPI_RX_FRAME_T frame) {
    struct batch *batch = NULL;
    pthread_mutex_lock(&q->lock);
    if (q->batch_count >= q->capacity) {
        // Handle backpressure here by expanding the capacity or dropping frames
    }
    if (!batch) {
        batch = &q->batches[q->batch_count++];
        batch->frames = custom_allocator_calloc(1, sizeof(NFAPI_RX_FRAME_T));
        if (!batch->frames) {
            perror("custom allocator calloc failed");
            pthread_mutex_unlock(&q->lock);
            exit(EXIT_FAILURE);
        }
        batch->capacity = 1;
    }
    validate_frame(frame); // Validate the frame structure
    batch->frames[batch->frame_count++] = frame;
    monitoring_update(q->monitor, q->allocator, 1, sizeof(NFAPI_RX_FRAME_T));
    pthread_mutex_unlock(&q->lock);
}

void dequeue_batch(queue_t q, struct batch **out_batch) {
    pthread_mutex_lock(&q->lock);
    if (q->batch_count > 0) {
        *out_batch = &q->batches[0];
        memmove(&q->batches[0], &q->batches[1], sizeof(struct batch) * (q->batch_count - 1));
        q->batch_count--;
    } else {
        *out_batch = NULL;
    }
    pthread_mutex_unlock(&q->lock);
}
