    buffer->frames = calloc(initial_capacity, sizeof(NFAPI_RX_FRAME_T));
    if (!buffer->frames) {
        free(buffer);
        return NULL;
    }

    buffer->capacity = initial_capacity;
    buffer->count = 0;
    buffer->mem_pool = custom_memory_allocator_init(); // Initialize custom memory allocator

    pthread_mutex_init(&buffer->lock, NULL);
