}

void nfapi_rx_buffer_push(NFAPI_RX_BUFFER* buffer, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&buffer->lock);

    if (buffer->count >= buffer->capacity) {
        void* new_mem = custom_memory_realloc(buffer->mem_pool, &buffer->frames, sizeof(NFAPI_RX_FRAME_T) * buffer->capacity * 2);
        if (!new_mem) {
            pthread_mutex_unlock(&buffer->lock);
            return;
        }

        buffer->frames = new_cast(NFAPI_RX_FRAME_T*, new_mem);
        buffer->capacity *= 2;
    }

    buffer->frames[buffer->count].pdu = *pdu;
    buffer->frames[buffer->count].crc_ind.crcflag = rand() % 2; // Set CRCFLAG randomly
