    buffer->frames[buffer->count].tag = generate_RX_UE_INFORMATION_TAG(); // Implement RX_UE_INFORMATION_TAG generation function

    buffer->count++;
    pthread_mutex_unlock(&buffer->lock);
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_rx_buffer_pop(NFAPI_RX_BUFFER* buffer) {
    pthread_mutex_lock(&buffer->lock);

    if (buffer->count == 0) {
        pthread_mutex_unlock(&buffer->lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = &buffer->frames[--buffer->count].pdu;
    pthread_mutex_unlock(&buffer->lock);
    return result;
}

