#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <time.h>
#include <pthread.h>
#include <yaml-cpp/yaml.h>

typedef struct {
    uint8_t header[6];
    uint8_t payload[1500];
    uint16_t crc_check_result;
} MAC_PACKET_T;

typedef struct {
    MAC_PACKET_T packet;
    bool crc_check_flag;
} FRAME_T;

struct memory_block {
    void* data;
    size_t size;
    struct memory_block* next;
};

struct mem_allocator {
    struct memory_block* free_list;
    pthread_mutex_t lock;
};

void init_mem_allocator(struct mem_allocator* alloc) {
    alloc->free_list = NULL;
    pthread_mutex_init(&alloc->lock, NULL);
}

void* mem_alloc(struct mem_allocator* alloc, size_t size) {
    void* result = NULL;
    struct memory_block* current = alloc->free_list;
    pthread_mutex_lock(&alloc->lock);
    if (current != NULL && current->size >= size) {
        result = current->data;
        current->size -= size;
        if (current->size == 0) {
            current->next = alloc->free_list;
            alloc->free_list = current;
        }
    } else {
        result = malloc(size);
    }
    pthread_mutex_unlock(&alloc->lock);
    return result;
}

void mem_free(struct mem_allocator* alloc, void* ptr) {
    struct memory_block* block = (struct memory_block*)malloc(sizeof(struct memory_block));
    block->data = ptr;
    block->size = strlen((char*)ptr) + 1;
    block->next = NULL;
    pthread_mutex_lock(&alloc->lock);
    if (alloc->free_list == NULL) {
        alloc->free_list = block;
    } else {
        struct memory_block* current = alloc->free_list;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = block;
    }
    pthread_mutex_unlock(&alloc->lock);
}

void init_frame_array(struct mem_allocator* alloc, FRAME_T** array, size_t capacity) {
    *array = (FRAME_T*)mem_alloc(alloc, capacity * sizeof(FRAME_T));
    for (size_t i = 0; i < capacity; ++i) {
        (*array)[i].crc_check_flag = rand() % 2 == 0;
    }
}

void push_frame(FRAME_T** array, size_t* len, struct mem_allocator* alloc) {
    FRAME_T* frame = (FRAME_T*)mem_alloc(alloc, sizeof(FRAME_T));
    frame->crc_check_flag = rand() % 2 == 0;
    memcpy(frame->payload, "Random Data", 10);
    (*len)++;
    *array = realloc(*array, (*len) * sizeof(FRAME_T));
    (*array)[*len - 1] = *frame;
}

void get_frame(FRAME_T** array, size_t* len, FRAME_T* result) {
    if (*len == 0) return;
    memcpy(result, &(*array)[*len - 1], sizeof(FRAME_T));
    (*len)--;
    *array = realloc(*array, *len * sizeof(FRAME_T));
}

void parse_config(const char* file, const char* interface, char ip_address[INET_ADDRSTRLEN], char netmask[INET_ADDRSTRLEN], char gateway[INET_ADDRSTRLEN]) {
    YAML::Node config = YAML::LoadFile(file);
    if (!config["interface"]) {
        return false;
    }
    YAML::const_iterator it = config["interface"].begin();
    if (it->second.Type() != YAML::NodeType::Scalar) {
        return false;
    }
    strncpy(interface, it->first.c_str(), INAMESIZE);
    it++;
    if (!it->second.IsDefined() || it->second.Type() != YAML::NodeType::Scalar) {
        return false;
    }
    strncpy(ip_address, it->first.c_str(), INET_ADDRSTRLEN);
    it++;
    if (!it->second.IsDefined() || it->second.Type() != YAML::NodeType::Scalar) {
        return false;
    }
    strncpy(netmask, it->first.c_str(), INET_ADDRSTRLEN);
    it++;
    if (!it->second.IsDefined() || it->second.Type() != YAML::NodeType::Scalar) {
        return false;
    }
    strncpy(gateway, it->first.c_str(), INET_ADDRSTRLEN);
    return inet_pton(AF_INET, ip_address, &((struct in6_addr*)&ip)) == 1 &&
           inet_pton(AF_INET, netmask, &((struct in6_addr*)&netmask)) == 1 &&
           inet_pton(AF_INET, gateway, &((struct in6_addr*)&gateway)) == 1;
}
