void init_hash_table(size_t size) {
    table = calloc(size, sizeof(NODE*));
    if (!table) exit(1);
    pthread_mutex_init(&table_mutex, NULL);

    for (size_t i = 0; i < size; ++i) table[i] = NULL;
}

void hash_function(unsigned int key) {
    return key % ARRAY_SIZE(table);
}

LOG_RECORD_T* new_log_record() {
    LOG_RECORD_T *record = custom_alloc(sizeof(LOG_RECORD_T));
    if (!record) exit(1);

    record->timestamp = time(NULL);
    record->log_level = RAND_RANGE(DEBUG, CRITICAL);
    record->message = strdup("");
    record->metadata = NULL;
    record->id = rand();
    record->priority_flag = rand() % 32;

    return record;
}

NODE* create_node(LOG_RECORD_T *record) {
    NODE *new_node = custom_alloc(sizeof(NODE));
    if (!new_node) exit(1);

    new_node->record = *record;
    new_node->next = NULL;
    return new_node;
}

void insert(LOG_RECORD_T *record, unsigned int key) {
    pthread_mutex_lock(&table_mutex);

    NODE **entry = &table[hash_function(key)];
    NODE *new_node = create_node(record);

    if (!*entry) {
        *entry = new_node;
    } else {
        NODE *current = *entry;
        while (current->next != NULL) current = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&table_mutex);
}

LOG_RECORD_T* find(unsigned int key) {
    pthread_mutex_lock(&table_mutex);

    NODE **entry = &table[hash_function(key)];
    NODE *current = *entry;

    while (current != NULL) {
        if (current->record.id == key) break;
        current = current->next;
    }

    pthread_mutex_unlock(&table_mutex);
    return current ? &current->record : NULL;
}

void delete(unsigned int key) {
    pthread_mutex_lock(&table_mutex);

    NODE **entry = &table[hash_function(key)];
    NODE *prev = NULL, *current = *entry;

    while (current != NULL) {
        if (current->record.id == key) {
            if (prev) prev->next = current->next;
            else *entry = current->next;
            custom_free(current);
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&table_mutex);
}

