void validate_rnti(const NFAPI_CRC_INDICATION_PDU_T* list, size_t len, size_t* current_rnti) {
    for (size_t i = 1; i < len; ++i) {
        if (*current_rnti == list[i].rnti) {
            fprintf(stderr, "RNTI is not unique\n");
            exit(EXIT_FAILURE);
        }
        *current_rnti = list[i].rnti;
    }
}

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu_list(size_t n, size_t max_entries) {
    if (n > max_entries) {
        fprintf(stderr, "Maximum number of entries exceeded\n");
        exit(EXIT_FAILURE);
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = safe_malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    size_t current_rnti = 0;
    for (size_t i = 0; i < n; ++i) {
        pdu_list[i].rxiitag = rand();
        pdu_list[i].rnti = current_rnti++;
        pdu_list[i].crcflag = (rand() % 2);
        validate_rnti(pdu_list, i + 1, &current_rnti);
    }

    return pdu_list;
}
