static SessionContext* session_pool = NULL;
static size_t max_sessions = 0;
static size_t pool_size = 0;
static pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void cleanup() {
    for (size_t i = 0; i < pool_size; ++i) {
        free(session_pool[i].peer_addr);
    }
    free(session_pool);
}

SessionContext* create_context() {
    SessionContext* ctx = malloc(sizeof(SessionContext));
    if (!ctx) {
        perror("Error allocating context");
        return NULL;
    }

    ctx->id = pool_size++;
    ctx->connected = false;
    pthread_mutex_init(&ctx->lock, NULL);

    return ctx;
}

SessionContext* find_or_create(const char* peer_addr) {
    if (!session_pool || max_sessions == pool_size) {
        // Handle expansion of the session pool here, consider using realloc or doubling the size
        return NULL;
    }

    pthread_mutex_lock(&pool_lock);
    for (size_t i = 0; i < pool_size; ++i) {
        if (!strcmp(session_pool[i].peer_addr, peer_addr)) {
            pthread_mutex_unlock(&pool_lock);
            return session_pool + i;
        }
    }

    SessionContext* ctx = create_context();
    strncpy(ctx->peer_addr, peer_addr, sizeof(ctx->peer_addr));
    pthread_mutex_unlock(&pool_lock);

    return ctx;
}

void destroy_context(SessionContext* ctx) {
    memset(ctx, 0, sizeof(*ctx));
    free(ctx->peer_addr);
    ctx->peer_addr = NULL;
}

void set_connected(SessionContext* ctx) {
    pthread_mutex_lock(&ctx->lock);
    ctx->connected = true;
    pthread_mutex_unlock(&ctx->lock);
}

bool get_connected(const SessionContext* ctx) {
    bool connected = false;
    pthread_mutex_lock(&ctx->lock);
    connected = ctx->connected;
    pthread_mutex_unlock(&ctx->lock);

    return connected;
}
