    if (current_count >= max_entries || find_email(profile->email)) {
        pthread_mutex_unlock(&lock);
        return -1; // Failed to add user profile
    }
    memcpy(&profile_pool[current_count++], profile, sizeof(UserProfile));
    pthread_mutex_unlock(&lock);
    return 0; // Successfully added user profile
}

int find_email(const char *email) {
    for (size_t i = 0; i < current_count; ++i) {
        if (strcmp(profile_pool[i].email, email) == 0) {
            return 1;
        }
    }
    return 0;
}

void cleanup() {
    pthread_mutex_lock(&lock);
    for (int i = current_count - 1; i >= 0; --i) {
        if (!profile_pool[i].status.ACTIVE) {
            memmove(&profile_pool[i], &profile_pool[i + 1], (current_count - i - 1) * sizeof(UserProfile));
        }
    }
    current_count = 0;
    pthread_mutex_unlock(&lock);
}

