void flushMemoryToDisk(const std::vector<LogEntry>& entriesToFlush);

int main() {
    ptree pt;
    read_xml(file_xml_parser(), "config.xml", pt); // Read configuration file

    auto start = system_clock::now();
    auto timeWindowEnd = start + seconds(pt.get<int>("TimeWindow"));

    std::map<std::string, std::pair<int, int>> resourceStats;
    std::vector<LogEntry> entriesToProcess;
    std::vector<LogEntry> entriesToFlush;

    for (const auto& logFilePath : pt.get_child("LogFiles")) {
        entriesToProcess = processLogFile(fs::path(logFilePath.data()));
        processAndStoreEntries(entriesToProcess, resourceStats, timeWindowEnd);
        entriesToFlush.insert(entriesToProcess.end(), entriesToProcess.begin(), entriesToProcess.end());

        if (entriesToProcess.size() >= pt.get<int>("MemoryFlushInterval")) {
            std::this_thread::sleep_for(seconds(1)); // Adjust the sleep interval as needed for performance optimization
            flushMemoryToDisk(std::move(entriesToFlush));
            entriesToFlush.clear();
        }
    }

    calculateAverageResponseTime(resourceStats);
    return 0;
}
