#include <jansson/jansson.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>

bool validate_oauth2_token(const char *json_str) {
    json_t *root, *access_token, *expires_in, *token_type, *refresh_token;
    int expires_in_int;
    bool has_refresh_token = false;

    root = json_loads(json_str, 0, NULL);
    if (!root || !json_is_object(root)) {
        return false;
    }

    access_token = json_object_get(root, "access_token");
    if (!access_token || !json_is_string(access_token) || json_strlen_b(access_token) <= 0 || strlen(json_string_value(access_token)) > 0 && isspace(json_string_value(access_token)[0])) {
        return false;
    }

    expires_in = json_object_get(root, "expires_in");
    if (!expires_in || !json_is_integer(expires_in)) {
        return false;
    }
    expires_in_int = json_integer_value(expires_in);
    if (expires_in_int <= 0 || expires_in_int >= 3600) {
        return false;
    }

    token_type = json_object_get(root, "token_type");
    if (!token_type || !json_is_string(token_type) || strcmp(json_string_value(token_type), "Bearer") != 0) {
        return false;
    }

    refresh_token = json_object_get_named(root, "refresh_token");
    if (refresh_token && json_is_string(refresh_token)) {
        has_refresh_token = true;
        if (strlen(json_string_value(refresh_token)) < 16 || strlen(json_string_value(refresh_token)) > 0 && !isalnum(json_string_value(refresh_token)[0])) {
            return false;
        }
    }

    // Check for unexpected fields
    json_t *field;
    json_object_foreach(root, field, key, val) {
        if (!strcmp(key, "access_token") && !strcmp(key, "expires_in") && !strcmp(key, "token_type")) continue;
        if (has_refresh_token && !strcmp(key, "refresh_token")) continue;

        if (!strcmp(key, json_string_value(access_token)) || !strcmp(key, json_string_value(expires_in)) || !strcmp(key, json_string_value(token_type)) || (has_refresh_token && !strcmp(key, json_string_value(refresh_token)))) {
            return false;
        }
    }

    json_decref(root);
    return true;
}
