using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Schema;
using System.Globalization;
using System.Data;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using System.Collections.Concurrent;

public class LogFileProcessor
{
    private readonly JsonSchema _schema;
    private ConcurrentDictionary<string, int> _errorCodes = new ConcurrentDictionary<string, int>();
    private ConcurrentDictionary<DateTime, long> _responseTimes = new ConcurrentDictionary<DateTime, long>();
    private long _totalErrors = 0;
    private long _totalResponseTime = 0;
    private DateTime _startDateTime;
    private DateTime _endDateTime;

    public LogFileProcessor(JsonSchema schema)
    {
        _schema = schema;
    }

    public void SetTimeRange(DateTime start, DateTime end)
    {
        _startDateTime = start;
        _endDateTime = end;
    }

    public async Task ProcessFilesAsync(IEnumerable<string> filePaths)
    {
        var tasks = filePaths.Select(ProcessFile).ToList();
        await Task.WhenAll(tasks);
        ExportMetrics();
    }

    private async Task ProcessFile(string filePath)
    {
        try
        {
            using (var reader = new StreamReader(filePath))
            {
                var jsonText = await reader.ReadToEndAsync();
                var logList = JsonConvert.DeserializeObject<List<dynamic>>(jsonText);

                foreach (var log in logList)
                {
                    if (!ValidateLog(log)) continue;

                    ParseAndAggregateMetrics(log);
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing file: {filePath}. {ex.Message}");
        }
    }

    private bool ValidateLog(dynamic log)
    {
        var validator = new JsonSchemaValidator(_schema);
        return validator.Validate(log);
    }

    private void ParseAndAggregateMetrics(dynamic log)
    {
        if (log["error"]?.Value<bool>() == true) IncrementErrorCount();
        if (log["responseTime"]?.Value<double>() > 0) AddResponseTime(DateTime.ParseExact(log["timestamp"].Value<string>(), "yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture), log["responseTime"].Value<double>());
        if (log["errorCode"]?.Value<string>() != null) _errorCodes[log["errorCode"].Value<string>()]++;
    }

    private void IncrementErrorCount()
    {
        Interlocked.Increment(ref _totalErrors);
    }

    private void AddResponseTime(DateTime date, double responseTime)
    {
        Interlocked.Add(ref _totalResponseTime, responseTime);
        _responseTimes[date] = _responseTimes.GetValueOrDefault(date) + responseTime;
    }

    private void ExportMetrics()
    {
        var data = new DataTable("LogAggregates");

        data.Columns.Add("ErrorCount", typeof(int));
        data.Columns.Add("TotalResponseTime", typeof(double));
        data.Columns.Add("AverageResponseTime", typeof(double));
        data.Columns.Add("TopErrorCodes", typeof(string));

        data.Rows.Add(_totalErrors, _totalResponseTime, _totalResponseTime / _errorCodes.Sum(), string.Join(", ", _errorCodes.OrderByDescending(k => k.Value).Select(k => k.Key)));

        foreach (var entry in _responseTimes)
        {
