    public double GetRandomDouble() => (double)_random.NextDouble() * (_maxValue - _minValue) + _minValue;

    public int GetRandomInt() => _random.Next(_minValue, _maxValue);

    public override string ToString() => $"Range: [{_minValue}, {_maxValue}]";
}
