let scriptCache = {};

function loadScript(src) {
    if (scriptCache[src]) return scriptCache[src];

    const script = document.createElement('script');
    script.onload = () => scriptCache[src] = script;
    script.src = src;
    document.head.appendChild(script);

    return script;
}
