#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int findLargestInteger(const char* filename, int maxElements) {
  FILE *file = fopen(filename, "r"); // open the file for reading
  if (!file) return -1; // exit if unable to open the file

  int numbers[maxElements];
  int count = 0;

  while (fscanf(file, "%d", &numbers[count]) == 1 && count < maxElements) {
    ++count;
  }

  fclose(file); // close the file

  if (!count) return -1; // exit if no numbers were read

  int largest = numbers[0];
  int index = 0;

  for (int i = 1; i < count; ++i) {
    if (numbers[i] > largest) {
      largest = numbers[i];
      index = i;
    }
  }

  return index; // return the index of the largest integer
}
