use std::env;
use std::fs::{self, File};
use std::io::{BufRead, BufWriter, Write};
use std::path::Path;
use std::sync::Mutex;
use log::*;

const APP_HOME: &str = "APP_HOME";
const ROOT_DIR: &str = "/opt/app/";

struct AppDirectoryInitializer {
    version: String,
    lock: Mutex<()>,
}

impl AppDirectoryInitializer {
    fn new(version: &str) -> Self {
        AppDirectoryInitializer {
            version: version.to_string(),
            lock: Mutex::new(()),
        }
    }

    fn validate_env(&self) -> Result<(), &'static str> {
        if env::var(APP_HOME).is_err() {
            return Err("APP_HOME is not set.");
        }
        let app_home = env::var(APP_HOME)?;
        if !Path::new(&app_home).exists() || !fs::read_dir(&app_home)? .next().is_some() {
            return Err("Specified APP_HOME directory does not exist or is not writable.");
        }
        Ok(())
    }

    fn create_directory(&self) -> Result<(), Box<dyn std::error::Error>> {
        let app_home = env::var(APP_HOME)?;
        let dir = format!("{}/{}", &app_home, self.version);
        if !Path::new(&dir).exists() {
            fs::create_dir_all(&dir)?;
        }
        Ok(())
    }

    fn init(&self) -> Result<(), Box<dyn std::error::Error>> {
        self.validate_env()?;
        let lock = self.lock.lock().unwrap();
        if !Path::new(&self.version()).exists() {
            self.create_directory()?
        }
        info!("Directory initialized successfully.");
        Ok(())
    }
}

impl Drop for AppDirectoryInitializer {
    fn drop(&mut self) {
        debug!("AppDirectoryInitializer is being dropped.");
    }
}
