using System.Numerics;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

public class DynamicValueGenerator {
    private readonly int _min, _max, _seed;
    private Random _rng = new Random(_seed);

    public DynamicValueGenerator(int min, int max, int seed) {
        _min = min;
        _max = max;
        _seed = seed;
    }

    public float NextFloat() => (float)_rng.NextDouble() * (_max - _min) + _min;

    public double NextDouble() => _rng.NextDouble() * (_max - _min) + _min;

    public int NextInt(bool inclusive = true) {
        if (!inclusive) return _rng.Next(_min, _max);
        return _rng.Next(_min, _max + 1).Clamp(_min, _max);
    }

    public override string ToString() => $"[{_min}, {_max}]";

    private Dictionary<string, KeyValuePair<int, int>> ReadConfig(string filename) {
        var config = new Dictionary<string, KeyValuePair<int, int>>();
        using (var file = File.OpenText(filename)) {
            var line = file.ReadLine();
            while ((line = file.ReadLine()) != null) {
                if (!Regex.IsMatch(line, @"^#.*$")) {
                    var parts = line.Split(' ');
                    if (parts.Length == 3) {
                        config[parts[0]] = new KeyValuePair<int, int>(int.Parse(parts[1]), int.Parse(parts[2]));
                    }
                }
            }
        }
        return config;
    }

    public void AdjustRange(string filename) {
        var config = ReadConfig(filename);
        if (config.ContainsKey("min")) _min = config["min"].Key;
        if (config.ContainsKey("max")) _max = config["max"].Key;
        if (_min > _max) throw new ArgumentException($"Configuration file contains invalid range: {_min} > {_max}");
    }

    public async Task ReadSequenceNumberAsync(string filename) {
        try {
            using (var reader = File.OpenText(filename)) {
                var line = await reader.ReadToEndAsync();
                if (line != null && !line.Trim().StartsWith("#")) {
                    int sequenceNumber;
                    if (int.TryParse(line, out sequenceNumber)) {
                        SequenceNumber = sequenceNumber + 1;
                    } else {
                        throw new ArgumentException($"Invalid file format: '{filename}'");
                    }
                }
            }
        } catch (Exception ex) {
            Console.WriteLine(ex);
        }
    }
}
```

