[' ```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_RX_FRAME_T;

typedef struct mem_block {
    size_t capacity;
    size_t used;
    NFAPI_RX_FRAME_T* data;
    pthread_mutex_t lock;
    void* custom_allocator;
} MemBlock;

MemBlock* create_mem_block(size_t initial_capacity, void* custom_allocator) {
    MemBlock* mem = malloc(sizeof(MemBlock));
    if (!mem) return NULL;
    mem->capacity = initial_capacity;
    mem->used = 0;
    mem->data = custom_allocator ? custom_allocator : malloc(initial_capacity * sizeof(NFAPI_RX_FRAME_T));
    if (!mem->data) {
        free(mem);
        return NULL;
    }
    pthread_mutex_init(&mem->lock, NULL);
    mem->custom_allocator = custom_allocator;
    return mem;
}

void destroy_mem_block(MemBlock* mem) {
    if (mem->custom_allocator) {
        free(mem->data);
    } else {
        free(mem);
    }
}

NFAPI_RX_FRAME_T* get_frame(MemBlock* mem, size_t idx) {
    pthread_mutex_lock(&mem->lock);
    NFAPI_RX_FRAME_T* frame = mem->data + idx;
    if (idx >= mem->capacity) {
        pthread_mutex_unlock(&mem->lock);
        return NULL;
    }
    mem->used++;
    pthread_mutex_unlock(&mem->lock);
    return frame;
}

void put_frame(MemBlock* mem, NFAPI_RX_FRAME_T* frame) {
    pthread_mutex_lock(&mem->lock);
    if (mem->used == mem->capacity) {
        pthread_mutex_unlock(&mem->lock);
        return;
    }
    memcpy(mem->data + mem->used, frame, sizeof(NFAPI_RX_FRAME_T));
    mem->used++;
    pthread_mutex_unlock(&mem->lock);
}

MemBlock* grow_mem_block(MemBlock* mem, size_t new_capacity) {
    if (new_capacity <= mem->capacity) return mem;
    NFAPI_RX_FRAME_T* new_data = realloc(mem->data, new_capacity * sizeof(NFAPI_RX_FRAME_T));
    if (!new_data) return NULL;
    mem->data = new_data;
    mem->capacity = new_capacity;
    return mem;
}
```

This code provides a custom memory block structure that manages an array of `NFAPI_RX_FRAME_T` structures. The memory block uses a pthread mutex lock for thread safety and can be extended with a custom allocator for efficient dynamic memory management. The functions provided allow for efficient insertion (put_frame) and retrieval (get_frame) operations, ensuring minimal memory overhead and optimal performance under concurrent access conditions. Additionally, the grow_mem_block function allows for automatic resizing of the array when needed to accommodate high-traffic environments.']

