#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdbool.h>
#include <iconv.h>
#include <pthread.h>
#include <sys/mman.h>
#include <time.h>

#define MAX_SIZE 4096
#define BUFFER_FACTOR 1.5

typedef struct {
    char *buf;
    size_t len;
    size_t cap;
    iconv_t ic;
} dynamic_str;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void dynamic_str_init(dynamic_str *ds) {
    ds->buf = malloc(MAX_SIZE);
    if (!ds->buf) {
        perror("malloc");
        return;
    }

    ds->len = 0;
    ds->cap = MAX_SIZE;
    ds->ic = iconv_open("UTF-8", NULL);
}

void dynamic_str_deinit(dynamic_str *ds) {
    if (ds->buf && ds->ic) {
        iconv(ds->ic, NULL, &ds->len, NULL, &ds->len, 0);
        iconv_close(ds->ic);
        free(ds->buf);
        ds->buf = NULL;
    }
}

void dynamic_str_append_slash(dynamic_str *ds, size_t limit) {
    pthread_mutex_lock(&mutex);

    if (!ds || !ds->buf || limit <= 0 || ds->cap - ds->len < 2) {
        fprintf(stderr, "Invalid arguments\n");
        goto exit;
    }

    size_t new_len = ds->len + 2;
    if (new_len > limit) {
        fprintf(stderr, "String length exceeds limit\n");
        goto exit;
    }

    if (ds->cap - new_len >= 2) {
        ds->buf[ds->len++] = '/';
        ds->buf[ds->len] = '\0';
        goto exit;
    }

    size_t required_size = ds->cap * BUFFER_FACTOR;
    if (required_size > limit) {
        fprintf(stderr, "Buffer size estimate exceeds limit\n");
        goto exit;
    }

    char *new_buf = realloc(ds->buf, required_size);
    if (!new_buf) {
        perror("realloc");
        goto exit;
    }

    ds->buf = new_buf;
    ds->cap = required_size;

exit:
    pthread_mutex_unlock(&mutex);
}

int main() {
    dynamic_str str;
    dynamic_str_init(&str);
    dynamic_str_append_slash(&str, 10);
    printf("%s\n", str.buf);
    dynamic_str_deinit(&str);
    return 0;
}
```

