['```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;
using System.Text;

public class WebPageUpdater
{
    private const int BufferSize = 1000; // Adjust as needed for optimal performance and memory usage
    private const string LoggingApiUrl = "https://logging-service.com/api/log"; // Replace with your logging service URL

    public async Task RunAsync(string[] args)
    {
        if (!args.Any())
        {
            Console.WriteLine("Usage: WebPageUpdater [inputFile1] [inputFile2] ... [outputFormat]");
            return;
        }

        var format = args.LastOrDefault() ?? "plain";
        var inputFiles = args.Take(args.Length - 1).ToArray();

        var processedLinesPerFile = new ConcurrentDictionary<string, int>();
        var errorsEncountered = new ConcurrentBag<Exception>();

        ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };

        await Parallel.ForEachAsync(inputFiles, options, async (file, token) =>
        {
            try
            {
                using var reader = new StreamReader(file);
                var lines = await ProcessFileAsync(reader, BufferSize).ConfigureAwait(false);

                processedLinesPerFile[Path.GetFileName(file)] += lines.Count;

                if (format == "formatted")
                    await LogFormattedLinesAsync(lines, file).ConfigureAwait(false);
                else
                    await LogPlainLinesAsync(lines).ConfigureAwait(false);
            }
            catch (Exception ex)
            {
                errorsEncountered.Add(ex);
            }
        });

        Console.WriteLine($"Processed lines:\n{string.Join("\n", processedLinesPerFile.Select(kv => $"{kv.Key}: {kv.Value}"))}");

        if (errorsEncountered.Any())
        {
            Console.WriteLine("Errors encountered:");
            foreach (var ex in errorsEncountered)
                Console.WriteLine(ex.Message);
        }
    }

    private async Task<List<string>> ProcessFileAsync(StreamReader reader, int bufferSize)
    {
        var lines = new List<string>();
        var lineBuffer = new StringBuilder();

        while (!reader.EndOfStream)
        {
            lineBuffer.Clear();

            for (int i = 0; i < bufferSize && !reader.EndOfStream; ++i)
                lineBuffer.AppendLine(await reader.ReadLineAsync());

            lines.AddRange(lineBuffer.ToString().TrimEnd('\r').Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries));
        }

        return lines;
    }

    private async Task LogPlainLinesAsync(IEnumerable<string> lines)
    {
        await SendLogRequestAsync(JsonConvert.SerializeObject(lines), "plain");
    }

    private async Task LogFormattedLinesAsync(IEnumerable<string> lines, string file)
    {
        var formattedLines = lines.Select((line, index) => $"{index + 1}: {line}").ToList();
        await SendLogRequestAsync(JsonConvert.SerializeObject(formattedLines), "formatted", file);
    }

    private async Task SendLogRequestAsync(string data, string format, string file = null)
    {
        var httpClient = new HttpClient();
        var request = new HttpRequestMessage(HttpMethod.Post, LoggingApiUrl);
        request.Content = new StringContent(data, Encoding.UTF8, "application/json");

        try
        {
            using (var response = await httpClient.SendAsync(request))
            {
                response.EnsureSuccessStatusCode();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to log data from '{file}': {ex.Message}");
        }
    }
}
```
