void load_and_invoke(const char *library_path, const char *symbol_name, const char *log_file) {
    void *handle;
    (*typeof(symbol_name)) target_function;
    struct timeval start, end;
    long usec_start, usec_end;
    long memory_peak = 0;
    FILE *log_fp;

    gettimeofday(&start, NULL);
    usec_start = start.tv_usec;

    handle = dlopen(library_path, RTLD_NOW | RTLD_LOCAL);
    if (!handle) {
        fprintf(stderr, "Error: Could not open library %s\n", library_path);
        return;
    }

    target_function = dlsym(handle, symbol_name);
    if ((*typeof(target_function))target_function == NULL) {
        fprintf(stderr, "Error: Function %s not found in library %s\n", symbol_name, library_path);
        dlclose(handle);
        return;
    }

    log_fp = fopen(log_file, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", log_file);
        dlclose(handle);
        return;
    }

    // Limit execution time
    gettimeofday(&end, NULL);
    usec_end = end.tv_usec;
    if (usec_end - usec_start > MAX_EXECUTION_TIME) {
        fprintf(stderr, "Error: Execution time limit exceeded\n");
        fputs("Execution interrupted.", log_fp);
        fclose(log_fp);
        dlclose(handle);
        return;
    }

    // Limit memory usage
    rlim_t memory_limit = MAX_MEMORY_USAGE * 1024 * 1024;
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    if (usage.ru_maxrss > memory_limit) {
        fprintf(stderr, "Error: Memory usage limit exceeded\n");
        fputs("Execution interrupted.", log_fp);
        fclose(log_fp);
        dlclose(handle);
        return;
    }

    // Invoke the function and log the result
    void *result = target_function();
    fprintf(log_fp, "Result: %p\n", result);
    fclose(log_fp);

    // Unload the library
    dlclose(handle);
}
