#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int *numbers;
    size_t num_elements;
    char max_filename_length;
    char *existing_files; // array of existing filenames to check for conflicts
    size_t num_existing_files;
} InputData;

// Function to generate a unique filename
char* generate_unique_filename(const char *base, const char *extension) {
    time_t now = time(NULL);
    struct tm tm = *localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y%m%dT%H%M%S", &tm);

    // Generate a random number of appropriate length for the system being used
    char rand_str[64];
    snprintf(rand_str, sizeof(rand_str), "%llu", rand());

    size_t new_filename_len = strlen(base) + strlen(timestamp) + strlen(rand_str) + strlen(extension);
    if (new_filename_len > max_filename_length) {
        fprintf(stderr, "Error: New filename exceeds maximum length.\n");
        return NULL;
    }

    char *new_filename = malloc(new_filename_len + 1); // extra space for null terminator
    if (!new_filename) {
        perror("malloc");
        return NULL;
    }

    snprintf(new_filename, new_filename_len, "%s%s%s%s", base, timestamp, rand_str, extension);

    // Check for conflicts with existing filenames
    int conflict = 0;
    size_t i;
    for (i = 0; i < num_existing_files && !conflict; ++i) {
        if (!strcmp(new_filename, existing_files[i])) {
            conflict = 1;
        }
    }

    if (conflict) {
        // Increment random number and try again
        snprintf(rand_str, sizeof(rand_str), "%llu", rand());
        strcpy(new_filename, generate_unique_filename(base, extension));
    }

    return new_filename;
}

// Function to read integers from standard input or a file specified by the user
void read_integers(InputData *data) {
    char line[256];
    FILE *fp = stdin;

    if (data->num_elements > 0 && data->num_elements <= 10000) { // handle non-empty lists first
        fp = fopen(data->numbers[0], "r");
        if (!fp) {
            perror("fopen");
            fprintf(stderr, "Error: Unable to open file.\n");
            return;
        }
    }

    size_t index = 0;
    while (fgets(line, sizeof(line), fp)) {
        char *endptr;
        long int number = strtol(line, &endptr, 10);
        if (*endptr || number < INT32_MIN || number > INT32_MAX) {
            fprintf(stderr, "Error: Invalid integer value.\n");
            return;
        }

        data->numbers[index] = number;
        ++index;
    }

    if (data->num_elements > index) {
        fprintf(stderr, "No integers provided.\n");
    } else {
        qsort(data->numbers, index, sizeof(long int), (int (*)(const void *, const void *))compare);
        printf("Largest integer: %ld at index: %zu\n", data->numbers[index - 1], index - 1);
    }

    fclose(fp);
}

// Comparison function for qsort
int compare(const void *a, const void *b) {
    return (*(const long int *)a - *(const long int *)b);
}

// Entry point of the program
int main() {
    // Initialize input data structure
    InputData data = {};
    data.max_filename_length = 255;
    data.num_existing_files = 1000; // adjust as needed
    data.existing_files = malloc(data.num_existing_files * sizeof(char *));
    if (!data.existing_files) {
        perror("malloc");
        return EXIT_FAILURE;
    }

    // Populate existing_files array with example filenames (adjust as needed)
    size_t i;
    for (i = 0; i < data.num_existing_files; ++i) {
        snprintf(data.existing_files[i], sizeof(data.existing_files[i]), "example_file%ld.ext", i);
    }

    // Read integers from input or file
    read_integers(&data);

    // Generate unique filename using the largest integer and a specified extension
    char *filename = generate_unique_filename("largest_integer.", ".txt");
    if (!filename) {
        return EXIT_FAILURE;
    }

    // Log the execution path, including the file being processed and the largest integer
    log_event(filename);

    // Perform additional operations using the unique filename here...

    free(filename);
    free(data.existing_files);
    return EXIT_SUCCESS;
}
