#include <iostream>
#include <string>
#include <vector>
#include <filesystem>
#include <fstream>
#include <chrono>
#include <random>
#include <sha256.h> // Include a non-standard hash library

namespace fs = std::filesystem;

// Function to generate a unique identifier for each filename
std::string generate_unique_identifier(const std::string& directory, const std::string& original_filename) {
    // Hash the directory contents as a starting point for uniqueness
    sha256::Hash hash = sha256::hash(directory);

    // Create an md5 string from the hash
    std::stringstream ss;
    ss << std::hex << hash.to_bytes().data();
    auto hashString = ss.str();
    if (hashString.length() > 32) {
        hashString.resize(32); // Make sure it's the right size
    }

    // Generate a random number to append to the filename
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, numeric_limits<unsigned int>::max());
    unsigned int randomNumber = dis(gen);

    // Combine the hash and random number to create a unique identifier
    auto id = hashString + std::to_string(randomNumber);

    return id;
}

// Function to rename files in a directory
void rename_files(const std::string& directory, const std::vector<std::string>& filenames) {
    // Create a new directory for the renamed files
    fs::path newDirectory(directory + "/renamed");
    if (fs::exists(newDirectory)) {
        fs::remove_all(newDirectory);
    }
    fs::create_directories(newDirectory);

    // Loop through each filename and rename the file
    for (const auto& filename : filenames) {
        // Validate that the resulting filename is valid
        std::regex pattern("([\\/:*?\"<>|]);"); // Pattern to avoid invalid characters
        if (std::regex_search(filename, pattern)) {
            std::cerr << "Invalid character found in file: " << filename << std::endl;
            continue;
        }

        auto id = generate_unique_identifier(directory, filename);
        auto extensionIndex = filename.find_last_of('.');

        // If the filename has an extension, update it with a timestamp and the unique identifier
        if (extensionIndex != std::string::npos) {
            auto extension = filename.substr(extensionIndex);
            auto baseName = filename.substr(0, extensionIndex);

            std::time_t now = std::time(nullptr);
            std::tm timeStruct;
            localtime_s(&now, &timeStruct);
            auto timestamp = std::put_time(&timeStruct, "%Y%m%dT%H%M%S");

            // Concatenate the base name, timestamp, unique identifier, and file extension
            auto newFilename = baseName + timestamp + id + extension;

            fs::path filePath(directory + "/" + filename);
            fs::path newFilePath(newDirectory / newFilename);

            // Rename the file, handle potential race conditions if necessary
            try {
                std::rename(filePath.c_str(), newFilePath.c_str());
            } catch (const std::exception& e) {
                std::cerr << "Error renaming file: " << filename << ", Error message: " << e.what() << std::endl;
            }
        } else {
            // If the filename has no extension, add a default one and follow the same process as above
            auto newFilename = filename + "_" + id + ".txt";
            fs::path filePath(directory + "/" + filename);
            fs::path newFilePath(newDirectory / newFilename);

            try {
                std::rename(filePath.c_str(), newFilePath.c_str());
            } catch (const std::exception& e) {
                std::cerr << "Error renaming file: " << filename << ", Error message: " << e.what() << std::endl;
            }
        }
    }
}
