struct array_ctx {
    NFAPI_RX_FRAME_T *data;
    size_t capacity;
    size_t length;
    sem_t lock;
    sem_t memory_sem; // Semaphore for managing memory usage
};

void my_malloc(size_t size, struct array_ctx *ctx) {
    if (ctx->memory_sem < size) {
        sem_post(&ctx->memory_sem);
        sleep(1); // Yield CPU to allow other threads to reclaim memory
        if (ctx->memory_sem < size) {
            MY_LOG_ERROR("Out of memory, maximum limit reached");
            exit(EXIT_FAILURE);
        }
    }
    ctx->data = realloc(ctx->data, sizeof(NFAPI_RX_FRAME_T) * (ctx->capacity + size));
    if (!ctx->data) {
        MY_LOG_ERROR("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    ctx->capacity += size;
}

void my_free(struct array_ctx *ctx, size_t index, size_t size) {
    if (index + size > ctx->length) {
        MY_LOG_ERROR("Invalid memory index or size");
        exit(EXIT_FAILURE);
    }
    memmove(ctx->data + index, ctx->data + index + size, sizeof(NFAPI_RX_FRAME_T) * (ctx->length - (index + size)));
    ctx->length -= size;
    sem_post(&ctx->memory_sem);
}

void array_lock(struct array_ctx *ctx) {
    sem_wait(&ctx->lock);
}

void array_unlock(struct array_ctx *ctx) {
    sem_post(&ctx->lock);
}

bool array_insert(struct array_ctx *ctx, const NFAPI_RX_FRAME_T *frame) {
