        return false;
    }

    my_malloc(1, ctx);
    *((NFAPI_RX_FRAME_T *) (ctx->data + ctx->length)) = *frame;
    ++ctx->length;
    array_unlock(ctx);

    // Update memory usage and log successful insertion
    sem_post(&ctx->memory_sem);
    MY_LOG_INFO("Successful insertion");
    return true;
}

