    if (memory_block->used + 1 >= max_frames_per_batch) {
        process_batch();
    }

    memory_block->data[memory_block->used] = frame;
    memory_block->used++;

    if (memory_block->used > memory_limit) {
        reclaim_memory();
    }

    pthread_mutex_unlock(&memory_block->mutex);
}

