    filter_images(dir, images, MAX_IMAGES);

    struct timespec backoff = {0, 500 * NANOSECONDS_PER_MILLISECOND};
    sem_init(resource_sem, 0, max_parallel);
    shared_memory = mmap(NULL, shared_memory_len, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);

    for (int i = 0; i < MAX_IMAGES; ++i) {
        if (!images[i].filename[0]) break; // End loop when no more images to process

        sem_wait(resource_sem);

        // If the resource pool is overloaded, apply a backoff strategy.
        if (time_after((struct timespec *) &backoff, get_monotonic_timespec())) {
            backoff.tv_sec += 2;
            nanosleep(&backoff, NULL);
        }

        // Process the image concurrently
        ImageMeta *image = images + i;
        pthread_t thread_id;
        pthread_create(&thread_id, NULL, process_image, image);
    }

    for (int i = 0; i < MAX_IMAGES; ++i) {
        pthread_join(thread_id, NULL);
    }

    sem_destroy(resource_sem);
    munmap(shared_memory, shared_memory_len);
}
