void connection_list_init() {
    head = mmap(NULL, sizeof(struct memory_block), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (head == MAP_FAILED) {
        log_event(ERROR, "Failed to initialize connection list memory");
        return;
    }

    sem_init(&mutex, 1, 1); // Initializing the lock with ownership by the first thread
}

void *get_next_memory_block() {
    struct memory_block *current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    TCP_CONNECTION_T **connections_ptr = &current->connections;
    size_t capacity = (*connections_ptr == NULL) ? batch_size : 0;
    *connections_ptr = custom_malloc(capacity * sizeof(TCP_CONNECTION_T));
    current->capacity = capacity;
    current->next = (struct memory_block *)custom_malloc(sizeof(struct memory_block));
    struct memory_block *new_block = current->next;
    new_block->capacity = 0;
    new_block->connections = NULL;
    new_block->next = NULL;
    return new_block;
}

void insert(TCP_CONNECTION_T connection) {
    sem_wait(&mutex);
    void *memory_block = get_next_memory_block();
    memcpy((TCP_CONNECTION_T *)((char *)memory_block + memory_block->capacity * sizeof(TCP_CONNECTION_T)), &connection, sizeof(TCP_CONNECTION_T));
    sem_post(&mutex);
}

void delete(CONNECTION_ID id) {
    sem_wait(&mutex);
    // Implement efficient traversal and deletion logic here
    sem_post(&mutex);
}

