Java: Disjoint Pairs in an Integer Array using Union-Find (Union-Find data structure, assuming no duplicate elements)

```java
import java.util.*;

public class DisjointPairs {
    private int[] parent;
    private int[] rank;

    public DisjointPairs(int[] arr) {
        Arrays.sort(arr);
        this.parent = new int[arr.length];
        this.rank = new int[arr.length];
        for (int i = 0; i < arr.length; i++) {
            parent[i] = i;
            rank[i] = 1;
        }
    }

    public int find(int x) {
        if (x != parent[x]) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
                rank[rootY] += rank[rootX];
            } else {
                parent[rootY] = rootX;
                rank[rootX] += rank[rootY];
            }
        }
    }

    public int disjointPairsCount() {
        int count = 0;
        for (int i = 0; i < parent.length; i++) {
            count += parent[i] == i ? 1 : 0;
        }
        return count * (count - 1) / 2;
    }

    public void findDisjointPairs(int[] arr) {
        DisjointPairs dp = new DisjointPairs(arr);
        for (int i = 0; i < arr.length - 1; i++) {
            long startTime = System.currentTimeMillis();
            int x = dp.find(arr[i]);
            int y = dp.find(arr[i + 1]);
            if (x != y) {
                dp.union(x, y);
            }
            long duration = System.currentTimeMillis() - startTime;
            System.out.printf("Pair (%d, %d): %d ms\n", arr[i], arr[i + 1], duration);
        }
    }
}
