typedef struct {
    char path[256];
    char *passphrase;
    unsigned int salt;
    unsigned int iterations;
    unsigned int key_size;
    char new_dir[256];
} Parameters;

void derive_key(const unsigned char *passphrase, size_t length,
                const unsigned char salt[], unsigned int iterations,
                unsigned char *derived_key, unsigned char iv[AES_BLOCK_SIZE],
                unsigned int key_size);

int is_valid_filename(const char *filename);
void format_timestamp(char timestamp[20]);
void generate_unique_identifier(char base[], const char *extension,
                                char unique_id[], size_t max_length);
void create_new_filepath(const char *old_path, const char *new_dir,
                         char new_filepath[256]);
int safe_mkdir(char path[256], mode_t mode);
void move_file(const char *old_path, const char *new_path);

int rename_files_in_directory(Parameters *params) {
    DIR *dir;
    struct dirent *entry;
    AES_KEY aes_ctx;
    unsigned char iv[AES_BLOCK_SIZE];
    unsigned char derived_key[AES_BLOCK_SIZE + AES_IV_LENGTH];
    unsigned int salt = params->salt;
    unsigned int iterations = params->iterations;
    char passphrase[strlen(params->passphrase)];
    memcpy(passphrase, params->passphrase, strlen(params->passphrase));

    derive_key((const unsigned char *)passphrase, strlen(passphrase),
               (const unsigned char *)&salt, iterations,
               derived_key, iv, params->key_size);

    dir = opendir(params->path);
    if (!dir) {
        perror("opendir");
        return 1;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    while ((entry = readdir(dir)) != NULL) {
        // Skip "." and ".." entries
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char filename[256];
        snprintf(filename, sizeof(filename), "%s/%s", params->path, entry->d_name);
        if (!is_valid_filename(entry->d_name)) {
            printf("Invalid filename: %s\n", entry->d_name);
            continue;
        }

        struct stat st;
        if (stat(filename, &st) == -1) {
            perror("stat");
            continue;
        }

        // Handle symbolic links and directories recursively
        if (S_ISLNK(st.st_mode)) {
            char linkpath[256];
            readlink(filename, linkpath, sizeof(linkpath));
            rename_files_in_directory(params);
        } else if (S_ISDIR(st.st_mode)) {
            // Recursively process directory contents
        } else {
            char extension[4];
            strcpy(extension, strchr(entry->d_name, '.') + 1);

            char timestamp[20];
            format_timestamp(timestamp);
            char unique_id[28]; // Maximum length for ISO 8601 + extension + random number
            generate_unique_identifier(extension, entry->d_name, unique_id, sizeof(unique_id));

            char new_filename[256];
            snprintf(new_filename, sizeof(new_filename), "%s/%s%s", params->new_dir, unique_id, extension);

            // Check if the resulting filename is valid for the operating system
            if (!is_valid_filename(new_filename)) {
                printf("Invalid new filename: %s\n", new_filename);
                continue;
            }

            create_new_dir(params->new_dir, mode);
            move_file(filename, new_filename);
        }
    }

    pthread_mutex_destroy(&mutex);
    closedir(dir);
    return 0;
}

// ... other functions implementation (is_valid_filename, format_timestamp, generate_unique_identifier, create_new_dir, move_file)
