#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <time.h>
#include <unistd.h>
#include <netinet/in.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <json-c/json.h>
#include <openssl/rand.h>

typedef struct {
    time_t timestamp;
    int level;
    char *message;
    void *metadata;
} LOG_RECORD_T;

typedef struct HASH_NODE {
    LOG_RECORD_T record;
    struct HASH_NODE *next;
    uint32_t id;
} HASH_NODE;

typedef struct {
    HASH_NODE **table;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} HASH_MAP;

HASH_MAP hashmap_init(size_t size) {
    HASH_MAP map = {0};
    map.table = calloc((size_t)(size + 1), sizeof(void*));
    map.size = size;
    return map;
}

uint32_t hash_func(const char *str) {
    uint32_t hash = 5381;
    int c;
    while ((c = *str++))
        hash = (hash << 5) + hash + c; /* hash * 33 + c */
    return hash % map.size;
}

void hashmap_insert(HASH_MAP *map, LOG_RECORD_T record) {
    HASH_NODE **node_ptr = &(map->table[hash_func(record.message)]);
    HASH_NODE *node = malloc(sizeof(HASH_NODE));
    node->record = record;
    node->id = rand();

    pthread_mutex_lock(&map->lock);
    if (!*node_ptr) {
        *node_ptr = node;
    } else {
        HASH_NODE *n = *node_ptr;
        while (n->next) n = n->next;
        n->next = node;
    }
    pthread_mutex_unlock(&map->lock);
}

LOG_RECORD_T* hashmap_get(HASH_MAP *map, const char *message) {
    HASH_NODE **node_ptr = &(map->table[hash_func(message)]);
    HASH_NODE *n = *node_ptr;
    LOG_RECORD_T *record = NULL;
    pthread_mutex_lock(&map->lock);
    while (n) {
        if (!strcmp(n->record.message, message)) {
            record = &n->record;
            break;
        }
        n = n->next;
    }
    pthread_mutex_unlock(&map->lock);
    return record;
