// Function to dynamically generate a unique filename
char* generate_unique_filename(const char* base_name, const char* file_type) {
    time_t now = time(NULL);
    struct tm tm = *localtime(&now);
    char timestamp[19]; // ISO 8601 format: YYYY-MM-DDTHH:MM:SS
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    int random_number = rand() % 1000000;
    char unique_filename[256];

    // Make sure the base name and file type are concatenated properly, regardless of their length
    size_t base_name_len = strlen(base_name);
    size_t file_type_len = strlen(file_type);
    snprintf(unique_filename, sizeof(unique_filename), "%s%s_%s%d", base_name, timestamp, file_type, random_number);

    // Check for existing files and generate a new filename if necessary
    struct stat file_stat;
    if (stat(unique_filename, &file_stat) == 0 && S_ISREG(file_stat.st_mode)) {
        int i = 1;
        char* ptr = unique_filename + base_name_len + timestamp_len + file_type_len - 4; // Skip extension
        while (stat(unique_filename, &file_stat) == 0 && S_ISREG(file_stat.st_mode)) {
            i++;
            snprintf(ptr + 3, 4, "%d", i);
            ptr = unique_filename + base_name_len + timestamp_len + file_type_len - 4 + 4 * i; // Increment extension number
        }
    }

    return unique_filename;
}

