    }

    private Task ProcessFileTask(Action<string> action) => Task.Factory.StartNew(action, CancellationToken.None, TaskCreationOptions.LongRunning, TaskScheduler.Default);

    private void ProcessFile(string filePath)
    {
        var extension = Path.GetExtension(filePath).ToLower();
        var formatHandler = _configuration[extension] as Func<StreamReader, FileFormatBase>;
        if (formatHandler == null)
        {
            _logger.LogError($"Unsupported file format: {extension}");
            return;
