        using (var reader = new StreamReader(filePath))
        {
            var formatter = formatHandler(reader);
            Parallel.ForEach(Partitioner.Create(0, reader.BaseStream.Length), processChunk =>
            {
                ProcessLines(formatter, processChunk, _lineBuffers);
            }, options => { });
        }
    }

    private void ProcessLines(FileFormatBase formatter, Range<long> chunk, ConcurrentQueue<string>[] lineBuffers)
    {
        var lines = new List<string>();
        while (chunk.Start < formatter.Stream.BaseStream.Length && formatter.ReadLineInto(lines))
        {
            if (_dataValidator.Validate(lines[0]))
                ProcessLine(_dataTransformer, lines);
            else
                _logger.LogError($"Invalid data detected: {lines[0]}");

            lines.Clear();
            Interlocked.Decrement(ref chunk.Length);
        }
    }

