using System.Threading.Tasks;
using static System.Console;

public class WebPageUpdater
{
    private const int BufferSize = 1024;
    private const int MaxLinesPerFile = 10000;
    private const int MemoryLimitForIpAddress = 64;
    private const int TimeoutInMilliseconds = 5000;
    private static readonly ConcurrentDictionary<string, SemaphoreSlim> _dnsResolutionLock = new();
    private static readonly HashSet<string> _dnsWhitelist = new HashSet<string> { "google.com", "microsoft.com" }; // customize this as needed

    public async Task Run(string[] args)
    {
        if (args.Length == 0)
            PrintUsage();

        var outputFormat = GetOutputFormat(args);
        ParallelOptions options = new() { MaxDegreeOfParallelism = Environment.ProcessorCount };
        var filesToProcess = new List<FileInfo>();

        foreach (var arg in args)
        {
            if (File.Exists(arg))
                filesToProcess.Add(new FileInfo(arg));
            else
                WriteLine($"Warning: '{arg}' does not appear to be a valid file path.");
        }

        var processedLines = new ConcurrentDictionary<string, long>();
        var errorsEncountered = new ConcurrentBag<Exception>();

        await Task.WhenAll(filesToProcess.Select(file => ProcessFileAsync(file, outputFormat, processedLines, errorsEncountered, options)));

        PrintResults(processedLines, errorsEncountered);
    }

    private static void PrintUsage()
    {
        WriteLine("Usage: WebPageUpdater [input_file1] [input_file2] ... [-o output_format]");
        WriteLine("-o output_format (optional): Specify the desired output format. Available options are 'default', 'with-line-numbers', or 'truncate-long-lines'.");
    }

    private static string GetOutputFormat(string[] args) =>
        args.Length > 1 && ("-o".Equals(args[0], StringComparison.OrdinalIgnoreCase) ? args[1] : "default");

    private async Task ProcessFileAsync(FileInfo file, string outputFormat, ConcurrentDictionary<string, long> processedLines, ConcurrentBag<Exception> errorsEncountered, ParallelOptions options)
    {
        try
        {
            var streamReader = new StreamReader(file.OpenRead(), Encoding.UTF8);
            var lines = new ConcurrentQueue<string>();

            await Task.Run(() =>
            {
                string line;
                while ((line = streamReader.ReadLine()) != null)
                {
                    lines.Enqueue(line);
                    if (lines.Count >= MaxLinesPerFile)
                        ProcessBufferedLines(lines, outputFormat, processedLines);
                }
            }, options);

            if (lines.Any())
                ProcessBufferedLines(lines, outputFormat, processedLines);
        }
        catch (Exception ex)
        {
            errorsEncountered.Add(ex);
        }
    }

    private void PrintResults(ConcurrentDictionary<string, long> processedLines, ConcurrentBag<Exception> errorsEncountered)
    {
        WriteLine("Summary:");
        foreach (var file in processedLines.Keys)
            WriteLine($"{file}: {processedLines[file]} lines processed");

        if (errorsEncountered.Count > 0)
        {
            WriteLine("\nErrors encountered:");
            foreach (var error in errorsEncountered)
                WriteLine(error);
        }
    }

    private ulong[] resolve_hostname(string hostname)
    {
        var ipAddress = new byte[16]; // IPv4 and IPv6 have the same size
        using var client = new WebClient();

        try
        {
            if (_dnsWhitelist.Contains(hostname))
                return null;

            var dnsLock = _dnsResolutionLock.GetOrAdd(hostname, new SemaphoreSlim(1));
            dnsLock.Wait();

            try
            {
                client.DownloadDataTaskAsync(new Uri("http://" + hostname)).ContinueWith(task =>
                {
                    if (task.IsFaulted)
                        return;

                    Buffer.BlockCopy(task.Result, 0, ipAddress, 0, Math.Min(ipAddress.Length, task.Result.Length));
                });
            }
            finally
            {
                dnsLock.Release();
            }
        }
        catch (Exception ex)
        {
            return new ulong[] { 0 }; // Return an invalid IPv4 address to indicate error
        }

        Array.Reverse(ipAddress); // IPv6 addresses are written in reverse byte order

        if (ipAddress.Length > MemoryLimitForIpAddress)
            throw new InvalidOperationException("IP address exceeded the specified memory allocation limit.");

        return ipAddress;
    }
}
