using BenchmarkDotNet.Running;

namespace EnhancedRandomValueGenerator
{
    public struct Range
    {
        public float Min;
        public float Max;
        public bool IsInclusive => Min <= Max - 1f;
    }

    public class EnhancedRandomValueGenerator
    {
        private readonly Range _range;
        private readonly int _precisionBits;
        private ConcurrentDictionary<long, object> _cache = new ConcurrentDictionary<long, object>();
        private Func<double> _randomFloatGenerator;
        private Func<int> _randomIntGenerator;

        public EnhancedRandomValueGenerator(float min, float max) : this(min, max, 64) { }

        public EnhancedRandomValueGenerator(float min, float max, int precisionBits)
        {
            if (min > max) throw new RangeException($"Min ({min}) cannot exceed Max ({max}).");
            _range = new Range { Min = min, Max = max };
            _precisionBits = Math.Max(1, precisionBits);
            _randomFloatGenerator = GenerateRandomFloat;
            _randomIntGenerator = GenerateRandomInteger;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private double GenerateRandomFloat()
        {
            // Implement your random float generator logic here.
            // For this example, we will use the Math.Rand() method.
            var r = Math.Rand();
            return (_range.IsInclusive) ? (_range.Max * r) : ((_range.Max - _range.Min) * r + _range.Min);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private int GenerateRandomInteger()
        {
            // Implement your random integer generator logic here.
            // For this example, we will use the generated double value and Math.Floor() method.
            return (int)Math.Floor(_randomFloatGenerator());
        }

        public float GetRandomFloat(bool isInclusive = true)
        {
            if (isInclusive) return _range.Min + (_randomFloatGenerator() * (_range.Max - _range.Min));
            return _range.Min + (_randomFloatGenerator() * (_range.Max - _range.Min - 1)) + 1;
        }

