        (*measurements + i)->thresholds[1] = -80;
        (*measurements + i)->thresholds[2] = 60;
        (*measurements + i)->thresholds[3] = 5;
        // Initialize dynamic threshold adjustment to a reasonable value
        (*measurements + i)->dynamic_threshold = 1.0f;
    }
}

void optimize_threshold(LTE_RRC_CME* measurement, float signal_quality) {
    measurement->dynamic_threshold += (signal_quality - measurement->dynamic_threshold) * 0.05f;
    // Ensure dynamic threshold adjustment is within acceptable range
    if(measurement->dynamic_threshold < -1.0f)
        measurement->dynamic_threshold = -1.0f;
    else if(measurement->dynamic_threshold > 2.0f)
        measurement->dynamic_threshold = 2.0f;
