typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ELEMENTS 10000

static NFAPI_CRC_INDICATION_PDU_T* array = NULL;
static size_t current_size = 0;
static const size_t chunk_size = (MAX_ELEMENTS + 9) / 10;
static pthread_mutex_t mutex;
static bool validate_required = false;
static size_t operation_counter = 0;

void init() {
    if (array) free(array);
    array = calloc(chunk_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    current_size = chunk_size;
    pthread_mutex_init(&mutex, NULL);
}

void push(const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!array) init();

    operation_counter++;
    if (operation_counter % 100 == 0) validate_required = true;

    if (current_size == chunk_size) {
        chunk_size += chunk_size;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(array, chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            printf("Memory allocation failed\n");
            return;
        }
        array = new_array;
    }

    pthread_mutex_lock(&mutex);
    memcpy(&array[current_size], data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    current_size++;
    pthread_mutex_unlock(&mutex);
}

void validate() {
    if (!validate_required) return;
    validate_required = false;

    size_t i, j;
    for (i = 0; i < current_size - 1; ++i) {
        for (j = i + 1; j < current_size; ++j) {
            if (array[i].crc_indication.crc != calculate_crc(&array[i], j - i)) break;
        }
        if (j == current_size) { // All CRC flags match, no need to continue
            break;
        }
    }

    if (i == current_size - 1) { // Validation passed
        printf("CRC validation successful\n");
    } else { // Validation failed
        printf("CRC validation failed at index %zu\n", i);
        // Handle validation failure here, e.g., reset CRC flags or log the issue
    }
}

bool calculate_crc(const NFAPI_CRC_INDICATION_PDU_T* data, size_t len) {
    unsigned long crc = 0xFFFFFFFF;

    for (size_t i = 0; i < len; ++i) {
        const uint8_t* ptr = (const uint8_t*)data + i * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        crc = crc32(crc, ptr, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    return !!(crc & 0x0000FFFF);
}
```

