        $this->charSet = $charSet;
        $this->db = $db;
        $this->hasher = hash($hashAlgorithm);
    }

    public function generateRandomString($length) {
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->charSet[rand(0, strlen($this->charSet)-1)];
        }
        return $this->ensureUniqueAndHash($randomString);
    }

    private function ensureUniqueAndHash($randomString) {
        $existingHashes = $this->getExistingHashes();
        if (in_array($this->hash($randomString), $existingHashes)) {
            throw new Exception("Collision detected: {$randomString} is not unique.");
        }
        $this->saveHash($this->hash($randomString));
        return $randomString;
    }

    private function getExistingHashes() {
        $stmt = $this->db->query('SELECT hash FROM random_strings');
        $hashes = [];
        foreach ($stmt as $row) {
            $hashes[] = $row['hash'];
        }
        return $hashes;
    }

    private function saveHash($hash) {
        $stmt = $this->db->prepare('INSERT INTO random_strings (hash) VALUES (:hash) ON DUPLICATE KEY UPDATE id = id');
        $stmt->bindParam(':hash', $hash);
        $stmt->execute();
    }

    private function hash($string) {
        return call_user_func($this->hasher, $string);
