typedef struct {
    size_t capacity;
    size_t length;
    wchar_t *data;
} wstr;

struct buffer_lock {
    pthread_mutex_t lock;
};

void buffer_init(struct buffer_lock *lock) {
    pthread_mutex_init(&lock->lock, NULL);
}

void buffer_lock(struct buffer_lock *lock) {
    pthread_mutex_lock(&lock->lock);
}

void buffer_unlock(struct buffer_lock *lock) {
    pthread_mutex_unlock(&lock->lock);
}

wstr *buffer_alloc(size_t size) {
    wstr *result = malloc(sizeof(wstr));
    result->capacity = size;
    result->length = 0;
    result->data = malloc(sizeof(wchar_t) * size);
    return result;
}

void buffer_free(wstr **buffer) {
    if (*buffer) {
        free((*buffer)->data);
        free(*buffer);
        *buffer = NULL;
    }
}

// Performs the necessary validation and checks for size limitation before modifying the filename and appending a slash.
wstr* modify_filename_and_safe_str_append_slash(const wchar_t *filename, size_t max_length, const wchar_t *number_format, const wchar_t *file_type, struct buffer_lock *output_buffer_lock, wstr *output_buffer) {
    // Validation checks
    if (!filename || !number_format || !file_type || !output_buffer) {
        printf("Warning: One or more input parameters are NULL.\n");
        return NULL;
    }

    size_t filename_length = wcslen(filename);
    if (filename_length > max_length) {
        printf("Error: Filename exceeds specified maximum length.\n");
        return NULL;
    }

    buffer_lock(output_buffer_lock);

    // Calculate the required size for the output buffer
    size_t output_size = filename_length + 1 + wcslen(number_format) + wcslen(file_type) + 2;

    if (output_buffer->capacity < output_size) {
        output_buffer->capacity *= 2;
        output_buffer->data = realloc(output_buffer->data, sizeof(wchar_t) * output_buffer->capacity);
    }

    size_t required_size = output_size + 1; // Including the null terminator for the final string

    if (required_size > output_buffer->capacity) {
        wstr *temp_buffer = buffer_alloc(required_size);
        memcpy(temp_buffer->data, output_buffer->data, output_buffer->length * sizeof(wchar_t));
        free(output_buffer);
        output_buffer = temp_buffer;
    }

    // Modify the filename extension and append a slash
    size_t number_digits = 0;
    const wchar_t *dot = wcsrchr(filename, L'.');
    if (dot) {
        number_digits = wcstol(dot + 1, NULL, 10);
    }

    wsprintf(output_buffer->data, L"%.*s%s%.*ls/%s", filename_length, filename, number_format, number_digits, file_type);
    output_buffer->length = wcslen(output_buffer->data);

    buffer_unlock(output_buffer_lock);

    return output_buffer;
}
```

