typedef struct {
    char *filename;
    size_t digits;
    const char *filetype;
    size_t size_limit;
    char *buffer;
    size_t buffer_size;
    const char *encoding;
    pthread_mutex_t mutex;
} Parameters;

int is_valid(Parameters *params) {
    if (!params || !params->filename || !params->filetype || !params->buffer || !params->encoding) {
        printf("Warning: invalid parameters\n");
        return NULL;
    }
    if (strlen(params->filename) >= params->size_limit) {
        printf("Error: filename size limit exceeded\n");
        return NULL;
    }
    return 1;
}

char *modify_filename_and_safe_str_append_slash(Parameters *params, size_t *out_len) {
    if (!is_valid(params)) {
        return NULL;
    }

    size_t required_size = strlen(params->filename) + 2 + params->digits + 1 + uchar_strlen(params->filetype); // Account for the filename, /, digits, . (if needed), filetype, and null terminator
    if (required_size > params->buffer_size) {
        char *temp_buf = malloc(required_size);
        if (!temp_buf) {
            printf("Error: memory allocation failed\n");
            return NULL;
        }
        pthread_mutex_lock(&params->mutex);
        strcpy(temp_buf, params->filename);
        pthread_mutex_unlock(&params->mutex);

        // Extract digits and file type from the filename
        size_t i = strlen(params->filename) - 1;
        size_t j = 0;
        while (i >= 0 && isdigit((unsigned char)params->filename[i])) {
            params->digits = params->filename[i--] - '0';
            ++j;
        }
        if (!j) {
            params->digits = 0;
        }
        const char *dot = strchr(params->filename, '.');
        if (dot && i < dot - params->filename) {
            params->filetype = dot + 1;
        } else {
            params->filetype = params->filetype;
        }

        // Append the necessary characters to temp_buf and calculate the final size
        required_size += uchar_strlen(params->filename + i + 1) + (params->digits > 0 ? (params->digits + 1) : 0);
        if (params->digits && params->filetype[0] != '.') {
            required_size += 1; // Account for the . character
        }
        required_size += uchar_strlen(params->filetype);
        if (required_size > params->buffer_size) {
            printf("Error: memory allocation failed\n");
            free(temp_buf);
            return NULL;
        }

        // Modify the filename and append a / character to temp_buf
        pthread_mutex_lock(&params->mutex);
        sprintf(temp_buf + strlen(temp_buf), "%s.%*.*s/%s", "", params->digits, params->digits, params->filename + i + 1, params->filetype);
        temp_buf[required_size] = '\0';
        pthread_mutex_unlock(&params->mutex);

        // Copy the result into the provided buffer if sufficient size
        if (required_size <= params->buffer_size) {
            strcpy(params->buffer, temp_buf);
        } else {
            // Use a local temporary buffer to perform the operation and then copy the result into the provided buffer
            memcpy(params->buffer, temp_buf, params->buffer_size - 1);
            params->buffer[params->buffer_size - 1] = '\0';
        }

        if (out_len) {
            *out_len = required_size;
        }
    } else {
        // Append a / character to the provided buffer if not already present
        if (params->buffer[strlen(params->buffer) - 1] != '/') {
            strcat(params->buffer, "/");
        }
    }

    return params->buffer;
}
