// Thread-safe function to rename a file, with retry mechanism and email notification on failure
int rename_file(const char *directory, const char *filename) {
    int retries = 3;
    while (retries > 0) {
        // Construct new filename
        char new_filename[MAX_FILENAME_LENGTH];
        strcpy(new_filename, filename);
        time_t timestamp = time(NULL);
        snprintf(&new_filename[strlen(new_filename)], sizeof(new_filename) - strlen(new_filename), "%06d%03d%s", (int)timestamp, generate_random(), strchr(new_filename, '.') + 1);

        // Check if the new filename is valid and does not exceed the maximum length
        if (!is_valid_filename(new_filename)) {
            retries--;
            continue;
        }

        struct stat st;
        stat(new_filename, &st);
        if (st.st_size == 0) { // File does not exist yet, continue with rename operation
            break;
        } else if (strcmp(new_filename, filename) == 0) { // New filename is the same as the old one, retry with a different random number
            retries--;
            continue;
        } else { // Another file with the new name exists in the directory, retry with a different random number and timestamp
            retries--;
