}

// Function to recursively check for duplicate filenames in a directory and update them if necessary
void check_and_update_filenames(const char *directory) {
    DIR *dir = opendir(directory);
    if (!dir) return; // Failed to open the directory, return

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
