// Custom synchronization mechanism using dynamic thread pooling
struct lock {
    pthread_mutex_t mtx;
    size_t active;
};

void init_lock(struct lock *l) {
    pthread_mutex_init(&l->mtx, NULL);
    l->active = 0;
}

void acquire_lock(struct lock *l) {
    while (pthread_mutex_trylock(&l->mtx) != 0 && ++l->active < MAX_ACTIVE_THREADS) {
        sched_yield();
    }
}

void release_lock(struct lock *l) {
    if (--l->active == 0)
        pthread_mutex_unlock(&l->mtx);
}

