bool renameFileInDirectory(const char *dir) {
    if (dir == NULL) dir = cwd;
    getcwd(cwd, sizeof(cwd));
    chdir(dir);

    sem_init(&sem, 0, 1); // Initialize semaphore to allow only one process to rename files at a time
    pthread_t checker_tid;
    void* checker_result = pthread_create(&checker_tid, NULL, checkDuplicates, dir);

    if (checker_result != 0) {
        perror("Error creating checker thread");
        return false;
    }

    DIR *dirp = opendir(".");
