        generateUniqueName(filename, filename);
        success &= renameFile(filename, entry->d_name);
        logRenameAttempt(entry->d_name, filename, success);
    }

    closedir(dirp);
    pthread_join(checker_tid, NULL);
    sem_destroy(&sem);

    chdir(cwd); // Return to the original working directory
    return success;
}

