#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>
#include <pthread.h>
#include <zip.h>

typedef struct {
    char path[1024];
    int level;
} CompressData;

void *compress_file(void *data) {
    CompressData *c_data = (CompressData *) data;
    zipFile zf = zipOpen((const char *) c_data->path, ZIP_DEFLATED, NULL);
    if (!zf) return NULL;

    struct stat st;
    stat(c_data->path, &st);
    char zfile_name[1024];
    snprintf(zfile_name, sizeof(zfile_name), "%s-%ld-%d.zip", c_data->path, (long int) time(NULL), rand() % 10000);

    zip_int64_t offset = 0;
    zip_source_t *src = zipSourceFileInZip(zf, c_data->path, &offset, 0, NULL, 0);
    if (zipAddFileToZip(zf, "", src, c_data->level) != ZIP_OK) {
        fprintf(stderr, "Error compressing file: %s\n", c_data->path);
        zipClose(zf, NULL);
        return NULL;
    }
    zipSourceFree(&src);

    if (zipClose(zf, NULL) != ZIP_OK) {
        fprintf(stderr, "Error closing archive: %s\n", c_data->path);
        return NULL;
    }

    FILE *out = fopen(zfile_name, "wb");
    if (!out) {
        fprintf(stderr, "Error opening output file: %s\n", zfile_name);
        return NULL;
    }

    zipOpenInFile(zf, out, 0);
    fclose(out);
    return zfile_name;
}

int compress_folder(const char *folder_path, int level) {
    DIR *dir = opendir(folder_path);
    if (!dir) {
        fprintf(stderr, "Error opening directory: %s\n", folder_path);
        return 0;
    }

    struct dirent *entry;
    pthread_t threads[128];
    CompressData data[128];
    int num_threads = 0, i;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
        snprintf(data[num_threads].path, sizeof(data[num_threads].path), "%s/%s", folder_path, entry->d_name);
        data[num_threads].level = level;

        if (entry->d_type == DT_DIR) {
            if (!compress_folder(data[num_threads].path, level)) goto cleanup;
        } else {
            pthread_create(&threads[num_threads], NULL, compress_file, &data[num_threads]);
            num_threads++;
            if (num_threads == 128) {
                for (i = 0; i < num_threads; ++i) {
                    pthread_join(threads[i], NULL);
                }
                num_threads = 0;
            }
        }
    }
    if (num_threads > 0) {
        for (; num_threads < 128; ++num_threads) {
            pthread_join(threads[num_threads], NULL);
        }
    }

cleanup:
    closedir(dir);

    char archive_name[1024];
    snprintf(archive_name, sizeof(archive_name), "%s.zip", folder_path);
    zipFile zf = zipOpen((const char *) archive_name, ZIP_DEFLATED, NULL);

    struct stat st;
    stat(folder_path, &st);
    if (st.st_size > (1UL << 38)) { // 4GB
        char *base = strdup(folder_path), *name;
        size_t len = strlen(base);
        while (st.st_size > (1UL << 38)) {
            name = &base[len - 1];
            while (*name != '/') name--;
            snprintf(&base[len], sizeof(base) - len, "%s%d", name == base ? "0" : "", (int)(st.st_size / (1UL << 38)));
            st.st_size -= (1UL << 38);
            zipOpenInFile(zf, archive_name, ZIP_FL_ENC_LF | ZIP_FL_ENC_UTF8);
            if (rename(base, archive_name) != 0) {
                fprintf(stderr, "Error renaming intermediate archive: %s\n", base);
                zipClose(zf, NULL);
                return 0;
            }
            stat(folder_path, &st);
        }
        free(base);
    }

    if (zipOpenInFile(zf, archive_name, ZIP_FL_ENC_LF | ZIP_FL_ENC_UTF8) != 0) {
        fprintf(stderr, "Error opening final archive: %s\n", archive_name);
        zipClose(zf, NULL);
        return 0;
    }

    DIR *dir2 = opendir(folder_path);
    if (!dir2) {
        fprintf(stderr, "Error reopening directory: %s\n", folder_path);
        zipClose(zf, NULL);
        return 0;
    }

    entry = readdir(dir2);
    while (entry != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) entry = readdir(dir2); continue;

        char path[1024];
        snprintf(path, sizeof(path), "%s/%s", folder_path, entry->d_name);
        if (entry->d_type == DT_DIR) {
            zipFile zf2 = zipOpen((const char *) path, ZIP_DEFLATED, NULL);
            if (zipOpenInFile(zf2, path, 0) != 0) {
                fprintf(stderr, "Error opening subdirectory: %s\n", path);
                zipClose(zf2, NULL);
            } else {
                zipAddFolderToZip(zf, "");
                zipClose(zf2, NULL);
            }
        } else {
            struct stat st;
            stat(path, &st);
            char zfile_name[1024];
            snprintf(zfile_name, sizeof(zfile_name), "%s-%ld-%d.zip", path, (long int) time(NULL), rand() % 10000);
            zipOpenInFile(zf, zfile_name, ZIP_FL_ENC_LF | ZIP_FL_ENC_UTF8);
            if (rename(path, zfile_name) != 0) {
                fprintf(stderr, "Error renaming file: %s\n", path);
            }
        }

        entry = readdir(dir2);
    }

    closedir(dir2);
    zipClose(zf, NULL);
    return 1;
}
