        now = int(time.time())
        elapsed_since_last_call = now - kwargs['last_called']
        if elapsed_since_last_call < 1 / 100:
            time.sleep(1 / 100 - elapsed_since_last_call)
        result = func(*args, **kwargs)
        kwargs['last_called'] = now
