// Function to generate a unique filename with timestamp, random number and specified file type
std::string generateUniqueFilename(const std::string& baseName) {
    auto now = std::chrono::system_clock::now().time_since_epoch().count();
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 9);
    std::string randomNumber = "";
    for (size_t i = 0; i < 6; ++i) {
        randomNumber += std::to_string(dis(gen));
    }

    auto extPosition = baseName.find_last_of('.');
    auto basePath = baseName.substr(0, extPosition);
    auto extension = baseName.substr(extPosition);
    std::time_t nowTime = std::chrono::system_clock::to_time_t(now);
    auto timestamp = ctime(&nowTime);
    timestamp[7] = '\0';  // Remove newline character

    return basePath + "_" + timestamp + "_" + randomNumber + extension;
}

