#define MAX_NAME_LEN 254 // Max filename length (excluding null terminator)

void update_extension(char *filename) {
    char extension[10];
    int len = strlen(filename), dot_index = -1, num_digits = 0;

    for (int i = len - 1; i >= 0; --i) {
        if (filename[i] == '.') {
            dot_index = i;
            break;
        }
    }

    // Check for valid extension
    if (dot_index != -1 && (len - dot_index - 1) < MAX_EXT_LEN) {
        strncpy(extension, filename + dot_index + 1, sizeof(extension));
        extension[sizeof(extension) - 1] = '\0';

        // Determine file type based on the last two characters of the extension
        if (strcmp(extension, "txt") == 0 || strcmp(extension, "TXT") == 0) {
            num_digits = 4;
        } else if (strcmp(extension, "pdf") == 0 || strcmp(extension, "PDF") == 0) {
            num_digits = 6;
        } else { // Default to txt files
            num_digits = 4;
        }

        // Generate new filename
        char new_filename[MAX_NAME_LEN];
        sprintf(new_filename, "%.*s%d%s", dot_index + 1, filename, num_digits, extension);
        strncpy(extension, new_filename + strlen(new_filename) - sizeof(extension), sizeof(extension));
        extension[sizeof(extension) - 1] = '\0';
        strcat(new_filename, extension);
    }

    // Ensure the new filename does not exceed MAX_NAME_LEN and is thread-safe
    if (strlen(new_filename) > MAX_NAME_LEN) {
        int truncate_len = MAX_NAME_LEN - dot_index - 1;
        strncpy(new_filename, filename, truncate_len);
        new_filename[truncate_len] = '\0';
    }
}
```

