#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    PHYSICAL_LAYER_FRAME_INFO info;
    uint32_t id; // Sequence number for debugging purposes
} LTEPHY_RX_BUFFER_T;

struct buffer_manager {
    LTEPHY_RX_BUFFER_T *buffers;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t condition;
};

void init_buffer_manager(struct buffer_manager *manager, size_t N) {
    if (N == 0 || N > 50000) {
        return; // Return without initializing in case of invalid input
    }

    manager->buffers = malloc(N * sizeof(LTEPHY_RX_BUFFER_T));
    manager->capacity = N;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->condition, NULL);
}

void push(struct buffer_manager *manager, LTEPHY_RX_BUFFER_T buffer) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count == manager->capacity) {
        pthread_cond_wait(&manager->condition, &manager->mutex);
    }

    if (manager->count >= manager->capacity) { // Handle overflow case gracefully
        free(manager->buffers);
        init_buffer_manager(manager, manager->capacity * 2);
    }

    manager->buffers[manager->count] = buffer;
    manager->count++;

    pthread_mutex_unlock(&manager->mutex);
}

size_t pop(struct buffer_manager *manager) {
    size_t index;
    LTEPHY_RX_BUFFER_T buffer;

    pthread_mutex_lock(&manager->mutex);

    if (manager->count == 0) {
        pthread_cond_wait(&manager->condition, &manager->mutex);
    }

    index = manager->count - 1;
    buffer = manager->buffers[index];
    manager->count--;

    pthread_mutex_unlock(&manager->mutex);

    return index;
}

// Function to periodically check ECF values and log discrepancies without affecting the ongoing operations.
void check_ecf(struct buffer_manager *manager) {
    size_t i, last_check = 0;

    while (true) {
        time_t now = time(NULL);

        if ((now - last_check) > 200) { // Check every 200th operation
            last_check = now;

            for (i = 0; i < manager->count && i % 200 == 0; ++i) {
                LTEPHY_RX_BUFFER_T buffer = pop(manager); // Get the buffer from the manager

                if (!is_ecf_consistent(buffer.info)) { // Check if ECF is consistent
                    log_discrepancy(buffer.id, &buffer.info); // Log the discrepancy
                }

                push(manager, buffer); // Return the buffer to the manager
            }
        }
    }
}

// Implement the required functions: is_ecf_consistent() and log_discrepancy().
```

