#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>

#define BUFFER_SIZE 1024

typedef struct FileMap {
    void *ptr;
    size_t length;
} FileMap;

void replaceSubstring(const char *filename, const char *oldSubstr, const char *newSubstr) {
    FILE *file = fopen(filename, "r+");
    if (!file) return;

    // Map the entire file into memory to allow in-place editing.
    FileMap map = mmap(NULL, getSize(filename), PROT_READ | PROT_WRITE, MAP_PRIVATE, fileno(file), 0);
    if (map.ptr == MAP_FAILED) {
        fclose(file);
        return;
    }

    char *data = map.ptr;
    size_t dataLength = map.length;

    // Process the file line by line, buffering in chunks to handle large files efficiently.
    char buffer[BUFFER_SIZE];
    char *bufferStart, *bufferEnd;
    size_t bytesRead;

    for (bufferStart = data, bufferEnd = bufferStart + BUFFER_SIZE; dataLength > 0; ) {
        if (dataLength >= BUFFER_SIZE) {
            bytesRead = BUFFER_SIZE;
        } else {
            bytesRead = dataLength;
            dataLength = 0;
        }

        memcpy(buffer, bufferStart, bytesRead);
        bufferStart += bytesRead;
        dataLength -= bytesRead;

        char *pos = buffer;
        while ((pos = strstr(pos, oldSubstr)) != NULL) {
            size_t oldLen = strlen(oldSubstr);
            size_t newLen = strlen(newSubstr);

            // Replace the substring and update the position pointers.
            memmove(pos + newLen, pos + oldLen, bufferEnd - pos - oldLen);
            memcpy(pos, newSubstr, newLen);
        }

        if (bufferStart != buffer) {
            // Write modified chunks back to the file if they were split across multiple iterations.
            size_t written = fwrite(buffer, 1, bytesRead, file);
            if (written != bytesRead) {
                perror("Error writing to file");
                munmap(map.ptr, map.length);
                fclose(file);
                return;
            }
        }
    }

    // Ensure the final buffer is written completely before unmapping the memory.
    size_t written = fwrite(bufferStart, 1, dataLength, file);
    if (written != dataLength) {
        perror("Error writing to file");
        munmap(map.ptr, map.length);
        fclose(file);
        return;
    }

    munmap(map.ptr, map.length);
    fclose(file);
}

size_t getSize(const char *filename) {
    struct stat st;
    if (stat(filename, &st) < 0) return -1;
    return st.st_size;
}
