    int sockfd;
    struct addrinfo hints, *res;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(socket_address, NULL, &hints, &res);
    if (status != 0) {
        log_entry("getaddrinfo: %s", gai_strerror(status));
        return;
    }

    sockfd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (sockfd == -1) {
        log_entry("socket: %s", strerror(errno));
        freeaddrinfo(res);
        return;
    }

    if (connect(sockfd, res->ai_addr, res->ai_addrlen) == -1) {
        log_entry("connect: %s", strerror(errno));
        close(sockfd);
        freeaddrinfo(res);
        return;
    }

    read_integers(sockfd > STDIN_FILENO ? "/dev/fd/{}" : "stdin", list, num_elements);

    freeaddrinfo(res);
    close(sockfd);
}
