    int fieldCount = 0;
    int batchSize = 1024; // Adjust this value as needed

    while (std::getline(inputFile, line)) {
        if (cancel) break;

        std::istringstream iss(line);
        std::vector<std::string> fields(std::istream_iterator<std::string>(iss), {});

        for (size_t i = 0; i < fields.size() - 1; ++i) {
            std::unique_ptr<char[], decltype(&operator delete[])> fieldPtr(const_cast<char*>(fields[i].c_str()), operator delete[]);
            octree.insert(fieldPtr.get(), fieldCount++);
        }

        int lastTwoFields = (fields.size() >= 2) ? ((fields.back().empty() ? 0 : std::stoi(fields.back())) + fields[fields.size() - 2].empty() ? 0 : std::stoi(fields[fields.size() - 2])) / 2 : 0;
        double avgField = lastTwoFields * 1.0 / (fields.size() - 1);

        for (size_t i = fieldCount - 2; i < fieldCount; ++i) {
            auto it = stringCache.find(line + ',' + fields[i]);
            if (it == stringCache.end()) {
                std::unique_ptr<char[], decltype(&operator delete[])> cachedFieldPtr(const_cast<char*>(it->first.c_str()), operator delete[]);
                octree.insert(cachedFieldPtr.get(), i);
                stringCache[it->first] = i;
            }
        }

        std::cout << line.substr(0, line.size() - fields.back().size()) + std::to_string(avgField) << std::endl;
    }
}
