typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void populate_list(NFAPI_CRC_INDICATION_PDU_T** list, size_t* len) {
    char filename[256];
    *len = 0;
    scanf("%s", filename);
    if (!strcmp(filename, "exit")) return;

    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    *len = 0;
    NFAPI_CRC_INDICATION_PDU_T* current_node = NULL;
    NFAPI_CRC_INDICATION_PDU_T* new_node;
    int num;

    while (fscanf(file, "%d", &num) == 1) {
        (*len)++;
        if ((*len) > 10000) {
            fprintf(stderr, "Error: List size exceeded the limit of 10,000 elements.\n");
            break;
        }

        new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            perror("Error allocating memory");
            break;
        }

        new_node->RX_UE_INFORMATION_TAG = 0x12345678;
        new_node->RNTI = rand() % 0xFFFF;
        new_node->CRC_INDICATION_REL8_TAG = rand() % 0xFFFF;
        new_node->CRCFLAG = rand() % 2 == 0;

        if (!current_node) {
            current_node = new_node;
            continue;
        }

        new_node->next = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node->next) {
            perror("Error allocating memory");
            break;
        }

        current_node->next->prev = current_node;
        current_node->next->next = new_node;
        current_node = current_node->next;
    }

    fclose(file);

    if (*len == 0) {
        printf("No integers provided.\n");
    } else {
        uintmax_t max = 0;
        uintmax_t index = 0;

        for (size_t i = 0; i < *len; ++i) {
            if ((*list)[i].CRCFLAG) continue; // Skip elements with CRC flag set
            if ((*list)[i].CRC_INDICATION_REL8_TAG > max) {
                max = (*list)[i].CRC_INDICATION_REL8_TAG;
                index = i;
            }
        }

        printf("Largest CRC_INDICATION_REL8_TAG: %d, Index: %lu\n", max, index);
    }
}

void generate_filename(const char* base, char* dest, size_t size) {
    time_t now = time(NULL);
    struct tm tm = *localtime(&now);
    strftime(dest, size, "%Y%m%dT%H%M%S", &tm);

    int rand_num = rand() % 100000;
    snprintf(dest + 19, size - 19, "%05d", rand_num);

    const char* ext = strrchr(base, '.');
    if (ext) {
        strncpy(dest + strlen(dest), ext, size - strlen(dest));
    }
}

void create_file(const char* filename) {
    int flags = O_WRONLY | O_CREAT | O_EXCL;
    int mode = S_IRUSR | S_IWUSR | S_IXUSR;

    int fd = open(filename, flags, mode);
    if (fd == -1) {
        perror("Error creating file");
        return;
    }

    if (fd > 2 && fcntl(fd, F_SETFD, FD_CLOEXEC) == -1) {
        perror("Error setting close-on-exec flag");
        close(fd);
        return;
    }
}

void init() {
