import org.slf4j.LoggerFactory;

public class StringHasher {
    private static final Logger LOGGER = LoggerFactory.getLogger(StringHasher.class);

    private final Map<String, byte[]> cache;
    private final ExecutorService executor;
    private final int chunkSize;
    private final boolean enableCaching;
    private final int progressUpdateThreshold;
    private final long processedStringsCount = 0L;

    public StringHasher(int chunkSize, boolean enableCaching, int progressUpdateThreshold) {
        this.chunkSize = chunkSize;
        this.enableCaching = enableCaching;
        this.progressUpdateThreshold = progressUpdateThreshold;
        this.cache = new ConcurrentHashMap<>();
        this.executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public Map<String, byte[]> hashStringsFromFiles(List<File> files) throws IOException {
        Objects.requireNonNull(files);

        for (File file : files) {
            if (!file.exists() || !file.isFile()) {
                throw new IllegalArgumentException("Invalid file: " + file.getAbsolutePath());
            }
        }

        Queue<Future<Map.Entry<String, byte[]>>> resultsQueue = new LinkedBlockingQueue<>(files.size());

        for (File file : files) {
            executor.submit(() -> readAndHashStringsFromFile(file, resultsQueue));
        }

        awaitCompletion(resultsQueue);

        Map<String, byte[]> hashedStrings = new ConcurrentHashMap<>();
        while (!resultsQueue.isEmpty()) {
            Future<Map.Entry<String, byte[]>> result = resultsQueue.take();
            Map.Entry<String, byte[]> entry = result.get();
            if (entry != null) {
                hashedStrings.put(entry.getKey(), entry.getValue());
            }
        }

        return hashedStrings;
    }

    private void readAndHashStringsFromFile(File file, Queue<Future<Map.Entry<String, byte[]>>> resultsQueue) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            int lineCounter = 0;

            while ((line = reader.readLine()) != null && lineCounter < Long.MAX_VALUE) { // Prevent reading past available memory limit
                if (line.isEmpty() || line == null) {
                    continue;
                }

                byte[] hashValue = computeSHA256(line);
                if (hashValue != null && (enableCaching || !cache.containsKey(line))) {
                    cache.put(line, hashValue);
                    resultsQueue.offer(Executors.callable(() -> new SimpleEntry<>(line, hashValue)));
                    processedStringsCount++;
                    if ((processedStringsCount % progressUpdateThreshold) == 0) {
                        LOGGER.info("Processed {} strings", processedStringsCount);
                    }
                }

                lineCounter++;
            }
        } catch (NoSuchAlgorithmException e) {
            LOGGER.error("Unable to compute SHA-256 hash: {}", e.getMessage());
        } catch (IOException e) {
            LOGGER.error("Error reading file {}: {}", file.getAbsolutePath(), e.getMessage());
        }
    }

    private void awaitCompletion(Queue<Future<Map.Entry<String, byte[]>>> resultsQueue) throws InterruptedException, ExecutionException {
        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

        while (!resultsQueue.isEmpty()) {
            Future<Map.Entry<String, byte[]>> result = resultsQueue.poll();
            if (result != null) {
                result.get();
            }
        }
    }

    // Other utility methods for computing SHA-256 hash and serializing/deserializing data structures...
}
