typedef struct {
    int rnti;
    RX_UE_INFORMATION_TAG tag;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_SIZE 255

void generate_unique_filename(char *input, char *output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestr[MAX_SIZE];

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(timestr, sizeof(timestr), "%Y%m%d_%H%M%S", timeinfo);

    int rnd = rand();
    snprintf(output, MAX_SIZE, "%s%05d%s.dat", input, rnd, timestr + 8); // Ensure file name adheres to OS-specific naming conventions and does not exceed 255 characters
}

void read_integers(char *filename, int *numbers) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    char c;
    int index = 0;
    while ((c = fgetc(file)) != EOF) {
        numbers[index++] = atoi(&c);
    }
    fclose(file);
}

void read_from_socket(int sockfd, int *numbers) {
    char buffer[1024];
    ssize_t num_read;
    int index = 0;

    while ((num_read = recv(sockfd, buffer, sizeof(buffer), 0)) > 0) {
        if (index >= 10000) break; // Limit the number of integers to 10,000 for efficient memory management
        numbers[index++] = atoi(buffer);
    }
}

void process_numbers(int *numbers, size_t length) {
    if (length == 0) {
        printf("No integers provided.\n");
        return;
    }

    int max_value = numbers[0];
    int max_index = 0;
    for (size_t i = 1; i < length; ++i) {
        if (numbers[i] > max_value) {
            max_value = numbers[i];
            max_index = i;
        }
    }

    printf("Largest integer: %d, index: %ld\n", max_value, max_index);
}

void initialize_doubly_linked_list(size_t num_elements) {
    // Dynamically allocate memory for the doubly-linked list and its elements
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Error allocating memory");
        return;
    }

    // Initialize and populate the list with random data
    for (size_t i = 0; i < num_elements; ++i) {
        list[i].rnti = rand();
        list[i].tag = (RX_UE_INFORMATION_TAG)rand();
        list[i].crc_indication.crcFlag = rand() % 2;

        if (i > 0) {
            list[i - 1].next = &list[i];
            list[i].prev = &list[i - 1];
        }
    }

    // Generate and save the doubly-linked list to a file using the unique filename
    char input_filename[MAX_SIZE];
    generate_unique_filename("input.dat", input_filename);
    FILE *file = fopen(input_filename, "w");
