import java.math.BigInteger;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class MD5Hasher {
    private static final int BATCH_SIZE = 1024;
    private static final int OCTREE_FEATURE_SIZE = 256;
    private static final int OCTREE_LEAF_NODES = (int) Math.pow(2, 4);

    public Map<String, BigInteger> computeMD5Hashes(List<String> strings) {
        if (strings == null || strings.isEmpty()) return new HashMap<>();

        ConcurrentLinkedQueue<String> queue = new ConcurrentLinkedQueue<>(strings);
        ExecutorService executor = Executors.newCachedThreadPool();
        Map<String, Future<BigInteger>> tasks = new HashMap<>();
        MD5HasherTask task;

        while (!queue.isEmpty()) {
            List<String> batch = new ArrayList<>(BATCH_SIZE);
            for (int i = 0; i < BATCH_SIZE && !queue.isEmpty(); i++) {
                batch.add(queue.poll());
            }

            task = new MD5HasherTask(batch);
            tasks.put(task.key, executor.submit(task));
        }

        Map<String, BigInteger> results = new HashMap<>();
        for (Map.Entry<String, Future<BigInteger>> entry : tasks.entrySet()) {
            try {
                results.put(entry.getKey(), entry.getValue().get());
            } catch (Exception e) {
                // Handle exceptions appropriately, e.g., logging or propagating the exception
            }
        }

        return results;
    }

    private static class MD5HasherTask implements Callable<BigInteger> {
        private final List<String> strings;

        public MD5HasherTask(List<String> strings) {
            this.strings = strings;
        }

        @Override
        public BigInteger call() throws Exception {
            Map<String, BigInteger> results = new HashMap<>();
            MessageDigest md = MessageDigest.getInstance("MD5");

            for (String str : strings) {
                if (str != null && !str.isEmpty()) {
                    md.reset();
                    md.update(str.getBytes());
                    results.put(str, new BigInteger(1, md.digest()));
                }
            }

            return new BigInteger(1, md.digest()); // In case no strings were processed (empty list)
        }
    }
}
