import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

public class FileMetadataExtractor {
    public static Map<File, Metadata> processFiles(List<String> filePaths) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        List<CompletableFuture<Metadata>> futures = new LinkedList<>();

        for (String filePath : filePaths) {
            if (!File.canRead(new File(filePath))) {
                System.out.println("Permission issue: " + filePath);
                continue;
            }
            File file = new File(filePath);
            if (file.isDirectory()) {
                System.out.println("Skipping directory: " + filePath);
                continue;
            }
            futures.add(CompletableFuture.supplyAsync(() -> extractMetadata(file), executor));
        }

        Map<File, Metadata> results = new HashMap<>();
        long startTime = System.currentTimeMillis();
        while (!futures.isEmpty() && (System.currentTimeMillis() - startTime) < 30_000L) {
            List<CompletableFuture<Metadata>> completedFutures = futures.stream().filter(future -> future.isDone()).collect(Collectors.toList());
            for (CompletableFuture<Metadata> future : completedFutures) {
                try {
                    Metadata metadata = future.get();
                    File file = metadata.getFile();
                    if (results.containsKey(file)) {
                        System.out.println("Collision: " + file.getAbsolutePath() + ", Size: " + metadata.getSize() + ", Timestamp: " + metadata.getTimestamp());
                    } else {
                        results.put(file, metadata);
                    }
                } catch (Exception e) {
                    System.out.println("Error processing file: " + e.getMessage());
                }
            }
            futures.removeIf(future -> !future.isDone());
        }
        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.SECONDS);
        return results;
    }

    private static class Metadata {
        final File file;
        final long size;
        final long timestamp;

        public Metadata(File file, long size, long timestamp) {
            this.file = file;
            this.size = size;
            this.timestamp = timestamp;
        }

        // Getters and Setters
    }

    private static Metadata extractMetadata(File file) throws IOException {
        long lastModifiedTimestamp = Files.getLastModifiedTime(file.toPath()).toMillis();
        long size = Files.size(file.toPath());
        return new Metadata(file, size, lastModifiedTimestamp);
    }
}
```

