import java.util.ArrayList;
import java.util.Collections;
import java.util.ConcurrentHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class FileMetadataProcessor {
    private static final int THREAD_POOL_SIZE = 4;
    private static final long MAX_TIME_PER_BATCH = TimeUnit.SECONDS.toMillis(30);
    private static final long MAX_MEMORY_USAGE = 1024 * 1024 * 5; // 5MB
    private static final String[] ENCODINGS = {"UTF-8", "UTF-16"};

    public void processFileMetadata(List<String> filePaths) {
        if (filePaths == null || filePaths.isEmpty()) {
            System.out.println("Warning: No files or empty input list provided.");
            return;
        }

        Map<String, Metadata> metadataMap = new ConcurrentHashMap<>();

        long startTime = System.currentTimeMillis();
        int batchSize = 500;
        for (int i = 0; i < filePaths.size(); ) {
            List<String> batch = new ArrayList<>(Math.min(batchSize, filePaths.size() - i));
            if (!processBatch(metadataMap, batch)) {
                break;
            }
            i += batch.size();
        }

        long elapsedTime = System.currentTimeMillis() - startTime;
        System.out.println("Processed " + metadataMap.size() + " files in " + elapsedTime + " ms.");
    }

    private boolean processBatch(Map<String, Metadata> metadataMap, List<String> filePaths) {
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        try {
            for (String filePath : filePaths) {
                executor.submit(() -> processFile(filePath, metadataMap));
            }
            executor.shutdown();
            executor.awaitTermination(MAX_TIME_PER_BATCH, TimeUnit.MILLISECONDS);
        } catch (InterruptedException e) {
            System.err.println("ProcessBatch interrupted: " + e.getMessage());
            return false;
        }

        if (metadataMap.values().stream().mapToLong(Metadata::getSize).sum() > MAX_MEMORY_USAGE) {
            System.err.println("Warning: Exceeded memory usage limit.");
            return false;
        }

        return true;
    }

    private void processFile(String filePath, Map<String, Metadata> metadataMap) {
        File file = new File(filePath);
        if (!file.exists() || !file.isFile()) {
            System.out.println("Skipping non-existent or non-file: " + filePath);
            return;
        }

        Metadata metadata;
        synchronized (metadataMap) {
            if (metadataMap.containsKey(filePath)) {
                metadata = metadataMap.get(filePath);
            } else {
                metadata = new Metadata();
