int writeToFile(const char* fileName, const void* data, size_t size, const char* sourceFile, int lineNumber) {
    int fd = open(fileName, O_WRONLY | O_CREAT | O_EXCL, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd == -1 && errno != EEXIST) {
        fprintf(stderr, "%s:%d: Error opening file %s for writing\n", sourceFile, lineNumber, fileName);
        return -1;
    }

    if (fd != -1) {
        ssize_t written = write(fd, data, size);
        close(fd);
        if (written != size) {
            fprintf(stderr, "%s:%d: Error writing to file %s\n", sourceFile, lineNumber, fileName);
            return -1;
        }
    }

    return 0;
}

