#define MAX_ATTEMPTS 10
#define MAX_DELAY 600 // Max delay in seconds, capped at 10 minutes
#define LOG_LIMIT 100

typedef struct _key {
    unsigned char *data;
    size_t length;
} key;

void cleanup(key *key) {
    if (key->data != NULL) {
        free(key->data);
        key->data = NULL;
        key->length = 0;
    }
}

int generate_key(key *key, size_t length) {
    int fd, retries = 0, i;
    char *buf = malloc(length);

    if (!buf) {
        perror("Failed to allocate memory");
        return -1;
    }

    for (i = 0; i < length; ++i)
        buf[i] = 0;

    while (retries < MAX_ATTEMPTS) {
        fd = open("/dev/urandom", O_RDONLY);

        if (fd >= 0) {
            ssize_t nread = read(fd, buf, length);

            if (nread == length) {
                key->data = buf;
                key->length = length;
                return 0;
            }

            close(fd);
        }

        if (errno != EINTR && errno != EAGAIN) {
            perror("Failed to read from /dev/urandom");
            cleanup(key);
            return -1;
        }

        retries++;
        usleep(pow(2, retries) * 1000000); // Exponential backoff between attempts
    }

    if (retries == MAX_ATTEMPTS) {
        fprintf(stderr, "Failed to generate key after %d attempts\n", MAX_ATTEMPTS);
        cleanup(key);
        return -1;
    }

    return -1;
