#define MAX_ATTEMPTS 10
#define DELAY_MIN 1
#define DELAY_MAX 300
#define DELAY_CAP 600
#define LOG_SIZE 100

typedef struct {
    void *key;
    size_t key_len;
} cryptographic_key;

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static int log_pos = 0;

void log(const char *msg) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), msg);

    pthread_mutex_lock(&log_mutex);
    if (log_pos >= LOG_SIZE) {
        log_pos--;
    }
    fputs(msg, stderr);
    fseek(stderr, 0, SEEK_END);
    pthread_mutex_unlock(&log_mutex);
}

cryptographic_key *generate_cryptographic_key(size_t key_len) {
    size_t attempts = 0;
    int fd;
    char *buf;

    do {
        fd = open("/dev/urandom", O_RDONLY);
        if (fd == -1) {
            log("Failed to open /dev/urandom");
            usleep(attempts * 1000000 + (attempts+1)*DELAY_MIN*1000000);
            attempts++;
            continue;
        }

        buf = mmap(NULL, key_len, PROT_READ, MAP_PRIVATE, fd, 0);
        if (buf == MAP_FAILED) {
            log("Failed to map memory for cryptographic key");
            close(fd);
            usleep(attempts * 1000000 + (attempts+1)*DELAY_MIN*1000000);
            attempts++;
            continue;
        }

        if (attempts > MAX_ATTEMPTS) {
            log("Failed to generate cryptographic key after maximum number of attempts");
            munmap(buf, key_len);
            close(fd);
            return NULL;
        }

        log(("Generated cryptographic key of length %ld").(key_len));
        cryptographic_key *result = malloc(sizeof(cryptographic_key));
        result->key = buf;
        result->key_len = key_len;
        return result;
    } while (1);
}

int main(int argc, char **argv) {
    size_t key_len = 32;
    int opt;

    while ((opt = getopt(argc, argv, "l:h")) != -1) {
        switch (opt) {
            case 'l':
                key_len = atoi(optarg);
                break;
            case 'h':
                printf("Usage: %s [-l <key_length>]\n", argv[0]);
                exit(EXIT_SUCCESS);
        }
    }

    cryptographic_key *key = generate_cryptographic_key(key_len);
    if (key == NULL) {
        exit(EXIT_FAILURE);
    }

    /* Use the key in your file processing framework */

    free(key->key);
    free(key);
    return EXIT_SUCCESS;
}
