// Function to generate a unique filename, ensuring valid character restrictions and maximum length of 255 characters
char* generate_unique_filename(const char* base_name) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestring[26];
    char randnumstr[8];
    char *new_filename = malloc(256);

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(timestring, sizeof(timestring), "%Y%m%dT%H%M%S", timeinfo);
    sprintf(randnumstr, "%07d", rand());

    strncat(new_filename, base_name, 255 - strlen(timestring) - strlen(randnumstr) - 4 - 1);
    strncat(new_filename, timestring, sizeof(timestring));
    strncat(new_filename, randnumstr, sizeof(randnumstr));
    strncat(new_filename, ".log", 4);

    return new_filename;
}

