    connection connections[MAX_CONNECTIONS];
    int num_connections = read_connections(&connections); // Read connections from standard input or file

    if (num_connections == 0) {
        printf("No connections provided.\n");
        return;
    }

    pthread_t log_thread;
    log_event(__func__, "Start processing.", "Connections provided: %d", num_connections);

    for (int i = 0; i < num_connections; ++i) {
        add_connection(&connections[i]); // Add connections to the dynamic list
    }

    remove_inactive_connections(&connections, num_connections); // Remove inactive connections

    const char* oldest_connection_filename = generate_unique_filename("oldest_active_");
    log_event(__func__, "Generating filename for oldest active connection.", "Filename: %s", oldest_connection_filename);
    update_connection(get_oldest_active(&connections), oldest_connection_filename); // Update oldest active connection with log filename

    log_event(__func__, "Processing complete.", "Oldest active connection processed: %d", get_index_of_oldest_active(&connections));
}
