typedef struct Packet {
    time_t timestamp;
    char srcIP[INET6_ADDRSTRLEN];
    char destIP[INET6_ADDRSTRLEN];
    int protocol;
    size_t payloadSize;
    struct Packet* prev;
    struct Packet* next;
} Packet;

Packet* create_packet(time_t timestamp, const char* srcIP, const char* destIP, int protocol, size_t payloadSize) {
    Packet* packet = malloc(sizeof(Packet));
    memcpy(packet->srcIP, srcIP, sizeof(packet->srcIP));
    memcpy(packet->destIP, destIP, sizeof(packet->destIP));
    packet->timestamp = timestamp;
    packet->protocol = protocol;
    packet->payloadSize = payloadSize;
    packet->prev = NULL;
    packet->next = NULL;
    return packet;
}

Packet* append_packet(Packet** head, Packet* new_packet) {
    if (*head == NULL) {
        *head = new_packet;
        return *head;
    }

    Packet* last = *head;
    while (last->next != NULL) last = last->next;

    last->next = new_packet;
    new_packet->prev = last;
    return *head;
}

void log_entry_id(char* filename, size_t len, const char* type, FILE** logfile) {
    time_t now = time(NULL);
    struct tm tm = *gmtime(&now);
    char iso8601[32];
    strftime(iso8601, sizeof(iso8601), "%Y-%m-%dT%H:%M:%SZ", &tm);
    uuid_t uuid;
    uuid_generate(uuid);
    char uuid_str[41];
    sprintf((char*)uuid_str, "%08x%04x%04x%04x%04x%04x%04x%04x",
            uuid_time_low(uuid), uuid_time_mid(uuid),
            uuid_time_hi_and_version(uuid),
            uuid_clock_seq_high_and_msw_reserved(uuid),
            uuid_clock_seq_low(uuid),
            uuid_node[0], uuid_node[1], uuid_node[2]);
    char* new_id = malloc(len + strlen(iso8601) + 7 + strlen(uuid_str) + strlen(type) + 5); // .log, [log_type].log, .txt
    strcpy(new_id, filename);
    strcat(new_id, iso8601);
    strcat(new_id, "-");
    strcat(new_id, uuid_str);
    strcat(new_id, ".");
    strcat(new_id, type);
    strcat(new_id, ".log");

    if (access(new_id, F_OK) == 0) { // If the file exists, increment the number in the filename until a unique one is found.
        size_t i = len + strlen(iso8601) + strlen(uuid_str) + strlen(type) + 5;
        char* current_id = new_id;
        while (access(new_id, F_OK) == 0) {
            ++current_id[i];
            if (++i >= len + strlen(iso8601) + strlen(uuid_str) + strlen(type) + 5 + 10) {
                current_id[len + strlen(iso8601) + strlen(uuid_str) + strlen(type) + 5] = '0';
                ++i;
            }
            new_id = current_id;
        }
    }

    *logfile = fopen(new_id, "a"); // Open the log file in append mode.
}

void analyze_packets(Packet** head) {
    if (*head == NULL) {
        printf("No packets provided.\n");
        return;
    }

    Packet* max_packet = *head;
    size_t max_payload = (*head)->payloadSize;

    for (Packet* cur = *head->next; cur != NULL; cur = cur->next) {
        if (cur->payloadSize > max_payload) {
            max_payload = cur->payloadSize;
            max_packet = cur;
        }
    }

    printf("Largest packet payload: %zu bytes, sequence number: %zu\n", max_payload, max_packet->timestamp);
}

