struct dyn_array {
    NFAPI_RX_FRAME_T *frames;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    config_t* cfg; // external configuration struct
};

dyn_array_t* create_dyn_array(config_t* cfg) {
    dyn_array_t* array = malloc(sizeof(dyn_array_t));
    array->cfg = cfg;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dyn_array(dyn_array_t* array) {
    free(array->frames);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void resize_dyn_array(dyn_array_t* array, size_t new_capacity) {
    pthread_mutex_lock(&array->lock);
    if (new_capacity > array->capacity) {
        NFAPI_RX_FRAME_T *new_frames = realloc(array->frames, new_capacity * sizeof(NFAPI_RX_FRAME_T));
        if (!new_frames) {
            // handle memory allocation failure
            pthread_mutex_unlock(&array->lock);
            return;
        }
        array->frames = new_frames;
        array->capacity = new_capacity;
    }
    pthread_mutex_unlock(&array->lock);
}

void insert_frame(dyn_array_t* array, const NFAPI_RX_FRAME_T* frame) {
    // Perform data validation checks here

    resize_dyn_array(array, array->size + 1);
    array->frames[array->size] = *frame;
    array->size++;
}

NFAPI_RX_FRAME_T* get_frame(const dyn_array_t* array, size_t index) {
    if (index >= array->size || index < 0) {
        // handle out-of-bounds access
        return NULL;
    }
    pthread_mutex_lock(&array->lock);
    NFAPI_RX_FRAME_T* frame = &array->frames[index];
    pthread_mutex_unlock(&array->lock);
    return frame;
}
