```java
import java.io.*;
import java.math.BigInteger;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import com.google.common.hash.*;

public final class FileHashUtil {
    private static final int CORE_POOL_SIZE = Runtime.getRuntime().availableProcessors();
    private static final BlockingQueue<Runnable> WORK_QUEUE = new LinkedBlockingQueue<>(CORE_POOL_SIZE * 2);
    private static final ExecutorService EXECUTOR = Executors.newFixedThreadPool(CORE_POOL_SIZE, r -> {
        Thread thread = Executors.defaultThreadFactory().newThread(r);
        thread.setDaemon(true);
        return thread;
    });

    public static Map<Path, HashCode> processDirectory(Path dir, Configuration config) throws IOException, InterruptedException {
        List<FileVisitor> visitors = Arrays.asList(new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                EXECUTOR.submit(() -> processFile(file, config));
                return FileVisitResult.CONTINUE;
            }
        }, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitDirectory(Path dir, BasicFileAttributes attrs) throws IOException {
                if (!attrs.isHidden())
                    Files.walkFileTree(dir, this);
                return FileVisitResult.CONTINUE;
            }
        });

        Files.walkFileTree(dir, new ThreadPoolFileVisitor<>(visitors));
        EXECUTOR.shutdown();
        EXECUTOR.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

        return results;
    }

    private static Map<Path, HashCode> results = new ConcurrentHashMap<>();

    private static void processFile(Path file, Configuration config) {
        try (InputStream is = Files.newInputStream(file)) {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[config.getBufferSize()];
            int read;
            while ((read = is.read(buffer)) != -1) {
                md.update(buffer, 0, read);
            }
            results.put(file, Hashing.md5().hashBytes(md.digest()));
        } catch (IOException | NoSuchAlgorithmException e) {
            // Handle errors gracefully and update the results accordingly
        }
    }
}
