void destroy_node(NFAPI_CRC_INDICATION_PDU_T* node) {
    free(node);
}

void populate_list(NFAPI_CRCI_INDICATION_PDU_T** head, int N) {
    *head = NULL;
    for (int i = 0; i < N; ++i) {
        (*head) = create_node();
        if (!(*head)) break;
        NFAPI_CRCI_INDICATION_PDU_T* temp = *head;
        while (temp->next) temp = temp->next;
        temp->next = create_node();
    }
}

char* generate_filename(const char* base, int len) {
    char timestamp[29]; // ISO 8601 format: YYYYMMDTHHMMSS
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y%m%dT%H%M%S", localtime(&now));

    char random[7]; // 6 random digits + terminating null byte
    rand() % 1000000, random;

    int total_len = strlen(base) + strlen(timestamp) + strlen(random) + 5; // .txt + separators
    if (total_len > 255) return NULL;

    char* filename = malloc(total_len);
    strcpy(filename, base);
    strcat(filename, "_");
    strcat(filename, timestamp);
    strcat(filename, "_");
    strcat(filename, random);
    strcat(filename, ".txt");

    return filename;
}

void save_list(const char* filename, NFAPI_CRCI_INDICATION_PDU_T* head) {
    FILE* file = fopen(filename, "w");
    if (!file) return;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    NFAPI_CRCI_INDICATION_PDU_T* current = head;
    while (current) {
        pthread_mutex_lock(&lock);
        fprintf(file, "%u %u %hu %d\n",
                current->RX_UE_INFORMATION_TAG,
                current->RNTI,
                current->CRC_INDICATION_REL8_TAG,
                current->CRCFLAG);
        pthread_mutex_unlock(&lock);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_destroy(&lock);
}

void read_integers(FILE* file, int* buffer, int max) {
    int i = 0;
    while (i < max && !feof(file)) {
        fscanf(file, "%d", &buffer[i]);
        ++i;
    }
}

int find_max(const int* buffer, int len) {
    int max = INT_MIN;
    int index = -1;
    for (int i = 0; i < len; ++i) {
        if (buffer[i] > max) {
            max = buffer[i];
            index = i;
        }
    }
    return index;
}

void process_input(char* filename, int buffer_len) {
    FILE* file;
    if (!filename || !(file = fopen(filename, "r"))) {
        log_error("Failed to open input file.");
        return;
    }

