    read_integers(file, buffer, sizeof(buffer));

    if (buffer_len == 0) {
        log_info("No integers provided.");
        fclose(file);
        return;
    }

    int max_index = find_max(buffer, buffer_len);
    log_info("Largest integer: %d at index: %d", buffer[max_index], max_index);
    fclose(file);
}

void network_read(int sockfd) {
