LTE_RRC_PAGING* init_dynamic_array(size_t capacity, size_t *num_elements) {
    LTE_RRC_PAGING *arr;

    if (!(arr = malloc(capacity * sizeof(LTE_RRC_PAGING))))
        handle_error("Memory allocation failed");

    *num_elements = 0;
    return arr;
}

void configure_array(FILE *config, LTE_RRC_PAGING *arr, size_t *num_elements) {
    json_object *root, *obj;
    json_object *iter;
    const char *key;

    root = json_tokener_parse(config);
    if (IS_ERROR(root))
        handle_error("Invalid configuration file");

    obj = json_object_get_ex(root, "paging_events");
    if (!obj || !IS_TYPED_ARRAY(obj))
        handle_error("Missing or invalid 'paging_events' field");

    *num_elements = json_array_length(obj);
    arr = init_dynamic_array(*num_elements, num_elements);

    for (iter = json_array_iter(obj); !json_object_get_ex(iter, "end"); iter = json_array_next(iter)) {
        obj = json_object_from_ot(iter->u.container);

        key = json_object_get_name(obj);
        if (strcmp(key, "paging_identity") != 0 || !json_object_is_int32(json_object_get_ex(obj, key)))
            handle_error("Missing or invalid 'paging_identity' field");

        key = json_object_get_name(json_object_array_get_idx(obj, 1));
        if (strcmp(key, "periodicity") != 0 || !json_object_is_int32(json_object_get_ex(obj, key)))
            handle_error("Missing or invalid 'periodicity' field");

        key = json_object_get_name(json_object_array_get_idx(obj, 2));
        if (strcmp(key, "priority_level") != 0 || !json_object_is_int32(json_object_get_ex(obj, key)))
            handle_error("Missing or invalid 'priority_level' field");

        arr[*num_elements].paging_identity = json_object_get_int32(obj, "paging_identity");
        arr[*num_elements].paging_periodicity = json_object_get_int32(obj, "periodicity");
        arr[*num_elements++].priority_level = json_object_get_int32(obj, "priority_level");
    }
}

void set_dynamic_priority(LTE_RRC_PAGING *arr, size_t num_elements, int congestion_level) {
    for (size_t i = 0; i < num_elements; ++i)
        arr[i].priority_level += congestion_level;
}

