```c
#include <tiffio.h>
#include <stdio.h>
#include <string.h>

int parseTIFFImage(const char *filename, int *bitsPerSample, int *samplesPerPixel)
{
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) return 1; // Error: Could not open file

    if (TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL) != COM_multipage)
    {
        *samplesPerPixel = TIFFGetField(tif, TIFFTAG_SAMPLESperpixel);
        *bitsPerSample = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);
    }
    else // Multisample case
    {
        int numExtraSamples = TIFFGetFieldDefault(tif, TIFFTAG_EXTRASAMPLES, 0);
        if (numExtraSamples > 4) return 2; // Error: Unsupported number of extra samples

        *samplesPerPixel = 1 + numExtraSamples;
        *bitsPerSample = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);
    }

    if (*bitsPerSample != 1 && *bitsPerSample != 8 && *bitsPerSample != 16) return 3; // Error: Unsupported bits per sample

    TIFFClose(tif);
    return 0; // Success
}
