AES_KEY aesKey;
void initAES(const std::string& password)
{
    unsigned char key[AES_BLOCK_SIZE];
    unsigned char iv[AES_IV_LENGTH];
    SHA1_CTX shaContext;

    SHA1Init(&shaContext);
    SHA1Update(&shaContext, (unsigned char*)password.c_str(), password.length());
    SHA1Final(key, &shaContext);

    // Set the key and IV length, derive encryption key from the password via the SHA-1 hash function
    AES_set_encrypt_key((const unsigned char *)key, 256, &aesKey);
    AES_IVinit(&aesKey, iv, AES_IV_LENGTH);
}
