#include <pthread.h>
#include <atomic>

typedef struct {
    uint8_t api_version;
    uint32_t api_config;
    // Other NFAPI_MESSAGE_T fields...
} NFAPI_MESSAGE_T;

typedef struct {
    NFAPI_CELL_ID_T cell_id;
    UE_CONTEXT_T* ue_context;
    // Other NFAPI_CELL_ID_T fields...
} CELL_LIST_ELEMENT_T;

typedef struct {
    std::atomic<int> count;
    CELL_LIST_ELEMENT_T** cell_list;
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
} UE_CONTEXT_MANAGER_T;

void error_log(const char* msg) {
    fprintf(stderr, "[ERROR] %s\n", msg);
}

UE_CONTEXT_MANAGER_T* init_ue_context_manager(size_t max_ues) {
    UE_CONTEXT_MANAGER_T* manager = (UE_CONTEXT_MANAGER_T*)malloc(sizeof(UE_CONTEXT_MANAGER_T));
    if (!manager) error_log("Failed to allocate memory for UE context manager");

    manager->count.store(0);
    manager->capacity = max_ues;
    manager->size = 0;
    manager->cell_list = (CELL_LIST_ELEMENT_T**)calloc(manager->capacity, sizeof(CELL_LIST_ELEMENT_T*));
    if (!manager->cell_list) error_log("Failed to allocate memory for cell list");

    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void resize_ue_context_manager(UE_CONTEXT_MANAGER_T* manager, size_t new_capacity) {
    if (new_capacity <= manager->size) return;

    CELL_LIST_ELEMENT_T** temp_list = (CELL_LIST_ELEMENT_T**)realloc(manager->cell_list, new_capacity * sizeof(CELL_LIST_ELEMENT_T*));
    if (!temp_list) error_log("Failed to resize cell list");

    manager->cell_list = temp_list;
    manager->capacity = new_capacity;
}

CELL_LIST_ELEMENT_T* alloc_ue_context_element() {
    CELL_LIST_ELEMENT_T* element = (CELL_LIST_ELEMENT_T*)malloc(sizeof(CELL_LIST_ELEMENT_T));
    if (!element) error_log("Failed to allocate memory for UE context element");

    return element;
}

void free_ue_context_manager(UE_CONTEXT_MANAGER_T* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->cell_list[i]) free(manager->cell_list[i]->ue_context);
        free(manager->cell_list[i]);
    }
    free(manager->cell_list);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

CELL_LIST_ELEMENT_T* get_or_create_ue_context(UE_CONTEXT_MANAGER_T* manager, NFAPI_CELL_ID_T cell_id) {
    pthread_mutex_lock(&manager->lock);

    size_t index = cell_id % manager->capacity;
    if (manager->cell_list[index]) {
        // If an element already exists for the given cell_id, return it.
        CELL_LIST_ELEMENT_T* existing_element = manager->cell_list[index];
        if (existing_element->cell_id == cell_id) {
            pthread_mutex_unlock(&manager->lock);
            return existing_element;
        }
    } else {
        // If no element exists for the given cell_id, create a new one and add it to the list.
        CELL_LIST_ELEMENT_T* new_element = alloc_ue_context_element();
        new_element->cell_id = cell_id;
        manager->cell_list[index] = new_element;
    }

    resize_ue_context_manager(manager, manager->size + 1);
    pthread_mutex_unlock(&manager->lock);

    return manager->cell_list[index];
}
```

