    struct node* next;
};

// Dynamic linked list object
struct dynamic_list {
    struct node* head;
    struct node* tail;
    size_t size;
    pthread_mutex_t lock;
};

// Initialize and manage the dynamic linked list
void init_dynamic_list(struct dynamic_list* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Batch processing function
void batch_process(struct dynamic_list* list, size_t batch_size) {
    // Implement batch processing here
}

// Insert a TCP connection into the dynamic linked list
void insert_connection(struct dynamic_list* list, const TCP_CONNECTION_T* connection) {
    struct node* new_node = (struct node*)my_malloc(sizeof(struct node));
    new_node->connection = *connection;
    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

// Delete a TCP connection from the dynamic linked list by id
void delete_connection(struct dynamic_list* list, connection_id id) {
    struct node* current = list->head;
    struct node* previous = NULL;

    pthread_mutex_lock(&list->lock);
    while (current != NULL && current->connection.id != id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->list->lock);
        return;
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    if (current == list->tail) {
        list->tail = previous;
    }

    free(current);
    list->size--;
    pthread_mutex_unlock(&list->lock);
}

// Traverse the dynamic linked list
void traverse_dynamic_list(const struct dynamic_list* list) {
    const struct node* current = list->head;
    while (current != NULL) {
        // Process each connection here
        current = current->next;
    }
}
