struct list {
    struct node *head, *tail;
    size_t size;
};

void nfapi_crc_indication_pdu_init(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->rxi = RX_UE_INFORMATION_TAG_INITIALIZER;
    pdu->rnti = RNTI_INITIALIZER;
    pdu->cind.crcflag = (rand() % 2);
}

void list_init(struct list *list) {
    list->head = list->tail = NULL;
    list->size = 0;
}

void push(struct list *list, NFAPI_CRC_INDICATION_PDU_T data) {
    struct node *node = malloc(sizeof(struct node));
    if (!node) {
        syslog(LOG_ERR, "Memory allocation failed.");
        return;
    }

    nfapi_crc_indication_pdu_init(&node->data);
    node->data = data;
    node->next = NULL;

    if (list->size == 0) {
        list->head = list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }

    ++(list->size);
}

void free_list(struct list *list) {
    struct node *current, *temp;

    current = list->head;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    list->size = 0;
    list->head = list->tail = NULL;
}

