    size_t i, n;
    scanf("%zu", &n);
    for (i = 0; i < n && n < MAX_LIST_SIZE; ++i) {
        if (scanf("%d", &array[i]) != 1) {
            syslog(LOG_ERR, "Invalid input.");
            free_list(&data_list);
            free_list(&crc_list);
            return;
        }
    }

    pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_t crc_mutex = PTHREAD_MUTEX_INITIALIZER;

    for (i = 0; i < n && n < MAX_LIST_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        nfapi_crc_indication_pdu_init(&pdu);
        pdu.rxi = array[i]; // Set RX_UE_INFORMATION_TAG with the corresponding integer value
        push(&data_list, pdu);
    }

    for (struct node *current = data_list.head; current != NULL; current = current->next) {
        if (pthread_mutex_lock(&crc_mutex) != 0) {
            syslog(LOG_ERR, "Mutex lock failed.");
            free_list(&data_list);
            free_list(&crc_list);
            return;
        }

        for (struct node *temp = current; temp != NULL; temp = temp->next) {
            if (!temp->data.rxi || !temp->data.rnti || !(temp->data.cind.crcflag)) {
                syslog(LOG_WARNING, "Invalid structure encountered.");
                pthread_mutex_unlock(&crc_mutex);
                continue;
            }

            push(&crc_list, temp->data);
        }

        pthread_mutex_unlock(&crc_mutex);
    }

    // Find and print the largest integer in the array
    int max = array[0];
    for (i = 1; i < n && n < MAX_LIST_SIZE; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }

    printf("Largest integer in the array: %d\n", max);

    free_list(&data_list);
    free_list(&crc_list);
}
