        unsigned long long tx_packets;
    } MAC_LAYER_STATS;
    struct UE_CONTEXT *next;
} NFAPI_LTE_UE_CONTEXT_T;

NFAPI_LTE_UE_CONTEXT_T* create_linked_list() {
    NFAPI_LTE_UE_CONTEXT_T* head = NULL;
    unsigned int capacity = 10000, current_capacity = 0;
    NFAPI_LTE_UE_CONTEXT_T* current = NULL;
    NFAPI_LTE_UE_CONTEXT_T** next_ptr = &current;

    void* memory = malloc(capacity * sizeof(NFAPI_LTE_UE_CONTEXT_T));
    if (!memory) {
        fprintf(stderr, "Out of memory!\n");
        return NULL;
    }

    head = (NFAPI_LTE_UE_CONTEXT_T*)memory;

    while (current_capacity < capacity) {
        *next_ptr = ((char*)memory + current_capacity * sizeof(NFAPI_LTE_UE_CONTEXT_T));
        (*next_ptr) -> next = NULL;

        if (++current_capacity == capacity) {
            capacity *= 2;
            memory = realloc(memory, capacity * sizeof(NFAPI_LTE_UE_CONTEXT_T));
            if (!memory) {
                fprintf(stderr, "Out of memory!\n");
                return head;
            }
        }

        next_ptr = &(*next_ptr) -> next;
    }

    return head;
}

void delete_linked_list(NFAPI_LTE_UE_CONTEXT_T* head) {
    NFAPI_LTE_UE_CONTEXT_T* current = head, *temp;
    while (current != NULL) {
        temp = current->next;
        free(current);
        current = temp;
    }
}
