NFAPI_PHY_RX_FRAME_INFO* create_frame_buffer(size_t capacity, bool metadata_enabled) {
    NFAPI_PHY_RX_FRAME_INFO* buffer = (NFAPI_PHY_RX_FRAME_INFO*)malloc(sizeof(NFAPI_PHY_RX_FRAME_INFO));
    if (!buffer) return nullptr;

    buffer->metadata_enabled = metadata_enabled;
    pthread_mutex_init(&(buffer->lock), nullptr);
    buffer->capacity = capacity;
    buffer->count = 0;
    buffer->data = (RX_FRAME_INFO*)calloc(capacity, sizeof(RX_FRAME_INFO));
    if (!buffer->data) {
        free(buffer);
        return nullptr;
    }

    return buffer;
}

void destroy_frame_buffer(NFAPI_PHY_RX_FRAME_INFO* buffer) {
    if (buffer) {
        free(buffer->data);
        pthread_mutex_destroy(&(buffer->lock));
        free(buffer);
    }
}

bool add_frame_to_buffer(NFAPI_PHY_RX_FRAME_INFO* buffer, const RX_FRAME_INFO* frame) {
    if (!buffer || !frame) return false;

    pthread_mutex_lock(&(buffer->lock));

    // Check for duplicate FRAME_SEQ_NUM and SNR within valid range
    for (size_t i = 0; i < buffer->count; ++i) {
        if (buffer->data[i].FRAME_SEQ_NUM == frame->FRAME_SEQ_NUM || frame->SNR < -95 || frame->SNR > 40) {
            pthread_mutex_unlock(&(buffer->lock));
            return false;
        }
    }

    // Add frame to buffer and update count
    buffer->data[buffer->count++] = *frame;

    pthread_mutex_unlock(&(buffer->lock));
    return true;
}

void enable_metadata_extraction(NFAPI_PHY_RX_FRAME_INFO* buffer, bool enable) {
    if (buffer) buffer->metadata_enabled = enable;
}
