#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <openssl/sha.h>

typedef struct {
    uint32_t ip;
    size_t len;
    void** masks;
    pthread_mutex_t lock;
} Entry;

typedef struct {
    unsigned long count;
    Entry** table;
    size_t size, capacity;
    pthread_mutex_t lock;
} HashTable;

// Helper function to calculate hash value using FNV-1a hash function
unsigned int hash(const void* key) {
    const unsigned int offsetBasis = 14695981039346656037UL;
    const unsigned int prime = 1099511628211UL;
    unsigned int hash = offsetBasis;
    char* key_str = (char*)key;
    for (size_t i = 0; i < strlen(key_str); ++i) {
        hash = (hash ^ key_str[i]) * prime;
    }
    return hash % UINT32_MAX;
}

void entry_init(Entry* entry, uint32_t ip, size_t len, void** masks, pthread_mutex_t lock) {
    entry->ip = ip;
    entry->len = len;
    entry->masks = masks;
    entry->lock = lock;
}

void hash_table_init(HashTable* table, size_t capacity) {
    table->capacity = capacity;
    table->size = 0;
    table->count = 0;
    table->table = calloc(table->capacity, sizeof(Entry*));
    table->lock = PTHREAD_MUTEX_INITIALIZER;
}

void hash_table_insert(HashTable* table, void* key, size_t len, void* mask) {
    unsigned int index = hash(key);
    pthread_mutex_lock(&table->lock);
    if (index >= table->capacity || !table->table[index]) {
        // Resize the hash table if necessary
        size_t new_capacity = table->capacity ? table->capacity * 2 : 16;
        Entry** new_table = realloc(table->table, new_capacity * sizeof(Entry*));
        if (!new_table) {
            fprintf(stderr, "Failed to allocate memory\n");
            pthread_mutex_unlock(&table->lock);
            return;
        }
        table->table = new_table;
        table->capacity = new_capacity;
    }

    Entry* entry = calloc(1, sizeof(Entry));
    if (!entry) {
        fprintf(stderr, "Failed to allocate memory\n");
        pthread_mutex_unlock(&table->lock);
        return;
    }

    // Assign the key and associated data to the new entry
    entry_init(entry, *(uint32_t*)key, len, &mask, PTHREAD_MUTEX_INITIALIZER);

    pthread_mutex_lock(&entry->lock);
    if (entry->masks) {
        // Append additional subnet mask to the existing entry gracefully
        void** new_masks = realloc(entry->masks, sizeof(void*) * (entry->len + 1));
        if (!new_masks) {
            fprintf(stderr, "Failed to allocate memory\n");
            pthread_mutex_unlock(&entry->lock);
            free(entry);
            pthread_mutex_unlock(&table->lock);
            return;
        }
        entry->masks = new_masks;
    } else {
        entry->masks = malloc(sizeof(void*) * 1);
    }

    // Assign the subnet mask to the newly allocated memory in the masks array
    entry->masks[entry->len++] = mask;
    pthread_mutex_unlock(&entry->lock);

    table->table[index] = entry;
    table->size++;
    table->count++;
    pthread_mutex_unlock(&table->lock);
}

// Helper function to print the largest IP address in terms of numerical value
void print_largest(HashTable* table) {
    uint32_t max_ip = 0;
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->table[i]) {
            Entry* entry = table->table[i];
            pthread_mutex_lock(&entry->lock);
            if (*(uint32_t*)&entry->ip > max_ip) {
                max_ip = *(uint32_t*)&entry->ip;
            }
            pthread_mutex_unlock(&entry->lock);
        }
    }
    printf("%s\n", inet_ntoa(*(struct in_addr*)&*(uint32_t*)&max_ip));
}
```']

