                    metadata = new Metadata(size, timestamp, owner);
                    if (metadata.size() > MAX_METADATA_SIZE) {
                        System.out.println("Warning: Exceeded maximum metadata size limit.");
                        continue;
                    }
                } else {
                    metadata = metadataMap.get(resolvedPath.toString());
                }

                AtomicInteger count = fileCountMap.get(resolvedPath.toString());
                if (count == null) {
                    count = new AtomicInteger();
                    fileCountMap.put(resolvedPath.toString(), count);
                }
                count.incrementAndGet();

                Runnable processFileTask = () -> {
                    if (count.get() == 1) {
                        metadataMap.put(resolvedPath.toString(), metadata);
                    }

                    try {
                        long size = Files.size(resolvedPath);
                        long timestamp = Files.getLastModifiedTime(resolvedPath).toMillis();

                        if (metadata != null && (metadata.size() + size > MAX_METADATA_SIZE || metadata.timestamp() == timestamp)) {
                            // Collision detected, log and continue processing
                            System.out.println("Warning: File collision detected for " + resolvedPath);
                        }
                    } catch (IOException e) {
                        System.err.println("Error processing file: " + resolvedPath + ". Skipping...");
                        e.printStackTrace();
                    }
                };

                executor.submit(processFileTask);
            }

            for (Map.Entry<String, AtomicInteger> entry : fileCountMap.entrySet()) {
                if (entry.getValue().get() > 1) {
                    executor.shutdownNow();
                    try {
                        while (!executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS)) {}
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        }

        return metadataMap;
    }

    private Path resolveSymbolicLinks(String path, int maxDepth) throws IOException {
        if (maxDepth <= 0) {
            return null;
        }

        try (Stream<Path> links = Files.walkSymlinks(Paths.get(path))) {
            Path resolvedPath = links.filter(Files::isRegularFile).findFirst().orElse(null);
            if (resolvedPath == null) {
                return resolveSymbolicLinks(links.filter(Files::isSymbolicLink).findFirst().orElse(null), maxDepth - 1);
            }
            return resolvedPath;
        }
    }

    private static class Metadata {
        private final long size;
        private final long timestamp;
        private final String owner;

        public Metadata(long size, long timestamp, String owner) {
            this.size = size;
            this.timestamp = timestamp;
            this.owner = owner;
        }

        public long size() {
            return size;
        }

        public long timestamp() {
            return timestamp;
        }

        public String owner() {
            return owner;
        }
    }

    // Implement the getFileOwner method here...

    private Path safe_str_append_slash(String str, byte[] outBuffer, int outBufSize) throws BadCharacterException, IndexOutOfBoundsException {
        // C implementation of safe_str_append_slash using Java's String and ByteBuffer APIs
        if (str == null || outBuffer == null) {
            throw new IllegalArgumentException("Input string or output buffer cannot be null.");
        }

        int strLength = str.length();
        if (strLength > Integer.MAX_VALUE - outBufSize) {
            throw new IndexOutOfBoundsException("String length exceeds the specified size limit.");
        }

        ByteBuffer buffer = ByteBuffer.wrap(outBuffer, 0, outBufSize);

        int position = str.codePointAt(0) > 0xFFFF ? strBytestreamCopierUTF16BE(str, buffer) : strBytestreamCopierUTF8(str, buffer);
        if (position < 0) {
            throw new BadCharacterException("Invalid character encountered.");
        }

        for (int i = 1; i < strLength; ++i) {
            position += Characters.codePointAt(str, i) > 0xFFFF ? strBytestreamCopierUTF16BE(str.substring(i), buffer) : strBytestreamCopierUTF8(str.substring(i), buffer);
            if (position < 0) {
                throw new BadCharacterException("Invalid character encountered.");
            }
        }

        buffer.flip();
        return ByteBuffer.wrap(outBuffer, 0, position).array();
    }

    private int strBytestreamCopierUTF8(String src, ByteBuffer dst) {
        for (int i = 0; i < src.length(); ++i) {
            byte[] bytes = Character.toChars(src.codePointAt(i));
            if (dst.remaining() < bytes.length) break;
            dst.put(bytes);
        }
        return dst.position();
    }

    private int strBytestreamCopierUTF16BE(String src, ByteBuffer dst) {
        for (int i = 0; i < src.length(); i += Character.charCount(src.codePointAt(i))) {
            char ch = src.codePointAt(i);
            int cp = Character.toCodePoint(ch);
            byte[] bytes = new byte[Character.toUTF16BE(cp, (char) ((cp >>> 16) & 0xFF), dst.remaining() < 2 ? -1 : dst.remaining());
            dst.put(bytes);
        }
        return dst.position();
    }

    // Implement other required methods like chunk and log performance metrics...
}
