typedef struct {
    void *data;
    size_t size;
    pthread_mutex_t lock;
} AllocatedBlock;

struct MemManager {
    AllocatedBlock *blocks;
    size_t capacity, used;
    sem_t free_sem, locked_sem;
};

void init_mem_manager(struct MemManager *mm, size_t initial_size) {
    mm->capacity = initial_size;
    mm->used = 0;
    mm->blocks = malloc(initial_size * sizeof(AllocatedBlock));

    for (size_t i = 0; i < initial_size; ++i) {
        pthread_mutex_init(&mm->blocks[i].lock, NULL);
    }

    sem_init(&mm->free_sem, 0, initial_size);
    sem_init(&mm->locked_sem, 0, 0);
}

AllocatedBlock *alloc_block(struct MemManager *mm) {
    sem_wait(&mm->free_sem);
    AllocatedBlock *block = &mm->blocks[mm->used];
    mm->used++;
    return block;
}

void free_block(struct MemManager *mm, AllocatedBlock *block) {
    memset(block, 0, sizeof(AllocatedBlock));
    sem_post(&mm->free_sem);
}

