void delete_connection(int connection_id) {
    pthread_mutex_lock(&connections_mutex);
    NODE* current = head, *prev = NULL;
    while (current != NULL) {
        if (current->data.connection_id == connection_id) {
            if (prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&connections_mutex);
}

