typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    SRS_INDICATION_TAG srs_indication_tag;
} NR_RX_FRAME_T;

struct node {
    NR_RX_FRAME_T data;
    struct node* next;
};

typedef struct node Node;
typedef struct list List;

struct list {
    pthread_mutex_t mutex;
    unsigned long mem_usage;
    unsigned long total_allocations;
    unsigned long fragmentation;
    bool is_empty;
    Node* head;
    Node* tail;
};

void log_memory_stats(List *list) {
    printf("Memory Usage: %lu bytes\n", list->mem_usage);
    printf("Total Allocations: %lu\n", list->total_allocations);
    printf("Fragmentation: %lu%%\n", list->fragmentation);
}

Node* new_node(NR_RX_FRAME_T data) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void destroy_node(Node **node) {
    if (*node == NULL) return;
    free(*node);
    *node = NULL;
}

List* create_list() {
    List *list = (List*) malloc(sizeof(List));
    if (!list) return NULL;
    list->mem_usage = 0;
    list->total_allocations = 0;
    list->fragmentation = 0;
    list->is_empty = true;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_list(List **list) {
    if (*list == NULL) return;
    pthread_mutex_destroy(&(*list)->mutex);
    while ((*list)->head != NULL) {
        Node *temp = (*list)->head;
        (*list)->head = (*list)->head->next;
        destroy_node(&temp);
    }
    free(*list);
    *list = NULL;
}

void log(const char* message) {
    // Implement your custom logging mechanism here
}

bool list_insert(List **list, NR_RX_FRAME_T data) {
    pthread_mutex_lock(&(*list)->mutex);

    Node *new_node = new_node(data);
    if (!new_node) {
        log("Memory Allocation Failed");
        pthread_mutex_unlock(&(*list)->mutex);
        return false;
    }

    if ((*list)->is_empty) {
        (*list)->head = new_node;
        (*list)->tail = new_node;
    } else {
        (*list)->tail->next = new_node;
        (*list)->tail = new_node;
    }
    (*list)->is_empty = false;

    (*list)->mem_usage += sizeof(Node);
    ++((*list)->total_allocations);
    (*list)->fragmentation = ((*list)->mem_usage - (*list)->total_allocations * sizeof(Node)) * 100 / (*list->mem_usage);

    pthread_mutex_unlock(&(*list)->mutex);
    return true;
}

NR_RX_FRAME_T list_remove(List **list) {
    pthread_mutex_lock(&(*list)->mutex);

    if ((*list)->is_empty) {
        pthread_mutex_unlock(&(*list)->mutex);
        return (NR_RX_FRAME_T){0};
    }

    NR_RX_FRAME_T data = (*list)->head->data;
    Node *temp = (*list)->head;
    (*list)->head = (*list)->head->next;

    if ((*list)->head == NULL) {
        (*list)->tail = NULL;
    }
    (*list)->mem_usage -= sizeof(Node);
    --((*list)->total_allocations);
    (*list)->fragmentation = ((*list)->mem_usage - (*list)->total_allocations * sizeof(Node)) * 100 / (*list->mem_usage);

    destroy_node(&temp);
    if ((*list)->is_empty) {
        (*list)->tail = NULL;
    }

    pthread_mutex_unlock(&(*list)->mutex);
