struct list_node {
    NR_RX_FRAME_T frame;
    struct list_node* next;
};

struct list_meta {
    struct list_node* head;
    size_t num_frames;
    size_t max_frames;
    pthread_mutex_t mutex;
};

void list_init(struct list_meta* list, size_t max_frames) {
    list->head = NULL;
    list->num_frames = 0;
    list->max_frames = max_frames;
    pthread_mutex_init(&list->mutex, NULL);
}

void* custom_malloc(size_t size) {
    void* mem = malloc(size);
    if (mem == NULL) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }
    return mem;
}

void list_insert(struct list_meta* list, NR_RX_FRAME_T frame) {
    struct list_node* node = (struct list_node*)custom_malloc(sizeof(struct list_node));
    node->frame = frame;
    pthread_mutex_lock(&list->mutex);
    if (list->num_frames >= list->max_frames) {
        struct list_node* tmp = list->head;
        while (tmp && list->num_frames > list->max_frames / 2) {
            list->num_frames--;
            node->next = tmp->next;
            free(tmp);
            tmp = node->next;
        }
    }
    if (list->head == NULL) {
        list->head = node;
    } else {
        struct list_node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
    list->num_frames++;
    pthread_mutex_unlock(&list->mutex);
}

NR_RX_FRAME_T list_delete(struct list_meta* list) {
    if (list->head == NULL) return (NR_RX_FRAME_T){0};
    struct list_node* first = list->head;
    NR_RX_FRAME_T frame = first->frame;
    list->head = first->next;
    free(first);
    list->num_frames--;
    return frame;
}

NR_RX_FRAME_T list_retrieve(struct list_meta* list, RX_UE_INFORMATION_TAG rxi) {
    struct list_node* current = list->head;
    while (current != NULL && current->frame.rxi != rxi) {
        current = current->next;
    }
    if (current == NULL) return (NR_RX_FRAME_T){0};
    return current->frame;
}

void list_process(struct list_meta* list, void (*process_frame)(NR_RX_FRAME_T)) {
    struct list_node* current = list->head;
    double start_time = clock();
    while (current != NULL) {
        NR_RX_FRAME_T frame = current->frame;
        process_frame(frame);
        current = current->next;
        list->num_frames--;
    }
    double end_time = clock();
    printf("Frame processing time: %.6f seconds\n", end_time - start_time);
}

void list_log_stats(struct list_meta* list) {
