#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#include <time.h>

typedef struct {
    CONNECTION_ID id;
    sockaddr_in remote_address;
    time_t last_active_time;
} TCP_CONNECTION_T;

typedef struct NODE {
    TCP_CONNECTION_T data;
    struct NODE* next;
} NODE;

typedef struct {
    pthread_mutex_t lock;
    NODE* head;
    size_t mem_usage;
    size_t memory_limit;
} LIST_MANAGER_T;

LIST_MANAGER_T* list_manager_create(size_t memory_limit) {
    LIST_MANAGER_T* manager = mmap(NULL, sizeof(LIST_MANAGER_T), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    manager->head = NULL;
    manager->mem_usage = 0;
    manager->memory_limit = memory_limit;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void list_manager_add(LIST_MANAGER_T* manager, TCP_CONNECTION_T connection) {
    NODE* new_node = malloc(sizeof(NODE));
    new_node->data = connection;
    new_node->next = manager->head;
    manager->head = new_node;
    manager->mem_usage += sizeof(TCP_CONNECTION_T);
}

void list_manager_remove(LIST_MANAGER_T* manager, CONNECTION_ID id) {
    pthread_mutex_lock(&manager->lock);
    NODE* current = manager->head;
    NODE* previous = NULL;

    while (current != NULL) {
        if (current->data.id == id) {
            if (previous == NULL) {
                manager->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            manager->mem_usage -= sizeof(TCP_CONNECTION_T);
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

