int parse_tiff_image(const char *filename, int *bits_per_sample, int *samples_per_pixel, EVP_CIPHER_CTX **cipher) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error: Could not open image file.\n");
        return -1;
    }

    if (TIFFGetField(tif, TIFTAG_SAMPLESPERPIXEL) != 3 ||
        TIFFGetField(tif, TIFTAG_BITSPERSAMPLE) < 8 ||
        TIFFGetField(tif, TIFTAG_BITSPERSAMPLE) > 16) {
        fprintf(stderr, "Error: Unsupported bits per sample.\n");
        TIFClose(tif);
        return -1;
    }

    *bits_per_sample = TIFFGetField(tif, TIFTAG_BITSPERSAMPLE);
    *samples_per_pixel = TIFFGetField(tif, TIFTAG_SAMPLESPERPIXEL);

    uint32_t image_size = TIFFScanlineSize(tif);
    if (TIFFScanlineSize(tif) % (*bits_per_sample) != 0) {
        fprintf(stderr, "Error: Image has extra samples.\n");
        uint32_t extra_samples = image_size / (*bits_per_sample);
        TIFClose(tif);
        return extra_samples;
    }

    EVP_CIPHER_CTX *ctx = NULL;
    const char *cipher_name = getenv("CRYPTO_OPERATION");
    if (cipher_name) {
        const EVP_CIPHER *enc = EVP_get_cipherbyname(cipher_name);
        if (!enc) {
            fprintf(stderr, "Error: Unsupported cryptographic operation.\n");
            TIFClose(tif);
            return -1;
        }

        if (1 != EVP_CIPHER_init(&ctx, enc)) {
            fprintf(stderr, "Error: Failed to initialize cipher.\n");
            TIFClose(tif);
            return -1;
        }
    }

    *cipher = ctx;

    int row;
    uint8_t buffer[TIFFScanlineSize(tif)];

    for (row = 0; row < TIFFNumberOfDirectories(tif); ++row) {
        if (ctx) {
            TIFFReadEncodedTile(tif, row, buffer, TIFFScanlineSize(tif));
            EVP_CIPHER_update(ctx, buffer, TIFFScanlineSize(tif));
        } else {
            TIFFReadTile(tif, row, buffer, TIFFScanlineSize(tif));
        }
    }

    TIFClose(tif);
    return 0;
}
```
