#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void push(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* new_node = create_node(new_data);
    if (!*head_ref) {
        *head_ref = new_node;
        return;
    }
    new_node->next = *head_ref;
    *head_ref = new_node;
}

Node* pop(Node** head_ref) {
    if (*head_ref == NULL)
        return NULL;

    Node* temp = *head_ref;
    *head_ref = (*head_ref)->next;
    free(temp);
    return temp;
}

int is_empty(Node* head) {
    return head == NULL;
}

pthread_mutex_t mutex;

void init_list(int N) {
    pthread_mutex_init(&mutex, NULL);
    int i;
    for (i = 0; i < N; ++i)
        push(&head, (NFAPI_CRC_INDICATION_PDU_T){ .rx_ue_info = i, .rnti = i, .crc_indication = {.crcflag = rand() % 2} });
}

void destroy_list(Node** head) {
    while (*head)
        pop(head);
}

NFAPI_CRC_INDICATION_PDU_T* get_random_entry(Node** head) {
    Node *current = *head;
    int count = 0;

    pthread_mutex_lock(&mutex);

    while (current != NULL && ++count < rand() % current->next->data.crc_indication.crcflag)
        current = current->next;

    pthread_mutex_unlock(&mutex);

    return &current->data;
}
