    for (uint32_t i = 0; i < TIFFNumberOfDirectories(tif); ++i) {
        if (TIFFGetField(tif, i, TIFFTagSampleFormat) != 0) {
            uint16_t sample_format = TIFFDirectorySampleFormat(tif, i);

            if (!samples_found) {
                current_bit_per_sample = TIFFDirectoryBitspersample(tif, i);
                samples_per_pixel = &TIFFDirectorySamplperpixel(tif, i);
                samples_found = 1;
            }

            if (current_bit_per_sample != sample_format) {
                fprintf(stderr, "Warning: Unsupported bits per sample configuration in '%s'\n", filename);
            }
        }
    }

    if (!samples_found) {
        fprintf(stderr, "Error: Missing essential metadata in '%s'\n", filename);
        return;
    }

    *bits_per_sample = current_bit_per_sample;
    *samples_per_pixel = samples_per_pixel ? *samples_per_pixel : 1;

    TIFFClose(tif);
}

