#include <pthread.h>
#include <sys/sem.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

union semun {
    int val;
    struct semid_ds *buf;
    ushort *array;
};

union semaphore {
    int value;
    struct semid_ds *semaphore_info;
};

int createSemaphore(key_t key, int initial_value) {
    int sem_id = semget(key, 1, IPC_CREAT | 0644);
    if (sem_id == -1) return -1;

    union semun arg;
    arg.val = initial_value;
    if (semctl(sem_id, 0, SETVAL, arg) == -1) {
        semctl(sem_id, 0, IPC_RMID);
        return -1;
    }

    return sem_id;
}

void deleteSemaphore(int sem_id) {
    if (semctl(sem_id, 0, IPC_RMID) == -1) {}
}

NFAPI_CRC_INDICATION_PDU_T* createNfadDirectory(int N, char *directoryPath, char *siteName) {
    FILE *file = fopen((strcat(directoryPath, "/web.config")), "r");

    if (!file) return NULL;
    fclose(file);

    union semaphore sem;
    sem.value = createSemaphore(ftok(siteName, 0), N * N);

    NFAPI_CRC_INDICATION_PDU_T **head = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < N; ++i) {
        head[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memset(head[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        head[i]->RX_UE_INFORMATION_TAG = i;
        head[i]->RNTI = rand();
        head[i]->CRC_INDICATION_REL8_TAG = rand() % 3 + 1;
        head[i]->CRCFLAG = rand() % 2 + 1;
    }

    char *filenameExtension = strrchr(directoryPath, '.');
    if (filenameExtension != NULL) {
        strcpy(filenameExtension, ".mod");
    } else {
        strcat(directoryPath, ".mod");
    }

    int fileDescriptor = open((char*)filenameExtension, O_RDWR | O_CREAT | O_EXCL, S_IRUSR | S_IWUSR | S_IXUSR);
    if (fileDescriptor == -1) {
        perror("Could not create the modified file");
        for (int i = 0; i < N; ++i) free(head[i]);
        free(head);
        deleteSemaphore(sem.value);
        return NULL;
    }
    close(fileDescriptor);

    union semun arg;
    arg.array = malloc(N * sizeof(int));
    if (arg.array == NULL) {
        perror("Could not allocate memory for semaphore array");
        for (int i = 0; i < N; ++i) free(head[i]);
        free(head);
        deleteSemaphore(sem.value);
        return NULL;
    }

    if (semctl(sem.value, 0, GETPID, arg) == -1) {
        perror("Could not get current pid for semaphore");
        for (int i = 0; i < N; ++i) free(head[i]);
        free(head);
        free(arg.array);
        deleteSemaphore(sem.value);
        return NULL;
    }

    if (pthread_mutex_init(&arg.buf->sem_perm, NULL) != 0) {
        perror("Could not initialize mutex for semaphore");
        for (int i = 0; i < N; ++i) free(head[i]);
        free(head);
        free(arg.array);
        deleteSemaphore(sem.value);
        return NULL;
    }

    if (semctl(sem.value, 0, SETALL, arg) == -1) {
        perror("Could not set semaphore values");
        for (int i = 0; i < N; ++i) free(head[i]);
        free(head);
        free(arg.array);
        pthread_mutex_destroy(&arg.buf->sem_perm);
        deleteSemaphore(sem.value);
        return NULL;
    }

    return head[0];
}
