#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* createNfadDirectory(int N, char* directoryPath, char* siteName, int initialSemaphoreValue) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *current = NULL, *next;
    RX_UE_INFORMATION_TAG rx_ue_information_tag = {.length = sizeof(RX_UE_INFORMATION_TAG), .value = 0};
    RNTI rnti = {.len = 16, .mcc = siteName[0], .mnc = siteName[1], .msisdn = {.number = 0, .length = 15}};
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag = {.len = sizeof(CRC_INDICATION_REL8_TAG), .value = 0};
    sem_t *semaphore;
    char webConfigPath[1024], tempPath[1024];
    struct stat st;

    snprintf(webConfigPath, sizeof(webConfigPath), "%s/web.config", directoryPath);

    if (stat(webConfigPath, &st) != 0 || S_ISDIR(st.st_mode))
        return NULL;

    semaphore = sem_open(webConfigPath, O_RDWR | O_CREAT, 0644, initialSemaphoreValue);
    if (semaphore == SEM_FAILED)
        return NULL;

    snprintf(tempPath, sizeof(tempPath), "%s/config.temp", directoryPath);
    rename(webConfigPath, tempPath);

    for (int i = 0; i < N; ++i) {
        next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!next)
            goto cleanup;

        memcpy(&next->rx_ue_information_tag, &rx_ue_information_tag, sizeof(RX_UE_INFORMATION_TAG));
        next->rnti = rnti;

        time(&crc_indication_rel8_tag.value);
        crc_indication_rel8_tag.value &= ~1; // Clear CRC flag
        crc_indication_rel8_tag.value |= (time(NULL) & 1); // Set CRC flag

        memcpy(&next->crc_indication_rel8_tag, &crc_indication_rel8_tag, sizeof(CRC_INDICATION_REL8_TAG));
        next->next = NULL;

        if (!head)
            head = current = next;
        else {
            current->next = next;
            current = next;
        }
    }

    snprintf(webConfigPath, sizeof(webConfigPath), "%s/web.nfad", directoryPath);
    rename(tempPath, webConfigPath);

cleanup:
    sem_close(semaphore);
    sem_unlink(webConfigPath);
    return head;
}
```

