int create_pdu_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t* count) {
    *array = (NFAPI_CRUC_INDICATION_PDU_T*)malloc(N_MAX * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) {
        perror("malloc failed");
        return 1; // Error code for memory allocation failure
    }

    *count = 0;

    for (size_t i = 0; i < N_MAX; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* current = &((*array)[*count]);

        if ((current->tag < RX_UE_INFORMATION_TAG_MIN) || (current->tag > RX_UE_INFORMATION_TAG_MAX)) {
            free(*array);
            *array = NULL;
            *count = 0;
            return 2; // Error code for invalid tag value
        }

        if ((current->rnti < RNTI_MIN) || (current->rnti > RNTI_MAX)) {
            free(*array);
            *array = NULL;
            *count = 0;
            return 3; // Error code for invalid RNTI value
        }

        if (!(current->crc_indication.flag & CRCFLAG)) {
            free(*array);
            *array = NULL;
            *count = 0;
            return 4; // Error code for incorrect CRCFLAG value
        }

        ++(*count);
    }

    return 0; // Success
