int process_crc_indications(NFAPI_CRC_INDICATION_PDU_T** buffer, size_t* length, const NFAPI_CRC_INDICATION_PDU_T* data) {
    static NFAPI_CRC_INDICATION_PDU_T* buf = NULL;
