    if (!data || !IS_VALID_RX_UE_INFORMATION_TAG(data->tag) || !IS_VALID_RNTI(data->rnti)) {
        fprintf(stderr, "Invalid RX_UE_INFORMATION_TAG or RNTI value\n");
