#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <time.h>

typedef struct TCP_CONNECTION_T {
    int connection_id;
    struct sockaddr_in remote_address;
    time_t last_active_time;
} TCP_CONNECTION;

typedef struct NODE_T {
    TCP_CONNECTION connection;
    struct NODE_T *next;
    pthread_mutex_t mutex;
} NODE;

struct MEMORY_MANAGER_T {
    void* cache[CACHE_SIZE];
    size_t used, free;
    void (*free_func)(void*);
};

typedef struct MEMORY_MANAGER_T MEMORY_MANAGER;

MEMORY_MANAGER *memory_manager_init(size_t cache_size, void (*free_func)(void*)) {
    MEMORY_MANAGER* mm = malloc(sizeof(MEMORY_MANAGER));
    memset(mm->cache, 0, sizeof(mm->cache));
    mm->used = mm->free = cache_size;
    mm->free_func = free_func;
    return mm;
}

void* memory_manager_alloc(MEMORY_MANAGER* mm) {
    if (mm->free > 0) {
        void* mem = &mm->cache[(--mm->free)];
        memset(mem, 0, sizeof(TCP_CONNECTION));
        return mem;
    } else {
        void* mem = mm->free_func(sizeof(TCP_CONNECTION));
        if (mem) {
            mm->used++;
        }
        return mem;
    }
}

void memory_manager_dealloc(MEMORY_MANAGER* mm, void* ptr) {
    if (ptr) {
        memset(ptr, 0, sizeof(TCP_CONNECTION));
        mm->free_func(ptr);
        mm->free++;
        mm->used--;
    }
}

list* list_init() {
    list *l = malloc(sizeof(list));
    l->head = NULL;
    l->tail = NULL;
    return l;
}

NODE* node_create(TCP_CONNECTION connection) {
    NODE* n = memory_manager_alloc(memory_manager);
    if (n) {
        pthread_mutex_init(&n->mutex, NULL);
        memcpy(&n->connection, &connection, sizeof(TCP_CONNECTION));
        n->next = NULL;
    }
    return n;
}

void node_free(NODE* n) {
    if (n) {
        pthread_mutex_destroy(&n->mutex);
        memory_manager_dealloc(memory_manager, n);
    }
}

list* list_insert(list *l, TCP_CONNECTION connection) {
    NODE* n = node_create(connection);
    if (!n) return l;

    pthread_mutex_lock(&l->mutex);
    if (l->head == NULL) {
        l->head = n;
        l->tail = n;
    } else {
        l->tail->next = n;
        l->tail = n;
    }
    pthread_mutex_unlock(&l->mutex);
    return l;
}

void list_delete(list *l, int connection_id) {
    NODE* current = l->head;
    NODE* temp;

    pthread_mutex_lock(&l->mutex);

    while (current != NULL) {
        if (current->connection.connection_id == connection_id) {
            if (current == l->head) {
                l->head = current->next;
            } else if (current == l->tail) {
                temp = l->tail->prev;
                l->tail = temp;
                l->tail->next = NULL;
            } else {
                temp->next = current->next;
            }
            node_free(current);
            pthread_mutex_unlock(&l->mutex);
            return;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&l->mutex);
}

void list_traverse(list *l) {
    NODE* current = l->head;
    while (current != NULL) {
        printf("ID: %d, Address: %s:%d, Last Active: %ld\n",
               current->connection.connection_id,
               inet_ntoa(current->connection.remote_address.sin_addr),
               ntohs(current->connection.remote_address.sin_port),
               current->connection.last_active_time);
        current = current->next;
    }
}
