#define MAX_NUM_ELEMENTS 1000000 // Maximum number of elements in the array

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _dynamic_array {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity > MAX_NUM_ELEMENTS) {
        fprintf(stderr, "Error: Initial capacity exceeds the maximum allowed limit.\n");
        return NULL;
    }

    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) {
        perror("malloc failed");
        return NULL;
    }

    array->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        perror("calloc failed");
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void resize_dynamic_array(DynamicArray* array, size_t new_capacity) {
    if (new_capacity <= array->size) {
        fprintf(stderr, "Error: New capacity is less than or equal to the current size.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("realloc failed");
        return;
    }

    array->data = new_data;
    array->capacity = new_capacity;
}

void push_back(DynamicArray* array, const NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        resize_dynamic_array(array, array->capacity * 2);
    }

    memcpy(&array->data[array->size], item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size++;
    pthread_mutex_unlock(&array->mutex);
}

