Record* initialize_collection(int* keys, long* offsets, size_t length) {
    if (!keys || !offsets || length == 0) {
        printf("Error: Invalid input arrays.\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    Record* head = NULL, *tail = NULL;
    Record* current = NULL;
    size_t chunkSize = 1000; // Adjust this value according to your requirements.
    size_t processed = 0;

    for (size_t i = 0; i < length && processed < length; ++i) {
        Record* newNode = malloc(sizeof(Record));
        if (!newNode) {
            printf("Error: Out of memory.\n");
            return NULL;
        }

        newNode->value = keys[i];
        newNode->key = i;
        newNode->offset = offsets[i];
        newNode->next = NULL;

        pthread_mutex_lock(&mutex);
        if (head == NULL) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
        pthread_mutex_unlock(&mutex);

        ++processed;

        if (processed % chunkSize == 0) {
            printf("Processed %zu records...\n", processed);
        }
    }

    return head;
}

