class NFAPI_CRC_INDICATION_LIST {
private:
    std::vector<NFAPI_CRCI_INDICATION_T> data;
    std::atomic_uint32_t currentIndex = 0;
    const uint32_t maxSize;
    Log log;

public:
    explicit NFAPI_CRCI_INDICATION_LIST(const uint32_t maxSize) : maxSize(maxSize) {}

    void enqueue(const NFAPI_CRCI_INDICATION_T& pdu) {
        if (data.size() == maxSize) {
            log.error("NFAPI_CRCI_INDICATION_LIST is full");
            return;
        }

        data[currentIndex] = pdu;
        currentIndex++;
        if (currentIndex == maxSize) currentIndex = 0;
    }

    NFAPI_CRCI_INDICATION_T dequeue() {
        if (data.empty()) {
            log.error("NFAPI_CRCI_INDICATION_LIST is empty");
            throw std::runtime_error("dequeue called on an empty list");
        }

        auto result = data[currentIndex - 1];
        currentIndex--;
        return result;
    }
};

class NFAPI {
private:
    NFAPI_CRCI_INDICATION_LIST pduList;
    std::vector<pthread_t> threads;

public:
    explicit NFAPI(const uint32_t maxSize) : pduList(maxSize) {}

    void start() {
        for (uint32_t i = 0; i < maxSize / 4; ++i) { // Adjust threads number according to your needs
            pthread_create(&threads[i], nullptr, &workerThread, static_cast<void*>(&pduList));
        }
    }

private:
