        auto* list = static_cast<NFAPI_CRCI_INDICATION_LIST*>(listPtr);

        while (true) {
            NFAPI_CRCI_INDICATION_T pdu; // Create a new PDU here if needed
            try {
                pdu = list->dequeue();
            } catch (const std::runtime_error& e) {
                continue;
            }

            // Process the PDU here
            // ...

            // Simulate some work before enqueuing a new PDU
            usleep(100 * 1000); // Adjust sleep time as needed

            list->enqueue(pdu);
        }

        return nullptr;
    }
};
