using Microsoft.AspNetCore.Identity;
using System;

public class CustomRandom
{
    private int _min;
    private int _max;

    public CustomRandom(int min, int max)
    {
        if (min > max)
            throw new ArgumentException("Min value must be smaller than max value.");

        _min = min;
        _max = max;
    }

    public int NextInt(bool inclusive = true) => NextInt(_min, _max, inclusive);
    public float NextFloat(bool inclusive = true) => NextFloat(_min, _max, inclusive);
    public T[] GetSequence<T>(int count, bool inclusive = true) => GetSequence<T>(_min, _max, count, inclusive).ToArray();

    private (int min, int max, bool inclusive) GetRange(bool inclusive = true) => (_min, _max, inclusive);

    public int NextInt(int min, int max, bool inclusive = true)
    {
        var (currentMin, currentMax, currentInclusive) = GetRange(inclusive);
        if (min < currentMin || max > currentMax)
            throw new ArgumentException("Range must be within the specified range.");

        Random random = new Random();
        return inclusive ? random.Next(min, max + 1) : random.Next(min, max);
    }

    public float NextFloat(int min, int max, bool inclusive = true)
    {
        var (currentMin, currentMax, currentInclusive) = GetRange(inclusive);
        if (min < currentMin || max > currentMax)
            throw new ArgumentException("Range must be within the specified range.");

        return (float)(NextInt(min, max, inclusive) + 0.5f) / (float)(max - min + 1);
    }

    public IEnumerable<T> GetSequence<T>(int min, int max, int count, bool inclusive = true)
    {
        var (currentMin, currentMax, currentInclusive) = GetRange(inclusive);
        if ((max - min + 1) < count)
            throw new ArgumentException("Count must be less than or equal to the range size.");

        HashSet<T> generatedNumbers = new HashSet<T>();
        Random random = new Random();

        for (int i = 0; i < count; i++)
        {
            T number;
            do
            {
                number = (T)(inclusive ? random.Next(min, max + 1) : random.Next(min, max));
            } while (generatedNumbers.Contains(number));

            generatedNumbers.Add(number);
        }

        return generatedNumbers;
    }

    public override string ToString() => $"Min: {_min}, Max: {_max}";
}

public class Startup
{
    // Your IdentityBuilder configuration goes here, including account expiration, user lockout defaults, and custom validation logic.
}
```

