    private int _max;

    public CustomRandom(int min, int max)
    {
        if (min > max)
            throw new ArgumentException("Min value must be less than or equal to max.");

        _min = min;
        _max = max;
    }

    public int NextInt()
    {
        return ThreadSafeRandom.Next(_min, _max);
    }

    public float NextFloat(bool inclusive)
    {
        var random = ThreadSafeRandom.NextDouble();
        if (inclusive)
            return (_min + (random * (_max - _min)));
        else
            return (_min + random * (_max - _min));
    }

    public override string ToString()
