        var sb = new StringBuilder($"{nameof(CustomRandom)}({_min}, {_max})");
        if (ThreadSafeRandom.GeneratedCount > 0)
            sb.AppendFormat($", generated: {ThreadSafeRandom.GeneratedCount} values.");
        return sb.ToString();
