import pandas as pd

def process_csv(file_path, dynamic_criteria, columns_to_aggregate):
    data = pd.read_csv(file_path)

    # Handle missing or invalid values
    data = data.fillna(0)
    data = data.loc[~data.isnull().any(axis=1)]

    # Aggregate data across specified columns
    aggregated_data = data.groupby([columns_to_aggregate]).agg({dynamic_criteria: 'sum'})

