void initialize_queue(QUEUE_T* q) {
    q->head = NULL;
    sem_init(&q->lock, 0, 1);
    sem_init(&q->queue_not_empty, 0, 0);
    pthread_mutex_init(&q->stats_lock, NULL);
}

void enqueue(QUEUE_T* q, MAC_FRAME* frame) {
    NODE* new_node = malloc(sizeof(NODE));
    new_node->frame = *frame;
    new_node->next = q->head;
    q->head = new_node;
    sem_post(&q->queue_not_empty);
}

MAC_FRAME* dequeue(QUEUE_T* q) {
    NODE* node = NULL;

    sem_wait(&q->lock);
    if (q->head != NULL) {
        node = q->head;
        q->head = node->next;
    }
    sem_post(&q->lock);

    return &node->frame;
}

