char *manage_string(const char *input) {
    size_t len = strlen(input);
    if (len > STRING_SIZE_LIMIT) {
        pthread_mutex_lock(&logger_mutex);
        fprintf(log_file, "Buffer overflow: %s\n", input);
        pthread_mutex_unlock(&logger_mutex);
        return NULL;
    }

    char *result = realloc(input, len + 2); // Allocate for slash
    if (!result) {
        pthread_mutex_lock(&logger_mutex);
        fprintf(log_file, "Insufficient memory: %s\n", input);
        pthread_mutex_unlock(&logger_mutex);
        return NULL;
    }

    result[len] = '/';
    result[len + 1] = '\0';

    return result;
}

void init_linked_list() {
    current_node = malloc(sizeof(struct node));
    if (!current_node) {
        pthread_mutex_lock(&logger_mutex);
        fprintf(log_file, "Insufficient memory: linked list\n");
        pthread_mutex_unlock(&logger_mutex);
        exit(EXIT_FAILURE);
    }

    current_node->data.value = rand() % 100 + 1;
    current_node->next = NULL;
}

void add_to_list(struct node *node) {
    pthread_rwlock_wrlock(&list_lock);

    if (list_size >= MAX_LIST_SIZE) {
        pthread_rwlock_unlock(&list_lock);
        return;
    }

    struct node **current = &records[list_size++];
    *current = node;

