use tiff::Reader as TiffReader;

pub fn extract_image_info(filepath: &str) -> Result<(u32, u32), Box<dyn std::error::Error>> {
    let mut reader = TiffReader::new(std::fs::File::open(filepath)?)?;
    let samples_per_pixel = reader.samples_per_sample().unwrap();
    let bits_per_sample = match samples_per_pixel {
        1 => 8, // For unsigned bytes (0-255)
        2 => 16, // For unsigned shorts (0-65535)
        4 => 32, // For unsigned ints (0-4294967295)
        8 => 64, // For floating point numbers
        _ => return Err(Box::new(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Invalid number of samples per pixel.",
        ))),
    };
    let image_width = reader.image_width().unwrap();
    let image_height = reader.image_height().unwrap();
    Ok((image_width, image_height))
}
