                }
                free(compressedPayload);
                continue;
            }
            free(payload);
            payload = compressedPayload;
        }

        /* Process the packet concurrently */
        sem_wait(&config->mutex);
        if (config->thread_count < config->thread_count) {
            pthread_create(&config->threads[config->thread_count++], NULL, processPacketThread, &packet);
