    uint32_t rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void populate_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    for (size_t i = 0; i < NUM_ELEMENTS; ++i) {
        list[i].rxi = i * 123 + time(NULL);
        list[i].rnti = rand();
        list[i].crcflag = rand() % 2;
    }
}

void read_integers(const char* filename, int* data) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return;
    }

    size_t n = 0;
    while (1) {
        int num;
        if (fscanf(file, "%d", &num) != 1) break; // EOF or error
        data[n++] = num;
    }

    fclose(file);

    if (!n) printf("No integers provided.\n");
}

int find_largest_index(const int* data, size_t len) {
    size_t largest_index = 0;
    int largest = data[0];

    for (size_t i = 1; i < len; ++i) {
        if (data[i] > largest) {
            largest = data[i];
            largest_index = i;
        }
    }

    return largest_index;
}

void generate_filename(const char* base, char* output, size_t max_chars) {
    strncpy(output, base, max_chars);

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
