    private static final ExecutorService EXECUTOR = Executors.newCachedThreadPool();
    private static final int MAX_THRESHOLD = 10485760; // 10 MB
    private static final int CHUNK_SIZE = 10;
    private static final HashFunction hashFunction = HashString.murmur3_32Bit();

    public List<ImageWithMetadata> optimizeImageProcessingPipeline(List<Path> imageFilePaths, int targetResolution, long maxFileSize, int bufferSize, ConcurrentHashMap<String, AtomicInteger> concurrencyMap, List<Float> qualitySettings, boolean applyLosslessCompression) {
        if (Objects.isNull(imageFilePaths) || Objects.isNull(concurrencyMap)) {
            LOGGER.severe("Invalid input - imageFilePaths or concurrencyMap is null");
            return null;
        }

        List<ImageWithMetadata> optimizedImages = new ArrayList<>();
        ConcurrentHashMap<String, ImageWithMetadata> processedImages = new ConcurrentHashMap<>();

        try {
            for (Path path : imageFilePaths) {
                if (!Files.exists(path)) {
                    LOGGER.warning("File not found: " + path);
                    continue;
                }

                long fileSize = Files.size(path);
                if (fileSize > maxFileSize) {
                    LOGGER.severe("File size exceeds maximum limit: " + path);
                    continue;
                }

                ImageAndMetadata imageAndMetadata = processImage(path, qualitySettings, applyLosslessCompression);
                if (imageAndMetadata == null) {
                    continue;
                }

                String metadataHashCode = hashFunction.newHasher()
                        .putString(imageAndMetadata.getMetadata(), StandardCharsets.UTF_8)
                        .hash().asInt();

                if (processedImages.containsKey(metadataHashCode)) {
                    LOGGER.warning("Collision detected: " + imageAndMetadata.getPath());
                }

                processedImages.put(metadataHashCode, imageAndMetadata);

                AtomicInteger concurrencyCounter = concurrencyMap.get(metadataHashCode);
                if (concurrencyCounter == null) {
                    concurrencyCounter = new AtomicInteger(1);
                    concurrencyMap.putIfAbsent(metadataHashCode, concurrencyCounter);
                }

                Runnable imageProcessingTask = () -> optimizedImages.add(imageAndMetadata);
                EXECUTOR.execute(() -> {
                    try {
                        Thread.sleep(bufferSize); // Adjust the sleep time as per buffer size
                        imageProcessingTask.run();
                    } catch (InterruptedException e) {
                        LOGGER.severe("Thread interrupted: " + e.getMessage());
                    }
                });
            }
        } catch (Exception e) {
            LOGGER.severe("Error during image processing: " + e.getMessage());
        }

        return optimizedImages;
    }

