// Define a custom packet header structure
typedef struct {
    uint8_t ip_version;
    uint8_t ip_hl; // header length
    uint8_t tos; // type of service
    uint16_t ip_tot_len; // total length
    uint16_t ip_id; // identification
    uint16_t ip_frag_offset; // fragment offset
    uint8_t ip_ttl; // time to live
    uint8_t ip_protocol; // protocol
    uint16_t tcp_chksum; // header checksum
    struct in_addr src_ip, dst_ip; // source and destination IP addresses
} tcp_packet_header;

// Custom comparator for qsort to prioritize by time of arrival (in seconds)
static inline int compare_time(const void *a, const void *b) {
    return (*(time_t*)a - *(time_t*)b);
}

struct packet_queue {
    tcp_packet_header **headers;
    size_t capacity, size;
    pthread_mutex_t lock;
    sem_t free_space;
};

void packet_queue_init(struct packet_queue *q, size_t max_size) {
    q->capacity = max_size + 1; // +1 for the sentinel value
    q->headers = malloc(sizeof(tcp_packet_header*) * q->capacity);
    q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
    sem_init(&q->free_space, 0, q->capacity); // initial value is the maximum number of free spaces
}

void packet_queue_destroy(struct packet_queue *q) {
    for (size_t i = 0; i < q->capacity; ++i) {
        if (q->headers[i]) {
            free(q->headers[i]);
        }
    }
    free(q->headers);
    pthread_mutex_destroy(&q->lock);
    sem_destroy(&q->free_space);
}

tcp_packet_header* packet_queue_push(struct packet_queue *q, const void *data, size_t data_size) {
    if (q->capacity <= q->size) {
        // Resize the packet queue when it's full
        size_t new_capacity = q->capacity * 2;
        tcp_packet_header **new_headers = realloc(q->headers, sizeof(tcp_packet_header*) * new_capacity);
        if (!new_headers) {
            fprintf(stderr, "Out of memory\n");
            return NULL;
        }
        q->headers = new_headers;
        q->capacity = new_capacity;
    }

    // Create a new packet header and fill it with data from the given buffer
    tcp_packet_header *new_header = malloc(sizeof(tcp_packet_header));
    if (!new_header) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }
    memcpy(new_header, data, data_size);

    // Initialize the header with valid IP version, header length, and protocol
    new_header->ip_version = 4;
    new_header->ip_hl = ((int)(sizeof(tcp_packet_header)) >> 2); // Header length field is in 32-bit words
    new_header->ip_protocol = IPPROTO_TCP;

    pthread_mutex_lock(&q->lock);
    while (sem_wait(&q->free_space) < 0 && errno != EINTR) {
        fprintf(stderr, "Semaphore wait failed\n");
        free(new_header);
        pthread_mutex_unlock(&q->lock);
        return NULL;
    }

    q->headers[q->size++] = new_header;
    pthread_mutex_unlock(&q->lock);

    // Sort the packet queue based on time of arrival
    qsort(q->headers, q->size, sizeof(tcp_packet_header*), compare_time);

    return new_header;
}

// Log a warning and return NULL for malformed packets
tcp_packet_header* process_packet(const void *data, size_t data_size) {
    // Check if the packet size is valid and has a correct header structure
    if (data_size < sizeof(tcp_packet_header)) {
        fprintf(stderr, "Malformed packet: too short\n");
        return NULL;
    }

    // Parse the packet header from the given buffer
    const tcp_packet_header *packet = data;

    // Additional validation and processing of the packet can be done here based on network configuration and varying packet sizes

    return (tcp_packet_header*)data;
}
