#include <locale.h>

#define MAX_FILENAME_LENGTH 256

typedef struct {
    char* base;
    size_t len;
} Filename;

Filename filename_create(const char* input) {
    Filename ret;
    if (input == NULL || strlen(input) > MAX_FILENAME_LENGTH - 1) return ret;
    ret.base = strdup(input);
    ret.len = strlen(ret.base);
    return ret;
}

void filename_truncate(Filename* filename, size_t max_length) {
    if (filename->len > max_length) {
        filename->base[max_length - 1] = '\0';
        filename->len = max_length - 1;
    }
}

int extension_count(const Filename filename) {
    int count = 0;
    const char* last_dot = strrchr(filename.base, '.');
    if (last_dot != NULL) {
        do {
            last_dot = strrchr(last_dot + 1, '.');
            if (last_dot != NULL) count++;
        } while (last_dot != NULL);
    }
    return count;
}

void filename_set_extension(Filename* filename, const char* extension) {
    size_t new_len = filename->len + strlen(extension) + 1;
    if (new_len > MAX_FILENAME_LENGTH - 1) {
        filename_truncate(filename, MAX_FILENAME_LENGTH - strlen(extension) - 1);
        strcat(filename->base + filename->len, extension);
    } else {
        filename->base[filename->len] = '\0';
        strcat(filename->base, extension);
    }
}

Filename filename_modify(const char* input, const char* base) {
    Filename filename = filename_create(input);
    if (extension_count(filename) > 0 && strlen(base) > 0) {
        filename_set_extension(&filename, base);
