        filename_truncate(&filename, filename.len + strlen(base));
        strcat(filename.base + filename.len, base);
    }
    return filename;
}

char* create_unique_identifier(size_t length) {
    char* identifier = malloc(length);
    if (identifier == NULL) return NULL;

    time_t now = time(NULL);
    snprintf(identifier, length, "%ld", (long)now);

    // Optionally append a hash for added uniqueness.
    // ...

    return identifier;
}

Filename filename_generate_unique(const char* input, const char* base) {
    Filename filename = filename_modify(input, base);
    if (filename.len + strlen(create_unique_identifier(strlen(filename.base))) > MAX_FILENAME_LENGTH - 1) {
        filename_truncate(&filename, MAX_FILENAME_LENGTH - strlen(create_unique_identifier(strlen(filename.base))) - 1);
    }
    strcat(filename.base + filename.len, create_unique_identifier(strlen(filename.base)));
    return filename;
}
