#include <stdbool.h>

typedef struct {
    // Your NFAPI_RX_FRAME_T structure here
} NFAPI_RX_FRAME_T;

typedef struct mem_block {
    size_t size;
    void *data;
    struct mem_block *next;
} mem_block_t;

static mem_block_t *head = NULL;
static pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;

NFAPI_RX_FRAME_T* array_init(size_t size) {
    NFAPI_RX_FRAME_T *arr = malloc(sizeof(NFAPI_RX_FRAME_T) * size);
    if (!arr) return NULL;
    memset(arr, 0, sizeof(NFAPI_RX_FRAME_T) * size);
    return arr;
}

void array_push(NFAPI_RX_FRAME_T **array, NFAPI_RX_FRAME_T *frame) {
    pthread_mutex_lock(&mtx);
    mem_block_t *block = malloc(sizeof(mem_block_t));
    if (!block) goto unlock_and_exit;
    block->size = sizeof(NFAPI_RX_FRAME_T);
    block->data = frame;
    block->next = head;
    head = block;
unlock_and_exit:
    pthread_mutex_unlock(&mtx);
}

void array_pop(NFAPI_RX_FRAME_T **array, size_t index) {
    pthread_mutex_lock(&mtx);
    mem_block_t *current = head;
    mem_block_t *prev = NULL;
    size_t i = 0;

    while (i < index && current != NULL) {
        prev = current;
        current = current->next;
        i++;
    }

    if (current == NULL) goto unlock_and_exit;

    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
unlock_and_exit:
    pthread_mutex_unlock(&mtx);
}

