typedef struct {
    /* Your NFAPI_RX_FRAME_T structure goes here */
} NFAPI_RX_FRAME_T;

struct frame_queue {
    NFAPI_RX_FRAME_T* frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
};

struct frame_queue* create_frame_queue(size_t initial_capacity) {
    struct frame_queue* queue = malloc(sizeof(*queue));
    if (!queue) return NULL;

    queue->frames = calloc(initial_capacity, sizeof(NFAPI_RX_FRAME_T));
    if (!queue->frames) {
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->count = 0;

    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);

    return queue;
}

void destroy_frame_queue(struct frame_queue* queue) {
    free(queue->frames);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_full);
    pthread_cond_destroy(&queue->not_empty);
    free(queue);
}

void enqueue(struct frame_queue* queue, const NFAPI_RX_FRAME_T* frame) {
    // Implement the logic for handling out-of-order frames and prioritization based on urgency.
    pthread_mutex_lock(&queue->lock);

    while (queue->count == queue->capacity) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }

    // Add your logic for handling incoming frame
    queue->frames[queue->count++] = *frame;

    if (queue->count == 1)
        pthread_cond_signal(&queue->not_empty);
    else
        pthread_cond_broadcast(&queue->not_full);

    pthread_mutex_unlock(&queue->lock);
}

const NFAPI_RX_FRAME_T* dequeue(struct frame_queue* queue) {
    // Implement the logic for dequeuing and handling empty queue situations.
    pthread_mutex_lock(&queue->lock);

    while (queue->count == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }

    const NFAPI_RX_FRAME_T* frame = &(queue->frames[--queue->count]);

    if (queue->count == queue->capacity / 2)
        pthread_cond_signal(&queue->not_full);

    pthread_mutex_unlock(&queue->lock);

    return frame;
}
```

