function traverseDOM(root, selector, callback) {
    if (!root || !selector || !callback) return;

    var node = root;
    if (node.matches && node.matches(selector)) callback(node);
    else {
        for (let child of root.children) traverseDOM(child, selector, callback);
    }
}

function getElementsBySelector(root, selector) {
    var results = [];
    traverseDOM(root, selector, function (element) {
        if (!results.includes(element))
            results.push(element);
    });
    return results;
}
