std::string generate_unique_filename(const std::string& input_filename, const std::string& extension) {
  // Generate a timestamp in ISO 8601 format
  auto now = boost::gregorian::date_facet::to_iso_extended_string(*boost::local_time::local_day());
  auto rnd = new boost::mt19937;
  // Use a random device to seed the generator
  rnd->seed(std::random_device{}());
  std::uniform_int_distribution<> dis(0, 1000000);
  int random_number = dis(*rnd);

  string unique_identifier = to_string(random_number);

  size_t pos = input_filename.find_last_of('.');
  if (pos != std::string::npos) {
    extension = input_filename.substr(pos);
    input_filename.erase(pos);
  }

  // Ensure the filename adheres to OS-specific naming conventions and does not exceed 255 characters
  string new_filename = input_filename + unique_identifier + extension;
  for (char& c : new_filename) {
    if (!isalnum(c) && c != '_' && c != '-')
      c = '_'; // Replace invalid characters with an underscore
  }

  // Check for existing files and generate a unique filename if needed
  int count = 1;
  string new_filename_with_count = new_filename;
  while (fs::exists(new_filename)) {
    count++;
    new_filename_with_count = new_filename + to_string(count);
    new_filename = new_filename_with_count;
  }

  return new_filename;
}

