void allocate_memory(size_t *keys, size_t *longs, size_t *records, size_t max_keys, size_t *used_keys) {
    *keys = malloc(max_keys * sizeof(size_t));
    *longs = malloc((*used_keys + 1) * sizeof(long));
    *records = malloc((*used_keys + 1) * sizeof(Record));
}

int find_empty_key(size_t keys[], size_t used_keys) {
    for (size_t i = 0; i < max_keys; ++i) {
        if (keys[i] == 0)
            return i;
    }
    return -1;
}

void randomize(Record *records, size_t used_keys, int min, int max) {
    srand(time(NULL));
    for (size_t i = 0; i < used_keys; ++i)
        records[i].value = rand() % (max - min + 1) + min;
}

void serialize(const char *filename, size_t keys[], long longs[], Record *records, size_t used_keys) {
    FILE *file = fopen(filename, "wb");
    if (!file)
        return;

    fwrite(keys, sizeof(size_t), used_keys + 1, file);
    fwrite(longs, sizeof(long long), used_keys + 1, file);
    fwrite(records, sizeof(Record), used_keys, file);
    fclose(file);
}

