    size_t empty_key = find_empty_key(*keys, *used_keys);
    if (empty_key != -1) {
        keys[empty_key] = 1;
        (*longs)[*used_keys] = 0;
        (*records)[*used_keys].key = empty_key;
        (*records)[*used_keys].offset = 0;
        (*records)[*used_keys].value = rand() % (max - min + 1) + min;
        (*used_keys)++;
    }
}

