typedef struct hash_table {
    size_t capacity; // current capacity of the hash table
    size_t num_elements; // number of elements in the hash table
    Record** data; // array of records
    void* external_source; // pointer to external data source for key validation
    bool(*key_validation)(int32_t); // function pointer for key validation logic
} HashTable;

// Initialize a new empty hash table with the given capacity and external data source
HashTable* create_hash_table(size_t initial_capacity, void* external_source, bool(*key_validation)(int32_t)) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        perror("Out of memory");
        return NULL;
    }

    table->capacity = initial_capacity;
    table->num_elements = 0;
    table->data = calloc(initial_capacity, sizeof(Record*));
    if (!table->data) {
        perror("Out of memory");
        free(table);
        return NULL;
    }
    table->external_source = external_source;
    table->key_validation = key_validation;

    return table;
}

// Insert a new record into the hash table, returning true if successful and false otherwise
bool insert(HashTable* table, int32_t key, int64_t offset) {
    if (!table->key_validation || !table->key_validation(key)) {
        return false;
    }

    size_t index = hash(key, table->capacity);
    for (size_t i = 0; i < table->capacity; ++i) {
        if (!table->data[index + i]) {
            table->data[index + i] = malloc(sizeof(Record));
            if (!table->data[index + i]) {
                perror("Out of memory");
                return false;
            }
            table->num_elements++;
            break;
