            return false;
        }
    }

    table->data[index]->key = key;
    table->data[index]->offset = offset;
    return true;
}

// Calculate the hash index for a given key and capacity
size_t hash(int32_t key, size_t capacity) {
    // Simple hash function using the key as an index modulo the capacity
    return key % capacity;
}

// Free all allocated memory associated with the hash table, including records and external data source
void destroy_hash_table(HashTable* table) {
    if (!table) {
        return;
    }

    for (size_t i = 0; i < table->capacity; ++i) {
        Record* record = table->data[i];
        if (record) {
            free(record);
        }
    }

    free(table->data);
    free(table);

    // Free external data source if it was allocated dynamically
    if (table->external_source && table->external_source != NULL) {
        free(table->external_source);
    }
}

