// Function to generate a unique timestamp-based name for a file
void generate_unique_name(char *filename, char *ext) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);

    snprintf(filename + strlen(filename), sizeof(filename) - strlen(filename) - strlen(ext) - 9, "%04d%02d%02d-%02d%02d%02d", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec);
    int rnd = rand() % 1000;
    snprintf(filename + strlen(filename), sizeof(filename) - strlen(ext) - 9, "-%03d%s", rnd, ext);
}

// Function to compress a file using gzip
int compress_file(const char *input, const char *output, int level) {
    FILE *in = fopen(input, "rb");
    gzFile out = gzopen(output, "wb" , level);
    if (!in || !out) return -1;

    char buffer[1024];
    while (fread(buffer, 1, sizeof(buffer), in)) {
        gzwrite(out, buffer, fread(buffer, 1, sizeof(buffer), in));
    }

    fclose(in);
    gzclose(out);
    return 0;
}

// Function to rename a file and update its metadata, ensuring thread safety
void safe_rename(const char *oldname, const char *newname) {
    pthread_mutex_lock(&lock);

    // Compress the file before renaming
    int ret = compress_file(oldname, newname, 9);
    if (ret == -1) {
        retry_count++;
        if (retry_count > max_retries) {
            sprintf(admin_email, "admin@example.com");
            send_email("Rename failure", "Failed to rename file: %s -> %s after %d retries.\nOriginal filename: %s\nNew filename: %s.", admin_email, oldname, newname, max_retries, oldname, newname);
        }
    } else {
        struct stat st;
        stat(newname, &st);
        if (st.st_size == 0) { // File was compressed successfully and is empty, remove it
            remove(newname);
        } else {
            retry_count = 0;
            // Update the file's metadata to reflect compression
            // ...
        }
    }

    pthread_mutex_unlock(&lock);
}

// Helper function to record renaming attempts for auditing purposes
