}

int rename_file(char *path, int level) {
    ctx = malloc(sizeof(Context));
    strcpy(ctx->path, path);

    DIR *dir = opendir(path);
    if (!dir) return -1; // Invalid directory path

    struct dirent *de;
    while ((de = readdir(dir)) != NULL) {
        char filename[256];
        strcpy(filename, de->d_name);
        if (strlen(filename) > 255 || strchr(filename, '/')) continue; // Skip files with invalid names or containing slashes

        generate_unique_name(filename, de->d_name);
        char newpath[256];
        snprintf(newpath, sizeof(newpath), "%s/%s", path, filename);

        if (access(newpath, F_OK) != 0 || access(newpath, W_OK) == 0) continue; // Skip files that don't exist or can't be written to due to permissions

        safe_rename(de->d_name, filename);
