{
    private readonly int _min, _max;

    public CustomRandom(int min, int max)
    {
        if (min > max) throw new ArgumentException("Min value cannot be greater than max.");
        _min = min;
        _max = max;
    }

    public int Next() => new Random((int)Math.Floor(DateTime.Now.Ticks)).Next(_min, _max + 1);
    public double NextDouble() => (double)_next();
    public float NextSingle() => (float)_next();

    private int _next() => new Random((int)Math.Floor(DateTime.Now.Ticks)).Next(_min, _max + 1);

