        exit(EXIT_FAILURE);
    }
    return ptr;
}

void custom_free(void* ptr) {
    int status = munmap(ptr, sizeof(TCP_CONNECTION));
    if (status == -1) {
        perror("munmap failed");
        exit(EXIT_FAILURE);
    }
}

// Dynamic linked list node structure
typedef struct NODE_T {
    TCP_CONNECTION connection;
    struct NODE_T* next;
} NODE;

// Thread-safe linked list management
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NODE* head = NULL;

void insert(TCP_CONNECTION connection) {
    NODE* new_node = (NODE*)custom_malloc(sizeof(NODE));
    memcpy(&new_node->connection, &connection, sizeof(TCP_CONNECTION));
    new_node->next = head;
    pthread_mutex_lock(&list_mutex);
    if (head != NULL) {
        head = new_node;
    } else {
        head = new_node;
    }
    pthread_mutex_unlock(&list_mutex);
}

void delete(uint32_t connection_id) {
    NODE* current = head;
    NODE** prev = &head;

    while (current != NULL) {
        if (current->connection.connection_id == connection_id) {
            *prev = current->next;
            custom_free(current);
            break;
        }
        prev = &current->next;
        current = current->next;
    }
