['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_RX_FRAME_T;

typedef struct slab_t {
    void *slab_data;
    size_t slab_size;
    int slab_index; // index of this slab in the list of slabs
    struct slab_t *next;
} Slab;

typedef struct allocator_t {
    Slab *slabs;
    int num_slabs;
    int slab_size;
    int max_slabs;
    int num_frames;
    double percent_used;
    pthread_mutex_t lock;
    void (*log_callback)(const char *msg);
} Allocator;

void slab_init(Slab *slab, void *data, size_t size, int index) {
    slab->slab_data = data;
    slab->slab_size = size;
    slab->slab_index = index;
    slab->next = NULL;
}

Allocator *allocator_init(int num_slabs, int slab_size, void (*log_cb)(const char *msg)) {
    Allocator *allocator = malloc(sizeof(Allocator));
    allocator->slabs = NULL;
    allocator->num_slabs = 0;
    allocator->slab_size = slab_size;
    allocator->max_slabs = num_slabs;
    allocator->num_frames = 0;
    allocator->percent_used = 0.0;
    pthread_mutex_init(&allocator->lock, NULL);
    allocator->log_callback = log_cb;
    return allocator;
}

void *frame_alloc(Allocator *allocator) {
    if (pthread_mutex_lock(&allocator->lock)) {
        fprintf(stderr, "Error: Mutex lock failed\n");
        return NULL;
    }

    Slab *current = allocator->slabs;
    void *frame = NULL;

    // Check all slabs
    while (current != NULL) {
        // If the slab is empty, allocate a new frame from this slab
        if (current->slab_data == NULL) {
            frame = current->slab_data;
            current->slab_data = calloc(1, allocator->slab_size);
            if (!frame) {
                fprintf(stderr, "Error: Memory allocation failed\n");
                pthread_mutex_unlock(&allocator->lock);
                return NULL;
            }
            current->num_frames++;
            allocator->num_frames++;
            allocator->percent_used = (double)allocator->num_frames / (allocator->num_slabs * allocator->slab_size);
            if (allocator->log_callback) {
                allocator->log_callback("Allocation: frame");
            }
            break;
        }

        // Move to the next slab
        current = current->next;
    }

    // If no empty slab was found, create a new one if necessary
    if (frame == NULL && allocator->num_slabs < allocator->max_slabs) {
        Slab *new_slab = malloc(sizeof(Slab));
        slab_init(new_slab, NULL, allocator->slab_size, allocator->num_slabs);
        if (!new_slab) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            pthread_mutex_unlock(&allocator->lock);
            return NULL;
        }
        current = &allocator->slabs[allocator->num_slabs - 1];
        current->next = new_slab;
        allocator->slabs = realloc(allocator->slabs, (allocator->num_slabs + 1) * sizeof(Slab));
        if (!allocator->slabs) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            pthread_mutex_unlock(&allocator->lock);
            free(new_slab);
            return NULL;
        }
        allocator->num_slabs++;
    }

    // Release the lock and return the allocated frame
    pthread_mutex_unlock(&allocator->lock);
    return frame;
}

void frame_free(Allocator *allocator, void *frame) {
    if (pthread_mutex_lock(&allocator->lock)) {
        fprintf(stderr, "Error: Mutex lock failed\n");
        return;
    }

    // Find the slab containing this frame and decrement its counter
    Slab *current = allocator->slabs;
    for (int i = 0; i < allocator->num_slabs; ++i) {
        if (current->slab_data == frame) {
            current->num_frames--;
            allocator->num_frames--;
            break;
        }
        current = current->next;
    }

    // If the slab is empty, free it and move to the next one
    if (current->num_frames == 0) {
        void *tmp = current->slab_data;
        current->slab_data = NULL;
        free(tmp);
        Slab *next = current->next;
        free(current);
        current = next;
    }

    // Release the lock
    pthread_mutex_unlock(&allocator->lock);
}
```

This code provides a basic implementation of a dynamic array manager with slab allocator for managing memory efficiently. The provided functions include `allocator_init()`, which initializes an allocator instance, and `frame_alloc()` and `frame_free()`, which handle allocation and deallocation of `NFAPI_RX_FRAME_T` structures.

The code also includes a custom synchronization mechanism using mutexes for thread safety. Additionally, the memory usage is monitored by keeping track of the number of allocated frames and the percentage of used vs. available memory. A configurable logging system is implemented to record allocation and deallocation events.

To use this implementation, you can create an allocator instance, configure its parameters as needed (e.g., slab size, number of slabs, log callback), and call `frame_alloc()` and `frame_free()` as required within your application. The logging system can be customized based on your requirements by providing a suitable log callback function.']

