#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct MAC_TRANSACTION_RECORD {
    uint32_t sequence_number;
    int tx_power_level;
    bool acknowledge_flag;
    struct MAC_TRANSACTION_RECORD *next;
} MAC_TRANSACTION_RECORD;

typedef struct NODE_LIST {
    pthread_mutex_t lock;
    MAC_TRANSACTION_RECORD *head;
    MAC_TRANSACTION_RECORD *tail;
    size_t size;
} NODE_LIST;

NODE_LIST* node_list_create() {
    NODE_LIST* list = malloc(sizeof(NODE_LIST));
    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    list->size = 0;
    return list;
}

void node_list_destroy(NODE_LIST* list) {
    MAC_TRANSACTION_RECORD *current, *next;
    pthread_mutex_lock(&list->lock);
    current = list->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->lock);
}

MAC_TRANSACTION_RECORD* node_list_insert(NODE_LIST *list, MAC_TRANSACTION_RECORD *node) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    ++(list->size);
    pthread_mutex_unlock(&list->lock);
    return node;
}

MAC_TRANSACTION_RECORD* node_list_remove(NODE_LIST *list, uint32_t sequence_number) {
    MAC_TRANSACTION_RECORD *current, *prev;
    pthread_mutex_lock(&list->lock);
    current = list->head;
    prev = NULL;
    while (current != NULL) {
        if (current->sequence_number == sequence_number) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            if (current == list->tail) {
                list->tail = prev;
            }
            MAC_TRANSACTION_RECORD *temp = current;
            current = current->next;
            free(temp);
            --(list->size);
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

MAC_TRANSACTION_RECORD* node_list_find(NODE_LIST *list, uint32_t sequence_number) {
    MAC_TRANSACTION_RECORD *current = list->head;
    while (current != NULL) {
        if (current->sequence_number == sequence_number) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}
