typedef struct memory_pool {
    void *memory;
    size_t size;
    struct memory_pool *next;
} memory_pool_t;

struct custom_mempool {
    memory_pool_t *head;
    size_t block_size;
};

void init_custom_mempool(struct custom_mempool *mempool, size_t block_size) {
    mempool->block_size = block_size;
    mempool->head = NULL;
}

void *custom_malloc(struct custom_mempool *mempool, size_t size) {
    if (size > mempool->block_size) {
        return malloc(size);
    }

    memory_pool_t *current = mempool->head;
    if (!current) {
        current = (memory_pool_t *)malloc(sizeof(memory_pool_t));
        current->memory = malloc(mempool->block_size);
        current->size = mempool->block_size;
        current->next = NULL;
        mempool->head = current;
    }

    memory_pool_t *temp = current;
    while (current->next && current->next->size <= size) {
        temp = current;
        current = current->next;
    }

    if (!current->next) {
        current->next = (memory_pool_t *)malloc(sizeof(memory_pool_t));
        current->next->memory = malloc(mempool->block_size);
        current->next->size = mempool->block_size;
        current->next->next = NULL;
    }

    void *result = ((char *)current->next + size) - mempool->block_size;
    temp->next = current->next->next;

    return result;
}

void custom_free(struct custom_mempool *mempool, void *ptr) {
    if (ptr >= mempool->head && ptr < mempool->head + mempool->block_size) {
        free(mempool->head);
        mempool->head = NULL;
        return;
    }

    memory_pool_t *current = mempool->head;
    while (current != NULL) {
        if ((char *)ptr >= ((char *)current + current->size) &&
            (char *)ptr < ((char *)current + current->size + mempool->block_size)) {
            free(ptr);
            current->size -= (uintptr_t)(ptr - ((char *)current + current->size));
        }
        current = current->next;
    }
}

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
dl_pdu_t *head = NULL;
uint32_t lost_packets = 0;

void add_dl_pdu(const dl_pdu_t *new_pdu) {
    pthread_mutex_lock(&list_mutex);
    dl_pdu_t *current = head;
    bool found_gap = false;
    uint32_t last_pdcp_sn = 0;

    while (current != NULL) {
        if (current->pdcp_sn > new_pdu->pdcp_sn) {
            break;
        }

        if (!found_gap && current->pdcp_sn == new_pdu->pdcp_sn - 1) {
            found_gap = true;
            lost_packets++;
        }

        last_pdcp_sn = current->pdcp_sn;
        current = current->next;
    }

    if (last_pdcp_sn != new_pdu->pdcp_sn - 1 || !found_gap) {
        dl_pdu_t *new_node = (dl_pdu_t *)custom_malloc(my_mempool, sizeof(dl_pdu_t));
        memcpy(new_node, new_pdu, sizeof(dl_pdu_t));
        new_node->next = head;
        head = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
}

void remove_dl_pdu(uint32_t pdcp_sn) {
    pthread_mutex_lock(&list_mutex);
    dl_pdu_t *current = head;
    dl_pdu_t **prev = &head;

    while (current != NULL) {
        if (current->pdcp_sn == pdcp_sn) {
            *prev = current->next;
            free(current);
            break;
        }

        prev = &current->next;
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
}

uint32_t get_lost_packets() {
    uint32_t result;
    pthread_mutex_lock(&list_mutex);
    result = lost_packets;
    lost_packets = 0;
    pthread_mutex_unlock(&list_mutex);
    return result;
}
