AES_GCM_CTX* init_aes_gcm(const char* password) {
    const int keylen = 32; // AES-256 key size in bytes
    unsigned char pass[keylen + RAND_MAX];
    const EVP_CIPHER_CTX* cipher = EVP_aes_256_gcm();

    // Pad password with random bytes if it's shorter than the desired key length
    memset(pass, 0, keylen);
    memcpy(pass, password, strlen(password));
    if (strlen(password) < keylen) {
        RAND_bytes(pass + strlen(password), keylen - strlen(password));
    }

    // Derive encryption key using PBKDF2-HMAC-SHA256
    int salt_size = 8;
    unsigned char salt[salt_size];
    RAND_bytes(salt, salt_size);
    EVP_PKEY_CTX* ctx = EVP_PKEY_ctx_new_id(EVP_PKEY_PBKDF2, NULL);
    if (!ctx) return NULL;
    int key_iterations = 100000;
    EVP_PKEY_pbkdf2_init(ctx);
    EVP_PKEY_pbkdf2(ctx, pass, keylen, salt, salt_size, key_iterations, EVP_sha256());
    unsigned char derived_key[EVP_MAX_KEY_LENGTH];
    size_t derived_key_len = sizeof(derived_key);
    if (!EVP_PKEY_pbkdf2(ctx, derived_key, &derived_key_len, salt, salt_size, key_iterations, EVP_sha256())) {
        EVP_PKEY_CTX_free(ctx);
        return NULL;
    }
    EVP_PKEY_CTX_free(ctx);

    // Initialize AES-256-GCM context with the derived key and a fixed IV length of 12 bytes
    AES_GCM_CTX* ctx = AES_GCM_CTX_new();
    if (!AES_set_encrypt_key(derived_key, 32, AES_GCM_KEYLEN, ctx)) {
        AES_GCM_CTX_free(ctx);
        return NULL;
    }
    AES_GCM_set_iv(ctx, salt, salt_size);
    return ctx;
}

