        new_filename_len = MAX_FILENAME_LENGTH;
        new_ext_len = new_filename_len - base_len - ext_start - base - 1;
        snprintf(new_ext, sizeof(new_ext), "%" PRIu32, rand() / (double) RAND_MAX * pow((double)10, new_ext_len));
    }

    char *new_filename = malloc(new_filename_len + 1);
    assert(new_filename != NULL);
    if (ext_start) {
