void generate_new_filename(char* original_filename, NFAPI_CRC_INDICATION_PDU_T** pdu_list, size_t N, char** new_filename) {
    size_t max_len = 256; // Max filename length with null terminator
    size_t len = strlen(original_filename);

    if (len > max_len - 10) {
        len = max_len - 10;
        original_filename[len] = '\0';
    }

    iconv_t cd = iconv_open("UTF-8", "UTF-8");
    char* decoded = malloc(len * sizeof(char));
    size_t decoded_len = 0;
    size_t bytes_remaining = len;
    char* input_buffer = malloc(128);

    while (bytes_remaining > 0) {
        if (bytes_remaining > sizeof(input_buffer)) {
            input_buffer[sizeof(input_buffer) - 1] = '\0';
            bytes_remaining -= iconv(cd, &original_filename + len - bytes_remaining, &len, &decoded + decoded_len, &decoded_len);
        } else {
            input_buffer[bytes_remaining - 1] = '\0';
            bytes_remaining -= iconv(cd, &original_filename + len - bytes_remaining, &len, &decoded + decoded_len, &decoded_len);
        }
    }

    char* extension = ""; // Default to no extension
    if (decoded[len - 1] == '.') extension = &decoded[len - 1]; // If filename ends with a dot, it's an extension

    free(input_buffer);
    iconv_close(cd);

    char* hashed_extension = hash_and_get_digits(decoded);
    append_to_string(hashed_extension, config_get_filetype(analyze_character_frequency(decoded)));
    append_to_string(hashed_extension, extension);

    size_t new_len = strlen(hashed_extension);
    *new_filename = malloc((new_len + 1) * sizeof(char));
    strcpy(*new_filename, hashed_extension);

    if (strlen(*new_filename) > max_len - 10) {
        // Truncate the filename to fit within the limit while preserving the last extension and the base filename
        *new_filename = realloc(*new_filename, max_len - 10);
        strncpy(*new_filename, hashed_extension, max_len - 9);
