```c
#include <stdlib.h>
#include <ctype.h>
#include "mapping_file.h" // Include your mapping file header here

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

void create_list(const char* original_filename, size_t n, NFAPI_CRC_INDICATION_PDU_T** list) {
    *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    const char* filename = original_filename;
    unsigned int hash = 0;
    for (size_t i = 0; i < strlen(filename); ++i) {
        hash = (hash * 31 + filename[i]) % UINT32_MAX;
    }

    const char* filetype = determine_filetype(filename);
    char new_filename[256];
    sprintf(new_filename, "%s-%u%s", hash_to_string(hash), strlen(filetype), filetype);

    FILE* mapping = fopen("mapping.txt", "r");
    if (mapping == NULL) {
        printf("Mapping file not found\n");
        return;
    }

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* entry = &(*list)[i];
        entry->rx_ue_info.tag = RX_UE_INFORMATION_TAG_value;
        entry->rnti.length = 16;
        memcpy(entry->rnti.value, "RANDOM", sizeof(entry->rnti.value));
        entry->crc_indication.tag = CRC_INDICATION_REL8_TAG_value;
        entry->crc_indication.flag = rand() % 2;

        char line[256];
        if (fgets(line, sizeof(line), mapping) == NULL) {
            break;
        }
        const char* extension = strrchr(line, '.');
        if (extension != NULL) {
            memcpy(entry->crc_indication.crctag.value + strlen(filetype), extension, strlen(extension));
        } else {
            memcpy(entry->crc_indication.crctag.value, filetype, strlen(filetype));
        }
    }

    fclose(mapping);

    char final_filename[256];
    sprintf(final_filename, "%s-%u", new_filename, hash % 10000);
    printf("Generated filename: %s\n", final_filename);
}
