#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <uuid/uuid.h>

typedef struct {
    unsigned long SESSION_ID;
    char *USER_IDENTIFIER;
    time_t LAST_ACCESS_TIMESTAMP;
} USER_SESSION_INFO_T;

struct hash_node {
    USER_SESSION_INFO_T data;
    struct hash_node *next;
};

typedef struct {
    unsigned long key;
    struct hash_node *head;
} HASH_TABLE_ENTRY;

unsigned long custom_hash(const void *key) {
    const USER_SESSION_INFO_T *data = key;
    unsigned long hv = (unsigned long)(data->USER_IDENTIFIER);
    hv += (hv << 10);
    hv ^= (hv >> 6);
    return hv % TABLE_SIZE;
}

void hash_table_init(HASH_TABLE *ht) {
    ht->size = TABLE_SIZE;
    ht->entries = calloc(TABLE_SIZE, sizeof(HASH_TABLE_ENTRY));
    if (!ht->entries) return;

    pthread_mutex_init(&ht->lock, NULL);
}

void *insert_user_session(void *args) {
