    unsigned long long byte_count;
    time_t timestamp;
} TCP_PACKET_STATS;

#define MAX_BUFFER_SIZE 10000
#define FILENAME_MAX_LENGTH 255

struct dynamic_buffer {
    TCP_PACKET_STATS* buffer;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
};

void create_dynamic_buffer(struct dynamic_buffer* buffer) {
    buffer->capacity = MAX_BUFFER_SIZE;
    buffer->length = 0;
    buffer->buffer = malloc(sizeof(TCP_PACKET_STATS) * buffer->capacity);
    if (!buffer->buffer) {
        perror("Failed to allocate memory");
        return;
    }
    buffer->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void append_to_dynamic_buffer(struct dynamic_buffer* buffer, TCP_PACKET_STATS stats) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->length == buffer->capacity) {
        buffer->capacity *= 2;
        buffer->buffer = realloc(buffer->buffer, sizeof(TCP_PACKET_STATS) * buffer->capacity);
        if (!buffer->buffer) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&buffer->mutex);
            return;
        }
    }
    memcpy(&buffer->buffer[buffer->length], &stats, sizeof(TCP_PACKET_STATS));
    buffer->length++;
    pthread_mutex_unlock(&buffer->mutex);
}

TCP_PACKET_STATS* get_dynamic_buffer(struct dynamic_buffer* buffer) {
    pthread_mutex_lock(&buffer->mutex);
    TCP_PACKET_STATS* result = malloc(sizeof(TCP_PACKET_STATS) * buffer->length);
    if (!result) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&buffer->mutex);
        return NULL;
    }
    memcpy(result, buffer->buffer, sizeof(TCP_PACKET_STATS) * buffer->length);
    pthread_mutex_unlock(&buffer->mutex);
    return result;
}

void destroy_dynamic_buffer(struct dynamic_buffer* buffer) {
    free(buffer->buffer);
    buffer->buffer = NULL;
    buffer->capacity = 0;
    buffer->length = 0;
}

