import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;

public class StringHasher {
    private static final int MAX_THREADS = 10;
    private static final int BUFFER_SIZE = 1024 * 16; // 16KB buffer for efficiency

    private Pattern filterPattern;

    public StringHasher(Pattern filterPattern) {
        this.filterPattern = filterPattern;
    }

    public List<String> hashStrings(List<String> strings) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);
        List<Future<String[]>> futures = new ArrayList<>();

        // Process input strings in batches of BUFFER_SIZE for efficiency
        for (int i = 0; i < strings.size(); i += BUFFER_SIZE) {
            int end = Math.min(strings.size(), i + BUFFER_SIZE);
            List<String> batch = strings.subList(i, end);

            Future<String[]> future = executor.submit(() -> processBatch(batch));
            futures.add(future);
        }

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

        List<byte[]> hashes = new ArrayList<>();
        for (Future<String[]> future : futures) {
            try {
                String[] result = future.get();
                hashes.addAll(Arrays.asList(result));
            } catch (Exception e) {
                // Handle exceptions gracefully, log or throw appropriate exception
            }
        }

        List<byte[]> sortedHashes = mergeSort(hashes);
        List<String> md5Hashes = new ArrayList<>();
        for (byte[] hash : sortedHashes) {
            String hashStr = byteArrayToHexString(hash);
            if (matchesFilterPattern(hashStr)) {
                md5Hashes.add(hashStr);
            }
        }

        return md5Hashes;
    }

    private static List<byte[]> mergeSort(List<byte[]> list) {
        if (list.size() <= 1) {
            return list;
        }

        int mid = list.size() / 2;
        List<byte[]> left = new ArrayList<>();
        List<byte[]> right = new ArrayList<>();
        for (int i = 0; i < mid; i++) {
            left.add(list.get(i));
        }
        for (int i = mid; i < list.size(); i++) {
            right.add(list.get(i));
        }

        left = mergeSort(left);
        right = mergeSort(right);

        return merge(left, right);
    }

    private static List<byte[]> merge(List<byte[]> left, List<byte[]> right) {
        List<byte[]> result = new ArrayList<>();
        for (; !left.isEmpty() && !right.isEmpty(); ) {
            byte[] a = left.get(0);
            byte[] b = right.get(0);
            if (Arrays.compare(a, b) <= 0) {
                result.add(a);
                left.remove(0);
            } else {
                result.add(b);
                right.remove(0);
            }
        }

        while (!left.isEmpty()) {
            result.add(left.get(0));
            left.remove(0);
        }

        while (!right.isEmpty()) {
            result.add(right.get(0));
            right.remove(0);
        }

        return result;
    }

    private static String byteArrayToHexString(byte[] array) {
        StringBuilder sb = new StringBuilder();
        for (byte b : array) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private boolean matchesFilterPattern(String hashStr) {
        return filterPattern == null || filterPattern.matcher(hashStr).matches();
    }

    private String[] processBatch(List<String> batch) {
        List<byte[]> hashes = new ArrayList<>();
        MessageDigest md;
        for (String str : batch) {
            if (str == null || !str.isEmpty()) {
                try {
                    md = MessageDigest.getInstance("MD5");
                    byte[] hash = md.digest(str.getBytes(StandardCharsets.UTF_8));
                    hashes.add(hash);
                } catch (Exception e) {
                    // Handle exceptions gracefully, log or throw appropriate exception
                }
            }
        }
        return hashes.toArray(new byte[0][]);
    }
}
