NFAPI_CRC_INDICATION_PDU_T* allocate_structures(size_t num_structures) {
    if (num_structures > MAX_STRUCTURES) {
        log("Error: Requested number of structures exceeds the maximum limit.");
        return nullptr;
    }

    NFAPI_CRC_INDICATION_PDU_T* data = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T)));
    if (data == nullptr) {
        log("Error: Failed to allocate memory for structures.");
        free(data);
        return nullptr;
    }

    num_allocated = 0;
    for (size_t i = 0; i < num_structures; ++i) {
        data[i].rnti = i + 1; // RNTI value must be greater than zero and unique within the structures
        if (data[i].rnti > MAX_STRUCTURES || num_allocated && data[i].rnti == data[num_allocated - 1].rnti) {
            log("Error: Invalid RNTI value.");
            free(data);
            return nullptr;
        }

        data[i].crc_indication_tag = CRC_INDICATION_REL8_TAG{}; // Initialize the tag with zeroes
