        if (num_allocated && data[i].crcflag != data[num_allocated - 1].crcflag) {
            log("Error: Inconsistent CRCFLAG values across structures.");
            free(data);
            return nullptr;
        }

        ++num_allocated;
    }

    if (pthread_mutex_lock(&log_mutex)) {
        log("Error: Failed to lock log mutex for logging.");
        free(data);
        return nullptr;
    }

    log("%d structures successfully allocated.", num_allocated);
    pthread_mutex_unlock(&log_mutex);

    return data;
}

