#include <time.h>

#define MAX_BUFFERS 100000
#define EXPIRATION_THRESHOLD (60 * 60) // in seconds
#define NUM_PRIORITIES 4

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp;
    // Additional fields...
} NFAPI_RX_FRAME_T;

typedef struct priority_queue {
    NFAPI_RX_FRAME_T frames[MAX_BUFFERS];
    int head, tail, size;
    pthread_mutex_t lock;
} PQ;

PQ* create_priority_queues(int num_priorities) {
    PQ* queues = malloc(num_priorities * sizeof(PQ));
    for (int i = 0; i < num_priorities; ++i) {
        queues[i].head = queues[i].tail = -1;
        queues[i].size = 0;
        pthread_mutex_init(&queues[i].lock, NULL);
    }
    return queues;
}

void push(PQ* queue, NFAPI_RX_FRAME_T frame) {
    pthread_mutex_lock(&queue->lock);
    while ((queue->head + 1) % MAX_BUFFERS == queue->tail || (time(NULL) - frame.timestamp > EXPIRATION_THRESHOLD)) {
        // Handle backpressure and data expiration...
    }
    queue->frames[queue->head] = frame;
    queue->head = (queue->head + 1) % MAX_BUFFERS;
    ++queue->size;
    pthread_mutex_unlock(&queue->lock);
}

NFAPI_RX_FRAME_T pop(PQ* queue, int priority) {
    pthread_mutex_lock(&queue[priority]->lock);
    if (queue[priority]->head == queue[priority]->tail || queue[priority]->size == 0) {
        // Handle empty queue...
    }
    NFAPI_RX_FRAME_T frame = queue[priority]->frames[queue[priority]->head];
    queue[priority]->frames[queue[priority]->head] = {};
    queue[priority]->head = (queue[priority]->head + 1) % MAX_BUFFERS;
    --queue[priority]->size;
    pthread_mutex_unlock(&queue[priority]->lock);
    return frame;
}

void cleanup(PQ* queues, int num_priorities) {
    for (int i = 0; i < num_priorities; ++i) {
        free(queues[i].frames);
        pthread_mutex_destroy(&queues[i].lock);
    }
    free(queues);
}
