#include <stdio.h>
#include <string.h>
#include <time.h>
#include <uuid/uuid.h>
#include <pthread.h>

char *generate_session_token(char *input, char *token_type) {
    // Generate timestamp in ISO 8601 format
    time_t now = time(NULL);
    char ts[29];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    // Construct token string using sprintf and strcat
    size_t input_len = strlen(input);
    size_t max_token_len = 255 - (strlen(ts) + strlen(token_type) + 6); // .uuid + :
    if (max_token_len < input_len + 13) {
        fprintf(stderr, "Error: Token exceeds maximum length\n");
        return NULL;
    }

    char token[max_token_len + 1];
    sprintf(token, "%s.%s:%s", ts, input, token_type);

    // Generate UUID and append it to the token string
    uuid_t uuid;
    uuid_generate(uuid);
    snprintf(token + strlen(token), max_token_len - strlen(token), ".%llx", (unsigned long long)*((uint64_t*)&uuid));

    return token;
}
