    *head = NULL;
}

void append_user_node(struct user_node **head, USER_SESSION_INFO_T data) {
    struct user_node *node = malloc(sizeof(struct user_node));
    node->data = data;
    node->prev = node->next = NULL;

    if (*head == NULL) {
        *head = node;
        return;
    }

    struct user_node *current = *head;
    while (current->next != NULL) current = current->next;

    current->next = node;
    node->prev = current;
}
