#include <sys/types.h>
#include <time.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>

char* generate_unique_filename(const char* base, pthread_mutex_t* mutex) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    size_t len = strlen(base) + 32; // assuming timestamp + random number + extension
    char* filename = malloc(len);
    snprintf(filename, len, "%s_%04d%02d%02d_%u.txt", base, tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, rand());

    pthread_mutex_lock(mutex);
    if (access(filename, F_OK) == 0) { // Check if the file already exists
        free(filename); // Free memory and try again with a different name
        generate_unique_filename(base, mutex);
    }
    pthread_mutex_unlock(mutex);

    return filename;
}
