size_t read_largest_integer(int* integers, size_t length, const char* source) {
    if (length == 0) return 0;

    size_t largest = *integers;
    size_t index = 0;

    for (size_t i = 1; i < length; ++i) {
        if (*(integers + i) > largest) {
            largest = *(integers + i);
            index = i;
