    }
}

// Insertion function
void insert(USER_SESSION_INFO_T session) {
    size_t hash = custom_hash(&session);
    pthread_mutex_lock(&table_lock[hash]);
    struct bucket* bucket = hash_table[hash];
    size_t probe = 0;

    while (bucket->data.session_id != 0) {
        if (custom_hash(&(bucket->data)) == hash && bucket->probe == probe) {
            ++probe;
            bucket = &hash_table[hash + probe] % TABLE_SIZE;
        } else {
            break;
        }
    }

    // ... Implement collision resolution strategy, such as rehashing or chaining.

    pthread_mutex_unlock(&table_lock[hash]);
}

// Deletion function
