    pthread_mutex_lock(&table_lock[hash]);

    struct bucket* bucket = hash_table[hash];
    size_t probe = 0;

    while (bucket->data.session_id != session_id) {
        if (custom_hash(&(bucket->data)) == hash && bucket->probe == probe) {
            ++probe;
            bucket = &hash_table[hash + probe] % TABLE_SIZE;
        } else {
            break;
        }
    }

    if (bucket->data.session_id == session_id) {
        // ... Implement data deallocation and collision resolution strategy.
    }

    pthread_mutex_unlock(&table_lock[hash]);
}

// Retrieval function
USER_SESSION_INFO_T* retrieve(SESSION_ID session_id) {
    size_t hash = custom_hash((const void*)&session_id);
    pthread_mutex_lock(&table_lock[hash]);

    struct bucket* bucket = hash_table[hash];
    size_t probe = 0;

    while (bucket->data.session_id != session_id) {
        if (custom_hash(&(bucket->data)) == hash && bucket->probe == probe) {
            ++probe;
            bucket = &hash_table[hash + probe] % TABLE_SIZE;
        } else {
            break;
        }
    }

    if (bucket->data.session_id == session_id) {
        USER_SESSION_INFO_T* session = &bucket->data;
        pthread_mutex_unlock(&table_lock[hash]);
        return session;
    } else {
        pthread_mutex_unlock(&table_lock[hash]);
        return NULL;
    }
