std::string generateSessionToken(const std::string& input, const std::string& type) {
    // Your external logging system implementation here

    auto timestamp = std::chrono::system_clock::now().time_since_epoch().count();
    std::ostringstream ss;
    ss << std::put_time(std::gmtime(&timestamp), "%Y-%m-%dT%H:%M:%S") << '.' << std::setfill('0') << std::setw(3) << timestamp % 1000;

    auto uuid = boost::uuids::random_generator()();
    ss << "-" << type << '-';
    ss << uuid.string();

    const int inputLength = input.length();
    std::ostringstream token(ss.str());  // Create a new output stream for the token
    if (inputLength > 0) {
        token << "-" << input.substr(0, 254 - ss.str().size()) << input.substr(inputLength - 1);
    } else {
        token << "-" << std::string(254 - ss.str().size(), '-');
    }

    return token.str();
}
