    bool remove(MAC_CONTEXT_T* context);
    const MAC_CONTEXT_T* get(size_t index) const;

private:
    boost::circular_buffer<MAC_CONTEXT_T*> buffer_;
    pthread_mutex_t mutex_;
    std::vector<pthread_t> threads_;
};

DynamicList::DynamicList(size_t threadCount) : buffer_(threadCount), threads_(threadCount) {
