    // join and clean up your worker threads here
}

bool DynamicList::insert(const MAC_CONTEXT_T* context) {
    pho_lock lock(PHOLockAlloc());
    pthread_mutex_lock(&mutex_);

    while (buffer_.size() >= buffer_.capacity()) {
        // handle backpressure here, e.g., by discarding data or queueing it for later processing
    }

    auto* newContext = pho_malloc(MAC_CONTEXT_SIZE);
    memcpy(newContext, context, MAC_CONTEXT_SIZE);
    buffer_.push_back(newContext);

    pthread_mutex_unlock(&mutex_);
    return true;
}

bool DynamicList::remove(MAC_CONTEXT_T* context) {
    pho_lock lock(PHOLockAlloc());
    pthread_mutex_lock(&mutex_);

    auto it = std::find(buffer_.begin(), buffer_.end(), context);
    if (it != buffer_.end()) {
        pho_free(context);
        buffer_.erase(it);
        return true;
    }

    pthread_mutex_unlock(&mutex_);
    return false;
}

const MAC_CONTEXT_T* DynamicList::get(size_t index) const {
    pthread_mutex_lock(&mutex_);
    auto it = buffer_.cbegin();
    std::advance(it, index);
    pthread_mutex_unlock(&mutex_);
    return *it;
}
