                }
            }
            fprintf(file, "Largest integer: %d at index: %d\n", max_val, max_index);
        }

        fwrite(pdu, sizeof(*pdu), 1, file);
        num_ints++;
    }

    free(buffers);
    fclose(file);
    pthread_mutex_destroy(&lock);

    // Allocate memory for the dynamically generated linked list and populate it with the PDUs
    NFAPI_CRC_INDICATION_PDU** new_list = malloc((num_ints + 1) * sizeof(*new_list));
    if (!new_list) {
        log("Error: memory allocation failed");
        return -1;
    }

    for (int i = 0; i < num_ints; ++i) {
        new_list[i] = list[i];
    }
    free(list);
    new_list[num_ints] = NULL;

    *list = new_list;

    // Invoke the callback function with the context provided
    if (context->callback) {
        context->callback(context);
    }

    return 0;
}
