#include <time.h>

#define CRCI_FAILURE_RATE 10 // Probabilistic CRC failure rate (adjust as needed)

// Custom memory allocator
typedef struct Node {
    NFAPI_RX_FRAME_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_RX_FRAME_T data) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void free_list(Node* head) {
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}

// Dynamic list
NFAPI_RX_FRAME_T* dynamic_list = NULL;
unsigned int size = 0;
unsigned int capacity = 0;
Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and manage the list
void init_list(unsigned int n) {
    if (n == 0) {
        fprintf(stderr, "Error: List size cannot be zero\n");
        return;
    }

    capacity = n;
    head = calloc(capacity, sizeof(Node));
    if (!head) {
        fprintf(stderr, "Error: Out of memory\n");
        return;
    }

    size = 0;
}

// Function to insert a new entry into the list
void push(NFAPI_RX_FRAME_T data) {
    pthread_mutex_lock(&lock);
    if (size >= capacity) {
        fprintf(stderr, "Error: List has reached its capacity\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&lock);
        return;
    }

    new_node->next = head[size % capacity];
    head[size % capacity] = new_node;
    size++;
    pthread_mutex_unlock(&lock);
}

// Function to retrieve a specific entry from the list by index (modulo the capacity)
NFAPI_RX_FRAME_T* get(unsigned int idx) {
    if (idx >= size || idx >= capacity) {
        fprintf(stderr, "Error: Index out of range\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);
    Node* current = head[idx % capacity];
    pthread_mutex_unlock(&lock);

    return &current->data;
}

// Function to clear and reinitialize the list, releasing resources on system restart
void reset() {
    free_list(head);
    size = 0;
    capacity = 0;
    head = NULL;
}

// Probabilistic CRC calculation
bool calculateCRC(NFAPI_RX_FRAME_T* frame) {
    if (rand() % CRCI_FAILURE_RATE == 0) return false; // Fail probabilistically based on the defined rate
    return true;
}
