        this.errorTypeClassifier = errorTypeClassifier;
    }

    public void processLogs(List<String> logs, Runnable onProgress, Consumer<String> onCancelRequest, BufferedWriter outputWriter) throws InterruptedException {
        this.outputWriter = outputWriter;
        for (int i = 0; i < logs.size(); ) {
            int chunkSize = Math.min(MAX_CHUNK_SIZE, logs.size() - i);
            List<String> logChunk = logs.subList(i, i + chunkSize);
            processLogsChunk(logChunk, onProgress, onCancelRequest);
            i += chunkSize;
        }
    }

    private void processLogsChunk(List<String> logChunk, Runnable onProgress, Consumer<String> onCancelRequest) {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        for (String log : logChunk) {
            if (!isCanceled) {
                LogTask logTask = new LogTask(log, hashedLogs::putIfAbsent);
                executor.submit(logTask);
            } else {
                break;
            }
        }
        if (onProgress != null) onProgress.run();
        executor.shutdown();
        while (!executor.isTerminated()) {}
    }

    public void cancelProcessing() {
        isCanceled = true;
        if (outputWriter != null && !outputWriter.closed()) {
            try {
                outputWriter.close();
            } catch (IOException e) {
                // Handle exception
            }
        }
    }

