                    .forEach(e -> {
                        try {
                            csvPrinter.printRecord(e.getKey(), e.getValue());
                        } catch (IOException ex) {
                            // Handle exception
                        }
                    });
                if (onProgress != null) onProgress.run();
            }
        }
    }
}

class LogTask implements Runnable {
    private final String log;
    private Function<String, Object> putIfAbsentFunction;

    public LogTask(String log, Function<String, Object> putIfAbsentFunction) {
        this.log = log;
        this.putIfAbsentFunction = putIfAbsentFunction;
    }

    @Override
    public void run() {
        try {
