public class NetworkPacketProcessor {
    private static final int MAX_CONCURRENT_TASKS = 50;
    private static final int SESSION_MAX_LIMIT = 1000;
    private static final long PACKET_SIZE_THRESHOLD = 1000 * 1024L; // 1 MB
    private static final Cache<Long, SessionContext> sessionCache = CacheBuilder.newBuilder()
            .maximumSize(MAX_LONGS_PER_PROCESSOR)
            .expireAfterAccessDuration(Duration.ofMinutes(1))
            .build();

    private ExecutorService executor;
    private DataStorage dataStorage;
    private Cache<Long, byte[]> packetCache = CacheBuilder.newBuilder()
            .maximumSize(MAX_LONGS_PER_PROCESSOR)
            .expireAfterWriteDuration(Duration.ofMinutes(1))
            .build();

    public NetworkPacketProcessor(DataStorage dataStorage) {
        this.dataStorage = dataStorage;
        executor = MoreExecutors.newFixedThreadPool(MAX_CONCURRENT_TASKS);
    }

    public void processPacketStream(InputStream packetStream, OutputStream logStream) throws IOException {
        try (PacketReader packetReader = new PacketReader(packetStream)) {
            while (packetReader.hasNext()) {
                NetworkPacket packet = packetReader.read();
                if (packet.getSize() > PACKET_SIZE_THRESHOLD) {
                    logStream.write((("Dropped oversized packet: " + packet.getId()).getBytes()));
                    continue;
                }

                long checksum = calculateChecksum(packet);
                if (!validateIntegrity(checksum, packet)) {
                    logStream.write(("Invalid packet: " + packet.getId()).getBytes());
                    continue;
                }

                SessionContext sessionContext = getOrCreateSessionContext(packet.getClientIp());
                PacketSummary summary = processPacket(sessionContext, packet);
                updateStatistics(summary);
                logPacketProgress(logStream, packet.getId(), summary);
            }
        }
    }

    private SessionContext getOrCreateSessionContext(String clientIp) {
        SessionContext sessionContext = sessionCache.getIfPresent(Long.parseUnsignedLong(clientIp));
        if (sessionContext == null && sessionCache.size() < SESSION_MAX_LIMIT) {
            sessionContext = new SessionContext(clientIp);
            sessionCache.put(System.currentTimeMillis(), sessionContext);
        }
        return sessionContext;
    }

    // Implement the remaining methods, including error handling, logging, and concurrency management.
}
