    gsl_hash_table_set(ht, key, value);
    pthread_mutex_unlock(&ht_lock);
}

NFAPI_TX_PACKET_T* retrieve(const char *key) {
    NFAPI_TX_PACKET_T *value = NULL;
    pthread_mutex_lock(&ht_lock);
    value = gsl_hash_table_get_ptr(ht, key);
    pthread_mutex_unlock(&ht_lock);
    return value;
}

void delete(const char *key) {
    pthread_mutex_lock(&ht_lock);
    gsl_hash_table_remove(ht, key);
    pthread_mutex_unlock(&ht_lock);
}
