#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

pthread_mutex_t data_lock = PTHREAD_MUTEX_INITIALIZER;
int max_num = 0;
int max_index = -1;

void *process(void *arg) {
    int *data = (int *) arg;
    int local_max = -1;
    int local_index = -1;

    for (int i = 0; data[i] != -1; ++i) {
        pthread_mutex_lock(&data_lock);
        if (local_max < data[i]) {
            local_max = data[i];
            local_index = i;
        }
        pthread_mutex_unlock(&data_lock);
    }

    pthread_mutex_lock(&data_lock);
    if (local_max > max_num) {
        max_num = local_max;
        max_index = local_index;
    }
    pthread_mutex_unlock(&data_lock);

    return NULL;
}
