#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_RX_FRAME_T;

typedef struct _NFAPI_RX_FRAME_MANAGER {
    NFAPI_RX_FRAME_T* frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    void* reduction_result; // Holds the result of asynchronous reduction operation
    bool reduction_in_progress;
} NFAPI_RX_FRAME_MANAGER;

NFAPI_RX_FRAME_MANAGER* initialize_and_manage_nfaapi_rx_frame(size_t initial_capacity) {
    NFAPI_RX_FRAME_MANAGER* manager = (NFAPI_RX_FRAME_MANAGER*) malloc(sizeof(NFAPI_RX_FRAME_MANAGER));

    if (!manager) {
        perror("Failed to allocate memory for NFAPI RX Frame Manager.");
        return NULL;
    }

    manager->frames = (NFAPI_RX_FRAME_T*) calloc(initial_capacity, sizeof(NFAPI_RX_FRAME_T));

    if (!manager->frames) {
        perror("Failed to allocate memory for NFAPI RX Frames.");
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->reduction_result = NULL;
    manager->reduction_in_progress = false;

    return manager;
}

void push(NFAPI_RX_FRAME_MANAGER* manager, const NFAPI_RX_FRAME_T frame) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count >= manager->capacity) {
        manager->capacity *= 2;
        manager->frames = realloc(manager->frames, manager->capacity * sizeof(NFAPI_RX_FRAME_T));

        if (!manager->frames) {
            perror("Failed to resize NFAPI RX Frames.");
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
    }

    manager->frames[manager->count] = frame;
    manager->count++;

    pthread_mutex_unlock(&manager->mutex);
}

NFAPI_RX_FRAME_T pop(NFAPI_RX_FRAME_MANAGER* manager) {
    if (manager->count == 0) return (NFAPI_RX_FRAME_T) {};

    pthread_mutex_lock(&manager->mutex);

    NFAPI_RX_FRAME_T frame = manager->frames[0];
    memmove(manager->frames, &manager->frames[1], sizeof(NFAPI_RX_FRAME_T) * (manager->count - 1));
    manager->count--;

    pthread_mutex_unlock(&manager->mutex);

    return frame;
}

void reduce_async(NFAPI_RX_FRAME_MANAGER* manager, void* initial_value, void (*reduce_func)(void*, const NFAPI_RX_FRAME_T, void*), void** result) {
    pthread_t thread_id;
    reduction_params params = { .manager = manager, .initial_value = initial_value, .reduce_func = reduce_func };

    *result = &params.initial_value;

    if (pthread_create(&thread_id, NULL, reduce_async_worker, &params) != 0) {
        perror("Failed to create reduction asynchronous thread.");
    } else {
        manager->reduction_in_progress = true;
    }
}

void* reduce_async_worker(void* params_void) {
    reduction_params* params = (reduction_params*) params_void;
    NFAPI_RX_FRAME_MANAGER* manager = params->manager;
    void* initial_value = params->initial_value;
    void (*reduce_func)(void*, const NFAPI_RX_FRAME_T, void*) = params->reduce_func;
    bool reduction_in_progress = true;

    pthread_mutex_lock(&manager->mutex);

    if (manager->reduction_in_progress) {
        reduction_params* active_params = (reduction_params*) manager->reduction_result;
        reduce_func(initial_value, active_params->frame, initial_value);
        params->frame = active_params->frame;
    } else {
        manager->reduction_in_progress = true;
        manager->reduction_result = &params->initial_value;
    }

    reduction_in_progress = false;
    pthread_mutex_unlock(&manager->mutex);

    while (reduction_in_progress) {
        usleep(100000); // Adjust sleep duration as needed
        pthread_mutex_lock(&manager->mutex);

        reduction_params* active_params = (reduction_params*) manager->reduction_result;
        if (!active_params) {
            reduction_in_progress = false;
            break;
        }

        reduce_func(params->initial_value, active_params->frame, params->initial_value);
        params->frame = active_params->frame;

        pthread_mutex_unlock(&manager->mutex);
    }

    manager->reduction_in_progress = false;
    pthread_exit(NULL);
}

struct reduction_params {
    NFAPI_RX_FRAME_MANAGER* manager;
    void* initial_value;
    void (*reduce_func)(void*, const NFAPI_RX_FRAME_T, void*);
};
```

