NFAPI_CRC_INDICATION_PDU_T generate_list(uint32_t n, uint32_t min_rnti, uint32_t max_rnti) {
    if (n <= 0 || max_rnti < min_rnti) {
        log(1, "Invalid input: n=%u, min_rnti=%u, max_rnti=%u", n, min_rnti, max_rnti);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T list = mmap(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T) * n, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (list == MAP_FAILED) {
        log(1, "Failed to allocate memory for list: %s", strerror(errno));
        return NULL;
    }

    sem_init(&semaphore, 0, n); // Initialize the semaphore with the number of available slots in the list

    // Function to create an individual structure and validate RNTI
    void* generate_one(uint32_t index) {
        NFAPI_CRC_INDICATION_PDU_T element = &list[index];

        uint32_t rnti;
        do {
            rnti = rand() % (max_rnti - min_rnti + 1) + min_rnti;
        } while (!validate_rnti(rnti, min_rnti, max_rnti));

        RNTI_CRC_FLAG* rxi_info = (RNTI_CRC_FLAG*)&element->rxi_info;
        rxi_info->rnti = rnti;
        rxi_info->crc_flag = rand() % 2;

        return element;
    }

    // Create worker threads to populate the list concurrently
    uint32_t chunk_size = (n + thread_count - 1) / thread_count;
    pthread_t threads[thread_count];
    for (uint32_t i = 0; i < thread_count; ++i) {
        void* start = (void*)(i * chunk_size);
        void* end = (i == thread_count - 1) ? NULL : ((void*)((i + 1) * chunk_size));
        pthread_create(&threads[i], NULL, generate_one, start);
    }

    // Wait for all threads to finish and free resources
    for (uint32_t i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    munmap(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * n); // Free the memory map

    return list;
}
