sem_t sem_list, sem_record;
pthread_mutex_t mtx_list, mtx_record;

NFAPI_CRC_INDICATION_PDU_T* create_pdu(void) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;
    pdu->rxi = rand(); // Populate RXI with random value
    pdu->rnti = rand() % MAX_RNTI + MIN_RNTI; // Generate RNTI within specified range
    pdu->crcflag = rand() % 2; // Set CRCFLAG to a random value
    return pdu;
}

record_t* create_record(int id, const char *key, size_t offset) {
    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    if (!new_record) return NULL;
    new_record->id = id;
    strncpy(new_record->key, key, sizeof(new_record->key));
    new_record->key[sizeof(new_record->key)-1] = '/'; // Append slash to the end of the key
    new_record->offset = offset;
    new_record->next = NULL;
    return new_record;
}

void list_init(NFAPI_CRC_INDICATION_PDU_T*** pdu_list, size_t* pdu_count) {
    sem_init(&sem_list, 0, 1);
    pthread_mutex_init(&mtx_list, NULL);
    *pdu_list = NULL;
    *pdu_count = 0;
}

void list_resize(NFAPI_CRC_INDICATION_PDU_T*** pdu_list, size_t* pdu_count, size_t new_capacity) {
    sem_wait(&sem_record); // Wait for record lock

    NFAPI_CRC_INDICATION_PDU_T** new_pdus = realloc(*pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!new_pdus) {
        perror("realloc failed");
        sem_post(&sem_record); // Signal record lock release
        return;
    }

    for (size_t i = *pdu_count; i < new_capacity; ++i)
        new_pdus[i] = NULL;

    *pdu_list = new_pdus;
    *pdu_count = new_capacity;
    sem_post(&sem_record); // Signal record lock release
}

NFAPI_CRC_INDICATION_PDU_T* list_get(const NFAPI_CRC_INDICATION_PDU_T** pdu_list, size_t index) {
    sem_wait(&sem_list); // Wait for list lock

    if (index >= *((size_t*)pthread_getspecific(key_to_thread_map)) || !pdu_list[index]) {
        sem_post(&sem_list); // Signal list lock release
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = pdu_list[index];
    sem_post(&sem_list); // Signal list lock release
    return pdu;
}

bool list_push(NFAPI_CRC_INDICATION_PDU_T** pdu_list, size_t* pdu_count, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    sem_wait(&sem_record); // Wait for record lock
    sem_wait(&sem_list); // Wait for list lock

    if (*pdu_count >= *((size_t*)pthread_getspecific(key_to_thread_map))) {
        sem_post(&sem_record); // Signal record lock release
        sem_post(&sem_list); // Signal list lock release
        return false;
    }

    if (!validate_rnti(pdu->rnti)) {
        sem_post(&sem_record); // Signal record lock release
        sem_post(&sem_list); // Signal list lock release
        free(pdu);
        return false;
    }

    if (!*pdu_list) {
        list_resize(pdu_list, pdu_count, INITIAL_CAPACITY);
    }

    *((*pdu_count))++ = pdu;
    sem_post(&sem_record); // Signal record lock release
    sem_post(&sem_list); // Signal list lock release
    return true;
}

