typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_RX_FRAME_T;

typedef struct Node {
    NFAPI_RX_FRAME_T frame;
    struct Node* next;
} Node;

struct Queue {
    size_t capacity; // Maximum number of frames in the queue
    size_t count; // Current number of frames in the queue
    Node* head; // Head of the queue
    Node* tail; // Tail of the queue
    pthread_mutex_t lock; // Mutex for concurrent access control
};

Queue* create_queue(size_t capacity) {
    Queue* q = (Queue*)custom_malloc(sizeof(Queue));
    q->capacity = capacity;
    q->count = 0;
    q->head = NULL;
    q->tail = NULL;
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

void insert_frame(Queue* q, const NFAPI_RX_FRAME_T* frame) {
    Node* new_node = (Node*)custom_malloc(sizeof(Node));
    new_node->frame = *frame;
    new_node->next = NULL;

    pthread_mutex_lock(&q->lock);
    if (!q->head) {
        q->head = new_node;
        q->tail = new_node;
    } else {
        q->tail->next = new_node;
        q->tail = new_node;
    }
    q->count++;
    pthread_mutex_unlock(&q->lock);
}

NFAPI_RX_FRAME_T* retrieve_frame(Queue* q) {
    if (q->count == 0) return NULL;

    pthread_mutex_lock(&q->lock);
    Node* temp = q->head;
    q->head = temp->next;
    if (!q->head) q->tail = NULL;
    q->count--;
    pthread_mutex_unlock(&q->lock);

    return &temp->frame;
}
