public class MD5Hasher {
    private static final int MAX_LOG_SIZE = 100_000_000;
    private static final long RETENTION_PERIOD = TimeUnit.DAYS.toMillis(7);
    private static final Comparator<String> LOG_COMPARATOR = (s1, s2) -> s1.compareToIgnoreCase(s2);
    private static final int RETRY_WRITE_ATTEMPTS = 3;
    private static final ExecutorService executor = Executors.newCachedThreadPool();

    private final ConcurrentSkipListMap<String, String> log = new ConcurrentSkipListMap<>(LOG_COMPARATOR);
    private final RedBlackTreeLogger logger = new RedBlackTreeLogger(log);
    private final BinarySearchTreeStats stats = new BinarySearchTreeStats();

    public Map<String, String> hashStrings(List<String> strings) {
        if (strings == null || strings.isEmpty()) return Collections.emptyMap();

        ProgressTracker tracker = new ProgressTracker(strings.size());
        MD5BatchProcessor processor = new MD5BatchProcessor(tracker, this::hashAndLog);

        ArrayList<String> batch = new ArrayList<>();
        for (String s : strings) {
            if (s == null || s.isEmpty()) continue;
            batch.add(s);
            if (batch.size() >= 1024) {
                processor.processBatch(batch);
                tracker.incrementProgress();
                batch.clear();
            }
        }
        if (!batch.isEmpty()) processor.processBatch(batch);

        return log;
    }

    private void hashAndLog(String string, MessageDigest digest) {
        try {
            logger.logEvent("Hashing", "Started hashing: " + string);
            digest.update(string.getBytes(StandardCharsets.UTF_8));
            String md5 = byteArrayToHex(digest.digest());
            logger.logEvent("Hashed", "Finished hashing: " + string + ", MD5 hash: " + md5);
            log.putIfAbsent(string, md5);
            stats.incrementHashes();
            if (log.size() > MAX_LOG_SIZE) compressAndArchiveLogs();
        } catch (Exception e) {
            logger.logError("Hashing", "Error hashing: " + string, e);
            retryWriteToFile(string + ": MD5 hash", md5 -> logger.logError("WriteFailed", "Failed to write log entry for: " + string, e), RETRY_WRITE_ATTEMPTS);
        }
    }

    // Implement the remaining classes and methods as per your specifications

    private static String byteArrayToHex(byte[] bytes) {
        StringBuilder hex = new StringBuilder();
        for (int i = 0; i < bytes.length; i++) {
            int v = bytes[i] & 0xFF;
            if (v <= 0xF) hex.append('0');
            hex.append(Integer.toHexString(v));
        }
        return hex.toString();
    }

    private void compressAndArchiveLogs() {
