['```java
import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.locks.ReentrantLock;

public class MD5HashUtil {
    private static final int BUFFER_SIZE = 1024;
    private static final String ERROR_MESSAGE = "Input string exceeds the maximum allowed length of 1024 characters.";
    private static final ConcurrentMap<String, BigInteger> cache = new ConcurrentHashMap<>();
    private static final ReentrantLock lock = new ReentrantLock();

    public static BigInteger md5Hash(String input) {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty.");
        }

        if (input.length() > BUFFER_SIZE) {
            return new BigInteger(ERROR_MESSAGE);
        }

        lock.lock();
        try {
            BigInteger hash = cache.get(input);
            if (hash != null) {
                return hash;
            }

            MessageDigest md;
            byte[] buffer = new byte[BUFFER_SIZE];
            byte[] data = input.getBytes();

            if (data.length > BUFFER_SIZE) {
                throw new IllegalArgumentException("Input string exceeds the maximum allowed length of 1024 characters.");
            }

            try {
                md = MessageDigest.getInstance("MD5");
            } catch (NoSuchAlgorithmException e) {
                throw new RuntimeException(e);
            }

            int remainingLength = data.length;
            int offset = 0;

            while (remainingLength > 0) {
                if (remainingLength > BUFFER_SIZE) {
                    System.arraycopy(data, offset, buffer, 0, BUFFER_SIZE);
                    remainingLength -= BUFFER_SIZE;
                    offset += BUFFER_SIZE;
                } else {
                    System.arraycopy(data, offset, buffer, 0, remainingLength);
                    remainingLength = 0;
                }

                md.update(buffer, 0, buffer.length);
            }

            byte[] digest = md.digest();
            hash = new BigInteger(1, digest);
            cache.putIfAbsent(input, hash);

            return hash;
        } finally {
            lock.unlock();
        }
    }
}
