import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.logging.Logger;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MD5Hasher {
    private static final Logger LOGGER = Logger.getLogger(MD5Hasher.class.getName());
    private static final ExecutorService EXECUTOR = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors() * 2);
    private static final ConcurrentLinkedQueue<String> QUEUE = new ConcurrentLinkedQueue<>();

    public static String md5Hash(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hash = digest.digest(input.getBytes());
            BigInteger number = new BigInteger(1, hash);
            StringBuilder sb = new StringBuilder(number.toString(16));
            while (sb.length() < 32) {
                sb.insert(0, "0");
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            LOGGER.severe("Error calculating MD5 hash: " + e.getMessage());
            throw new RuntimeException(e);
        }
    }

    public static void logWithMD5Hash(String metadata, String input) {
        QUEUE.add(metadata + ": " + md5Hash(input));
        EXECUTOR.submit(() -> LOGGER.info(QUEUE.poll()));
    }

    // Unit tests
    public static void main(String[] args) throws Exception {
        String[] testCases = {"Hello World", "\uD83D\uDC42", "123456789012345678901234567890", "A" + new String(new char[Integer.MAX_VALUE])};
        for (String testCase : testCases) {
            System.out.println("Input: " + testCase);
            System.out.println("MD5 Hash: " + md5Hash(testCase));
        }
    }
}
