import org.bouncycastle.crypto.digests.SHA-256Digest;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.*;

public class SecureHasher {
    private static final Logger log = LoggerFactory.getLogger(SecureHasher.class);
    private static final int THREAD_COUNT = Runtime.getRuntime().availableProcessors();
    private static final FileLoggerAppender fileLoggerAppender;

    static {
        try {
            // Configure the Logback appender for auto-rotating log files based on size.
            // Customize the settings as needed (e.g., maximum log file size, retention policy)
            final RollingRandomAccessFileAppender<ILoggingEvent> appender = new RollingRandomAccessFileAppender<>();
            appender.setContext(LogManager.getContext(false));
            appender.setName("FileLogger");
            appender.setFile("/path/to/your-app.log");
            appender.setAppend(true);
            appender.setMaximumFileSize(50 * 1024 * 1024); // 50 MB
            appender.setMaxHistory(30); // 30 days retention policy
            appender.start();
            fileLoggerAppender = (FileLoggerAppender) appender;
        } catch (IOException ex) {
            log.error("Error initializing Logback appender", ex);
            throw new RuntimeException(ex);
        }
    }

    private static ExecutorService executor = Executors.newFixedThreadPool(THREAD_COUNT);

    public static String hash(String input) {
        try {
            final SHA-256Digest digest = new SHA-256Digest();
            return bytesToHex(digest.digest(input.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException ex) {
            log.error("Error generating SHA-256 hash", ex);
            throw new RuntimeException(ex);
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void logMessageWithHash(String message, String tag) {
        final String hash = hash(message);
        final ILoggingEvent event = new SimpleLoggingEvent(tag, System.currentTimeMillis(), Level.INFO, hash, null, message);
        fileLoggerAppender.doAppend(event);
    }

    public static void main(String[] args) {
        // Example of asynchronous hashing and logging
        final List<Future<Void>> futures = new ArrayList<>();
        for (int i = 0; i < 1000; ++i) {
            final String input = "Input message" + i;
            final Callable<Void> callable = () -> {
                logMessageWithHash(input, "MyTag");
                return null;
            };
            futures.add(executor.submit(callable));
        }

        try {
            for (Future<Void> future : futures) {
                future.get();
            }
        } catch (InterruptedException | ExecutionException ex) {
            log.error("Error during concurrent processing", ex);
            throw new RuntimeException(ex);
        } finally {
            executor.shutdownNow();
        }
    }
}
```

Finally, you can utilize the `logMessageWithHash()` method in your existing logging framework to generate a SHA-256 hash for each logged message alongside other relevant metadata.']

