typedef struct {
    int TFTP_BLOCK_NUMBER;
    char* data;
    int integrity;
} TFTP_PACKET;

TFTP_PACKET* create_packet(int block_number, const void* data, size_t size, int integrity) {
    TFTP_PACKET* packet = malloc(sizeof(TFTP_PACKET));
    packet->TFTP_BLOCK_NUMBER = block_number;
    packet->data = malloc(size);
    memcpy(packet->data, data, size);
    packet->integrity = integrity;
    return packet;
}

void destroy_packet(TFTP_PACKET* packet) {
    free(packet->data);
    free(packet);
}

